	[DataUpgrader(Version = "1.0.50", Date = "2026/07/05")]
	private void FixAbnormalGearMateFavorability(DataContext context)
	{
		List<int> previousTaiwuIds = DomainManager.Taiwu.GetPreviousTaiwuIds();
		if (previousTaiwuIds == null || previousTaiwuIds.Count <= 0)
		{
			return;
		}
		int newTaiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		int oldTaiwuCharId = previousTaiwuIds[previousTaiwuIds.Count - 1];
		foreach (int charId in _sectZhujianGearMates.Keys)
		{
			short favorability = DomainManager.Character.GetFavorability(charId, oldTaiwuCharId);
			if (favorability != short.MinValue)
			{
				short currFavorability = DomainManager.Character.GetFavorability(charId, newTaiwuCharId);
				if (currFavorability < favorability)
				{
					DomainManager.Character.DirectlySetFavorabilities(context, charId, newTaiwuCharId, favorability, favorability);
					Logger.Warn($"Transfering gear mate {charId}'s favorability from old taiwu {oldTaiwuCharId}({favorability}) to new taiwu {newTaiwuCharId}({currFavorability})");
				}
			}
		}
	}

	[DataUpgrader(Version = "1.0.56", Date = "2026/07/11")]
	private void FixResourceDisasterLocations(DataContext context)
	{
		List<Location> changedLocations = new List<Location>();
		List<Location> needRemoveLocations = new List<Location>();
		foreach (KeyValuePair<Location, SerializableList<BuildingAreaEffectProgress>> buildingAreaEffectProgress in _buildingAreaEffectProgresses)
		{
			buildingAreaEffectProgress.Deconstruct(out var key, out var value);
			Location effectLocation = key;
			SerializableList<BuildingAreaEffectProgress> effects = value;
			bool needSet = false;
			foreach (BuildingAreaEffectProgress effect in effects.Items)
			{
				if (effect.Type != 2)
				{
					continue;
				}
				needRemoveLocations.Clear();
				needRemoveLocations.AddRange(effect.CurrentActiveLocations.Where(ContainsAnyResourceDisaster));
				if (needRemoveLocations == null || needRemoveLocations.Count <= 0)
				{
					continue;
				}
				needSet = true;
				foreach (Location location in needRemoveLocations)
				{
					effect.RemoveLocation(location);
				}
			}
			if (needSet)
			{
				changedLocations.Add(effectLocation);
			}
		}
		foreach (Location location2 in changedLocations)
		{
			SetElement_BuildingAreaEffectProgresses(location2, _buildingAreaEffectProgresses[location2], context);
		}
	}

	private static bool ContainsAnyResourceDisaster(Location location)
	{
		foreach (IAdventureRuntime runtime in DomainManager.Adventure.QueryAnyInLocation(location))
		{
			if (ResourceDisasterHelper.IsDisasterAdventure(runtime.CoreId))
			{
				return false;
			}
		}
		return true;
	}

	public void InitializeOwnedItems()
	{
		foreach (JiaoPool jiaoPool in _jiaoPools)
		{
			foreach (int jiaoId in jiaoPool.Jiaos)
			{
				ItemKey itemKey = GetJiaoById(jiaoId).Key;
				DomainManager.Item.SetOwner(itemKey, ItemOwnerType.Building, 44);
			}
		}
		foreach (GameData.Domains.Character.Animal animal in _animals.Values)
		{
			if (animal.ItemKey != ItemKey.Invalid && animal.Location != Location.Invalid)
			{
				sbyte itemType = animal.ItemKey.ItemType;
				sbyte b = itemType;
				if ((uint)(b - 4) <= 1u)
				{
					DomainManager.Item.SetOwner(animal.ItemKey, ItemOwnerType.FleeCarrier, animal.Location.AreaId);
				}
			}
		}
		int keptBook = GetThreeCorpsesOwnedLegendaryBookTypes();
		for (sbyte i = 0; i < 14; i++)
		{
			if ((keptBook & (1 << (int)i)) != 0)
			{
				ItemKey bookItemKey = DomainManager.LegendaryBook.GetLegendaryBookItem(i);
				DomainManager.Item.SetOwner(bookItemKey, ItemOwnerType.System, 11);
			}
		}
		if (!_isDreamBack)
		{
			return;
		}
		Dictionary<int, ItemKey> unpackedItems = _unhandledCrossArchiveGameData.UnpackedItems;
		if (unpackedItems == null || unpackedItems.Count <= 0 || IsDreamBackStateUnlocked(1))
		{
			return;
		}
		foreach (ItemKey unpackedKey in _unhandledCrossArchiveGameData.UnpackedItems.Values)
		{
			if (ItemTemplateHelper.GetItemSubType(unpackedKey.ItemType, unpackedKey.TemplateId) == 1202 && DomainManager.Item.ItemExists(unpackedKey))
			{
				ItemBase item = DomainManager.Item.GetBaseItem(unpackedKey);
				if (item.Owner.OwnerType == ItemOwnerType.None)
				{
					item.SetOwner(ItemOwnerType.System, 19);
				}
			}
		}
	}

	private void OnInitializedDomainData()
	{
		DataContext context = DataContextManager.GetCurrentThreadDataContext();
		SetEmptyToolKey(ItemKey.Invalid, context);
	}

	private void InitializeOnInitializeGameDataModule()
	{
		for (sbyte cmdType = 0; cmdType < TeammateCommand.Instance.Count; cmdType++)
		{
			TeammateCommandItem cmdConfig = TeammateCommand.Instance[cmdType];
			if (cmdConfig.MedalType >= 0 && cmdConfig.Type == ETeammateCommandType.Normal)
			{
				TeammateCommandNormal.Add(cmdType);
			}
		}
		foreach (sbyte cmdType2 in TeammateCommandNormal)
		{
			ETeammateCommandImplement implement = TeammateCommand.Instance[cmdType2].Implement;
			sbyte cmdTypeAdvance = TeammateCommand.Instance.First(IsAdvance).TemplateId;
			TeammateCommandAdvanceMapping[cmdType2] = cmdTypeAdvance;
			TeammateCommandAdvanceMapping[cmdTypeAdvance] = cmdType2;
			bool IsAdvance(TeammateCommandItem config)
			{
				return config.Type == ETeammateCommandType.Advance && config.Implement == implement;
			}
		}
	}

	private void InitializeOnEnterNewWorld()
	{
		DataContext context = DataContextManager.GetCurrentThreadDataContext();
		_travelingEventsCommittedOffset = 0;
