	private void InitializeDreamBackRelatedCharacters()
	{
		if (!_isDreamBack)
		{
			return;
		}
		_dreamBackRelatedCharacters = new RelatedCharacters();
		int key;
		AbridgedCharacter value;
		foreach (KeyValuePair<int, AbridgedCharacter> abridgedDreamBackCharacter in _abridgedDreamBackCharacters)
		{
			abridgedDreamBackCharacter.Deconstruct(out key, out value);
			int charId = key;
			AbridgedCharacter abridgedChar = value;
			ushort relationTypes = abridgedChar.TaiwuRelationToSelf;
			if (relationTypes == 0 || relationTypes == ushort.MaxValue)
			{
				_dreamBackRelatedCharacters.General.Add(charId);
				continue;
			}
			for (int i = 0; i < 17; i++)
			{
				ushort currType = (ushort)(1 << i);
				if ((relationTypes & currType) != 0)
				{
					_dreamBackRelatedCharacters.Add(charId, currType);
				}
			}
		}
		_dreamBackRelatedCharsForRelations = new RelatedCharactersForRelations(_dreamBackRelatedCharacters);
		foreach (KeyValuePair<int, AbridgedCharacter> abridgedDreamBackCharacter2 in _abridgedDreamBackCharacters)
		{
			abridgedDreamBackCharacter2.Deconstruct(out key, out value);
			int charId2 = key;
			AbridgedCharacter abridgedChar2 = value;
			ushort reverseRelationTypes = abridgedChar2.SelfRelationToTaiwu;
			if (reverseRelationTypes != 0 && reverseRelationTypes != ushort.MaxValue)
			{
				if (RelationType.HasRelation(reverseRelationTypes, 16384))
				{
					_dreamBackRelatedCharsForRelations.RelatedAdored.Add(charId2);
				}
				if (RelationType.HasRelation(reverseRelationTypes, 32768))
				{
					_dreamBackRelatedCharsForRelations.RelatedEnemies.Add(charId2);
				}
			}
		}
	}

