	public (CharacterDisplayDataForRelations, bool) GetCharacterDisplayDataForDreamBackRelations(int charId)
	{
		AbridgedCharacter abridgedChar = ((charId == _dreamBackTaiwu.Id) ? _dreamBackTaiwu : _abridgedDreamBackCharacters.GetValueOrDefault(charId));
		if (abridgedChar == null)
		{
			return (null, false);
		}
		NameAndLifeRelatedData nameAndLifeRelatedData = default(NameAndLifeRelatedData);
		CharacterDomain.GetNameRelatedData(abridgedChar, ref nameAndLifeRelatedData.NameRelatedData);
		nameAndLifeRelatedData.LifeState = abridgedChar.AliveState;
		CharacterDisplayDataForRelations displayData = new CharacterDisplayDataForRelations
		{
			Main = DomainManager.Character.GetCharacterDisplayDataForGeneralScrollList(abridgedChar),
			Location = abridgedChar.Location,
			DeathDate = -1
		};
		ushort relationType = GetDreamBackRelationTypeWithTaiwu(charId).Item1;
		displayData.RelationType = relationType;
		return (displayData, true);
	}

	public (ushort, ushort) GetDreamBackRelationTypeWithTaiwu(int charId)
	{
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		if (taiwuCharId != _overwrittenTaiwu.Id)
		{
			return (0, 0);
		}
		if (!_abridgedDreamBackCharacters.TryGetValue(charId, out var abridgedCharacter))
		{
			return (0, 0);
		}
		return (abridgedCharacter.SelfRelationToTaiwu, abridgedCharacter.TaiwuRelationToSelf);
	}

	public int GetAreaPastLifeRelationCount(short areaId)
	{
		if (!GetIsDreamBack())
		{
			return 0;
		}
		Span<MapBlockData> blocks = DomainManager.Map.GetAreaBlocks(areaId);
		int count = 0;
		Span<MapBlockData> span = blocks;
		for (int i = 0; i < span.Length; i++)
		{
			MapBlockData block = span[i];
			if (block.CharacterSet == null)
			{
				continue;
			}
			foreach (int charId in block.CharacterSet)
			{
				(ushort, ushort) categorySelfToTarget = GetDreamBackRelationTypeWithTaiwu(charId);
				if (TryGetDreamBackLifeRecordByRelatedCharId(charId, out var _))
				{
					count++;
				}
				else if (categorySelfToTarget.Item1 != 0 && categorySelfToTarget.Item2 != 0)
				{
					count++;
				}
			}
		}
		return count;
	}

	[DomainMethod]
	public List<NameAndLifeRelatedData> GetNameAndLifeRelatedDataListForDreamBack(List<int> charIds)
	{
		List<NameAndLifeRelatedData> collection = new List<NameAndLifeRelatedData>();
		int i = 0;
		for (int count = charIds.Count; i < count; i++)
		{
			int charId = charIds[i];
			NameAndLifeRelatedData nameAndLifeRelatedData = default(NameAndLifeRelatedData);
			if (_abridgedDreamBackCharacters.TryGetValue(charId, out var abridgedChar))
			{
				CharacterDomain.GetNameRelatedData(abridgedChar, ref nameAndLifeRelatedData.NameRelatedData);
				nameAndLifeRelatedData.LifeState = abridgedChar.AliveState;
			}
			else if (charId == _dreamBackTaiwu.Id)
			{
				CharacterDomain.GetNameRelatedData(_dreamBackTaiwu, ref nameAndLifeRelatedData.NameRelatedData);
				nameAndLifeRelatedData.LifeState = _dreamBackTaiwu.AliveState;
			}
			else
			{
				nameAndLifeRelatedData.NameRelatedData.CharTemplateId = -1;
				nameAndLifeRelatedData.LifeState = 2;
			}
			collection.Add(nameAndLifeRelatedData);
		}
		return collection;
	}

