	}

	public List<GameData.Domains.Character.Character> ReleaseAllKilledByLongYufuCharacters(DataContext context, int ensureCount = 0)
	{
		int offset = 0;
		List<GameData.Domains.Character.Character> characters = new List<GameData.Domains.Character.Character>();
		Location location = DomainManager.Taiwu.GetTaiwu().GetValidLocation();
		while (_killedByYufuCharactersBinary.Size > offset)
		{
			GameData.Domains.Character.Character character = DomainManager.Character.UnpackCharacter(context, _killedByYufuCharactersBinary, ref offset, connectWithSrc: false);
			characters.Add(character);
			character.AddNoMindGuyFeature(context, resetAge: true);
			Location oldLoc = character.GetLocation();
			if (oldLoc != location)
			{
				character.SetLocation(location, context);
				Events.RaiseCharacterLocationChanged(context, character.GetId(), oldLoc, location);
			}
		}
		List<short> nearbyBlockIds = new List<short>();
		DomainManager.Map.GetSettlementBlocksAndAffiliatedBlocks(location.AreaId, location.BlockId, nearbyBlockIds);
		while (characters.Count < ensureCount)
		{
			int num = context.Random.Next(1, 16);
			if (1 == 0)
			{
			}
			short num2 = num switch
			{
				0 => 119, 
				1 => 120, 
				2 => 121, 
				3 => 122, 
				4 => 123, 
				5 => 124, 
				6 => 125, 
				7 => 126, 
				8 => 127, 
				9 => 128, 
				10 => 129, 
				11 => 130, 
				12 => 131, 
				13 => 132, 
				14 => 133, 
				_ => 119, 
			};
			if (1 == 0)
			{
			}
			short org = num2;
			GameData.Domains.Character.Character victim = DomainManager.Character.CreateTemporaryIntelligentCharacter(context, org, location);
			characters.Add(victim);
			victim.AddNoMindGuyFeature(context, resetAge: false);
			victim.SetOrganizationInfo(new OrganizationInfo(16, 0, principal: true, -1), context);
			DomainManager.Character.ConvertTemporaryIntelligentCharacter(context, victim);
			victim.SetOrganizationInfo(new OrganizationInfo(16, 0, principal: true, DomainManager.Taiwu.GetTaiwuVillageSettlementId()), context);
			Location oldLoc2 = victim.GetLocation();
			if (oldLoc2 != location)
			{
				victim.SetLocation(location, context);
				Events.RaiseCharacterLocationChanged(context, victim.GetId(), oldLoc2, location);
			}
		}
		return characters;
	}

