	public bool TryGetConflictCombatSkillEffect(short templateId, out CombatSkillEffectBase effect)
	{
		foreach (var (id, effectWrapper) in _conflictEffectWrappers)
		{
			if (effectWrapper.Effect is CombatSkillEffectBase combatSkillEffectBase && combatSkillEffectBase.SkillTemplateId == templateId)
			{
				effect = combatSkillEffectBase;
				return true;
			}
		}
		effect = null;
		return false;
