	[DomainMethod]
	public void ApplyConflictCombatSkillResult(DataContext context, short templateId, bool overwrite)
	{
		if (_conflictCombatSkills.TryGetValue(templateId, out var conflict))
		{
			if (overwrite)
			{
				int charId = DomainManager.Taiwu.GetTaiwuCharId();
				CombatSkillKey combatSkillKey = new CombatSkillKey(charId, templateId);
				GameData.Domains.CombatSkill.CombatSkill combatSkill = DomainManager.CombatSkill.GetElement_CombatSkills(combatSkillKey);
				ushort selectedPages = conflict.BreakPlate.SelectedPages;
				combatSkill.SetActivationState(selectedPages, context);
				combatSkill.SetBreakoutStepsCount(conflict.BreakStepCount, context);
				combatSkill.SetForcedBreakoutStepsCount(conflict.ForcedBreakStepCount, context);
				DomainManager.Taiwu.OverwriteBreakPlateWithConflictCombatSkill(context, conflict);
				DomainManager.SpecialEffect.OverwriteSpecialEffectWithConflictCombatSkill(context, conflict);
			}
			RemoveElement_ConflictCombatSkills(templateId, context);
		}
	}

