		crossArchiveGameData.ClearedSkillPlateStepInfo = null;
		if (crossArchiveGameData.CombatSkills != null)
		{
			foreach (GameData.Domains.CombatSkill.CombatSkill combatSkill in crossArchiveGameData.CombatSkills)
			{
				short skillId = combatSkill.GetId().SkillTemplateId;
				GameData.Domains.Taiwu.SkillBreakPlate plate = crossArchiveGameData.CombatSkillBreakPlates?.GetOrDefault(skillId);
				CombatSkillBreakPreset preset = crossArchiveGameData.CombatSkillBreakPresets?.GetOrDefault(skillId);
				if (plate != null || preset != null)
				{
					ConflictCombatSkill conflictingCombatSkill = new ConflictCombatSkill
					{
						TemplateId = skillId,
						BreakStepCount = combatSkill.GetBreakoutStepsCount(),
						ForcedBreakStepCount = combatSkill.GetForcedBreakoutStepsCount(),
						BreakPlate = plate,
						BreakPreset = preset
					};
					AddElement_ConflictCombatSkills(skillId, conflictingCombatSkill, context);
				}
			}
		}
		if (crossArchiveGameData.TaiwuCombatSkillProficiencies != null)
		{
			int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
			foreach (KeyValuePair<short, int> taiwuCombatSkillProficiency in crossArchiveGameData.TaiwuCombatSkillProficiencies)
			{
				taiwuCombatSkillProficiency.Deconstruct(out var key, out var value);
				short skillId2 = key;
				int proficiency = value;
				CombatSkillKey key2 = new CombatSkillKey(taiwuCharId, skillId2);
				int existProficiency;
				bool exist = _combatSkillProficiencies.TryGetValue(key2, out existProficiency);
				if (!exist || existProficiency < proficiency)
				{
					if (exist)
					{
						SetElement_CombatSkillProficiencies(key2, proficiency, context);
					}
					else
					{
						AddElement_CombatSkillProficiencies(key2, proficiency, context);
					}
				}
			}
		}
		crossArchiveGameData.CombatSkills = null;
		if (overwriteEquipment)
		{
			int taiwuCharId2 = DomainManager.Taiwu.GetTaiwuCharId();
			for (int i = 0; i < _masteredCombatSkillPlans.Length; i++)
			{
				SetElement_MasteredCombatSkillPlans(i, crossArchiveGameData.MasteredCombatSkillPlans[i], context);
			}
			SetCharacterMasteredCombatSkills(context, taiwuCharId2, crossArchiveGameData.CurrMasteredCombatSkillPlan);
			byte count = crossArchiveGameData.UnlockedCombatSkillPlanCount;
			if (count == 0)
			{
				count = 9;
			}
			SetUnlockedCombatSkillPlanCount(count, context);
			SetTaiwuMaxNeiliAllocation(crossArchiveGameData.TaiwuMaxNeiliAllocation, context);
			DomainManager.Taiwu.UpdateTaiwuNeiliAllocation(context);
		}
		crossArchiveGameData.MasteredCombatSkillPlans = null;
		crossArchiveGameData.CurrMasteredCombatSkillPlan.Items = null;
	}

	private void InitializeDejaVuEventCharacters(DataContext context)
	{
		CharacterSet characterSet = DomainManager.Extra.GetDejaVuEventCharacters();
		foreach (int charId in DomainManager.Taiwu.GetGroupCharIds().GetCollection())
		{
			characterSet.Add(charId);
		}
		if (DomainManager.Character.TryGetKidnappedCharacters(DomainManager.Taiwu.GetTaiwuCharId(), out var list))
		{
			foreach (KidnappedCharacter victim in list.GetCollection())
			{
				characterSet.Add(victim.CharId);
			}
		}
		DomainManager.Extra.SetDejaVuEventCharacters(characterSet, context);
	}

