	{
		Location location = DomainManager.Taiwu.GetTaiwu().GetLocation();
		if (!location.IsValid())
		{
			location = DomainManager.Taiwu.GetTaiwu().GetValidLocation();
		}
		if (isJiaoLoong)
		{
			short templateId = (short)context.Random.Next(0, 39);
			GameData.DLC.FiveLoong.Jiao jiao;
			if (templateId >= 31)
