				if (_childrenOfLoong.TryGetValue(GmCmd_AddChildOfLoong(context, templateId), out var loong))
				{
					SetFleeCarrierLocation(context, loong.Key, location);
				}
			}
			else if (_jiaos.TryGetValue(GmCmd_AddJiao(context, templateId, 0, 2, isMale: false, isMaxTamePoint: false, isMaxProperty: false), out jiao))
			{
				SetFleeCarrierLocation(context, jiao.Key, location);
			}
		}
		else
		{
			ItemKey item = DomainManager.Item.CreateItem(context, 4, (short)context.Random.Next(27, 45));
			SetFleeCarrierLocation(context, item, location);
		}
	}

