	[DomainMethod]
	public string GmCmd_CastTasterUltimateOnCurrentBlock(DataContext context, bool isCombatSkill)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location location = taiwu.GetLocation();
		if (!location.IsValid())
		{
			return null;
		}
		MapBlockData belongSettlementBlock = DomainManager.Map.GetBelongSettlementBlock(location);
		if (belongSettlementBlock == null)
		{
			return null;
		}
		Inventory inventory = taiwu.GetInventory();
		List<int> bookIds = new List<int>();
		foreach (ItemKey itemKey in inventory.Items.Keys)
		{
			if (itemKey.ItemType != 10 || ((!isCombatSkill || Config.SkillBook.Instance[itemKey.TemplateId].ItemSubType != 1001) && (isCombatSkill || Config.SkillBook.Instance[itemKey.TemplateId].ItemSubType != 1000)))
			{
				continue;
			}
			sbyte progress = DomainManager.Taiwu.GetTotalReadingProgress(itemKey.Id);
			if (progress < 100)
			{
				bookIds.Add(itemKey.Id);
				if (bookIds.Count >= 8)
				{
					break;
				}
			}
		}
		if (bookIds.Count == 0)
		{
			return null;
		}
		List<int> charIds = new List<int> { taiwu.GetId() };
		List<short> blockIds = ObjectPool<List<short>>.Instance.Get();
		DomainManager.Map.GetSettlementBlocksAndAffiliatedBlocks(belongSettlementBlock.AreaId, belongSettlementBlock.BlockId, blockIds);
		foreach (short blockId in blockIds)
		{
			MapBlockData block = DomainManager.Map.GetBlock(location.AreaId, blockId);
			if (block.CharacterSet == null)
			{
				continue;
			}
			foreach (int charId in block.CharacterSet)
			{
				charIds.Add(charId);
			}
		}
		ObjectPool<List<short>>.Instance.Return(blockIds);
		StringBuilder sb = new StringBuilder();
		int attainment = 0;
		sb.AppendLine("book skill attainment:");
		foreach (int bookId in bookIds)
		{
			GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(bookId);
			if (isCombatSkill)
			{
				foreach (int charId2 in charIds)
				{
					attainment += DomainManager.Character.GetElement_Objects(charId2).GetCombatSkillAttainment(book.GetCombatSkillType());
				}
			}
			else
			{
				foreach (int charId3 in charIds)
				{
					attainment += DomainManager.Character.GetElement_Objects(charId3).GetLifeSkillAttainment(book.GetLifeSkillType());
				}
			}
			sb.AppendLine(isCombatSkill ? $"{Config.SkillBook.Instance[book.GetTemplateId()].Name} -> {Config.CombatSkillType.Instance[Config.SkillBook.Instance[book.GetTemplateId()].CombatSkillType].Name}:{attainment}" : $"{Config.SkillBook.Instance[book.GetTemplateId()].Name} -> {Config.LifeSkillType.Instance[Config.SkillBook.Instance[book.GetTemplateId()].LifeSkillType].Name}:{attainment}");
		}
		TasterUltimateResult result = CastTasterUltimateSkill(context, charIds, bookIds, isCombatSkill);
		sb.AppendLine("book read:");
		foreach (KeyValuePair<IntPair, byte> readBookPageDatum in result.ReadBookPageData)
		{
			readBookPageDatum.Deconstruct(out var key, out var value);
			IntPair pair = key;
			byte pageRead = value;
			StringBuilder stringBuilder = sb;
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(5, 2, stringBuilder);
			handler.AppendFormatted(DomainManager.Character.GetElement_Objects(pair.First));
			handler.AppendLiteral("'s ");
			handler.AppendFormatted(DomainManager.Item.GetElement_SkillBooks(pair.Second).GetName());
			handler.AppendLiteral(": ");
			stringBuilder2.Append(ref handler);
			for (int i = 0; i < 6; i++)
			{
				if ((pageRead & (1 << i)) != 0)
				{
					stringBuilder = sb;
					StringBuilder stringBuilder3 = stringBuilder;
					handler = new StringBuilder.AppendInterpolatedStringHandler(1, 1, stringBuilder);
					handler.AppendFormatted(i);
					handler.AppendLiteral("、");
					stringBuilder3.Append(ref handler);
				}
			}
			sb.AppendLine();
		}
		sb.AppendLine("practice level:");
		return sb.ToString();
	}

