		{
			return (0, 0, 0);
		}
		int animal = 0;
		int cricket = 0;
		int adventure = 0;
		foreach (BuildingAreaEffectProgress effect in list.Items)
		{
			switch (effect.BuildingScaleEffect)
			{
			case EBuildingScaleEffect.AnimalProgressDelta:
				animal = effect.Progress;
				break;
			case EBuildingScaleEffect.CricketProgressDelta:
				cricket = effect.Progress;
				break;
			case EBuildingScaleEffect.AdventureProgressDelta:
				adventure = effect.Progress;
				break;
			}
		}
		return (animal, cricket, adventure);
	}

