	[DomainMethod]
	public void AddTaiwuOneWayRelationCoolDown(DataContext context, int charId, bool isAdoreRelation)
	{
		int date = DomainManager.World.GetCurrDate() + 3;
		if (_taiwuAddOneWayRelationCoolDown.TryGetValue(charId, out var coolDown))
		{
			SetElement_TaiwuAddOneWayRelationCoolDown(charId, isAdoreRelation ? new IntPair(date, coolDown.Second) : new IntPair(coolDown.First, date), context);
		}
		else
		{
			AddElement_TaiwuAddOneWayRelationCoolDown(charId, isAdoreRelation ? new IntPair(date, 0) : new IntPair(0, date), context);
		}
	}

	[DomainMethod]
	public int GetTaiwuAddOneWayRelationResultCode(int charId)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			return int.MaxValue;
		}
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		int code = 0;
		if (TryGetElement_TaiwuAddOneWayRelationCoolDown(charId, out var coolDown))
		{
			int currDate = DomainManager.World.GetCurrDate();
			if (currDate < coolDown.First)
			{
				code = 2 | code;
			}
			if (currDate < coolDown.Second)
			{
				code = 4 | code;
			}
		}
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		(ushort, ushort) relationTuple = DomainManager.Character.GetRelationBetweenCharacters(taiwuCharId, charId);
		if (relationTuple.Item1 != ushort.MaxValue && RelationType.HasRelation(relationTuple.Item1, 16384))
		{
			code |= 8;
		}
		if (relationTuple.Item1 != ushort.MaxValue && RelationType.HasRelation(relationTuple.Item1, 32768))
		{
			code |= 0x10;
		}
		if (relationTuple.Item2 != ushort.MaxValue && RelationType.HasRelation(relationTuple.Item2, 16384))
		{
			code |= 0x40;
		}
		if (relationTuple.Item1 == ushort.MaxValue || !RelationType.HasRelation(relationTuple.Item1, 8192))
		{
			code |= 0x400;
		}
		if (relationTuple.Item1 == ushort.MaxValue)
		{
			code |= 0x8000;
		}
		if (!DomainManager.Taiwu.IsNormalInteractionUnlocked())
		{
			code |= 0x20;
		}
		if (taiwuChar.GetAgeGroup() != 2 || AgeGroup.GetAgeGroup(taiwuChar.GetActualAge()) != 2)
		{
			code |= 0x80;
		}
		if (character.GetAgeGroup() != 2 || AgeGroup.GetAgeGroup(character.GetActualAge()) != 2)
		{
			code |= 0x100;
		}
		if (relationTuple.Item1 != ushort.MaxValue && (RelationType.ContainParentRelations(relationTuple.Item1) || RelationType.ContainChildRelations(relationTuple.Item1) || RelationType.ContainBrotherOrSisterRelations(relationTuple.Item1)))
		{
			code |= 0x200;
		}
		List<short> taiwuFeatureIds = taiwuChar.GetFeatureIds();
		if (taiwuFeatureIds.Contains(740))
		{
			code |= 0x800;
		}
		if (taiwuFeatureIds.Contains(741))
		{
			code |= 0x1000;
		}
		List<short> charFeatureIds = character.GetFeatureIds();
		if (charFeatureIds.Contains(740))
		{
			code |= 0x2000;
		}
		if (charFeatureIds.Contains(741))
		{
			code |= 0x4000;
		}
		return code;
	}

	[DomainMethod]
	public bool IsTaiwuAbleToAddOneWayRelation(int charId, bool isAdoreRelation)
	{
		if (TryGetElement_TaiwuAddOneWayRelationCoolDown(charId, out var coolDown))
		{
			return DomainManager.World.GetCurrDate() >= (isAdoreRelation ? coolDown.First : coolDown.Second);
		}
		return true;
	}

	[DomainMethod]
	public int GetTaiwuAddOneWayRelationCoolDown(int charId, bool isAdoreRelation)
	{
		IntPair coolDown;
		return TryGetElement_TaiwuAddOneWayRelationCoolDown(charId, out coolDown) ? Math.Max(0, (isAdoreRelation ? coolDown.First : coolDown.Second) - DomainManager.World.GetCurrDate()) : 0;
	}

