	public bool TryGetAnimalIdsByLocation(Location location, out List<int> animals)
	{
		animals = null;
		Dictionary<short, List<int>> animalAreaData;
		return LocationAnimalMap.TryGetValue(location.AreaId, out animalAreaData) && animalAreaData.TryGetValue(location.BlockId, out animals);
	}

	public bool TryGetAnimalsByLocation(Location location, out List<GameData.Domains.Character.Animal> animals)
	{
		animals = new List<GameData.Domains.Character.Animal>();
		if (!TryGetAnimalIdsByLocation(location, out var animalIds))
		{
			return false;
		}
		foreach (int animalId in animalIds)
		{
			if (TryGetAnimal(animalId, out var animal))
			{
				animals.Add(animal);
			}
		}
		return true;
	}

	public bool TryGetAnimalAreaDataByAreaId(short areaId, out Dictionary<short, List<int>> animalAreaData)
