	public bool TryGetAnimalAttackInRange(Location location, int range, bool isTaiwuVictim, out HashSet<(Location, int)> result)
	{
		result = null;
		if (location.Equals(Location.Invalid))
		{
			return false;
		}
		if (!TryGetAnimalAreaDataByAreaId(location.AreaId, out var animalAreaData))
		{
			return false;
		}
		result = new HashSet<(Location, int)>();
		short key;
		List<int> value;
		if (range == -1)
		{
			foreach (KeyValuePair<short, List<int>> item in animalAreaData)
			{
				item.Deconstruct(out key, out value);
				short blockId = key;
				List<int> animalIds = value;
				foreach (int animalId in animalIds)
				{
					if (TryGetAnimal(animalId, out var animal) && IsAnimalAbleToAttack(animal, isTaiwuVictim))
					{
						result.Add((new Location(location.AreaId, blockId), animalId));
					}
				}
			}
		}
		else
		{
			ByteCoordinate pos = DomainManager.Map.GetBlockData(location.AreaId, location.BlockId).GetBlockPos();
			foreach (KeyValuePair<short, List<int>> item2 in animalAreaData)
			{
				item2.Deconstruct(out key, out value);
				short blockId2 = key;
				List<int> animalIds2 = value;
				MapBlockData block = DomainManager.Map.GetBlockData(location.AreaId, blockId2);
				if (!block.IsPassable() || block.GetManhattanDistanceToPos(pos.X, pos.Y) > range)
				{
					continue;
				}
				foreach (int animalId2 in animalIds2)
				{
					if (TryGetAnimal(animalId2, out var animal2) && IsAnimalAbleToAttack(animal2, isTaiwuVictim))
					{
						result.Add((new Location(location.AreaId, blockId2), animalId2));
					}
				}
			}
		}
		return result.Count > 0;
	}

