	public void GetAnimalGenerateLocationListByCenterLocation(DataContext context, Location centerLocation, int count, ref List<Location> locations)
	{
		locations.Clear();
		int taiwuBlockId = DomainManager.Taiwu.GetTaiwu()?.GetLocation().BlockId ?? (-1);
		List<MapBlockData> pool = ObjectPool<List<MapBlockData>>.Instance.Get();
		pool.Clear();
		Span<MapBlockData> areaBlocks = DomainManager.Map.GetAreaBlocks(centerLocation.AreaId);
		for (int i = 0; i < areaBlocks.Length; i++)
		{
			MapBlockData block = areaBlocks[i];
			if (BlockCanGeneratingAnimal(block, isTaiwuSkill: true, (short)taiwuBlockId) && block.TemplateId != centerLocation.BlockId)
			{
				pool.Add(block);
			}
		}
		ByteCoordinate centerBlockPos = DomainManager.Map.GetBlock(centerLocation).GetBlockPos();
		MapBlockData[] blockList = pool.OrderBy((MapBlockData mapBlockData) => mapBlockData.GetManhattanDistanceToPos(centerBlockPos.X, centerBlockPos.Y)).ToArray();
		for (int i2 = 0; i2 < count && i2 < blockList.Length; i2++)
		{
			locations.Add(blockList[i2].GetLocation());
		}
		ObjectPool<List<MapBlockData>>.Instance.Return(pool);
	}

