	public void CheckAnimalAttackTaiwuOnAdvanceMonth(IRandomSource randomSource)
	{
		Location location = DomainManager.Taiwu.GetTaiwu().GetLocation();
		if (!location.IsValid() || !DomainManager.Extra.TryGetAnimalIdsByLocation(location, out var animalIds) || animalIds.Count == 0)
		{
			return;
		}
		short templateId = -1;
		int maxConsummateLevel = -1;
		foreach (int animalId in animalIds)
		{
			if (TryGetAnimal(animalId, out var animal) && IsAnimalAbleToAttack(animal, isTaiwuVictim: true))
			{
				sbyte consummateLevel = Config.Character.Instance[animal.CharacterTemplateId].ConsummateLevel;
				if (consummateLevel > maxConsummateLevel || (consummateLevel == maxConsummateLevel && randomSource.NextBool()))
				{
					maxConsummateLevel = consummateLevel;
					templateId = animal.CharacterTemplateId;
				}
			}
		}
		if (templateId >= 0)
		{
			DomainManager.World.GetMonthlyEventCollection().AddRandomAnimalAttack(location, templateId);
		}
	}

	public void UpdateAnimalAreaData(DataContext context)
	{
		List<int> pool = ObjectPool<List<int>>.Instance.Get();
		for (short areaId = 0; areaId < 141; areaId++)
		{
			if (!DomainManager.Map.IsAreaBroken(areaId))
			{
				int count = 0;
				if (TryGetAnimalAreaDataByAreaId(areaId, out var animalAreaData))
				{
					pool.Clear();
					foreach (List<int> animalIds in animalAreaData.Values)
					{
						foreach (int animalId in animalIds)
						{
							if (TryGetAnimal(animalId, out var animal) && IsAnimalAbleToAttack(animal, isTaiwuVictim: false))
							{
								pool.Add(animalId);
							}
						}
					}
					count = pool.Count;
				}
				short blockId;
				if (count >= 12)
				{
					ApplyAnimalDeadByAccident(context, pool.GetRandom(context.Random));
				}
				else if (TryGetRandomBlockForGeneratingAnimal(context, areaId, isTaiwuSkill: false, out blockId))
				{
					CreateAnimalByCharacterTemplateId(context, GetRandomAnimalForGeneratingAnimal(context), new Location(areaId, blockId));
				}
			}
		}
		ObjectPool<List<int>>.Instance.Return(pool);
	}

	private void InitializeAnimals(bool isResetting)
	{
		if (isResetting)
		{
			_nextAnimalId = 0;
		}
		foreach (GameData.Domains.Character.Animal animal in _animals.Values)
		{
			UpdateLocationAnimalMap(animal);
			if (animal.ItemKey != ItemKey.Invalid)
			{
				ItemKeyAnimalMap[animal.ItemKey] = animal.Id;
			}
			if (animal.Location != Location.Invalid && animal.ItemKey != ItemKey.Invalid)
			{
				GameData.Domains.Item.Material material;
				GameData.Domains.Item.Medicine medicine;
				if (DomainManager.Item.TryGetElement_Carriers(animal.ItemKey.Id, out var carrier))
				{
					carrier.SetOwner(ItemOwnerType.FleeCarrier, animal.Location.AreaId);
				}
				else if (DomainManager.Item.TryGetElement_Materials(animal.ItemKey.Id, out material))
				{
					material.SetOwner(ItemOwnerType.FleeCarrier, animal.Location.AreaId);
				}
				else if (DomainManager.Item.TryGetElement_Medicines(animal.ItemKey.Id, out medicine))
				{
					medicine.SetOwner(ItemOwnerType.FleeCarrier, animal.Location.AreaId);
				}
			}
		}
	}

	private void UpdateLocationAnimalMap(GameData.Domains.Character.Animal animal)
	{
		if (!LocationAnimalMap.ContainsKey(animal.Location.AreaId))
		{
			LocationAnimalMap[animal.Location.AreaId] = new Dictionary<short, List<int>>();
		}
		if (!LocationAnimalMap[animal.Location.AreaId].ContainsKey(animal.Location.BlockId))
		{
			LocationAnimalMap[animal.Location.AreaId][animal.Location.BlockId] = new List<int>();
		}
		LocationAnimalMap[animal.Location.AreaId][animal.Location.BlockId].Add(animal.Id);
	}

	private int GenerateNextObjectId(DataContext context)
	{
		int objectId = _nextAnimalId;
		_nextAnimalId++;
		if ((uint)_nextAnimalId > 2147483647u)
		{
			_nextAnimalId = 0;
		}
		SetNextAnimalId(_nextAnimalId, context);
		return objectId;
	}

	private bool TryGetRandomBlockForGeneratingAnimal(DataContext context, short areaId, bool isTaiwuSkill, out short blockId)
	{
		blockId = -1;
		if (areaId < 0)
		{
			return false;
		}
		if (DomainManager.Map.IsAreaBroken(areaId))
		{
			return false;
		}
		int taiwuBlockId = DomainManager.Taiwu.GetTaiwu()?.GetLocation().BlockId ?? (-1);
		List<short> pool = ObjectPool<List<short>>.Instance.Get();
		pool.Clear();
		Span<MapBlockData> areaBlocks = DomainManager.Map.GetAreaBlocks(areaId);
		for (int i = 0; i < areaBlocks.Length; i++)
		{
			MapBlockData block = areaBlocks[i];
			if (BlockCanGeneratingAnimal(block, isTaiwuSkill, (short)taiwuBlockId))
			{
				pool.Add(block.BlockId);
			}
		}
		if (pool.Count > 0)
		{
			blockId = pool.GetRandom(context.Random);
		}
		ObjectPool<List<short>>.Instance.Return(pool);
		return blockId >= 0;
	}

	private bool BlockCanGeneratingAnimal(MapBlockData block, bool isTaiwuSkill, short taiwuBlockId)
	{
		return block.IsPassable() && block.GetConfig().Type == EMapBlockType.Wild && (!isTaiwuSkill || (block.BlockId != taiwuBlockId && block.Visible));
	}

	private short GetRandomAnimalForGeneratingAnimal(DataContext context)
	{
		return AnimalCharIdGroups.GetRandom(context.Random)[0];
	}

	[DomainMethod]
	public List<short> GetArtisanOrderCanProduceItemSubType(ArtisanOrder order)
	{
		List<short> res = new List<short> { -1 };
		if (order == null || order.ArtisanId < 0)
		{
			return res;
		}
		if (!DomainManager.Character.TryGetElement_Objects(order.ArtisanId, out var _))
		{
			return res;
		}
		sbyte lifeSkillType = order.LifeSkillType;
		if (lifeSkillType < 0)
		{
			return res;
		}
		sbyte b = lifeSkillType;
		sbyte b2 = b;
		if (b2 != 5 && b2 != 14)
		{
			foreach (MaterialItem materialConfig in (IEnumerable<MaterialItem>)Config.Material.Instance)
			{
				if (materialConfig.RequiredLifeSkillType != lifeSkillType || materialConfig.IsSpecial)
				{
					continue;
				}
				foreach (short makeItemType in materialConfig.CraftableItemTypes)
				{
					foreach (short makeItemSubType in MakeItemType.Instance[makeItemType].MakeItemSubTypes)
					{
						MakeItemResult result = MakeItemSubType.Instance[makeItemSubType].Result;
						short itemSubType = ItemTemplateHelper.GetItemSubType(result.ItemType, result.TemplateId);
						if (!res.Contains(itemSubType))
						{
							res.Add(itemSubType);
						}
					}
				}
			}
		}
		res.RemoveAll(delegate(short t)
		{
			if (t < 0)
			{
				return false;
			}
			MakeItemTypeItem makeItemTypeItem = MakeItemType.Instance.Where((MakeItemTypeItem m) => !string.IsNullOrEmpty(m.TypeBigIcon)).FirstOrDefault((MakeItemTypeItem m) => m.ItemSubType == t);
			return makeItemTypeItem == null;
		});
		return res;
	}

	[DomainMethod]
	public ProductionPool GetArtisanOrderMaterialPreview(ArtisanOrder order, List<ItemDisplayData> itemList)
	{
		if (itemList == null)
		{
			return null;
		}
		ProductionPool pool = GetArtisanOrderProductionPool(order);
		Dictionary<Production, int> weights = new Dictionary<Production, int>();
		AddMaterialWeightToProductions(order, itemList, weights);
		foreach (var (production2, weight) in weights)
		{
			if (pool.Productions.TryGetValue(production2, out var data))
			{
				data.Weight += weight;
				pool.Productions[production2] = data;
			}
			else
			{
				pool.Productions[production2] = new ProductionData(weight, canProduce: false);
			}
		}
		return pool;
	}

	[DomainMethod]
	public void AddMaterialToArtisanOrder(DataContext context, ArtisanOrder order, List<ItemDisplayData> itemList)
	{
		if (itemList == null)
		{
			return;
		}
		AddMaterialWeightToProductions(order, itemList, order.ProductionWeight);
		foreach (ItemDisplayData itemData in itemList)
		{
			DomainManager.Taiwu.RemoveItem(context, itemData.RealKey, itemData.Amount, itemData.ItemSourceType, deleteItem: true);
		}
		if (order.IsArtisanOrder())
		{
			SetNpcArtisanOrder(context, order);
		}
		else
		{
			SetBuildingArtisanOrder(context, order);
		}
	}

	[DomainMethod]
	public void AddResourceItemToArtisanOrder(DataContext context, ArtisanOrder order, List<ItemDisplayData> itemList)
	{
		if (itemList == null)
		{
			return;
		}
		int addProgress = itemList.Sum((ItemDisplayData itemDisplayData) => GameData.Domains.Building.SharedMethods.GetItemProductionProgress(itemDisplayData) * itemDisplayData.Amount);
		SetArtisanOrderProgress(context, order, order.Progress + addProgress);
		foreach (ItemDisplayData itemData in itemList)
		{
			if (itemData.IsResource)
			{
				DomainManager.Taiwu.GetTaiwu().ChangeResource(context, itemData.ResourceType, -itemData.Amount);
			}
			else
			{
				DomainManager.Taiwu.RemoveItem(context, itemData.RealKey, itemData.Amount, itemData.ItemSourceType, deleteItem: true);
			}
		}
	}

	[DomainMethod]
	public ProductionPool GetArtisanOrderProductionPool(ArtisanOrder order)
	{
		if (order == null || order.ArtisanId < 0)
		{
			return null;
		}
		if (!DomainManager.Character.TryGetElement_Objects(order.ArtisanId, out var artisan))
		{
			return null;
		}
		if (!order.IsArtisanOrder())
		{
			VillagerRoleBase villagerRole = DomainManager.Extra.GetVillagerRole(order.ArtisanId);
			if (villagerRole == null)
			{
				return null;
			}
			BuildingBlockData buildingBlockData = DomainManager.Building.GetBuildingBlockData(order.BuildingBlockKey);
			BuildingBlockItem buildingConfig = BuildingBlock.Instance[buildingBlockData.TemplateId];
			if (!Enumerable.Contains(buildingConfig.VillagerRoleTemplateIds, villagerRole.RoleTemplateId))
			{
				return null;
			}
		}
		ProductionPool res = new ProductionPool(GetCookingProductionAddOn(artisan));
		sbyte lifeSkillType = order.LifeSkillType;
		int attainment = artisan.GetLifeSkillAttainment(lifeSkillType);
		int attainmentEffect = 0;
		if (!order.IsArtisanOrder())
		{
			attainmentEffect = DomainManager.Building.GetBuildingEffectForMake(order.BuildingBlockKey, lifeSkillType).attainmentEffect;
		}
		int[] attainments = new int[3]
		{
			attainment,
			attainment * 100 / SharedConstValue.MakeItemStageAttainmentFactor[1],
			attainment * 100 / SharedConstValue.MakeItemStageAttainmentFactor[2]
		};
		int highestGrade = 0;
		switch (lifeSkillType)
		{
		case 14:
			foreach (MaterialItem materialConfig2 in (IEnumerable<MaterialItem>)Config.Material.Instance)
			{
				if (materialConfig2.RequiredLifeSkillType != lifeSkillType || materialConfig2.IsSpecial)
				{
					continue;
				}
				short requiredAttainment3 = materialConfig2.RequiredAttainment;
				requiredAttainment3 = GameData.Domains.Building.SharedMethods.GetRequiredLifeSkillAttainmentByBuildingEffect(requiredAttainment3, attainmentEffect);
				foreach (short makeItemType2 in materialConfig2.CraftableItemTypes)
				{
					foreach (short makeItemSubType2 in MakeItemType.Instance[makeItemType2].MakeItemSubTypes)
					{
						MakeItemResult result2 = MakeItemSubType.Instance[makeItemSubType2].Result;
						if (order.ItemSubType < 0 || ItemTemplateHelper.GetItemSubType(result2.ItemType, result2.TemplateId) == order.ItemSubType)
						{
							int addGrade3 = AddProductionToPool(res, res.CookAddOn, result2.ItemType, result2.TemplateId, materialConfig2.Grade, requiredAttainment3, attainments);
							highestGrade = Math.Max(highestGrade, addGrade3);
						}
					}
				}
			}
			break;
		case 5:
			foreach (TeaWineItem teaWineConfig in (IEnumerable<TeaWineItem>)Config.TeaWine.Instance)
			{
				if (teaWineConfig.ItemSubType == order.ItemSubType || (order.IsArtisanOrder() && order.ItemSubType < 0))
				{
					int requiredAttainment2 = SharedConstValue.TeaWineArtisanOrderAttainmentRequirement[teaWineConfig.Grade];
					requiredAttainment2 = GameData.Domains.Building.SharedMethods.GetRequiredLifeSkillAttainmentByBuildingEffect(requiredAttainment2, attainmentEffect);
					int addGrade2 = AddProductionToPool(res, 0, teaWineConfig.ItemType, teaWineConfig.TemplateId, teaWineConfig.Grade, requiredAttainment2, attainments);
					highestGrade = Math.Max(highestGrade, addGrade2);
				}
			}
			break;
		default:
			foreach (MaterialItem materialConfig in (IEnumerable<MaterialItem>)Config.Material.Instance)
			{
				if (materialConfig.RequiredLifeSkillType != lifeSkillType || materialConfig.IsSpecial)
				{
					continue;
				}
				for (int index = 0; index < materialConfig.CraftableItemTypes.Count; index++)
				{
					short makeItemType = materialConfig.CraftableItemTypes[index];
					bool flag = index == 0;
					bool flag2 = flag;
					if (flag2)
					{
						bool flag3 = (uint)(lifeSkillType - 8) <= 1u;
						flag2 = flag3;
					}
					short requiredAttainment = (flag2 ? GlobalConfig.Instance.MakeMadicineAttainments[materialConfig.Grade] : materialConfig.RequiredAttainment);
					requiredAttainment = GameData.Domains.Building.SharedMethods.GetRequiredLifeSkillAttainmentByBuildingEffect(requiredAttainment, attainmentEffect);
					foreach (short makeItemSubType in MakeItemType.Instance[makeItemType].MakeItemSubTypes)
					{
						MakeItemResult result = MakeItemSubType.Instance[makeItemSubType].Result;
						if (order.ItemSubType < 0 || ItemTemplateHelper.GetItemSubType(result.ItemType, result.TemplateId) == order.ItemSubType)
						{
							int addGrade = AddProductionToPool(res, 0, result.ItemType, result.TemplateId, materialConfig.Grade, requiredAttainment, attainments);
							highestGrade = Math.Max(highestGrade, addGrade);
						}
					}
				}
			}
			break;
		}
		int[] weightAdd = new int[9];
		for (int i = 0; i <= 2; i++)
		{
			int grade = highestGrade - i;
			if (grade < 0)
			{
				break;
			}
			weightAdd[grade] = SharedConstValue.InitialProductionWeight[i];
		}
		foreach (Production production in res.Productions.Keys)
		{
			sbyte grade2 = ItemTemplateHelper.GetGrade(production.ItemType, production.TemplateId);
			if (order.ProductionWeight.TryGetValue(production, out var weight))
			{
				res.Productions[production] = new ProductionData(weightAdd[grade2] + weight, res.Productions[production].CanProduce);
			}
			else
			{
				res.Productions[production] = new ProductionData(weightAdd[grade2], res.Productions[production].CanProduce);
			}
		}
		return res;
	}

