	private void FinishArtisanOrder(DataContext context, ArtisanOrder order)
	{
		ProductionPool pool = GetArtisanOrderProductionPool(order);
		int total = 0;
		Production key;
		ProductionData value;
		foreach (KeyValuePair<Production, ProductionData> production3 in pool.Productions)
		{
			production3.Deconstruct(out key, out value);
			Production production = key;
			ProductionData data = value;
			if (data.CanProduce)
			{
				total += data.Weight;
			}
		}
		int countDown = ((total != 0) ? context.Random.Next(total) : 0);
		int currDate = DomainManager.World.GetCurrDate();
		MonthlyNotificationCollection monthlyNotificationCollection = DomainManager.World.GetMonthlyNotificationCollection();
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		TaiwuVillageStoragesRecordCollection storageRecordCollection = DomainManager.Taiwu.GetTaiwuVillageStoragesRecordCollection();
		GameData.Domains.Character.Character artisan = DomainManager.Character.GetElement_Objects(order.ArtisanId);
		foreach (KeyValuePair<Production, ProductionData> production4 in pool.Productions)
		{
			production4.Deconstruct(out key, out value);
			Production production2 = key;
			ProductionData data2 = value;
			if (!data2.CanProduce || data2.Weight == 0)
			{
				continue;
			}
			countDown -= data2.Weight;
			if (countDown > 0)
			{
				continue;
			}
			ItemKey key2 = DomainManager.Item.CreateItem(context, production2.ItemType, production2.TemplateId);
			GameData.Domains.Character.Character subscriber;
			if (order.SubscriberId < 0 || order.SubscriberId == DomainManager.Taiwu.GetTaiwuCharId())
			{
				ItemSourceType storageType = (ItemSourceType)order.StorageType;
				if (storageType == ItemSourceType.Inventory && !DomainManager.Taiwu.GetTaiwu().IsOnRegularSettlement())
				{
					storageType = ItemSourceType.Warehouse;
				}
				short settlementId = DomainManager.Character.GetElement_Objects(order.ArtisanId).GetOrganizationInfo().SettlementId;
				DomainManager.Taiwu.AddItem(context, key2, 1, storageType);
				BuildingBlockData blockData;
				if (order.IsArtisanOrder())
				{
					switch (storageType)
					{
					case ItemSourceType.Inventory:
						monthlyNotificationCollection.AddNpcCraftFinished0(order.ArtisanId, settlementId, key2.ItemType, key2.TemplateId, DomainManager.Taiwu.GetTaiwuCharId());
						break;
					case ItemSourceType.Warehouse:
						monthlyNotificationCollection.AddNpcCraftFinished1(order.ArtisanId, settlementId, key2.ItemType, key2.TemplateId);
						storageRecordCollection.AddOutsiderMakeHarvest1(currDate, TaiwuVillageStorageType.Warehouse, order.ArtisanId, settlementId, production2.ItemType, production2.TemplateId);
						break;
					case ItemSourceType.Treasury:
						monthlyNotificationCollection.AddNpcCraftFinished2(order.ArtisanId, settlementId, key2.ItemType, key2.TemplateId);
						storageRecordCollection.AddOutsiderMakeHarvest(currDate, TaiwuVillageStorageType.Treasury, order.ArtisanId, settlementId, production2.ItemType, production2.TemplateId);
						break;
					case ItemSourceType.Stock:
						monthlyNotificationCollection.AddNpcCraftFinished3(order.ArtisanId, settlementId, key2.ItemType, key2.TemplateId);
						storageRecordCollection.AddOutsiderMakeHarvest2(currDate, TaiwuVillageStorageType.Stock, order.ArtisanId, settlementId, production2.ItemType, production2.TemplateId);
						break;
					case ItemSourceType.Trough:
						break;
					}
				}
				else if (DomainManager.Building.TryGetElement_BuildingBlocks(order.BuildingBlockKey, out blockData))
				{
					switch (storageType)
					{
					case ItemSourceType.Inventory:
						monthlyNotificationCollection.AddVillagerCraftFinished0(blockData.TemplateId, key2.ItemType, key2.TemplateId, DomainManager.Taiwu.GetTaiwuCharId());
						break;
					case ItemSourceType.Warehouse:
						monthlyNotificationCollection.AddVillagerCraftFinished1(blockData.TemplateId, key2.ItemType, key2.TemplateId);
						storageRecordCollection.AddVillagerMakeHarvest1(currDate, TaiwuVillageStorageType.Warehouse, blockData.TemplateId, production2.ItemType, production2.TemplateId);
						break;
					case ItemSourceType.Treasury:
						monthlyNotificationCollection.AddVillagerCraftFinished2(blockData.TemplateId, key2.ItemType, key2.TemplateId);
						storageRecordCollection.AddVillagerMakeHarvest(currDate, TaiwuVillageStorageType.Treasury, blockData.TemplateId, production2.ItemType, production2.TemplateId);
						break;
					case ItemSourceType.Stock:
						monthlyNotificationCollection.AddVillagerCraftFinished3(blockData.TemplateId, key2.ItemType, key2.TemplateId);
						storageRecordCollection.AddVillagerMakeHarvest2(currDate, TaiwuVillageStorageType.Stock, blockData.TemplateId, production2.ItemType, production2.TemplateId);
						break;
					case ItemSourceType.Trough:
						break;
					}
				}
			}
			else if (DomainManager.Character.TryGetElement_Objects(order.SubscriberId, out subscriber))
			{
				subscriber.AddInventoryItem(context, key2, 1);
				lifeRecordCollection.AddReceiveProduct(order.SubscriberId, currDate, order.ArtisanId, key2.ItemType, key2.TemplateId);
			}
			else
			{
				artisan.AddInventoryItem(context, key2, 1);
			}
			break;
		}
		SetArtisanOrderProgress(context, order, 0);
	}

	private int GetCookingProductionAddOn(GameData.Domains.Character.Character artisan)
	{
		List<GameData.Domains.Character.LifeSkillItem> learnedLifeSkills = artisan.GetLearnedLifeSkills();
		int count = 0;
		if (learnedLifeSkills != null)
		{
			foreach (GameData.Domains.Character.LifeSkillItem book in learnedLifeSkills)
			{
				if (LifeSkill.Instance[book.SkillTemplateId].Type == 14 && book.IsAllPagesRead())
				{
					count++;
				}
			}
		}
		return count;
	}

	private int AddProductionToPool(ProductionPool res, int addOn, sbyte itemType, short baseTemplateId, sbyte baseGrade, int requiredAttainment, int[] attainments)
	{
		int upperGrade = 2 + addOn;
		int highestGrade = 0;
		for (int i = -1; i < upperGrade; i++)
		{
			if (ProductionPool.TryGetProductionTemplateId((sbyte)(baseGrade + i), itemType, baseTemplateId, out var templateId))
			{
				Production production = new Production(itemType, templateId);
				int index = i - addOn + 1;
				if (index < 0 || attainments[index] >= requiredAttainment)
				{
					res.Productions[production] = new ProductionData(0, canProduce: true);
					highestGrade = Math.Max(highestGrade, ItemTemplateHelper.GetGrade(itemType, templateId));
				}
				else
				{
					res.Productions.TryAdd(production, new ProductionData(0, canProduce: false));
				}
			}
		}
		return highestGrade;
	}

	private void AddMaterialWeightToProductions(ArtisanOrder order, List<ItemDisplayData> itemList, Dictionary<Production, int> weights)
	{
		if (!DomainManager.Character.TryGetElement_Objects(order.ArtisanId, out var artisan))
		{
			return;
		}
		int cookAddOn = GetCookingProductionAddOn(artisan);
		foreach (ItemDisplayData itemData in itemList)
		{
			if (itemData.RealKey.ItemType != 5)
			{
				continue;
			}
			MaterialItem materialConfig = Config.Material.Instance[itemData.RealKey.TemplateId];
			if (materialConfig.IsSpecial)
			{
				continue;
			}
			sbyte baseGrade = materialConfig.Grade;
			if (materialConfig.RequiredLifeSkillType == 14)
			{
				baseGrade = Math.Min(8, (sbyte)(baseGrade + cookAddOn));
			}
			for (int index = 0; index < materialConfig.CraftableItemTypes.Count; index++)
			{
				short makeItemType = materialConfig.CraftableItemTypes[index];
				foreach (short makeItemSubType in MakeItemType.Instance[makeItemType].MakeItemSubTypes)
				{
					MakeItemSubTypeItem typeConfig = MakeItemSubType.Instance[makeItemSubType];
					MakeItemResult result = typeConfig.Result;
					sbyte grade = ((materialConfig.RequiredLifeSkillType == 8 && index == 0) ? GameData.Domains.Building.SharedMethods.GetHerbMaterialTempGrade(baseGrade, isManual: true, !typeConfig.IsOdd) : baseGrade);
					for (int i = -1; i < 2; i++)
					{
						sbyte targetGrade = (sbyte)(grade + i);
						if (ProductionPool.TryGetProductionTemplateId(targetGrade, result.ItemType, result.TemplateId, out var templateId))
						{
							Production production = new Production(result.ItemType, templateId);
							int weight = SharedConstValue.MaterialWeightToArtisanOrder[i + 1] * itemData.Amount;
							if (!weights.TryAdd(production, weight))
							{
								weights[production] += weight;
							}
						}
					}
				}
			}
		}
	}

