	[DomainMethod]
	public void InterceptArtisanOrder(DataContext context, int artisanId, int subscriberId, bool isDebateWon)
	{
		if (!DomainManager.Character.TryGetElement_Objects(artisanId, out var artisan) || !DomainManager.Character.TryGetElement_Objects(subscriberId, out var subscriber) || !TryGetElement_NpcArtisanOrders(artisanId, out var order))
		{
			return;
		}
		int originId = order.SubscriberId;
		if (DomainManager.Character.TryGetElement_Objects(originId, out var origin))
		{
			SetArtisanOrderSubscriber(context, artisanId, subscriberId, order.LifeSkillType);
			ProductionPool pool = GetArtisanOrderProductionPool(order);
			if (pool != null)
			{
				int favor;
				int price = pool.GetInterceptOrderPrice(isDebateWon, out favor);
				subscriber.ChangeResource(context, 6, -price);
				artisan.ChangeResource(context, 6, price);
				DomainManager.Character.ChangeFavorabilityOptional(context, origin, subscriber, favor, -1);
				LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
				int currDate = DomainManager.World.GetCurrDate();
				lifeRecordCollection.AddCaptureOrderCorrectly(subscriberId, currDate, artisanId, originId);
			}
		}
	}

	[DomainMethod]
	public void CreateArtisanOrder(DataContext context, int artisanId, int subscriberId, sbyte lifeSkillType, short makeItemSubType = -1)
	{
		if (DomainManager.Character.TryGetElement_Objects(artisanId, out var artisan) && DomainManager.Character.TryGetElement_Objects(subscriberId, out var subscriber))
		{
			ArtisanOrder order = CreateArtisanOrderWithoutCost(context, artisan, subscriber, lifeSkillType, makeItemSubType);
			int currDate = DomainManager.World.GetCurrDate();
			LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
			lifeRecordCollection.AddOrderProduct(subscriberId, currDate, artisanId, artisan.GetLocation());
			ProductionPool pool = GetArtisanOrderProductionPool(order);
			if (pool != null)
			{
				int favor;
				int price = pool.GetCreateOrderPrice(out favor);
				subscriber.ChangeResource(context, 6, -price);
				artisan.ChangeResource(context, 6, price);
			}
		}
	}

