	private ArtisanOrder SetArtisanOrderSubscriber(DataContext context, int artisanId, int subscriberId, sbyte lifeSkillType)
	{
		int originId = -1;
		if (TryGetElement_NpcArtisanOrders(artisanId, out var order))
