		{
			order = NewNpcArtisanOrder(artisanId, subscriberId, lifeSkillType);
		}
		SetNpcArtisanOrder(context, order);
		DomainManager.Character.SetSubscriberOrder(context, originId, subscriberId, artisanId);
		return order;
	}

