		DomainManager.Extra.UpdateNpcArtisanOrderProgress(context);
		DomainManager.Extra.UpdateBuildingArtisanOrderProgress(context);
	}

	public void UpdateNpcArtisanOrderProgress(DataContext context)
	{
		HashSet<int> toRemoveList = new HashSet<int>();
		foreach (var (id, order) in _npcArtisanOrders)
		{
			if (IsArtisanOrderInvalid(order))
			{
				toRemoveList.Add(id);
				continue;
			}
			order.ProgressDelta = GetArtisanOrderDelta(order.ArtisanId, order.LifeSkillType);
			if (order.Progress + order.ProgressDelta >= GameData.Domains.Building.SharedMethods.MaxProductionProgress(order.IsAffectedByChallenge))
			{
				FinishArtisanOrder(context, order);
				toRemoveList.Add(id);
			}
			else
			{
				SetArtisanOrderProgress(context, order, order.Progress + order.ProgressDelta);
			}
		}
		foreach (int id2 in toRemoveList)
		{
			ArtisanOrder order2 = _npcArtisanOrders[id2];
			if (order2.SubscriberId >= 0)
			{
				DomainManager.Character.RemoveSubscriberOrder(context, order2.SubscriberId, id2);
			}
			RemoveElement_NpcArtisanOrders(id2, context);
		}
	}

	public void TransferTaiwuArtisanOrder(DataContext context, int newTaiwuCharId, int oldTaiwuCharId)
	{
		if (!DomainManager.Character.TryGetElement_SubscriberOrders(oldTaiwuCharId, out var list))
		{
			return;
		}
		List<int> collection = list.GetCollection();
		for (int index = collection.Count - 1; index >= 0; index--)
		{
			if (TryGetElement_NpcArtisanOrders(collection[index], out var order))
			{
				SetArtisanOrderSubscriber(context, order.ArtisanId, newTaiwuCharId, order.LifeSkillType);
			}
		}
	}

	public int GetArtisanOrderDelta(int artisanId, sbyte lifeSkillType)
	{
		GameData.Domains.Character.Character artisan = DomainManager.Character.GetElement_Objects(artisanId);
		int attainment = artisan.GetLifeSkillAttainment(lifeSkillType) * SharedConstValue.ArtisanAttainmentFactor1;
		OrganizationInfo orgInfo = artisan.GetOrganizationInfo();
		Settlement settlement = DomainManager.Organization.GetSettlement(orgInfo.SettlementId);
		int factor = ((lifeSkillType != 5) ? ((settlement.GetMaxSafety() != 0) ? (settlement.GetSafety() * SharedConstValue.ArtisanAttainmentFactor2 / settlement.GetMaxSafety()) : 0) : ((settlement.GetMaxCulture() != 0) ? (settlement.GetCulture() * SharedConstValue.ArtisanAttainmentFactor2 / settlement.GetMaxCulture()) : 0));
		CValuePercentBonus buildingBonus = DomainManager.Building.GetBuildingBlockEffect(artisan.GetOrganizationInfo().SettlementId, EBuildingScaleEffect.ArtisanOrderProgressBonus);
		return (SharedConstValue.MonthlyOrderProgressBase + attainment) * SharedConstValue.MonthlyOrderProgressFactor * factor / 100 * buildingBonus;
	}

