	public void ExchangeBuildingArtisanOrder(DataContext context, BuildingBlockKey keyA, BuildingBlockKey keyB)
	{
		ulong idA = (ulong)keyA;
		ulong idB = (ulong)keyB;
		ArtisanOrder orderA;
		bool hasA = TryGetElement_BuildingArtisanOrders(idA, out orderA);
		ArtisanOrder orderB;
		bool hasB = TryGetElement_BuildingArtisanOrders(idB, out orderB);
		if (hasA && hasB)
		{
			RemoveElement_BuildingArtisanOrders(idA, context);
			RemoveElement_BuildingArtisanOrders(idB, context);
			orderA.BuildingBlockKey = keyB;
			orderB.BuildingBlockKey = keyA;
			AddElement_BuildingArtisanOrders(idB, orderA, context);
			AddElement_BuildingArtisanOrders(idA, orderB, context);
		}
		else if (hasA)
		{
			RemoveElement_BuildingArtisanOrders(idA, context);
			orderA.BuildingBlockKey = keyB;
			AddElement_BuildingArtisanOrders(idB, orderA, context);
		}
		else if (hasB)
		{
			RemoveElement_BuildingArtisanOrders(idB, context);
			orderB.BuildingBlockKey = keyA;
			AddElement_BuildingArtisanOrders(idA, orderB, context);
		}
	}

