	private void SetBuildingArtisanOrderDelta(DataContext context, ArtisanOrder order)
	{
		(int baseValue, int finialValue) buildingArtisanOrderDelta = GetBuildingArtisanOrderDelta(order.BuildingBlockKey, order.ArtisanId, order.LifeSkillType);
		int baseValue = buildingArtisanOrderDelta.baseValue;
		int finialValue = buildingArtisanOrderDelta.finialValue;
		order.ProgressBaseDelta = baseValue;
		order.ProgressDelta = finialValue;
		SetBuildingArtisanOrder(context, order);
	}

	private (int baseValue, int finialValue) GetBuildingArtisanOrderDelta(BuildingBlockKey blockKey, int artisanId, sbyte lifeSkillType)
	{
		if (artisanId < 0 || lifeSkillType < 0 || !DomainManager.Character.TryGetElement_Objects(artisanId, out var leader) || !DomainManager.Building.TryGetElement_ShopManagerDict(blockKey, out var workers))
		{
			return (baseValue: 0, finialValue: 0);
		}
		VillagerRoleBase villagerRole = DomainManager.Extra.GetVillagerRole(artisanId);
		if (villagerRole == null)
		{
			return (baseValue: 0, finialValue: 0);
		}
		BuildingBlockData buildingBlockData = DomainManager.Building.GetBuildingBlockData(blockKey);
		BuildingBlockItem buildingConfig = BuildingBlock.Instance[buildingBlockData.TemplateId];
		if (!Enumerable.Contains(buildingConfig.VillagerRoleTemplateIds, villagerRole.RoleTemplateId))
		{
			return (baseValue: 0, finialValue: 0);
		}
		int leaderAttainment = leader.GetLifeSkillAttainment(lifeSkillType) + SharedConstValue.AddOnAttainmentOfLeader;
		int workerAttainment = 0;
		foreach (int workerId in workers.GetCollection())
		{
			if (workerId != artisanId && DomainManager.Character.TryGetElement_Objects(workerId, out var worker))
			{
				workerAttainment += worker.GetLifeSkillAttainment(lifeSkillType) + SharedConstValue.AddOnAttainmentOfWorker;
			}
		}
		CValuePercentBonus buildingBonus = DomainManager.Building.GetBuildingBlockEffect(blockKey.GetLocation(), EBuildingScaleEffect.ArtisanOrderProgressBonus);
		int baseValue = (SharedConstValue.MonthlyOrderProgressBase + leaderAttainment + workerAttainment / SharedConstValue.WorkerAttainmentDivider) * SharedConstValue.MonthlyOrderProgressFactor;
		return (baseValue: baseValue, finialValue: baseValue * buildingBonus);
	}

	private ArtisanOrder NewBuildingArtisanOrder(BuildingBlockKey blockKey, int artisanId)
	{
		int subscriberId = DomainManager.Taiwu.GetTaiwuCharId();
		BuildingBlockData blockData = DomainManager.Building.GetBuildingBlockData(blockKey);
		BuildingBlockItem config = BuildingBlock.Instance[blockData.TemplateId];
		sbyte lifeSkillType = config.RequireLifeSkillType;
		(int baseValue, int finialValue) buildingArtisanOrderDelta = GetBuildingArtisanOrderDelta(blockKey, artisanId, lifeSkillType);
		int baseValue = buildingArtisanOrderDelta.baseValue;
		int finialValue = buildingArtisanOrderDelta.finialValue;
		short templateId = config.TemplateId;
		if (1 == 0)
		{
		}
		short num = templateId switch
		{
			127 => 900, 
			128 => 901, 
			_ => -1, 
		};
		if (1 == 0)
		{
		}
		short itemSubType = num;
		return new ArtisanOrder(blockKey, artisanId, subscriberId, lifeSkillType, baseValue, finialValue, itemSubType)
		{
			StorageType = (int)DomainManager.Extra.GetBuildingDefaultStoreLocation().GetMakeType(blockKey.BuildingBlockIndex)
		};
	}

