	public bool TrySetShopVillagerQualificationImprove(GameData.Domains.Character.Character character, sbyte skillType, bool isLifeSkill)
	{
		DataContext context = DataContextManager.GetCurrentThreadDataContext();
		int charId = character.GetId();
		if (_shopVillagerQualificationImprove.TryGetValue(charId, out var improve))
		{
			if (improve.Items == null)
			{
				InitImprove();
			}
			bool ret = UpdateValue();
			DomainManager.Extra.SetElement_ShopVillagerQualificationImprove(charId, improve, context);
			return ret;
		}
		InitImprove();
		bool ret2 = UpdateValue();
		DomainManager.Extra.AddElement_ShopVillagerQualificationImprove(charId, improve, context);
		return ret2;
		void InitImprove()
		{
			improve = GameData.Utilities.ShortList.Create();
			for (int i = 0; i < 30; i++)
			{
				improve.Items.Add(0);
			}
		}
		bool UpdateValue()
		{
			sbyte skillTypeIndex = skillType;
			if (!isLifeSkill)
			{
				skillTypeIndex += 16;
			}
			short oriValue = improve.Items[skillTypeIndex];
			oriValue++;
			improve.Items[skillType] = oriValue;
			if (isLifeSkill)
			{
				character.ChangeBaseLifeSkillQualification(context, skillType, 1);
			}
			else
			{
				character.ChangeBaseCombatSkillQualification(context, skillType, 1);
			}
			return true;
		}
	}

