	[DomainMethod]
	public RecruitCharacterData RequestRecruitCharacterData(DataContext context, BuildingBlockKey buildingBlockKey, int earningDataIndex, bool autoRemove = false)
	{
		RecruitCharacterData recruitCharacterData = null;
		if (DomainManager.Building.TryGetElement_CollectBuildingEarningsData(buildingBlockKey, out var data) && data != null && data.RecruitLevelList.Count > 0 && earningDataIndex >= 0)
		{
			if (!TryGetElement_RecruitCharacterDataLists((ulong)buildingBlockKey, out var list))
			{
				AddElement_RecruitCharacterDataLists((ulong)buildingBlockKey, list = new RecruitCharacterDataList(), context);
			}
			while (list.Items.Count < data.RecruitLevelList.Count)
			{
				list.Items.Add(null);
			}
			if (list.Items.CheckIndex(earningDataIndex) && list.Items[earningDataIndex] != null)
			{
				recruitCharacterData = list.Items[earningDataIndex];
			}
			else
			{
				int peopleLevel = data.RecruitLevelList[earningDataIndex].First;
				BuildingBlockData blockData = DomainManager.Building.GetBuildingBlockData(buildingBlockKey);
				recruitCharacterData = GameData.Domains.Character.Character.GenerateRecruitCharacterData(context.Random, (sbyte)peopleLevel, buildingBlockKey, blockData);
				list.Items[earningDataIndex] = recruitCharacterData;
			}
			if (autoRemove)
			{
				list.Items.RemoveAt(earningDataIndex);
			}
			SetElement_RecruitCharacterDataLists((ulong)buildingBlockKey, list, context);
		}
		return recruitCharacterData;
	}

	public List<RecruitCharacterData> RequestRecruitCharacterDataList(DataContext context, BuildingBlockKey buildingBlockKey, bool autoRemove = false)
	{
		BuildingEarningsData earnData = DomainManager.Building.GetBuildingEarningData(buildingBlockKey);
		if (earnData != null)
		{
			List<RecruitCharacterData> result = new List<RecruitCharacterData>();
			for (int i = 0; i < earnData.RecruitLevelList.Count; i++)
			{
				RecruitCharacterData data = RequestRecruitCharacterData(context, buildingBlockKey, i);
				result.Add(data);
			}
			return result;
		}
		return null;
	}

	[DomainMethod]
	public List<BuildingRecruitData> RequestAllRecruitCharacterData(DataContext context, BuildingBlockKey targetBuildingBlock)
	{
		List<BuildingRecruitData> result = new List<BuildingRecruitData>();
		BuildingRecruitCharacterData recruitCharacterData = null;
		Dictionary<short, List<BuildingBlockKey>> summaryInfo = DomainManager.Building.GetBuildingRecruitPair();
		foreach (KeyValuePair<short, List<BuildingBlockKey>> buildingTypePair in summaryInfo)
		{
			BuildingRecruitData buildingTypeData = new BuildingRecruitData();
			buildingTypeData.BuildingTemplateId = buildingTypePair.Key;
			buildingTypeData.CharacterDataList = new List<BuildingRecruitCharacterData>();
			foreach (BuildingBlockKey buildingBlockKey in buildingTypePair.Value)
			{
				if (!DomainManager.Building.TryGetElement_CollectBuildingEarningsData(buildingBlockKey, out var recruitData) || recruitData == null || recruitData.RecruitLevelList.Count <= 0 || (!BuildingBlockKey.Invalid.Equals(targetBuildingBlock) && !buildingBlockKey.Equals(targetBuildingBlock)))
				{
					continue;
				}
				if (!TryGetElement_RecruitCharacterDataLists((ulong)buildingBlockKey, out var list))
				{
					AddElement_RecruitCharacterDataLists((ulong)buildingBlockKey, list = new RecruitCharacterDataList(), context);
				}
				while (list.Items.Count < recruitData.RecruitLevelList.Count)
				{
					list.Items.Add(null);
				}
				for (int earningDataIndex = 0; earningDataIndex < recruitData.RecruitLevelList.Count; earningDataIndex++)
				{
					recruitCharacterData = new BuildingRecruitCharacterData();
					if (list.Items.CheckIndex(earningDataIndex) && list.Items[earningDataIndex] != null)
					{
						recruitCharacterData.CharacterData = list.Items[earningDataIndex];
					}
					else
					{
						int peopleLevel = recruitData.RecruitLevelList[earningDataIndex].First;
						BuildingBlockData blockData = DomainManager.Building.GetBuildingBlockData(buildingBlockKey);
						recruitCharacterData.CharacterData = GameData.Domains.Character.Character.GenerateRecruitCharacterData(context.Random, (sbyte)peopleLevel, buildingBlockKey, blockData);
						list.Items[earningDataIndex] = recruitCharacterData.CharacterData;
					}
					buildingTypeData.CharacterDataList.Add(recruitCharacterData);
					recruitCharacterData.BuildingBlockKey = buildingBlockKey;
					recruitCharacterData.RecruitInfoIndex = earningDataIndex;
					recruitCharacterData.RecruitLevel = recruitData.RecruitLevelList[earningDataIndex];
				}
				SetElement_RecruitCharacterDataLists((ulong)buildingBlockKey, list, context);
			}
			if (buildingTypeData.CharacterDataList.Count > 0)
			{
				result.Add(buildingTypeData);
			}
		}
		result.Sort((BuildingRecruitData a, BuildingRecruitData b) => b.CharacterDataList.Count - a.CharacterDataList.Count);
		return result;
	}

