	private void InitBuildingAreaEffectProgresses(DataContext context)
	{
		List<Settlement> settlements = new List<Settlement>();
		DomainManager.Organization.GetAllSettlements(settlements);
		foreach (Settlement settlement in settlements)
		{
			Location location = settlement.GetLocation();
			if (location.IsValid() && MapAreaData.IsRegularArea(location.AreaId) && DomainManager.Building.TryGetElement_BuildingAreas(location, out var _) && !_buildingAreaEffectProgresses.ContainsKey(location))
			{
				SerializableList<BuildingAreaEffectProgress> list = SerializableList<BuildingAreaEffectProgress>.Create();
				for (sbyte effectType = 0; effectType < 3; effectType++)
				{
					list.Items.Add(new BuildingAreaEffectProgress(effectType));
				}
				AddElement_BuildingAreaEffectProgresses(location, list, context);
			}
		}
	}

	public void OnBuildingAreaEffectLocationChanged(DataContext context, sbyte effectType, Location fromLocation, Location toLocation)
	{
		if (fromLocation.AreaId >= 0 && toLocation.AreaId >= 0 && fromLocation.AreaId != toLocation.AreaId)
		{
			throw new InvalidOperationException($"Cannot move effect across area from {fromLocation} to {toLocation}.");
		}
		short areaId = ((fromLocation.AreaId >= 0) ? fromLocation.AreaId : toLocation.AreaId);
		if (areaId < 0)
		{
			return;
		}
		MapAreaData areaData = DomainManager.Map.GetElement_Areas(areaId);
		if (areaData.SettlementInfos == null)
		{
			return;
		}
		SettlementInfo[] settlementInfos = areaData.SettlementInfos;
		for (int i = 0; i < settlementInfos.Length; i++)
		{
			SettlementInfo settlementInfo = settlementInfos[i];
			Location settlementLocation = new Location(areaId, settlementInfo.BlockId);
			if (!_buildingAreaEffectProgresses.TryGetValue(settlementLocation, out var effects))
			{
				continue;
			}
			BuildingAreaEffectProgress effect = effects.Items[effectType];
			if (!fromLocation.IsValid() || effect.RemoveLocation(fromLocation))
			{
				if (toLocation.IsValid())
				{
					effect.AddLocation(toLocation);
				}
				SetElement_BuildingAreaEffectProgresses(settlementLocation, effects, context);
				break;
			}
		}
	}

	public void UpdateBuildingAreaEffectProgresses(DataContext context)
	{
		IRandomSource random = context.Random;
		foreach (KeyValuePair<Location, SerializableList<BuildingAreaEffectProgress>> buildingAreaEffectProgress in _buildingAreaEffectProgresses)
		{
			buildingAreaEffectProgress.Deconstruct(out var key, out var value);
			Location settlementLocation = key;
			SerializableList<BuildingAreaEffectProgress> effectList = value;
			bool isModified = false;
			foreach (BuildingAreaEffectProgress effect in effectList.Items)
			{
				EBuildingScaleEffect effectType = effect.BuildingScaleEffect;
				int value2 = DomainManager.Building.GetBuildingBlockEffect(settlementLocation, effectType);
				if (value2 <= 0)
				{
					continue;
				}
				isModified = true;
				int newCount = effect.OfflineChangeProgress(value2);
				if (newCount <= 0)
				{
					continue;
				}
				List<MapBlockData> blocks = ObjectPool<List<MapBlockData>>.Instance.Get();
				DomainManager.Map.GetSettlementAffiliatedBlocks(settlementLocation.AreaId, settlementLocation.BlockId, blocks);
				switch (effectType)
				{
				case EBuildingScaleEffect.AnimalProgressDelta:
				{
					for (int k = 0; k < newCount; k++)
					{
						if (!TryGetRandomBlockForGeneratingAnimal(context, settlementLocation.AreaId, isTaiwuSkill: false, out var targetBlockId))
						{
							break;
						}
						Location location2 = new Location(settlementLocation.AreaId, targetBlockId);
						short animalTemplateId = GetRandomAnimalForGeneratingAnimal(context);
						CreateAnimalByCharacterTemplateId(context, animalTemplateId, location2);
						effect.AddLocation(location2);
						Logger.Info($"Creating animal {Config.Character.Instance[animalTemplateId].GivenName} at {location2} by building area effect at {settlementLocation}.");
					}
					break;
				}
				case EBuildingScaleEffect.CricketProgressDelta:
				{
					for (int i2 = blocks.Count - 1; i2 >= 0; i2--)
					{
						MapBlockData block2 = blocks[i2];
						if (DomainManager.Map.LocationHasCricket(context, block2.GetLocation()) || !CricketPlaceDataHelper.BlockAllowCricket(block2))
						{
							blocks.RemoveAt(i2);
						}
					}
					for (int l = 0; l < newCount; l++)
					{
						if (blocks.Count <= 0)
						{
							break;
						}
						int index2 = random.Next(blocks.Count);
						MapBlockData targetBlock2 = blocks[index2];
						CollectionUtils.SwapAndRemove(blocks, index2);
						Location location3 = targetBlock2.GetLocation();
						CreateExtraCricketMapUnit(context, location3, short.MaxValue, showAsRegular: true, -1);
						effect.AddLocation(location3);
						Logger.Info($"Creating cricket at {location3} by building area effect at {settlementLocation}.");
					}
					break;
				}
				case EBuildingScaleEffect.AdventureProgressDelta:
				{
					for (int i = blocks.Count - 1; i >= 0; i--)
					{
						MapBlockData block = blocks[i];
						if (DomainManager.Adventure.QueryAnyAdventureOrMajorEvent(block))
						{
							blocks.RemoveAt(i);
						}
					}
					for (int j = 0; j < newCount; j++)
					{
						if (blocks.Count <= 0)
						{
							break;
						}
						int index = random.Next(blocks.Count);
						MapBlockData targetBlock = blocks[index];
						CollectionUtils.SwapAndRemove(blocks, index);
						Location location = targetBlock.GetLocation();
						sbyte resType = (sbyte)context.Random.Next(6);
						if (ResourceDisasterHelper.GenerateDisasterAdventure(context, resType, location))
						{
							effect.AddLocation(location);
							DomainManager.World.GetMonthlyNotificationCollection().AddPreciousMaterial(location);
							Logger.Info($"Creating {newCount} adventure(s) at {location} by building area effect at {settlementLocation}.");
						}
					}
					break;
				}
				}
				ObjectPool<List<MapBlockData>>.Instance.Return(blocks);
			}
			if (isModified)
			{
				SetElement_BuildingAreaEffectProgresses(settlementLocation, effectList, context);
			}
		}
	}

