	public void TriggerTaiwuVillageVowMonthlyEventFromCrossArchive(DataContext context, BuildingBlockData data)
	{
		short taiwuVillageAreaId = DomainManager.Taiwu.GetTaiwuVillageLocation().AreaId;
		sbyte taiwuVillageStateId = DomainManager.Map.GetStateTemplateIdByAreaId(taiwuVillageAreaId);
		sbyte taiwuVillageSectOrgTemplateId = MapState.Instance[taiwuVillageStateId].SectID;
		sbyte level = 1;
		for (sbyte sectTemplateId = 1; sectTemplateId <= 15; sectTemplateId++)
		{
			if (sectTemplateId != taiwuVillageSectOrgTemplateId)
			{
				sbyte lockIndex = OrganizationDomain.GetLargeSectIndex(sectTemplateId);
				if (data.SlotIsUnlocked(lockIndex))
				{
					AddElement_TaiwuVillageVowOrgTemplateCrossArchiveDict(sectTemplateId, ++level, context);
				}
			}
		}
	}

	public void TriggerTaiwuVillageVowMonthlyEvent(DataContext context)
	{
		if (!DomainManager.World.IsTaskFinished(31))
		{
			return;
		}
		if (_taiwuVillageVowOrgTemplateCrossArchiveDict.Count > 0)
		{
			foreach (var (orgTemplateId, level) in _taiwuVillageVowOrgTemplateCrossArchiveDict)
			{
				TaiwuVillageVowOrgTemplateIdList.Add((orgTemplateId, level));
			}
		}
		ClearTaiwuVillageVowOrgTemplateCrossArchiveDict(context);
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		for (int i = 0; i < TaiwuVillageVowOrgTemplateIdList.Count; i++)
		{
			(sbyte templateId, sbyte level) tuple = TaiwuVillageVowOrgTemplateIdList[i];
			sbyte orgTemplateId2 = tuple.templateId;
			sbyte level2 = tuple.level;
			Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(orgTemplateId2);
			MonthlyEventCollection monthlyEventCollection = DomainManager.World.GetMonthlyEventCollection();
			monthlyEventCollection.AddTaiwuVillageStoneClaimed(taiwu.GetId(), settlement.GetId(), settlement.GetId(), level2);
		}
		TaiwuVillageVowOrgTemplateIdList.Clear();
	}

