	[DomainMethod]
	public void FeedCarrier(DataContext context, ItemKey carrier, ItemKey food, int count, ItemSourceType sourceType)
	{
		FeedCarrier(context, DomainManager.Taiwu.GetTaiwu(), carrier, food, count, sourceType);
	}

	public void FeedCarrier(DataContext context, GameData.Domains.Character.Character character, ItemKey carrier, ItemKey food, int count = 1, ItemSourceType sourceType = ItemSourceType.Inventory)
	{
		if (food.ItemType != 5)
		{
			return;
		}
		int addDurability = SharedMethods.GetFoodAddCarrierDurability(carrier.TemplateId, food.TemplateId) * count;
		ItemBase baseItem = DomainManager.Item.GetBaseItem(carrier);
		sbyte grade = baseItem.GetGrade();
		short currDurability = baseItem.GetCurrDurability();
		baseItem.ChangeCurrDurability(context, addDurability);
		bool isTaiwu = character.IsTaiwu();
		if (isTaiwu)
		{
			ProfessionFormulaItem formula = ProfessionFormula.Instance[11];
			int addSeniority = formula.Calculate(baseItem.GetCurrDurability() - currDurability, grade);
			DomainManager.Extra.ChangeProfessionSeniority(context, 1, addSeniority);
		}
		if (IsItemTamable(carrier) && DomainManager.Extra.TryGetCarrierTamePoint(carrier.Id, out var tamePoint))
		{
			int addTamePoint = SharedMethods.GetFoodAddCarrierTamePoint(carrier.TemplateId, food.TemplateId, count);
			int finial = Math.Clamp(tamePoint + addTamePoint, 0, 100);
			SetCarrierTamePoint(context, carrier.Id, finial);
			if (isTaiwu)
			{
				ProfessionFormulaItem formula2 = ProfessionFormula.Instance[12];
				int addSeniority2 = formula2.Calculate(finial - tamePoint, grade);
				DomainManager.Extra.ChangeProfessionSeniority(context, 1, addSeniority2);
			}
		}
		if (isTaiwu)
		{
			DomainManager.Taiwu.RemoveItem(context, food, count, sourceType, deleteItem: true);
		}
		else
		{
			character.RemoveInventoryItem(context, food, count, deleteItem: true);
		}
	}

