	public bool TryGetValidCarrierLocation(DataContext context, GameData.Domains.Character.Character character, out Location location)
	{
		location = character.GetLocation();
		if (!location.IsValid())
		{
			location = character.GetValidLocation();
		}
		if (!location.IsValid())
		{
			return false;
		}
		return TryGetValidCarrierLocation(context, location.AreaId, out location);
	}

	public bool TryGetValidCarrierLocation(DataContext context, short areaId, out Location location)
	{
		location = Location.Invalid;
		if (DomainManager.Map.IsAreaBroken(areaId))
		{
			MapAreaData area = DomainManager.Map.GetElement_Areas(areaId);
			AreaTravelRoute[] neighbors = MapArea.Instance[area.GetTemplateId()].NeighborAreas;
			for (int i = 0; i < neighbors.Length; i++)
			{
				if (!DomainManager.Map.IsAreaBroken(neighbors[i].DestAreaId))
				{
					areaId = neighbors[i].DestAreaId;
					break;
				}
			}
		}
		if (DomainManager.Map.IsAreaBroken(areaId))
		{
			return false;
		}
		List<MapBlockData> blocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		Span<MapBlockData> areaBlocks = DomainManager.Map.GetAreaBlocks(areaId);
		for (int j = 0; j < areaBlocks.Length; j++)
		{
			MapBlockData block = areaBlocks[j];
			if (block.Visible && block.IsNonDeveloped() && block.IsPassable())
			{
				blocks.Add(block);
			}
		}
		if (blocks.Count == 0)
		{
			return false;
		}
		short blockId = blocks.GetRandom(context.Random).BlockId;
		ObjectPool<List<MapBlockData>>.Instance.Return(blocks);
		location = new Location(areaId, blockId);
		return true;
	}

