	public void ApplyTamingResult(DataContext context, GameData.Domains.Character.Character character, ItemKey carrier, bool isWin, Location location, ItemKey rope)
	{
		if (isWin)
		{
			int increment = context.Random.Next(1, 11);
			if (rope.IsValid())
			{
				increment += Config.Misc.Instance[rope.TemplateId].Grade + 1;
			}
			SetCarrierTamePoint(context, carrier.Id, Math.Clamp(GetCarrierTamePoint(carrier.Id) + increment, 0, 100));
			return;
		}
		ItemKey equipment = character.GetEquipment()[12];
		if (equipment.IsValid() && equipment.Equals(carrier))
		{
			character.ChangeEquipment(context, 12, -1, ItemKey.Invalid);
		}
		else
		{
			equipment = character.GetEquipment()[13];
			if (equipment.IsValid() && equipment.Equals(carrier))
			{
				character.ChangeEquipment(context, 13, -1, ItemKey.Invalid);
			}
		}
		if (character.GetInventory().Items.ContainsKey(carrier))
		{
			character.RemoveInventoryItem(context, carrier, 1, deleteItem: false);
		}
		SetFleeCarrierLocation(context, carrier, location);
	}

	public void UpdateTaiwuTaming(DataContext context)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location location = taiwu.GetLocation();
		if (!location.IsValid())
		{
			location = taiwu.GetValidLocation();
		}
		List<ItemKey> carriers = ObjectPool<List<ItemKey>>.Instance.Get();
		carriers.Clear();
		foreach (ItemKey carrier in taiwu.GetValidAnimalEquipment())
		{
			if (IsItemTamable(carrier))
			{
				SetCarrierTamePoint(context, carrier.Id, Math.Clamp(GetCarrierTamePoint(carrier.Id) + (10 - Config.Carrier.Instance[carrier.TemplateId].Grade), 0, 100));
				if (IsCarrierWillingToBetray(context, carrier))
				{
					carriers.Add(carrier);
				}
			}
		}
		foreach (ItemKey item in taiwu.GetInventory().Items.Keys)
		{
			if (IsItemTamable(item) && IsCarrierWillingToBetray(context, item))
			{
				carriers.Add(item);
			}
		}
		if (carriers.Count > 0 && TryGetValidCarrierLocation(context, taiwu, out var fleeLocation))
		{
			ItemKey betrayer = context.Random.GetRandomElement(carriers);
			MonthlyEventCollection monthlyEventCollection = DomainManager.World.GetMonthlyEventCollection();
			monthlyEventCollection.AddTamingCarriers(GetCharacterTemplateIdByCarrierTemplateId(betrayer.TemplateId), location, (ulong)betrayer, fleeLocation);
		}
		ObjectPool<List<ItemKey>>.Instance.Return(carriers);
	}

	public void PostAdvanceMonth_UpdateNpcTaming(DataContext context, int areaId)
	{
		PreAdvanceMonthNpcTamingModification modification = new PreAdvanceMonthNpcTamingModification();
		Span<MapBlockData> areaBlocks = DomainManager.Map.GetAreaBlocks((short)areaId);
		Span<MapBlockData> span = areaBlocks;
		for (int i = 0; i < span.Length; i++)
		{
			MapBlockData blockData = span[i];
			if (blockData.CharacterSet == null || blockData.TemplateEnemyList != null || IsLocationContainsAnimal(new Location(blockData.AreaId, blockData.BlockId)))
			{
				continue;
			}
			foreach (int charId in blockData.CharacterSet)
			{
				GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
				foreach (ItemKey carrier in character.GetValidAnimalEquipment())
				{
					if (IsItemTamable(carrier) && IsCarrierWillingToBetray(context, carrier) && TryGetValidCarrierLocation(context, character, out var location))
					{
						modification.TamerRecords.Add((charId, location, carrier));
					}
				}
			}
		}
		ParallelModificationsRecorder recorder = context.ParallelModificationsRecorder;
		recorder.RecordType(ParallelModificationType.PreAdvanceMonthUpdateNpcTaming);
		recorder.RecordParameterClass(modification);
	}

	public void UpdateTaiwuTeammateTaming(DataContext context)
	{
		PreAdvanceMonthNpcTamingModification modification = new PreAdvanceMonthNpcTamingModification();
		HashSet<int> charIds = DomainManager.Taiwu.GetGroupCharIds().GetCollection();
		foreach (int charId in charIds)
		{
			if (charId == DomainManager.Taiwu.GetTaiwuCharId())
			{
				continue;
			}
			GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
			foreach (ItemKey carrier in character.GetValidAnimalEquipment())
			{
				if (IsItemTamable(carrier) && IsCarrierWillingToBetray(context, carrier) && TryGetValidCarrierLocation(context, character, out var location))
				{
					modification.TamerRecords.Add((charId, location, carrier));
				}
			}
		}
		foreach (int charId2 in DomainManager.Taiwu.GetTaiwuSpecialGroup())
		{
			if (!_sectZhujianGearMates.ContainsKey(charId2))
			{
				continue;
			}
			GameData.Domains.Character.Character character2 = DomainManager.Character.GetElement_Objects(charId2);
			foreach (ItemKey carrier2 in character2.GetValidAnimalEquipment())
			{
				if (IsItemTamable(carrier2) && IsCarrierWillingToBetray(context, carrier2) && TryGetValidCarrierLocation(context, character2, out var location2))
				{
					modification.TamerRecords.Add((charId2, location2, carrier2));
				}
			}
		}
		ParallelModificationsRecorder recorder = context.ParallelModificationsRecorder;
		recorder.RecordType(ParallelModificationType.PreAdvanceMonthUpdateNpcTaming);
		recorder.RecordParameterClass(modification);
	}

	public void ComplementPreAdvanceMonth_UpdateNpcTaming(DataContext context, PreAdvanceMonthNpcTamingModification mod)
	{
		foreach (var record in mod.TamerRecords)
		{
			if (!DomainManager.Character.TryGetElement_Objects(record.Item1, out var character))
			{
				continue;
			}
			ItemKey carrier = record.Item3;
			if (IsItemTamable(carrier))
			{
				AiHelper.NpcCombatResultType result = DomainManager.Character.SimulateEnemyAttack(context, GetCharacterTemplateIdByCarrierTemplateId(carrier.TemplateId), character);
				bool flag = (uint)(result - 2) <= 1u;
				bool isWin = flag;
				LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
				int currDate = DomainManager.World.GetCurrDate();
				Location location = character.GetLocation();
				if (isWin)
				{
					lifeRecordCollection.AddTameCarrierSucceed(character.GetId(), currDate, carrier.ItemType, carrier.TemplateId, location);
				}
				else
				{
					lifeRecordCollection.AddTameCarrierFail(character.GetId(), currDate, carrier.ItemType, carrier.TemplateId, location);
				}
				ApplyTamingResult(context, character, carrier, isWin, record.Item2, ItemKey.Invalid);
			}
		}
	}

