	public void SetPoisonImmunity(DataContext context, int charId, sbyte poisonType, bool isImmune)
	{
		if (_characterPoisonImmunities.TryGetValue(charId, out var prevPoisonImmunities))
		{
			byte newPoisonImmunities = BitOperation.SetBit(prevPoisonImmunities, poisonType, isImmune);
			if (newPoisonImmunities == 0)
			{
				RemoveElement_CharacterPoisonImmunities(charId, context);
			}
			else
			{
				SetElement_CharacterPoisonImmunities(charId, newPoisonImmunities, context);
			}
		}
		else if (isImmune)
		{
			byte newPoisonImmunities2 = BitOperation.SetBit(0, poisonType, bit: true);
			AddElement_CharacterPoisonImmunities(charId, newPoisonImmunities2, context);
		}
	}

	public void AddPoisonImmunities(DataContext context, int charId, byte poisonImmunities)
	{
		if (_characterPoisonImmunities.TryGetValue(charId, out var prevPoisonImmunities))
		{
			SetElement_CharacterPoisonImmunities(charId, (byte)(prevPoisonImmunities | poisonImmunities), context);
		}
		else
		{
			AddElement_CharacterPoisonImmunities(charId, poisonImmunities, context);
		}
	}

