	[DomainMethod]
	public bool SetAdvancedTeammateCommands(DataContext context, int charId, sbyte cmdType)
	{
		TeammateCommandItem config = TeammateCommand.Instance[cmdType];
		if (config == null || config.Type != ETeammateCommandType.Advance)
		{
			return false;
		}
		SByteList advanceCmdTypesSByteList;
		bool exist = _advancedTeammateCommandDict.TryGetValue(charId, out advanceCmdTypesSByteList);
		ref List<sbyte> items = ref advanceCmdTypesSByteList.Items;
		List<sbyte> advanceCmdTypes = items ?? (items = new List<sbyte>());
		if (advanceCmdTypes.Contains(cmdType))
		{
			return false;
		}
		int costAuthority = config.UpgradeAuthorityCost;
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		if (taiwu.GetResource(7) < costAuthority)
		{
			return false;
		}
		taiwu.ChangeResource(context, 7, -costAuthority);
		advanceCmdTypes.Add(cmdType);
		if (exist)
		{
			SetElement_AdvancedTeammateCommandDict(charId, advanceCmdTypesSByteList, context);
		}
		else
		{
			AddElement_AdvancedTeammateCommandDict(charId, advanceCmdTypesSByteList, context);
		}
		UpdateCharAdvancedTeammateCommands(context, charId);
		return true;
	}

	[DomainMethod]
	public bool CancelAdvancedTeammateCommands(DataContext context, int charId, sbyte cmdType)
	{
		TeammateCommandItem config = TeammateCommand.Instance[cmdType];
		if (config == null || config.Type != ETeammateCommandType.Advance)
		{
			return false;
		}
		if (!_advancedTeammateCommandDict.TryGetValue(charId, out var advanceCmdTypesSByteList))
		{
			return false;
		}
		List<sbyte> advanceCmdTypes = advanceCmdTypesSByteList.Items;
		if (advanceCmdTypes == null || advanceCmdTypes.Count <= 0 || !advanceCmdTypes.Contains(cmdType))
		{
			return false;
		}
		advanceCmdTypes.Remove(cmdType);
		if (advanceCmdTypes.Count != 0)
		{
			SetElement_AdvancedTeammateCommandDict(charId, advanceCmdTypesSByteList, context);
		}
		else
		{
			RemoveElement_AdvancedTeammateCommandDict(charId, context);
		}
		UpdateCharAdvancedTeammateCommands(context, charId);
		return true;
	}

	private void UpdateCharAdvancedTeammateCommands(DataContext context, int charId)
	{
		if (!TryGetElement_CharTeammateCommandDict(charId, out var charCmdTypesSByteList))
		{
			return;
		}
		List<sbyte> items = charCmdTypesSByteList.Items;
		if (items != null && items.Count > 0)
		{
			_advancedTeammateCommandDict.TryGetValue(charId, out var advanceCmdTypesSbyteList);
			if (ReplaceAdvanceTeammateCommands(charCmdTypesSByteList.Items, advanceCmdTypesSbyteList.Items))
			{
				SetElement_CharTeammateCommandDict(charId, charCmdTypesSByteList, context);
			}
		}
	}

