	public void TryRegenerateTeammateCommand(DataContext context, GameData.Domains.Character.Character character)
	{
		int charId = character.GetId();
		if (character.GetOrganizationInfo().OrgTemplateId != 16 && !DomainManager.Taiwu.IsInGroup(charId) && _changedTeammateCharIds.Contains(charId))
		{
			_changedTeammateCharIds.Remove(charId);
			SetChangedTeammateCharIds(_changedTeammateCharIds, context);
		}
		if (!_changedTeammateCharIds.Contains(charId))
		{
			GenerateCharTeammateCommands(context, charId);
		}
	}

	public void GenerateCharTeammateCommands(DataContext context, int charId, bool generateNotExist = false)
	{
		if (generateNotExist || _charTeammateCommandDict.ContainsKey(charId))
		{
			GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
			SByteList cmdList = SByteList.Create();
			IReadOnlyList<sbyte> readOnlyList2;
			if (character.GetCreatingType() == 1)
			{
				IReadOnlyList<sbyte> readOnlyList = Array.Empty<sbyte>();
				readOnlyList2 = readOnlyList;
			}
			else
			{
				IReadOnlyList<sbyte> readOnlyList = character.Template.DisableTeammateCommands;
				readOnlyList2 = readOnlyList;
			}
			IReadOnlyList<sbyte> disableCmdTypes = readOnlyList2;
			GetRandomCmdTypes(context.Random, cmdList.Items, character.GetFeatureMedalValue, disableCmdTypes);
			ReplaceAdvanceTeammateCommands(cmdList.Items, _advancedTeammateCommandDict.GetOrDefault(charId).Items);
			SetCharTeammateCommands(context, charId, cmdList);
		}
	}

	public void FillNegativeTeammateCommands(IRandomSource random, int charId, int count, IList<sbyte> newCmds)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		List<int> typeWeights = ObjectPool<List<int>>.Instance.Get();
		CalcMedalCounts(typeWeights, character.GetFeatureMedalValue);
		bool noWeight = typeWeights.Sum() == 0;
		List<sbyte> negativePool = ObjectPool<List<sbyte>>.Instance.Get();
		negativePool.Clear();
		negativePool.AddRange(from x in TeammateCommand.Instance
			where x.Type == ETeammateCommandType.Negative
			select x.TemplateId);
		List<sbyte> tempPool = ObjectPool<List<sbyte>>.Instance.Get();
		for (int i = 0; i < count; i++)
		{
			int type = (noWeight ? (-1) : RandomUtils.GetRandomIndex(typeWeights, random));
			tempPool.Clear();
			tempPool.AddRange(negativePool.Where((sbyte x) => TeammateCommand.Instance[x].MedalType == type));
			sbyte cmdType = ((tempPool.Count > 0) ? tempPool.GetRandom(random) : negativePool.GetRandom(random));
			negativePool.Remove(cmdType);
			tempPool.Clear();
			tempPool.AddRange(newCmds.Where((sbyte x) => TeammateCommand.Instance[x].Type != ETeammateCommandType.Negative));
			bool preferReplace = tempPool.Any((sbyte x) => TeammateCommand.Instance[x].MedalType == type);
			if (preferReplace)
			{
				tempPool.RemoveAll((sbyte x) => TeammateCommand.Instance[x].MedalType != type);
			}
			if (!preferReplace && newCmds.Count < 3)
			{
				newCmds.Add(cmdType);
			}
			else if (tempPool.Count > 0)
			{
				sbyte replaceCmdType = tempPool.GetRandom(random);
				int index = newCmds.IndexOf(replaceCmdType);
				newCmds.RemoveAt(index);
				newCmds.Insert(index, cmdType);
			}
		}
		ObjectPool<List<sbyte>>.Instance.Return(tempPool);
		ObjectPool<List<sbyte>>.Instance.Return(negativePool);
		ObjectPool<List<int>>.Instance.Return(typeWeights);
	}

