	public static void GetRandomCmdTypes(IRandomSource random, IList<sbyte> cmdList, Func<sbyte, int> medalProvider, IReadOnlyList<sbyte> disableCmdList = null)
	{
		List<int> medalCounts = ObjectPool<List<int>>.Instance.Get();
		CalcMedalCounts(medalCounts, medalProvider);
		for (int i = 0; i < 3; i++)
		{
			sbyte cmdType = GetRandomCmdType(random, medalCounts, cmdList, disableCmdList);
			if (cmdType >= 0)
			{
				TeammateCommandItem cmdConfig = TeammateCommand.Instance[cmdType];
				medalCounts[cmdConfig.MedalType] -= cmdConfig.MedalCount;
				cmdList.Add(cmdType);
			}
		}
		ObjectPool<List<int>>.Instance.Return(medalCounts);
	}

	private static sbyte GetRandomCmdType(IRandomSource random, IReadOnlyList<int> medalCounts, ICollection<sbyte> cmdList, IReadOnlyList<sbyte> disableCmdList = null)
	{
		List<sbyte> pool = ObjectPool<List<sbyte>>.Instance.Get();
		List<int> weights = ObjectPool<List<int>>.Instance.Get();
		pool.Clear();
		weights.Clear();
		foreach (sbyte cmdType in TeammateCommandNormal)
		{
			if ((disableCmdList == null || !disableCmdList.Contains(cmdType)) && (cmdList == null || cmdList.Count <= 0 || !cmdList.Contains(cmdType)))
			{
				TeammateCommandItem cmdConfig = TeammateCommand.Instance[cmdType];
				int medalCount = medalCounts.GetOrDefault(cmdConfig.MedalType);
				if (medalCount >= cmdConfig.MedalCount)
				{
					pool.Add(cmdType);
					weights.Add(medalCount);
				}
			}
		}
		sbyte result = (sbyte)((pool.Count > 0) ? pool[RandomUtils.GetRandomIndex(weights, random)] : (-1));
		ObjectPool<List<sbyte>>.Instance.Return(pool);
		ObjectPool<List<int>>.Instance.Return(weights);
		return result;
	}

	private static void CalcMedalCounts(ICollection<int> typeWeights, Func<sbyte, int> medalProvider)
	{
		typeWeights.Clear();
		for (sbyte type = 0; type < 3; type++)
		{
			typeWeights.Add(Math.Abs(medalProvider(type)));
		}
	}

	private static bool ReplaceAdvanceTeammateCommands(IList<sbyte> cmdTypes, IReadOnlyList<sbyte> advanceCmdTypes)
	{
		bool anyChanged = false;
		for (int i = 0; i < cmdTypes.Count; i++)
		{
			sbyte cmdType = cmdTypes[i];
			TeammateCommandItem cmdConfig = TeammateCommand.Instance[cmdType];
			ETeammateCommandType type = cmdConfig.Type;
			if ((type == ETeammateCommandType.Normal || type == ETeammateCommandType.Advance) ? true : false)
			{
				bool isAdvance = cmdConfig.Type == ETeammateCommandType.Advance;
				sbyte cmdTypeAdvance = (isAdvance ? cmdType : TeammateCommandAdvanceMapping[cmdType]);
				if (isAdvance != (advanceCmdTypes?.Contains(cmdTypeAdvance) ?? false))
				{
					anyChanged = true;
					cmdTypes[i] = TeammateCommandAdvanceMapping[cmdType];
				}
			}
		}
		return anyChanged;
	}

