	[DomainMethod]
	public bool AddCharacterMasteredCombatSkill(DataContext context, int charId, short skillTemplateId)
	{
		if (_characterMasteredCombatSkills.TryGetValue(charId, out var masteredSkills))
		{
			ref List<short> items = ref masteredSkills.Items;
			if (items == null)
			{
				items = new List<short>();
			}
			if (masteredSkills.Items.Contains(skillTemplateId))
			{
				return false;
			}
			masteredSkills.Items.Add(skillTemplateId);
			SetElement_CharacterMasteredCombatSkills(charId, masteredSkills, context);
		}
		else
		{
			masteredSkills = GameData.Utilities.ShortList.Create();
			masteredSkills.Items.Add(skillTemplateId);
			AddElement_CharacterMasteredCombatSkills(charId, masteredSkills, context);
		}
		if (DomainManager.CombatSkill.TryGetElement_CombatSkills(new CombatSkillKey(charId, skillTemplateId), out var combatSkill))
		{
			combatSkill.InvalidateSelfAndInfluencedCache(11, context);
		}
		if (charId == DomainManager.Taiwu.GetTaiwuCharId())
		{
			int currPlanId = DomainManager.Taiwu.GetCurrCombatSkillPlanId();
			SetElement_MasteredCombatSkillPlans(currPlanId, masteredSkills, context);
			GameData.Domains.Character.Character character = DomainManager.Taiwu.GetTaiwu();
			CombatSkillEquipment skillEquipment = character.GetCombatSkillEquipment();
			character.ApplyCombatSkillEquipmentModification(context, skillEquipment);
			DomainManager.Global.InvokeGuidingTrigger(context, 278);
		}
		return true;
	}

	[DomainMethod]
	public bool RemoveCharacterMasteredCombatSkill(DataContext context, int charId, short skillTemplateId)
	{
		if (!_characterMasteredCombatSkills.TryGetValue(charId, out var masteredSkills))
		{
			return false;
		}
		if (masteredSkills.Items == null || !masteredSkills.Items.Remove(skillTemplateId))
		{
			return false;
		}
		if (masteredSkills.Items.Count == 0)
		{
			RemoveElement_CharacterMasteredCombatSkills(charId, context);
		}
		else
		{
			SetElement_CharacterMasteredCombatSkills(charId, masteredSkills, context);
		}
		if (DomainManager.CombatSkill.TryGetElement_CombatSkills(new CombatSkillKey(charId, skillTemplateId), out var combatSkill))
		{
			combatSkill.InvalidateSelfAndInfluencedCache(11, context);
		}
		if (charId == DomainManager.Taiwu.GetTaiwuCharId())
		{
			int currPlanId = DomainManager.Taiwu.GetCurrCombatSkillPlanId();
			SetElement_MasteredCombatSkillPlans(currPlanId, masteredSkills, context);
			GameData.Domains.Character.Character character = DomainManager.Taiwu.GetTaiwu();
			CombatSkillEquipment skillEquipment = character.GetCombatSkillEquipment();
			character.ApplyCombatSkillEquipmentModification(context, skillEquipment);
		}
		return true;
	}

	public void SetCharacterMasteredCombatSkills(DataContext context, int charId, GameData.Utilities.ShortList masteredSkills)
	{
		if (_characterMasteredCombatSkills.TryGetValue(charId, out var prevMasteredSkills))
		{
			if (masteredSkills.Items == null || masteredSkills.Items.Count == 0)
			{
				RemoveElement_CharacterMasteredCombatSkills(charId, context);
			}
			else
			{
				UpdateCombatSkillRequirementPercent(context, charId, prevMasteredSkills.Items);
				SetElement_CharacterMasteredCombatSkills(charId, masteredSkills, context);
			}
		}
		else if (masteredSkills.Items != null && masteredSkills.Items.Count > 0)
		{
			AddElement_CharacterMasteredCombatSkills(charId, masteredSkills, context);
		}
		UpdateCombatSkillRequirementPercent(context, charId, masteredSkills.Items);
		if (charId == DomainManager.Taiwu.GetTaiwuCharId())
		{
			int currPlanId = DomainManager.Taiwu.GetCurrCombatSkillPlanId();
			SetElement_MasteredCombatSkillPlans(currPlanId, masteredSkills, context);
		}
	}

