	public void UpdateTaiwuMasteredCombatSkillsByPlan(DataContext context)
	{
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		int planId = DomainManager.Taiwu.GetCurrCombatSkillPlanId();
		GameData.Utilities.ShortList currPlan = _masteredCombatSkillPlans[planId];
		List<short> items = currPlan.Items;
		bool currPlanExist = items != null && items.Count > 0;
		GameData.Utilities.ShortList prevPlan;
		bool prevPlanExist = _characterMasteredCombatSkills.TryGetValue(taiwuCharId, out prevPlan);
		if (prevPlanExist)
		{
			RemoveElement_CharacterMasteredCombatSkills(taiwuCharId, context);
		}
		if (currPlanExist)
		{
			for (int i = currPlan.Items.Count - 1; i >= 0; i--)
			{
				short skillTemplateId = currPlan.Items[i];
				sbyte gridCost = taiwu.GetCombatSkillGridCost(skillTemplateId);
				if (gridCost <= 1)
				{
					currPlan.Items.RemoveAt(i);
				}
			}
			AddElement_CharacterMasteredCombatSkills(taiwuCharId, currPlan, context);
		}
		HashSet<short> shouldUpdateSkillIds = ObjectPool<HashSet<short>>.Instance.Get();
		shouldUpdateSkillIds.Clear();
		if (currPlanExist)
		{
			foreach (short skillId in currPlan.Items)
			{
				shouldUpdateSkillIds.Add(skillId);
			}
		}
		if (prevPlanExist && prevPlan.Items != null)
		{
			foreach (short skillId2 in prevPlan.Items)
			{
				shouldUpdateSkillIds.Add(skillId2);
			}
		}
		UpdateCombatSkillRequirementPercent(context, taiwuCharId, shouldUpdateSkillIds);
		ObjectPool<HashSet<short>>.Instance.Return(shouldUpdateSkillIds);
	}

	public void CopyTaiwuCombatSkillsPlan(DataContext context, int srcPlanId, int dstPlanId)
	{
		GameData.Utilities.ShortList srcPlan = _masteredCombatSkillPlans[srcPlanId];
		GameData.Utilities.ShortList dstPlan = _masteredCombatSkillPlans[dstPlanId];
		dstPlan.Items?.Clear();
		List<short> items = srcPlan.Items;
		if (items != null && items.Count > 0)
		{
			ref List<short> items2 = ref dstPlan.Items;
			if (items2 == null)
			{
				items2 = new List<short>();
			}
			dstPlan.Items.AddRange(srcPlan.Items);
		}
		SetElement_MasteredCombatSkillPlans(dstPlanId, dstPlan, context);
		GameData.Utilities.ShortList srcOrderPlan = _combatSkillOrderPlans.GetOrDefault(srcPlanId);
		GameData.Utilities.ShortList dstOrderPlan = _combatSkillOrderPlans.GetOrDefault(dstPlanId);
		dstOrderPlan.Items?.Clear();
		items = srcOrderPlan.Items;
		if (items != null && items.Count > 0)
		{
			ref List<short> items2 = ref dstOrderPlan.Items;
			if (items2 == null)
			{
				items2 = new List<short>();
			}
			dstOrderPlan.Items.AddRange(srcOrderPlan.Items);
		}
		SetCombatSkillOrderPlan(context, dstPlanId, dstOrderPlan);
	}

	public void DeleteTaiwuCombatSkillsPlan(DataContext context, int planId)
	{
		GameData.Utilities.ShortList plan = _masteredCombatSkillPlans[planId];
		plan.Items?.Clear();
		for (int i = planId; i < 8; i++)
		{
			SetElement_MasteredCombatSkillPlans(i, _masteredCombatSkillPlans[i + 1], context);
		}
		SetElement_MasteredCombatSkillPlans(8, plan, context);
		_combatSkillOrderPlans.GetOrDefault(planId).Items?.Clear();
		for (int j = planId; j < 8; j++)
		{
			SetCombatSkillOrderPlan(context, j, _combatSkillOrderPlans.GetOrDefault(j + 1));
		}
		SetCombatSkillOrderPlan(context, 8, plan);
	}

	private void UpdateCombatSkillRequirementPercent(DataContext context, int charId, IEnumerable<short> skillIds)
