		foreach (short skillTemplateId in skillIds)
		{
			if (charCombatSkills.TryGetValue(skillTemplateId, out var combatSkill))
			{
				combatSkill.InvalidateSelfAndInfluencedCache(11, context);
			}
		}
	}

	public int ChangeCombatSkillProficiency(DataContext context, CombatSkillKey key, int delta)
	{
		int oldValue = _combatSkillProficiencies.GetOrDefault(key);
		int newValue = Math.Clamp(oldValue + delta, 0, 999999999);
		if (newValue == oldValue)
		{
			return 0;
		}
		if (_combatSkillProficiencies.ContainsKey(key))
		{
			SetElement_CombatSkillProficiencies(key, newValue, context);
		}
		else
		{
			AddElement_CombatSkillProficiencies(key, newValue, context);
		}
		if (newValue >= 999 && key.CharId == DomainManager.Taiwu.GetTaiwuCharId())
		{
			AchievementManager.RequestSetStat(context, 147, 1);
		}
		if (DomainManager.CombatSkill.TryGetElement_CombatSkills(key, out var skill))
		{
			skill.SetActivationState(skill.GetActivationState(), context);
		}
		if (key.CharId == DomainManager.Taiwu.GetTaiwuCharId() && newValue >= GlobalConfig.Instance.SkillProficiencyIsEnoughToGainLegacyPoint && !_proficiencyEnoughSkills.Contains(key.SkillTemplateId))
		{
			AddElement_ProficiencyEnoughSkills(key.SkillTemplateId, default(VoidValue), context);
			DomainManager.Taiwu.AddLegacyPoint(context, 23);
		}
		return newValue - oldValue;
	}

	public void UpdateCombatSkillProficiency(DataContext context, GameData.Domains.Character.Character character)
	{
		int charId = character.GetId();
		int maxCount = 9;
		int maxDelta = (OrganizationDomain.IsSect(character.GetOrganizationInfo().OrgTemplateId) ? GlobalConfig.UpdateProficiencyMaxDelta[0] : GlobalConfig.UpdateProficiencyMaxDelta[1]) + 1;
		Dictionary<short, GameData.Domains.CombatSkill.CombatSkill> combatSkills = DomainManager.CombatSkill.GetCharCombatSkills(charId);
		if (combatSkills.Count <= maxCount)
		{
			foreach (short skillId in combatSkills.Keys)
			{
				ChangeCombatSkillProficiency(context, new CombatSkillKey(charId, skillId), context.Random.Next(0, maxDelta));
			}
			return;
		}
		List<(short, short)> weightTable = context.AdvanceMonthRelatedData.WeightTable.Occupy();
		weightTable.Clear();
		foreach (short skillId2 in combatSkills.Keys)
		{
			sbyte grade = Config.CombatSkill.Instance[skillId2].Grade;
			weightTable.Add((skillId2, (short)((grade + 1) * (grade + 1))));
		}
		for (int i = 0; i < maxCount; i++)
		{
			int index = RandomUtils.GetRandomIndex(weightTable, context.Random);
			short skillId3 = weightTable[index].Item1;
			ChangeCombatSkillProficiency(context, new CombatSkillKey(charId, skillId3), context.Random.Next(0, maxDelta));
			weightTable.RemoveAt(index);
		}
		context.AdvanceMonthRelatedData.WeightTable.Release(ref weightTable);
	}

	public void InitCombatSkillProficiency(DataContext context, GameData.Domains.Character.Character character)
	{
		int birthDate = character.GetBirthDate();
		int monthCount = DomainManager.World.GetCurrDate() - birthDate - GlobalConfig.Instance.AgeBaby * 12;
		if (monthCount <= 0)
		{
			return;
		}
		int charId = character.GetId();
		Dictionary<short, GameData.Domains.CombatSkill.CombatSkill> combatSkills = DomainManager.CombatSkill.GetCharCombatSkills(charId);
		if (combatSkills.Count == 0)
		{
			return;
		}
		int maxCount = 9;
		int maxDelta = (OrganizationDomain.IsSect(character.GetOrganizationInfo().OrgTemplateId) ? GlobalConfig.UpdateProficiencyMaxDelta[0] : GlobalConfig.UpdateProficiencyMaxDelta[1]);
		int totalDelta = monthCount * maxCount * maxDelta;
		int prob = Math.Min(100, maxCount * 100 / combatSkills.Count);
		foreach (short skillId in combatSkills.Keys)
		{
			int maxVal = Math.Min(monthCount * maxDelta * prob / 100, totalDelta) + 1;
			int delta = context.Random.Next(0, maxVal);
			ChangeCombatSkillProficiency(context, new CombatSkillKey(charId, skillId), delta);
			totalDelta -= delta;
			if (totalDelta <= 0)
			{
				break;
			}
		}
	}

	public void CopyCombatSkillProficiency(DataContext context, int charIdA, int charIdB)
	{
		Dictionary<short, GameData.Domains.CombatSkill.CombatSkill> combatSkills = DomainManager.CombatSkill.GetCharCombatSkills(charIdA);
		foreach (short skillId in combatSkills.Keys)
		{
			CombatSkillKey keyA = new CombatSkillKey(charIdA, skillId);
			if (_combatSkillProficiencies.TryGetValue(keyA, out var val))
			{
				CombatSkillKey keyB = new CombatSkillKey(charIdB, skillId);
				SetCombatSkillProficiency(context, keyB, val);
			}
		}
	}

