	public void TransferTaiwuProficiency(DataContext context, int oldTaiwuCharId, int newTaiwuCharId)
	{
		List<short> removeTargets = ObjectPool<List<short>>.Instance.Get();
		List<short> transferTargets = ObjectPool<List<short>>.Instance.Get();
		foreach (CombatSkillKey key in _combatSkillProficiencies.Keys)
		{
			if (key.CharId == newTaiwuCharId)
			{
				removeTargets.Add(key.SkillTemplateId);
			}
			if (key.CharId == oldTaiwuCharId)
			{
				transferTargets.Add(key.SkillTemplateId);
			}
		}
		foreach (short skillId in removeTargets)
		{
			if (!transferTargets.Contains(skillId))
			{
				CombatSkillKey key2 = new CombatSkillKey(newTaiwuCharId, skillId);
				RemoveElement_CombatSkillProficiencies(key2, context);
			}
		}
		foreach (short skillId2 in transferTargets)
		{
			CombatSkillKey oldKey = new CombatSkillKey(oldTaiwuCharId, skillId2);
			int value = _combatSkillProficiencies[oldKey];
			RemoveElement_CombatSkillProficiencies(oldKey, context);
			CombatSkillKey newKey = new CombatSkillKey(newTaiwuCharId, skillId2);
			if (removeTargets.Contains(skillId2))
			{
				SetElement_CombatSkillProficiencies(newKey, value, context);
			}
			else
			{
				AddElement_CombatSkillProficiencies(newKey, value, context);
			}
		}
		ObjectPool<List<short>>.Instance.Return(removeTargets);
		ObjectPool<List<short>>.Instance.Return(transferTargets);
	}

	public short GetJumpThreshold(short combatSkillId)
	{
		if (!CombatSkillJumpThresholdIsValid(combatSkillId))
		{
			return -1;
		}
		short threshold;
		return _combatSkillJumpThreshold.TryGetValue(combatSkillId, out threshold) ? threshold : GlobalConfig.Instance.DefaultJumpThreshold;
	}

	public bool SetJumpThreshold(DataContext context, short combatSkillId, short threshold)
	{
		if (threshold <= 0)
		{
			return false;
		}
		if (!CombatSkillJumpThresholdIsValid(combatSkillId))
		{
			return false;
		}
		if (_combatSkillJumpThreshold.ContainsKey(combatSkillId))
		{
			SetElement_CombatSkillJumpThreshold(combatSkillId, threshold, context);
		}
		else
		{
			AddElement_CombatSkillJumpThreshold(combatSkillId, threshold, context);
		}
		return true;
	}

	private bool CombatSkillJumpThresholdIsValid(short combatSkillId)
	{
		if (!DomainManager.CombatSkill.GetBreakSuccess(DomainManager.Taiwu.GetTaiwuCharId(), combatSkillId))
		{
			return false;
		}
		CombatSkillItem combatSkillItem = Config.CombatSkill.Instance[combatSkillId];
		return combatSkillItem != null && combatSkillItem.MaxJumpDistance > 0;
	}

