	[DomainMethod]
	public bool CanIdentifyCricket(int cricketId)
	{
		GameData.Domains.Item.Cricket cricket = DomainManager.Item.GetElement_Crickets(cricketId);
		ItemKey cricketKey = cricket.GetItemKey();
		ItemDisplayData cricketData = DomainManager.Item.GetItemDisplayData(cricketKey);
		if (IsCricketIdentified(cricketId) || !cricket.IsAlive || ItemTemplateHelper.GetCricketGrade(cricketData.CricketColorId, cricketData.CricketPartId) >= 7 || CricketParts.Instance[cricket.GetColorId()].Type == ECricketPartsType.Trash || EventHelper.IsCricketGreat(cricketKey))
		{
			return false;
		}
		return true;
	}

	[DomainMethod]
	public bool CanUpgradeCricket(int cricketId)
	{
		GameData.Domains.Item.Cricket cricket = DomainManager.Item.GetElement_Crickets(cricketId);
		ItemKey cricketKey = cricket.GetItemKey();
		ItemDisplayData cricketData = DomainManager.Item.GetItemDisplayData(cricketKey);
		if (!IsCricketIdentified(cricketId) || !IsCricketSmart(cricketId) || !cricket.IsAlive || ItemTemplateHelper.GetCricketGrade(cricketData.CricketColorId, cricketData.CricketPartId) >= 7 || CricketParts.Instance[cricket.GetColorId()].Type == ECricketPartsType.Trash)
		{
			return false;
		}
		int seniorityPercent = GetProfessionData(17).GetSeniorityPercent();
		int requireWinCount = 100 - seniorityPercent / 2;
		return cricket.GetWinsCount() - cricket.GetLossesCount() >= requireWinCount;
	}

	public ItemKey UpgradeCricket(DataContext context, int charId, int cricketId)
	{
		GameData.Domains.Item.Cricket cricket = DomainManager.Item.GetElement_Crickets(cricketId);
		if (!CanUpgradeCricket(cricketId) || !CricketUpgradeRandomPool.ContainsKey(cricket.GetColorData().Type))
		{
			return ItemKey.Invalid;
		}
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		List<short> typeRandomPool = CricketUpgradeRandomPool[cricket.GetColorData().Type];
		short newColorType = typeRandomPool[context.Random.Next(typeRandomPool.Count)];
		ItemKey newKey = DomainManager.Item.CreateCricket(context, newColorType, 0);
		GameData.Domains.Item.Cricket newCricket = DomainManager.Item.GetElement_Crickets(newKey.Id);
		newCricket.SetCurrDurability(cricket.GetCurrDurability(), context);
		newCricket.SetAgeProgress(cricket.GetAgeProgress(), context);
		newCricket.SetSpirit(cricket.GetSpirit(), context);
		newCricket.SetSpiritAddProperties(cricket.GetSpiritAddProperties(), context);
		newCricket.SetOriginState(cricket.GetOriginState(), context);
		newCricket.SetWinsCount(cricket.GetWinsCount(), context);
		newCricket.SetLossesCount(cricket.GetLossesCount(), context);
		newCricket.SetBestEnemyColorId(cricket.GetBestEnemyColorId(), context);
		newCricket.SetBestEnemyPartId(cricket.GetBestEnemyPartId(), context);
		character.RemoveInventoryItem(context, cricket.GetItemKey(), 1, deleteItem: true);
		character.AddInventoryItem(context, newKey, 1);
		DomainManager.Taiwu.ReplaceCricketPlan(context, cricket.GetItemKey(), newKey);
		return newKey;
	}

	public void AdjustCricketExtraAge(DataContext context, int cricketId, short delta)
	{
		if (!_cricketExtraAge.Keys.Contains(cricketId))
		{
			DomainManager.Extra.AddElement_CricketExtraAge(cricketId, delta, context);
			return;
		}
		short nowValue = (short)(_cricketExtraAge[cricketId] + delta);
		DomainManager.Extra.SetElement_CricketExtraAge(cricketId, nowValue, context);
	}

