	private bool CheckCricketIsSmart(IRandomSource random, ItemKey cricketKey)
	{
		GameData.Domains.Item.Cricket cricket = DomainManager.Item.GetElement_Crickets(cricketKey.Id);
		if (ItemTemplateHelper.GetCricketGrade(cricket.GetColorId(), cricket.GetPartId()) >= 7 || CricketParts.Instance[DomainManager.Item.GetElement_Crickets(cricketKey.Id).GetColorId()].Type == ECricketPartsType.Trash)
		{
			return false;
		}
		return random.CheckPercentProb(20);
	}

	private void InitTaiwuSelectedDebateCardType(DataContext context)
	{
		List<sbyte> types = DebateGameGetPlayerSelectedStrategyCardTypes(DomainManager.Taiwu.GetTaiwuCharId());
		int res = 0;
		if (types != null)
		{
			foreach (sbyte type in types)
			{
				res |= 1 << (int)type;
			}
		}
		SetTaiwuSelectedDebateCardType(res, context);
	}

	public List<sbyte> DebateGameGetPlayerSelectedStrategyCardTypes(int charId)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		List<(sbyte, short)> types = new List<(sbyte, short)>();
		List<sbyte> res = new List<sbyte>();
		for (sbyte i = 0; i < 16; i++)
		{
			types.Add((i, character.GetLifeSkillAttainment(i)));
		}
		types.Sort(DebateGameCompareDebaterAttainment);
		for (int j = 0; j < DebateConstants.CardTypeLimit; j++)
		{
			res.Add(types[j].Item1);
		}
		return res;
	}

	private int DebateGameCompareDebaterAttainment((sbyte, short) a, (sbyte, short) b)
	{
		return -a.Item2.CompareTo(b.Item2);
	}

