	private void InitializeDreamBackLifeRecordsCacheData()
	{
		_dreamBackLifeRecordsTaiwuRelatedCharacters = new Dictionary<int, short>();
		int index = -1;
		int offset = -1;
		while (_dreamBackLifeRecords.Next(ref index, ref offset))
		{
			var (charId, templateId) = _dreamBackLifeRecords.GetDreamBackRelatedCharacterId(offset);
			if (GameData.Domains.Character.Character.IsCharacterIdValid(charId) && (!_dreamBackLifeRecordsTaiwuRelatedCharacters.ContainsKey(charId) || _dreamBackLifeRecordsTaiwuRelatedCharacters[charId] > templateId))
			{
				_dreamBackLifeRecordsTaiwuRelatedCharacters[charId] = templateId;
			}
		}
	}

