	public void InitFeasts(DataContext context)
	{
		List<ulong> keys = new List<ulong>();
		foreach (ulong key in _feasts.Keys)
		{
			keys.Add(key);
		}
		foreach (ulong key2 in keys)
		{
			RemoveElement_Feasts(key2, context);
		}
		Dictionary<BuildingBlockKey, CharacterList> houses = DomainManager.Building.GetAllComfortableHouses();
		foreach (BuildingBlockKey blockKey in houses.Keys)
		{
			SetFeast(context, blockKey, GetFeast(blockKey));
		}
	}

	public IReadOnlyDictionary<ulong, GameData.Domains.Building.Feast> GetAllFeasts()
	{
		return _feasts;
	}

	[DomainMethod]
	public GameData.Domains.Building.Feast GetFeast(BuildingBlockKey blockKey)
	{
		GameData.Domains.Building.Feast feast;
		return TryGetElement_Feasts((ulong)blockKey, out feast) ? feast : new GameData.Domains.Building.Feast(blockKey);
	}

	public void SetFeast(DataContext context, BuildingBlockKey blockKey, GameData.Domains.Building.Feast feast)
	{
		ulong key = (ulong)blockKey;
		if (_feasts.ContainsKey(key))
		{
			SetElement_Feasts(key, feast, context);
		}
		else
		{
			AddElement_Feasts(key, feast, context);
		}
	}

	public void RemoveFeast(DataContext context, BuildingBlockKey blockKey)
	{
		FeastReceiveGift(context, blockKey, -1);
		for (int i = 0; i < GlobalConfig.Instance.FeastCount; i++)
		{
			FeastRemoveDish(context, blockKey, i);
		}
		ulong key = (ulong)blockKey;
		if (_feasts.ContainsKey(key))
		{
			RemoveElement_Feasts(key, context);
		}
	}

	[DomainMethod]
	public void FeastRemoveDish(DataContext context, BuildingBlockKey blockKey, int index, ItemSourceType sourceType = ItemSourceType.Invalid)
	{
		GameData.Domains.Building.Feast feast = GetFeast(blockKey);
		ItemKey dish = feast.GetDish(index);
		if (!dish.IsValid())
		{
			return;
		}
		feast.DishDurability.Remove(index, out var durability);
		feast.Dish[index] = ItemKey.Invalid;
		DomainManager.Item.RemoveOwner(dish, ItemOwnerType.Building, 47);
		if (durability < GlobalConfig.Instance.FeastDurability)
		{
			DomainManager.Item.RemoveItem(context, dish);
		}
		else
		{
			if (sourceType == ItemSourceType.Invalid)
			{
				sourceType = DomainManager.Building.ApplyBuildingItemOutputSetting(feast.BuildingBlockKey, dish);
			}
			DomainManager.Taiwu.AddItem(context, dish, 1, sourceType);
		}
		SetFeast(context, blockKey, feast);
	}

	[DomainMethod]
	public void FeastAddDish(DataContext context, BuildingBlockKey blockKey, int index, ItemKey itemKey, ItemSourceType sourceType)
	{
		GameData.Domains.Building.Feast feast = GetFeast(blockKey);
		if (feast.GetDish(index).IsValid())
		{
			FeastRemoveDish(context, blockKey, index, sourceType);
		}
		feast.Dish[index] = itemKey;
		feast.DishDurability[index] = GlobalConfig.Instance.FeastDurability;
		DomainManager.Taiwu.RemoveItem(context, itemKey, 1, sourceType, deleteItem: false);
		DomainManager.Item.SetOwner(itemKey, ItemOwnerType.Building, 47);
		SetFeast(context, blockKey, feast);
	}

	[DomainMethod]
	public bool IsFeastException(DataContext context, BuildingBlockKey blockKey)
	{
		GameData.Domains.Building.Feast feast = GetFeast(blockKey);
		if (!DomainManager.Building.TryGetElement_BuildingBlocks(blockKey, out var buildingBlock))
		{
			return false;
		}
		if (!buildingBlock.CanUse())
		{
			return false;
		}
		return feast.GetInUseDishSlotCount() <= 0;
	}

	[DomainMethod]
	public void FeastSetAutoRefill(DataContext context, BuildingBlockKey blockKey, bool value)
	{
		GameData.Domains.Building.Feast feast = GetFeast(blockKey);
		feast.AutoRefill = value;
		SetFeast(context, blockKey, feast);
	}

	[DomainMethod]
	public void FeastQuickRefill(DataContext context, BuildingBlockKey blockKey)
	{
		List<int> indexes = new List<int>();
		List<ItemKey> items = new List<ItemKey>();
		GameData.Domains.Building.Feast feast = GetFeast(blockKey);
		if (DomainManager.Building.BuildingBlockLevel(feast.BuildingBlockKey) != 0)
		{
			List<int> characters = DomainManager.Building.GetCharsInComfortableHouse(context, feast.BuildingBlockKey).GetCollection();
			FeastAutoRefill(context, feast, items, indexes, characters);
		}
	}

	[DomainMethod]
	public void FeastSetTargetType(DataContext context, BuildingBlockKey blockKey, short targetType)
	{
		GameData.Domains.Building.Feast feast = GetFeast(blockKey);
		feast.TargetType = targetType;
		SetFeast(context, blockKey, feast);
	}

	[DomainMethod]
	public void FeastReceiveGift(DataContext context, BuildingBlockKey blockKey, int index)
	{
		GameData.Domains.Building.Feast feast = GetFeast(blockKey);
		if (index >= 0)
		{
			ReceiveGift(context, feast, index);
		}
		else
		{
			for (int i = 0; i < GlobalConfig.Instance.FeastGiftCount; i++)
			{
				ReceiveGift(context, feast, i);
			}
		}
		SetFeast(context, blockKey, feast);
	}

	public void FeastAddGift(DataContext context, GameData.Domains.Building.Feast feast, ItemKey itemKey, int amount)
	{
		if (feast.GetInUseGiftSlotCount() >= GlobalConfig.Instance.FeastGiftCount)
		{
			FeastReceiveGift(context, feast.BuildingBlockKey, -1);
		}
		for (int i = 0; i < GlobalConfig.Instance.FeastGiftCount; i++)
		{
			if (feast.GetGift(i) == ItemKey.Invalid)
			{
				feast.Gift[i] = itemKey;
				feast.GiftCount[i] = amount;
				break;
			}
		}
		SetFeast(context, feast.BuildingBlockKey, feast);
	}

	public void FeastAdvanceMonth(DataContext context)
	{
		DomainManager.Building.ClearFeastParticipants();
		List<int> indexes = new List<int>();
		List<ItemKey> items = new List<ItemKey>();
		foreach (var (blockKey, feast2) in _feasts)
		{
			if (DomainManager.Building.BuildingBlockLevel(feast2.BuildingBlockKey) != 0)
			{
				List<int> characters = DomainManager.Building.GetCharsInComfortableHouse(context, feast2.BuildingBlockKey).GetCollection();
				for (int index = characters.Count - 1; index >= 0; index--)
				{
					DomainManager.Building.TryRemoveFeastCustomer(context, characters[index]);
				}
				if (feast2.AutoRefill)
				{
					FeastAutoRefill(context, feast2, items, indexes, characters);
				}
				FeastResidentTryEat(context, feast2, items, indexes, characters);
			}
		}
	}

	public void ExchangeFeast(DataContext context, BuildingBlockKey keyA, BuildingBlockKey keyB)
	{
		ulong idA = (ulong)keyA;
		ulong idB = (ulong)keyB;
		GameData.Domains.Building.Feast dataA;
		bool hasA = TryGetElement_Feasts(idA, out dataA);
		GameData.Domains.Building.Feast dataB;
		bool hasB = TryGetElement_Feasts(idB, out dataB);
		if (hasA && hasB)
		{
			RemoveElement_Feasts(idA, context);
			RemoveElement_Feasts(idB, context);
			dataA.BuildingBlockKey = keyB;
			dataB.BuildingBlockKey = keyA;
			AddElement_Feasts(idB, dataA, context);
			AddElement_Feasts(idA, dataB, context);
		}
		else if (hasA)
		{
			RemoveElement_Feasts(idA, context);
			dataA.BuildingBlockKey = keyB;
			AddElement_Feasts(idB, dataA, context);
		}
		else if (hasB)
		{
			RemoveElement_Feasts(idB, context);
			dataB.BuildingBlockKey = keyA;
			AddElement_Feasts(idA, dataB, context);
		}
	}

	private void ReceiveGift(DataContext context, GameData.Domains.Building.Feast feast, int index)
	{
		ItemKey gift = feast.GetGift(index);
		if (gift == ItemKey.Invalid)
		{
			return;
		}
		ItemSourceType sourceType = DomainManager.Building.ApplyBuildingItemOutputSetting(feast.BuildingBlockKey, gift);
		feast.GiftCount.Remove(index, out var amount);
		feast.Gift[index] = ItemKey.Invalid;
		if (ItemTemplateHelper.IsMiscResource(gift.ItemType, gift.TemplateId))
		{
			if (sourceType == ItemSourceType.Treasury)
			{
				DomainManager.Taiwu.StoreResourceInTreasury(context, ItemTemplateHelper.GetMiscResourceType(gift.ItemType, gift.TemplateId), amount);
			}
			else
			{
				DomainManager.Taiwu.GetTaiwu().ChangeResource(context, ItemTemplateHelper.GetMiscResourceType(gift.ItemType, gift.TemplateId), amount);
			}
			return;
		}
		if (gift.IsValid())
		{
			DomainManager.Item.RemoveOwner(gift, ItemOwnerType.Building, 47);
		}
		if (ItemTemplateHelper.IsThanksLetter(gift.ItemType, gift.TemplateId))
		{
			if (!gift.IsValid())
			{
				gift = DomainManager.Item.CreateMisc(context, gift.TemplateId);
			}
			sourceType = ItemSourceType.Inventory;
		}
		DomainManager.Taiwu.AddItem(context, gift, amount, sourceType);
	}

	[DomainMethod]
	public void UseFeastThanksLetter(DataContext context, ItemKey itemKey, int amount)
	{
		MiscItem config = Config.Misc.Instance[itemKey.TemplateId];
		if (config != null)
		{
			DomainManager.Taiwu.GetTaiwu().ChangeExp(context, config.GainExp * amount);
			DomainManager.Taiwu.RemoveItem(context, itemKey, amount, ItemSourceType.Inventory, deleteItem: true);
		}
	}

	private void FeastAutoRefill(DataContext context, GameData.Domains.Building.Feast feast, List<ItemKey> items, List<int> diet, List<int> characters)
	{
		if (feast.IsFull)
		{
			return;
		}
		bool noDrinking = false;
		bool noMeatEating = false;
		Inventory inventory = DomainManager.Taiwu.Stock;
		bool randomAll = false;
		bool ignoreHate = feast.TargetType >= 0 && Config.Feast.Instance[feast.TargetType].IgnoreHate;
		diet.Clear();
		foreach (int charId in characters)
		{
			if (DomainManager.Character.TryGetElement_Objects(charId, out var character))
			{
				if (!ignoreHate)
				{
					diet.Add(character.GetHatingItemSubType());
				}
				noDrinking = noDrinking || character.IsForbiddenToDrinkingWines();
				noMeatEating = noMeatEating || character.IsForbiddenToEatMeat();
			}
		}
		for (int i = 0; i < GlobalConfig.Instance.FeastCount; i++)
		{
			if (feast.GetDish(i).IsValid())
			{
				continue;
			}
			items.Clear();
			if (!randomAll)
			{
				foreach (ItemKey itemKey in inventory.Items.Keys)
				{
					short subtype = ItemTemplateHelper.GetItemSubType(itemKey.ItemType, itemKey.TemplateId);
					if (diet.Contains(subtype))
					{
						continue;
					}
					if (itemKey.ItemType == 9)
					{
						if (subtype != 901 || !noDrinking)
						{
							items.Add(itemKey);
						}
					}
					else if (itemKey.ItemType == 7 && (subtype != 701 || !noMeatEating))
					{
						items.Add(itemKey);
					}
				}
				if (items.Count == 0)
				{
					randomAll = true;
					FeastAddRandomDishFromStock(context, feast, inventory, items, i);
				}
				else
				{
					FeastAddDishFromList(context, feast, items, i);
				}
			}
			else
			{
				FeastAddRandomDishFromStock(context, feast, inventory, items, i);
			}
		}
	}

	private void FeastAddRandomDishFromStock(DataContext context, GameData.Domains.Building.Feast feast, Inventory inventory, List<ItemKey> items, int index)
	{
		foreach (ItemKey itemKey in inventory.Items.Keys)
		{
			if (itemKey.ItemType == 9)
			{
				items.Add(itemKey);
			}
			else if (itemKey.ItemType == 7)
			{
				items.Add(itemKey);
			}
		}
		FeastAddDishFromList(context, feast, items, index);
	}

	private void FeastAddDishFromList(DataContext context, GameData.Domains.Building.Feast feast, List<ItemKey> items, int index)
	{
		if (items.Count == 0)
		{
			return;
		}
		if (feast.TargetType >= 0)
		{
			FeastItem targetConfig = Config.Feast.Instance[feast.TargetType];
			int totalCount = targetConfig.RequirementData.Sum((int[] d) => d[0]);
			int remainCount = totalCount;
			sbyte lowestGrade = sbyte.MaxValue;
			List<EFoodFoodType> foodTypeList = new List<EFoodFoodType>();
			Dictionary<EFoodFoodType, int> countByFoodType = new Dictionary<EFoodFoodType, int>();
			Dictionary<short, int> countBySubType = new Dictionary<short, int>();
			foreach (var (slotIndex, itemKey2) in feast.Dish)
			{
				if (!itemKey2.HasTemplate)
				{
					continue;
				}
				lowestGrade = Math.Min(lowestGrade, ItemTemplateHelper.GetGrade(itemKey2.ItemType, itemKey2.TemplateId));
				GameData.Domains.Building.Feast.GetFoodTypeList(itemKey2, foodTypeList);
				foreach (EFoodFoodType foodType in foodTypeList)
				{
					countByFoodType.TryGetValue(foodType, out var foodTypeCount);
					countByFoodType[foodType] = foodTypeCount + 1;
				}
				short subType = ItemTemplateHelper.GetItemSubType(itemKey2.ItemType, itemKey2.TemplateId);
				countBySubType.TryGetValue(subType, out var subTypeCount);
				countBySubType[subType] = subTypeCount + 1;
			}
			bool canReachTarget = true;
			ItemKey addDish = ItemKey.Invalid;
			for (int i = 0; i < targetConfig.RequirementType.Count; i++)
			{
				EFeastRequirementType requirementType = targetConfig.RequirementType[i];
				int[] requirementData = targetConfig.RequirementData[i];
				int requirementCount = requirementData[0];
				int requirementGrade = requirementData[1];
				EFoodFoodType targetFoodType = GameData.Domains.Building.Feast.GetFoodType(requirementType);
				int curFoodCount = ((requirementType == EFeastRequirementType.SubTypeDiff) ? countBySubType.Values.Sum() : countByFoodType.GetOrDefault(targetFoodType));
				remainCount -= curFoodCount;
				bool typeIsMeet = ((requirementType == EFeastRequirementType.SubTypeDiff) ? countBySubType.All((KeyValuePair<short, int> p) => p.Value <= 1) : (remainCount >= 1));
				bool gradeIsMeet = lowestGrade >= requirementGrade;
				if (!typeIsMeet || !gradeIsMeet)
				{
					canReachTarget = false;
					break;
				}
				int needCount = requirementCount - curFoodCount;
				int ownedCount = ((requirementType == EFeastRequirementType.SubTypeDiff) ? (from k in items
					group k by ItemTemplateHelper.GetItemSubType(k.ItemType, k.TemplateId) into g
					select g.Key).Distinct().ToList().Count : items.Count((ItemKey k) => GameData.Domains.Building.Feast.GetFoodTypeList(k, foodTypeList).Contains(targetFoodType) && ItemTemplateHelper.GetGrade(k.ItemType, k.TemplateId) >= requirementGrade));
				if (ownedCount < needCount)
				{
					canReachTarget = false;
					break;
				}
				ItemKey findItem = ((requirementType == EFeastRequirementType.SubTypeDiff) ? items.FirstOrDefault((ItemKey k) => ItemTemplateHelper.GetGrade(k.ItemType, k.TemplateId) >= requirementGrade && !countBySubType.ContainsKey(ItemTemplateHelper.GetItemSubType(k.ItemType, k.TemplateId)), ItemKey.Invalid) : items.FirstOrDefault((ItemKey k) => ItemTemplateHelper.GetGrade(k.ItemType, k.TemplateId) >= requirementGrade && GameData.Domains.Building.Feast.GetFoodTypeList(k, foodTypeList).Contains(targetFoodType), ItemKey.Invalid));
				if (!findItem.IsValid())
				{
					canReachTarget = false;
					break;
				}
				addDish = findItem;
			}
			if (canReachTarget)
			{
				FeastAddDish(context, feast.BuildingBlockKey, index, addDish, ItemSourceType.Stock);
				return;
			}
		}
		FeastAddDish(context, feast.BuildingBlockKey, index, items[context.Random.Next(items.Count)], ItemSourceType.Stock);
	}

	private void FeastResidentTryEat(DataContext context, GameData.Domains.Building.Feast feast, List<ItemKey> items, List<int> indexes, List<int> characters)
	{
		if (feast.CheckAvoidAutoCheckIn())
		{
			return;
		}
		short feastType = feast.GetFeastType();
		AddUnlockedFestType(context, feastType);
		foreach (int charId in characters)
		{
			if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
			{
				continue;
			}
			if (character.GetEatingItems().GetAvailableEatingSlot(character.GetCurrMaxEatingSlotsCount()) < 0)
			{
				ShopEventCollection shopEventCollection = DomainManager.Building.GetOrCreateShopEventCollection(feast.BuildingBlockKey);
				LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
				shopEventCollection.AddBanquet_10(DomainManager.World.GetCurrDate(), charId);
				lifeRecordCollection.AddBanquet_10(charId, DomainManager.World.GetCurrDate());
				continue;
			}
			int hating = (Config.Feast.Instance[feastType].IgnoreHate ? (-1) : character.GetHatingItemSubType());
			bool noDrinking = character.IsForbiddenToDrinkingWines();
			bool noMeatEating = character.IsForbiddenToEatMeat();
			indexes.Clear();
			for (int i = 0; i < GlobalConfig.Instance.FeastCount; i++)
			{
				ItemKey dish = feast.GetDish(i);
				if (dish.IsValid())
				{
					short itemSubType = ItemTemplateHelper.GetItemSubType(dish.ItemType, dish.TemplateId);
					if (hating != itemSubType && (!noDrinking || itemSubType != 901) && (!noMeatEating || itemSubType != 701))
					{
						indexes.Add(i);
					}
				}
			}
			if (indexes.Count > 0)
			{
				FeastEatDish(context, feast, items, indexes, character, feastType, characters);
			}
		}
	}

	private void FeastEatDish(DataContext context, GameData.Domains.Building.Feast feast, List<ItemKey> items, List<int> indexes, GameData.Domains.Character.Character character, short feastType, List<int> characters)
	{
		int index = indexes[context.Random.Next(indexes.Count)];
		ItemKey dish = feast.GetDish(index);
		ItemKey dishCopy = DomainManager.Item.CreateCopyOfItem(context, dish);
		int characterId = character.GetId();
		sbyte grade = ItemTemplateHelper.GetGrade(dish.ItemType, dish.TemplateId);
		int happiness = GlobalConfig.Instance.FeastBaseHappiness[grade];
		int favor = GlobalConfig.Instance.FeastBaseFaovr[grade];
		sbyte level = DomainManager.Building.BuildingBlockLevel(feast.BuildingBlockKey);
		int happinessB = GlobalConfig.Instance.FeastBuildingLevelHappinessPercent[level - 1];
		int favorB = GlobalConfig.Instance.FeastBuildingLevelFavorPercent[level - 1];
		FeastItem config = Config.Feast.Instance[feastType];
		bool loveItem = config.ForceLove || character.GetLovingItemSubType() == ItemTemplateHelper.GetItemSubType(dish.ItemType, dish.TemplateId);
		if (loveItem)
		{
			happinessB += GlobalConfig.Instance.FeastLoveItemHappinessPercent;
			favorB += GlobalConfig.Instance.FeastLoveItemFavorPercent;
		}
		happinessB += config.HappinessPercent;
		favorB += config.FavorPercent;
		happiness = happiness * happinessB / 100;
		favor = favor * favorB / 100;
		character.ChangeHappiness(context, happiness);
		DomainManager.Character.ChangeFavorabilityOptional(context, character, DomainManager.Taiwu.GetTaiwu(), favor, -1);
		int exp = favor * config.ExpPercent / 100;
		int otherFavor = favor * config.OtherFavorPercent / 100;
		if (exp > 0)
		{
			character.ChangeExp(context, exp);
		}
		if (otherFavor > 0 && characters.Count > 1)
		{
			indexes.Clear();
			foreach (int charId in characters)
			{
				if (characterId != charId)
				{
					indexes.Add(charId);
				}
			}
			int charBId = indexes[context.Random.Next(indexes.Count)];
			if (DomainManager.Character.TryGetElement_Objects(charBId, out var charB))
			{
				DomainManager.Character.ChangeFavorabilityOptional(context, character, charB, favor, -1);
			}
		}
		bool isVillager = character.GetOrganizationInfo().OrgTemplateId == 16;
		int giftGradeUpper = Math.Max(0, grade + GlobalConfig.Instance.FeastGiftGradeFactor[0] + (loveItem ? 1 : 0) + ((!isVillager) ? (-1) : 0) + config.GiftBonus + 1);
		int giftGradeLower = Math.Max(0, giftGradeUpper + GlobalConfig.Instance.FeastGiftGradeFactor[1]);
		sbyte giftGrade = (sbyte)((giftGradeUpper > 0) ? context.Random.Next(giftGradeLower, giftGradeUpper) : 0);
		IReadOnlyDictionary<ItemKey, int> taiwuGiftItems = GetTaiwuGiftItems(characterId);
		items.Clear();
		foreach (var (potentialItemKey, _) in character.GetInventory().Items)
		{
			if (!taiwuGiftItems.ContainsKey(potentialItemKey) && ItemTemplateHelper.IsTransferable(potentialItemKey.ItemType, potentialItemKey.TemplateId) && ItemTemplateHelper.GetGrade(potentialItemKey.ItemType, potentialItemKey.TemplateId) == giftGrade)
			{
				items.Add(potentialItemKey);
			}
		}
		int amount;
		ItemKey gift;
		if (items.Count == 0)
		{
			int randomAddOn = context.Random.Next(GlobalConfig.Instance.FeastGiftResourceAddon[0], GlobalConfig.Instance.FeastGiftResourceAddon[1]);
			int value = ItemTemplateHelper.GetBaseValue(2, giftGrade);
			amount = value * context.Random.Next(GlobalConfig.Instance.FeastGiftResourcePercent[0], GlobalConfig.Instance.FeastGiftResourcePercent[1] + 1) / 100 + randomAddOn;
			indexes.Clear();
			for (sbyte i = 0; i < 6; i++)
			{
				if (character.GetResource(i) >= amount)
				{
					indexes.Add(i);
				}
			}
			if (indexes.Count == 0)
			{
				amount = value * context.Random.Next(GlobalConfig.Instance.FeastGiftMoneyPercent[0], GlobalConfig.Instance.FeastGiftMoneyPercent[1] + 1) / 100 + randomAddOn;
				if (character.GetResource(6) >= amount)
				{
					gift = new ItemKey(12, 0, 6, -1);
					character.ChangeResource(context, 6, -amount);
				}
				else
				{
					gift = DomainManager.Item.CreateItem(context, 12, (short)(295 + giftGrade));
					DomainManager.Item.SetOwner(gift, ItemOwnerType.Building, 47);
					amount = 1;
				}
			}
			else
			{
				sbyte resourceType = (sbyte)indexes.GetRandom(context.Random);
				gift = new ItemKey(12, 0, resourceType, -1);
				character.ChangeResource(context, resourceType, -amount);
			}
		}
		else
		{
			gift = items.GetRandom(context.Random);
			amount = 1;
			character.RemoveInventoryItem(context, gift, amount, deleteItem: false);
			DomainManager.Item.SetOwner(gift, ItemOwnerType.Building, 47);
		}
		FeastAddGift(context, feast, gift, amount);
		DomainManager.Taiwu.RecordLifeSummary(context, 59);
		DomainManager.Building.SetCharacterParticipantFeast(characterId, feastType, happiness, dishCopy);
		if (--feast.DishDurability[index] <= 0)
		{
			FeastRemoveDish(context, feast.BuildingBlockKey, index);
		}
		ShopEventCollection shopEventCollection = DomainManager.Building.GetOrCreateShopEventCollection(feast.BuildingBlockKey);
		shopEventCollection.AddFeastRecord(characterId, character.GetHappiness(), dish, gift, feastType, loveItem);
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		lifeRecordCollection.AddFeastRecord(character, dish, gift, feastType, loveItem);
		SetFeast(context, feast.BuildingBlockKey, feast);
	}

	private void AddUnlockedFestType(DataContext context, short feastType)
	{
		if (_unlockedFeastTypes.Contains(feastType))
		{
			return;
		}
		_unlockedFeastTypes.Add(feastType);
		SetUnlockedFeastTypes(_unlockedFeastTypes, context);
		foreach (short type in _unlockedFeastTypes)
		{
			if (type != 0)
			{
				AchievementManager.RequestSetStat(context, (short)7, (int)type);
			}
		}
	}

