	public int SetFollowingNpcNickName(DataContext context, int characterId, string nickName)
	{
		if (!_followingNpcList.Contains(characterId))
		{
			return -1;
		}
		if (string.IsNullOrEmpty(nickName))
		{
			RemoveFollowingNpcNickName(context, characterId);
			return -1;
		}
		if (_followingNickNameMap.TryGetValue(characterId, out var key))
		{
			DomainManager.World.UnregisterCustomText(context, key);
			int newKey = DomainManager.World.RegisterCustomText(context, nickName);
			SetElement_FollowingNickNameMap(characterId, newKey, context);
			return newKey;
		}
		int newKey2 = DomainManager.World.RegisterCustomText(context, nickName);
		AddElement_FollowingNickNameMap(characterId, newKey2, context);
		return newKey2;
	}

