	public SecretInformationShopCharacterData AddOrGetSecretInformationShopCharacterData(DataContext context, int charId, bool forceFilter = true)
	{
		if (!TryGetElement_SecretInformationShopCharacterData(charId, out var data))
		{
			data = new SecretInformationShopCharacterData();
			AddElement_SecretInformationShopCharacterData(charId, data, context);
		}
		if (data.CollectedSecretInformationIds.CheckIndex(0) && !((SecretInformationId)data.CollectedSecretInformationIds[0]).Valid)
		{
			return data;
		}
		if (!data.CollectedSecretInformationIds.CheckIndex(0) && DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			short areaId = character.GetLocation().AreaId;
			if (areaId >= 0)
			{
				int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
				HashSet<int> set = new HashSet<int>();
				foreach (int targetCharId in DomainManager.Information.SecretInformationAllHandledCharacterIds())
				{
					if (DomainManager.Character.TryGetElement_Objects(targetCharId, out var targetChar) && targetChar.GetLocation().AreaId == areaId)
					{
						set.UnionWith(from id in DomainManager.Information.QueryCharacterKnownSecretInformationIds(targetCharId)
							select (int)id);
					}
				}
				EventArgBox argBox = new EventArgBox();
				set.RemoveWhere((int secretId) => DomainManager.Information.RequestShopSecretInformationIdShouldExclude((SecretInformationId)secretId, argBox, charId));
				data.CollectedSecretInformationIds.AddRange(set);
				InformationDomain informationDomain = DomainManager.Information;
				IReadOnlyCollection<SecretInformationId> taiwuKnown = informationDomain.QueryCharacterKnownSecretInformationIds(taiwuCharId);
				data.CollectedSecretInformationIds.Sort(delegate(int secretId1, int secretId2)
				{
					int num = informationDomain.QuerySecretOccurence((SecretInformationId)secretId1)?.Date ?? 0;
					int num2 = informationDomain.QuerySecretOccurence((SecretInformationId)secretId2)?.Date ?? 0;
					if (num != num2)
					{
						return num2.CompareTo(num);
					}
					int num3 = (taiwuKnown.Contains((SecretInformationId)secretId1) ? 1 : (-1));
					int value = (taiwuKnown.Contains((SecretInformationId)secretId2) ? 1 : (-1));
					return num3.CompareTo(value);
				});
				int maxCount = GlobalConfig.Instance.SecretInformationShopCharacterCollectInAreaMaxAmount;
				if (data.CollectedSecretInformationIds.Count > maxCount)
				{
					data.CollectedSecretInformationIds.RemoveRange(maxCount, data.CollectedSecretInformationIds.Count - maxCount);
				}
				SetElement_SecretInformationShopCharacterData(charId, data, context);
			}
		}
		else if (forceFilter)
		{
			EventArgBox argBox2 = new EventArgBox();
			data.CollectedSecretInformationIds.RemoveAll((int secretId) => DomainManager.Information.RequestShopSecretInformationIdShouldExclude((SecretInformationId)secretId, argBox2, charId));
			SetElement_SecretInformationShopCharacterData(charId, data, context);
		}
		return data;
	}

