	public int GetItemPriceFluctuation(TemplateKey templateKey)
	{
		return _itemPriceFluctuation.GetValueOrDefault(templateKey, 0);
	}

	public void ChangeItemPriceFluctuation(DataContext context, TemplateKey templateKey, int delta)
	{
		if (delta == 0)
		{
			return;
		}
		if (_itemPriceFluctuation.TryGetValue(templateKey, out var fluctuation))
		{
			fluctuation += delta;
			if (fluctuation == 0)
			{
				RemoveElement_ItemPriceFluctuation(templateKey, context);
			}
			else
			{
				SetElement_ItemPriceFluctuation(templateKey, fluctuation, context);
			}
		}
		else
		{
			AddElement_ItemPriceFluctuation(templateKey, delta, context);
		}
	}

	public void UpdateItemPriceFluctuations(DataContext context)
	{
		if (_itemPriceFluctuation.Count == 0)
		{
			return;
		}
		List<TemplateKey> templateKeys = new List<TemplateKey>(_itemPriceFluctuation.Keys);
		IReadOnlySet<int> merchantIds = DomainManager.Taiwu.GetVillagerRoleSet(3);
		foreach (TemplateKey templateKey in templateKeys)
		{
			if (!HasMerchant(templateKey))
			{
				int fluctuation = _itemPriceFluctuation[templateKey];
				if (fluctuation > 0)
				{
					fluctuation = Math.Max(0, fluctuation - 10);
				}
				else if (fluctuation < 0)
				{
					fluctuation = Math.Min(0, fluctuation + 10);
				}
				if (fluctuation == 0)
				{
					RemoveElement_ItemPriceFluctuation(templateKey, context);
				}
				else
				{
					SetElement_ItemPriceFluctuation(templateKey, fluctuation, context);
				}
			}
		}
		bool HasMerchant(TemplateKey key)
		{
			if (merchantIds.Count == 0)
			{
				return false;
			}
			foreach (int merchantId in merchantIds)
			{
				if (DomainManager.Extra.GetVillagerRole(merchantId) is VillagerRoleMerchant merchant && merchant.ItemTemplateKey.Equals(key) && merchant.ArrangementTemplateId == 8)
				{
					return true;
				}
			}
			return false;
		}
	}

	private int GetPresentInheritPropertyValue(GameData.DLC.FiveLoong.Jiao jiao1, GameData.DLC.FiveLoong.Jiao jiao2, short propertyTemplateId)
	{
		int value1 = 0;
		int value2 = 0;
		switch (propertyTemplateId)
		{
		case 9:
			value1 = jiao1.Height.Inherited + jiao2.Height.Inherited;
			value2 = jiao1.Height.Fostered + jiao2.Height.Fostered;
			break;
		case 10:
			value1 = jiao1.Weight.Inherited + jiao2.Weight.Inherited;
			value2 = jiao1.Weight.Fostered + jiao2.Weight.Fostered;
			break;
		case 11:
			value1 = jiao1.LifeSpan.Inherited + jiao2.LifeSpan.Inherited;
			value2 = jiao1.LifeSpan.Fostered + jiao2.LifeSpan.Fostered;
			break;
		}
		value2 /= 100;
		return value1 * GlobalConfig.Instance.JiaoLoongPresentPropertyFactor[0] / 100 + value2 * GlobalConfig.Instance.JiaoLoongPresentPropertyFactor[1] / 100;
	}

	private int GetCarrierInheritPropertyValue(GameData.DLC.FiveLoong.Jiao jiao1, GameData.DLC.FiveLoong.Jiao jiao2, short propertyTemplateId)
	{
		int value1 = jiao1.Properties.SeparateGet(propertyTemplateId).Inherited + jiao2.Properties.SeparateGet(propertyTemplateId).Inherited;
		int value2 = (jiao1.Properties.SeparateGet(propertyTemplateId).Fostered + jiao2.Properties.SeparateGet(propertyTemplateId).Fostered) / 100;
		return value1 * GlobalConfig.Instance.JiaoLoongCarrierPropertyFactor[0] / 100 + value2 * GlobalConfig.Instance.JiaoLoongCarrierPropertyFactor[1] / 100;
	}

	private int GetGiftInheritPropertyValue(GameData.DLC.FiveLoong.Jiao jiao1, GameData.DLC.FiveLoong.Jiao jiao2, short propertyTemplateId)
	{
		int value1 = jiao1.Properties.SeparateGet(propertyTemplateId).Inherited + jiao2.Properties.SeparateGet(propertyTemplateId).Inherited;
		int value2 = (jiao1.Properties.SeparateGet(propertyTemplateId).Fostered + jiao2.Properties.SeparateGet(propertyTemplateId).Fostered) / 100;
		return value1 * GlobalConfig.Instance.JiaoLoongGiftPropertyFactor[0] / 100 + value2 * GlobalConfig.Instance.JiaoLoongGiftPropertyFactor[1] / 100;
	}

	private int GetFleeChance(GameData.DLC.FiveLoong.Jiao jiao)
	{
		return (jiao.TamePoint >= 50) ? Math.Max(0, (900 - 10 * jiao.TamePoint) * 100 / (2 * jiao.TamePoint + 1800) * GlobalConfig.Instance.JiaoFleeBehaviorInfluence[jiao.Behavior] / 100) : ((100 - jiao.TamePoint) / 2 * GlobalConfig.Instance.JiaoFleeBehaviorInfluence[jiao.Behavior] / 100);
	}

