	public int GetRandomEventPropertyDelta(short propertyTemplateId, GameData.DLC.FiveLoong.Jiao jiao, int isDecrease)
	{
		return Config.JiaoProperty.Instance[propertyTemplateId].EscapeChange * GlobalConfig.Instance.JiaoPropertyChangeBehaviorInfluence[jiao.Behavior] / 100 * isDecrease;
	}

	public int BringUpJiaoFailProb(GameData.DLC.FiveLoong.Jiao jiao)
	{
		int param1 = (jiao.LastChoiceIsAggressive ? GlobalConfig.Instance.BringUpJiaoCalcParam[1] : 0);
		int param2 = jiao.TamePoint + GlobalConfig.Instance.BringUpJiaoCalcParam[2];
		return (int)MathF.Max(0f, ((float)(GlobalConfig.Instance.BringUpJiaoCalcParam[0] - jiao.TamePoint) + (float)param1 / (float)param2) * (float)GlobalConfig.Instance.BringUpJiaoBehaviorParam[jiao.Behavior] / 100f);
	}

