	[DomainMethod]
	public int GetJiaoEvolutionChoice(DataContext context, ItemKey key)
	{
		if (!TryGetJiaoIdByItemKey(key, out var id))
		{
			return 0;
		}
		if (!_jiaoEvolutionChoice.TryGetValue(id, out var choices) || choices == 0)
		{
			SetJiaoEvolutionChoice(id);
			choices = _jiaoEvolutionChoice[id];
		}
		return choices;
	}

	[DomainMethod]
	public void JiaoEvolveToChildOfLoong(DataContext context, ItemKey key, short childOfLoongTemplateId)
	{
		if (!TryGetJiaoIdByItemKey(key, out var id))
		{
			return;
		}
		if (childOfLoongTemplateId < 0)
		{
			if (!_jiaoEvolutionChoice.TryGetValue(id, out var choices) || choices == 0)
			{
				return;
			}
			List<short> templateIds = ObjectPool<List<short>>.Instance.Get();
			templateIds.Clear();
			for (short i = 31; i <= 39; i++)
			{
				if (IsAbleToEvolveChildOfLoong(id, i))
				{
					templateIds.Add(i);
				}
			}
			childOfLoongTemplateId = templateIds[context.Random.Next(0, templateIds.Count)];
			ObjectPool<List<short>>.Instance.Return(templateIds);
		}
		JiaoEvolveToChildOfLoong(context, id, childOfLoongTemplateId);
	}

