	}

	public JiaoLoongDisplayData GetJiaoLoongDisplayDataByItemKey(ItemKey key, bool getItemData)
	{
		JiaoLoongDisplayData res = new JiaoLoongDisplayData();
		if (key.ItemType == 4)
		{
			short templateId = key.TemplateId;
			if (templateId >= 77 && templateId <= 85)
			{
				res.IsJiao = false;
				res.Jiao = null;
				res.Loong = GetChildrenOfLoongByItemKey(key);
				res.Id = res.Loong.Id;
				res.EvolutionChoice = 0;
			}
			else
			{
				res.IsJiao = true;
				res.Jiao = GetJiaoByItemKey(key);
				res.Loong = null;
				res.Id = res.Jiao.Id;
				res.EvolutionChoice = GetJiaoEvolutionChoice(res.Jiao.Id);
			}
			res.TemplateId = GetJiaoTemplateIdByCarrierTemplateId(key.TemplateId);
			res.TamePoint = GetCarrierTamePoint(key.Id);
		}
		else
		{
			res.IsJiao = true;
			res.Jiao = GetJiaoByItemKey(key);
			res.Loong = null;
			res.Id = res.Jiao.Id;
			res.EvolutionChoice = 0;
			res.TemplateId = res.Jiao.TemplateId;
			res.TamePoint = GetCarrierTamePoint(key.Id);
			res.TamePoint = res.Jiao.TamePoint;
		}
		if (getItemData)
		{
			res.ItemDisplayData = DomainManager.Item.GetItemDisplayData(key);
		}
		res.MaxTamePoint = GetCarrierMaxTamePoint(key.Id);
		if (res.Jiao != null)
		{
			res.JiaoLoongNameRelatedData = res.Jiao.GetNameRelatedData();
			JiaoItem jiaoConfig = Config.Jiao.Instance[res.Jiao.TemplateId];
			res.ColorCount = Convert.ToSByte(jiaoConfig.ColorList?.Count ?? 0);
		}
		else if (res.Loong != null)
		{
			res.JiaoLoongNameRelatedData = res.Loong.GetNameRelatedData();
		}
		return res;
	}

