	public bool TryGetJiaoFromPool(int poolId, out GameData.DLC.FiveLoong.Jiao jiao, int jiaoCount = -1, int jiaoIndex = 0)
	{
		jiao = null;
		if (poolId >= _jiaoPools.Count)
		{
			return false;
		}
		JiaoPool pool = _jiaoPools[poolId];
		if (jiaoCount == 0 && pool.Jiaos.Count == 0)
		{
			return true;
		}
		if (jiaoCount > 0 && pool.Jiaos.Count != jiaoCount)
		{
			return false;
		}
		if (jiaoIndex >= pool.Jiaos.Count)
		{
			return false;
		}
		return _jiaos.TryGetValue(pool.Jiaos[jiaoIndex], out jiao);
	}

