	public int GetJiaoEvolutionChoice(int jiaoId)
	{
		if (!_jiaos.TryGetValue(jiaoId, out var jiao) || jiao.GrowthStage != 2)
		{
			return 0;
		}
		int res = 0;
		int validCount = 0;
		for (short i = 0; i <= 8; i++)
		{
			int propertyValue = jiao.Properties.Get(jiao.TemplateId, i);
			if (propertyValue >= Config.JiaoProperty.Instance[i].MaxValue)
			{
				res |= 1 << PropertyToChildrenOfLoong[i];
				validCount++;
			}
			else if (propertyValue >= Config.JiaoProperty.Instance[i].MaxValue * 75 / 100)
			{
				validCount++;
			}
		}
		return (validCount >= 3) ? res : 0;
	}

