	public ItemKey DropJiaoEgg(DataContext context, bool isIgnoreDropRate, short charTemplateId, sbyte forceGender = -1)
	{
		if (!TryGetDlcEntry<FiveLoongDlcEntry>(2764950uL, out var entry))
		{
			return ItemKey.Invalid;
		}
		if (!isIgnoreDropRate && !context.Random.CheckPercentProb(entry.JiaoEggDropRate))
		{
			entry.JiaoEggDropRate += GlobalConfig.Instance.JiaoEggDropRateUpPerMiss;
			return ItemKey.Invalid;
		}
		Tester.Assert(FiveLoongDlcEntry.IsCharacterLoong(charTemplateId) || FiveLoongDlcEntry.IsCharacterMinionLoong(charTemplateId));
		short loongTemplateId = (FiveLoongDlcEntry.IsCharacterLoong(charTemplateId) ? LoongInfo.CharacterTemplateIdToLoongTemplateId(charTemplateId) : LoongInfo.CharacterTemplateIdToLoongTemplateId(FiveLoongDlcEntry.MinionLoongToLoong(charTemplateId)));
		short jiaoTemplateId = Loong.Instance[loongTemplateId].Jiao;
		bool isMale = ((forceGender != -1) ? (forceGender == 1) : context.Random.CheckPercentProb(entry.MaleJiaoEggDropRate));
		ItemKey key = DomainManager.Item.CreateItem(context, 5, GetJiaoEggTemplateIdByJiaoTemplateId(jiaoTemplateId));
		int tamePoint = context.Random.Next(GlobalConfig.Instance.JiaoInitialTamePoint[0], GlobalConfig.Instance.JiaoInitialTamePoint[1] + 1);
		sbyte behaviorType = (sbyte)context.Random.Next(5);
		GameData.DLC.FiveLoong.Jiao jiao = new GameData.DLC.FiveLoong.Jiao(key, isMale, tamePoint, jiaoTemplateId, behaviorType);
		if (forceGender == -1)
		{
			entry.MaleJiaoEggDropRate += (isMale ? (-GlobalConfig.Instance.JiaoEggGenderModification) : GlobalConfig.Instance.JiaoEggGenderModification);
		}
		entry.JiaoEggDropRate = GlobalConfig.Instance.InitJiaoEggDropRate;
		AddElement_Jiaos(jiao.Id, jiao, context);
		SetJiaoKeyToId(jiao.Key, jiao.Id);
		return key;
	}

