	[DomainMethod]
	public List<ItemKey> PutJiaoOutOfPool(DataContext context, int poolId)
	{
		if (!TryGetJiaoFromPool(poolId, out var firstJiao))
		{
			return new List<ItemKey>();
		}
		JiaoPool pool = _jiaoPools[poolId];
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Inventory inventory = taiwu.GetInventory();
		List<ItemKey> res = new List<ItemKey>();
		if (pool.Jiaos.Count == 2)
		{
			SetJiaoPoolStatus(new IntPair(poolId, 8), context);
		}
		else if (pool.Jiaos.Count > 2)
		{
			SetJiaoPoolStatus(new IntPair(poolId, 7), context);
		}
		else if (firstJiao.GrowthStage == 1)
		{
			SetJiaoPoolStatus(new IntPair(poolId, 9), context);
		}
		else if (firstJiao.GrowthStage == 2 || firstJiao.GrowthStage == 0)
		{
			SetJiaoPoolStatus(new IntPair(poolId, 10), context);
		}
		foreach (int id in pool.Jiaos)
		{
			if (_jiaos.TryGetValue(id, out var jiao))
			{
				ItemBase item = DomainManager.Item.GetBaseItem(jiao.Key);
				item.RemoveOwner(ItemOwnerType.Building, 44);
				item.SetOwner(ItemOwnerType.CharacterInventory, taiwu.GetId());
				inventory.OfflineAdd(jiao.Key, 1);
				res.Add(jiao.Key);
			}
		}
		pool.Jiaos.Clear();
		pool.NextPeriod = -1;
		taiwu.SetInventory(inventory, context);
		SetJiaoPools(_jiaoPools, context);
		return res;
	}

