	public void JiaoGrow(DataContext context, int poolId)
	{
		if (!TryGetJiaoFromPool(poolId, out var jiao, 1) || jiao.GrowthStage != 1)
		{
			return;
		}
		JiaoNurturanceItem config = JiaoNurturance.Instance[jiao.NurturanceTemplateId];
		foreach (IntPair pair in config.BasePropertyChange)
		{
			AddJiaoProperty(context, jiao, (short)pair.First, pair.Second);
			switch (pair.First)
			{
			case 0:
				AddJiaoPoolRecord(context, poolId, new JiaoPoolRecord(34, jiao.Id, jiao.NurturanceTemplateId, (short)pair.First, pair.Second));
				break;
			case 2:
			case 3:
				AddJiaoPoolRecord(context, poolId, new JiaoPoolRecord(25, jiao.Id, jiao.NurturanceTemplateId, (short)pair.First, pair.Second));
				break;
			case 1:
				AddJiaoPoolRecord(context, poolId, new JiaoPoolRecord(29, jiao.Id, jiao.NurturanceTemplateId, (short)pair.First, pair.Second));
				break;
			default:
				AddJiaoPoolRecord(context, poolId, new JiaoPoolRecord(1, jiao.Id, jiao.NurturanceTemplateId, (short)pair.First, pair.Second));
				break;
			}
		}
		jiao.NextPeriod = JiaoNurturance.Instance[jiao.NurturanceTemplateId].StageCostMonth;
		SetJiaoPools(_jiaoPools, context);
		SetElement_Jiaos(jiao.Id, jiao, context);
	}

	public bool JiaoBreed(DataContext context, int poolId)
	{
		if (!TryGetJiaoFromPool(poolId, out var _, 2))
		{
			return false;
		}
		JiaoPool pool = _jiaoPools[poolId];
		if (!TryGetJiao(pool.Jiaos[0], out var parentJiao1) || !TryGetJiao(pool.Jiaos[1], out var parentJiao2))
		{
			return false;
		}
		if (!TryGetDlcEntry<FiveLoongDlcEntry>(2764950uL, out var entry))
		{
			return false;
		}
		bool isMale = context.Random.CheckPercentProb(entry.MaleJiaoEggDropRate);
		short templateId = GetJiaoInheritTemplateId(parentJiao1.TemplateId, parentJiao2.TemplateId);
		ItemKey key = DomainManager.Item.CreateItem(context, 5, GetJiaoEggTemplateIdByJiaoTemplateId(templateId));
		DomainManager.Item.SetOwner(key, ItemOwnerType.Building, 44);
		int fatherId = (parentJiao1.Gender ? parentJiao1.Id : parentJiao2.Id);
		int motherId = (parentJiao1.Gender ? parentJiao2.Id : parentJiao1.Id);
		GameData.DLC.FiveLoong.Jiao jiao2 = new GameData.DLC.FiveLoong.Jiao(key, isMale, context.Random.Next(GlobalConfig.Instance.JiaoInitialTamePoint[0], GlobalConfig.Instance.JiaoInitialTamePoint[1] + 1), templateId, (sbyte)context.Random.Next(5), fatherId, motherId)
		{
			Properties = new GameData.DLC.FiveLoong.JiaoProperty(GetCarrierInheritPropertyValue(parentJiao1, parentJiao2, 0), GetCarrierInheritPropertyValue(parentJiao1, parentJiao2, 1), GetCarrierInheritPropertyValue(parentJiao1, parentJiao2, 2), GetCarrierInheritPropertyValue(parentJiao1, parentJiao2, 3), GetCarrierInheritPropertyValue(parentJiao1, parentJiao2, 4), GetGiftInheritPropertyValue(parentJiao1, parentJiao2, 6), GetCarrierInheritPropertyValue(parentJiao1, parentJiao2, 5), GetGiftInheritPropertyValue(parentJiao1, parentJiao2, 7), GetGiftInheritPropertyValue(parentJiao1, parentJiao2, 8)),
			Height = (Inherited: GetPresentInheritPropertyValue(parentJiao1, parentJiao2, 9), Fostered: 0),
			Weight = (Inherited: GetPresentInheritPropertyValue(parentJiao1, parentJiao2, 10), Fostered: 0),
			LifeSpan = (Inherited: GetPresentInheritPropertyValue(parentJiao1, parentJiao2, 11), Fostered: 0),
			Generation = Math.Max(parentJiao1.Generation, parentJiao2.Generation) + 1
		};
		pool.Jiaos.Add(jiao2.Id);
		entry.MaleJiaoEggDropRate += (isMale ? (-GlobalConfig.Instance.JiaoEggGenderModification) : GlobalConfig.Instance.JiaoEggGenderModification);
		parentJiao1.CanBreed = false;
		parentJiao2.CanBreed = false;
		AddJiaoPoolRecord(context, poolId, new JiaoPoolRecord(20, parentJiao1.Id, parentJiao2.Id, jiao2.Key.TemplateId));
		SetJiaoPools(_jiaoPools, context);
		AddElement_Jiaos(jiao2.Id, jiao2, context);
		SetElement_Jiaos(parentJiao1.Id, parentJiao1, context);
		SetElement_Jiaos(parentJiao2.Id, parentJiao2, context);
		SetJiaoKeyToId(jiao2.Key, jiao2.Id);
		return true;
	}

	public void JiaoEvolveToCarrier(DataContext context, int poolId)
	{
		if (!TryGetJiaoFromPool(poolId, out var jiao, 1) || jiao.GrowthStage != 1)
		{
			return;
		}
		ItemKey newKey = DomainManager.Item.CreateItem(context, 4, GetJiaoCarrierTemplateIdByJiaoTemplateId(jiao.TemplateId));
		DomainManager.Item.SetOwner(newKey, ItemOwnerType.Building, 44);
		ItemKey key = jiao.Key;
		jiao.GrowthStage = 2;
		jiao.Key = newKey;
		_jiaoPools[poolId].NextPeriod = -1;
		_jiaoEvolutionChoice[jiao.Id] = GetJiaoEvolutionChoice(jiao.Id);
		if (IsAbleToEvolveChildOfLoong(jiao.Id))
		{
			Location location = DomainManager.Taiwu.GetTaiwu().GetLocation();
			if (!location.IsValid())
			{
				location = DomainManager.Taiwu.GetTaiwu().GetValidLocation();
			}
			MonthlyEventCollection monthlyEventCollection = DomainManager.World.GetMonthlyEventCollection();
			monthlyEventCollection.AddDLCLoongJiaoGrowUp(location, jiao.Id);
		}
		DomainManager.Item.RemoveItem(context, key);
		AddJiaoPoolRecord(context, poolId, new JiaoPoolRecord(18, jiao.Id));
		SetCarrierTamePoint(context, jiao.Key.Id, jiao.TamePoint);
		SetJiaoPools(_jiaoPools, context);
		SetElement_Jiaos(jiao.Id, jiao, context);
		SetJiaoKeyToId(jiao.Key, jiao.Id);
		DomainManager.World.TriggerExtraTask(context, 42, 244);
	}

	public void JiaoEvolveToChildOfLoong(DataContext context, int id, short childOfLoongTemplateId)
	{
		if (_jiaos.TryGetValue(id, out var jiao) && jiao.GrowthStage == 2)
		{
			ItemKey newKey = DomainManager.Item.CreateItem(context, 4, GetJiaoCarrierTemplateIdByJiaoTemplateId(childOfLoongTemplateId));
			ChildrenOfLoong loong = new ChildrenOfLoong(jiao, newKey, childOfLoongTemplateId);
			GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
			int jiaoTamePoint;
			int tamePoint = (TryGetCarrierTamePoint(jiao.Key.Id, out jiaoTamePoint) ? jiaoTamePoint : jiao.TamePoint);
			ProfessionFormulaItem formula = ProfessionFormula.Instance[14];
			int addSeniority = formula.Calculate();
			RemoveJiaoFromPool(context, jiao.Key);
			RemoveJiaoFromTaiwuStorage(context, jiao.Key);
			SetChildOfLoongKeyToId(loong.Key, loong.Id);
			taiwu.AddInventoryItem(context, newKey, 1);
			DomainManager.Item.RemoveItem(context, jiao.Key);
			SetCarrierTamePoint(context, loong.Key.Id, tamePoint);
			AddElement_ChildrenOfLoong(loong.Id, loong, context);
			RemoveElement_Jiaos(jiao.Id, context);
			SetOwnedChildrenOfLoong(childOfLoongTemplateId);
			DomainManager.World.FinishTriggeredExtraTask(context, 42, 244);
			DomainManager.Extra.ChangeProfessionSeniority(context, 1, addSeniority);
			List<ItemDisplayData> itemDisplayDataList = new List<ItemDisplayData>();
			itemDisplayDataList.Add(DomainManager.Item.GetItemDisplayData(newKey, taiwu.GetId()));
			GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.OpenGetItem_Item, itemDisplayDataList, arg2: false);
		}
	}

	[DomainMethod]
	public sbyte GetJiaoEvolutionPageStatus()
	{
		if (DomainManager.Taiwu.GetTaiwuVillageLocation() != DomainManager.Taiwu.GetTaiwu().GetLocation())
		{
			return 1;
		}
		GetAllTaiwuJiao(includeEquipment: true);
		foreach (var (jiao2, _) in _taiwuJiaos)
		{
			if (IsAbleToEvolveChildOfLoong(jiao2.Id))
			{
				return 0;
			}
		}
		return 2;
	}

	public ItemSourceType GetJiaoSource(int jiaoId)
	{
		foreach (ItemKey equipment in DomainManager.Taiwu.GetTaiwu().GetValidAnimalEquipment())
		{
			if (IsItemJiaoRelated(equipment) && TryGetJiaoIdByItemKey(equipment, out var equippingJiaoId) && TryGetJiao(equippingJiaoId, out var equippingJiao) && equippingJiao.Id == jiaoId)
			{
				return ItemSourceType.Equipment;
			}
		}
		IReadOnlyDictionary<ItemKey, int> inventory = DomainManager.Taiwu.GetItems(ItemSourceType.Inventory);
		foreach (ItemKey itemKey in inventory.Keys)
		{
			if (TryGetJiaoIdByItemKey(itemKey, out var id) && jiaoId == id)
			{
				return ItemSourceType.Inventory;
			}
		}
		IReadOnlyDictionary<ItemKey, int> warehouse = DomainManager.Taiwu.GetItems(ItemSourceType.Warehouse);
		foreach (ItemKey itemKey2 in warehouse.Keys)
		{
			if (TryGetJiaoIdByItemKey(itemKey2, out var id2) && jiaoId == id2)
			{
				return ItemSourceType.Warehouse;
			}
		}
		IReadOnlyDictionary<ItemKey, int> treasury = DomainManager.Taiwu.GetItems(ItemSourceType.Treasury);
		foreach (ItemKey itemKey3 in treasury.Keys)
		{
			if (TryGetJiaoIdByItemKey(itemKey3, out var id3) && jiaoId == id3)
			{
				return ItemSourceType.Treasury;
			}
		}
		foreach (JiaoPool pool in _jiaoPools)
		{
			foreach (int id4 in pool.Jiaos)
			{
				if (TryGetJiao(id4, out var _) && jiaoId == id4)
				{
					return ItemSourceType.JiaoPool;
				}
			}
		}
		return ItemSourceType.Invalid;
	}

	[DomainMethod]
	public JiaoEvolutionDisplayData GetNextRandomChildrenOfLoong(DataContext context, int jiaoId)
	{
		if (!TryGetJiao(jiaoId, out var jiao))
		{
			return new JiaoEvolutionDisplayData();
		}
		int index;
		if (jiao.LastEvolutionResult == -1)
		{
			RemoveLoongScaleFromTaiwuStorage(context, GlobalConfig.Instance.RequiredLoongScaleForFirstTimeEvolution);
			InitializeRandomChildrenOfLoongPool(context, jiaoId, isForceNewSeed: true);
			index = _jiaoEvolutionPool[jiaoId].Count - 1;
		}
		else
		{
			RemoveLoongScaleFromTaiwuStorage(context, GlobalConfig.Instance.RequiredLoongScaleForEvolution);
			if (!_jiaoEvolutionPool.TryGetValue(jiaoId, out var _))
			{
				InitializeRandomChildrenOfLoongPool(context, jiaoId, isForceNewSeed: false);
			}
			index = _jiaoEvolutionPool[jiaoId].IndexOf(jiao.LastEvolutionResult);
			if (index <= 0)
			{
				InitializeRandomChildrenOfLoongPool(context, jiaoId, isForceNewSeed: true);
				index = _jiaoEvolutionPool[jiaoId].Count - 1;
			}
			else
			{
				index--;
			}
		}
		jiao.LastEvolutionResult = _jiaoEvolutionPool[jiaoId][index];
		SetJiao(context, jiao);
		return GetJiaoEvolutionDisplayData(jiaoId);
	}

	private void InitializeRandomChildrenOfLoongPool(DataContext context, int id, bool isForceNewSeed)
	{
		if (!TryGetJiao(id, out var jiao))
		{
			return;
		}
		if (jiao.RandomSeed == -1 || isForceNewSeed)
		{
			jiao.RandomSeed = context.Random.Next(int.MaxValue);
		}
		if (!_jiaoEvolutionPool.TryGetValue(id, out var pool))
		{
			pool = new List<short>();
		}
		Random rand = new Random(jiao.RandomSeed);
		pool.Clear();
		for (short i = 31; i <= 39; i++)
		{
			if (IsAbleToEvolveChildOfLoong(id, i))
			{
				pool.Add(i);
			}
		}
		for (int i2 = pool.Count - 1; i2 > 0; i2--)
		{
			int swapIdx = rand.Next(i2 + 1);
			List<short> list = pool;
			int index = swapIdx;
			List<short> list2 = pool;
			int index2 = i2;
			short value = pool[i2];
			short value2 = pool[swapIdx];
			list[index] = value;
			list2[index2] = value2;
		}
		_jiaoEvolutionPool[id] = pool;
	}

	public JiaoEvolutionDisplayData GetJiaoEvolutionDisplayData(int jiaoId)
	{
		if (!TryGetJiao(jiaoId, out var jiao) || jiao.GrowthStage != 2)
		{
			return new JiaoEvolutionDisplayData();
		}
		if (!_jiaoEvolutionChoice.TryGetValue(jiaoId, out var choices) || choices == 0)
		{
			SetJiaoEvolutionChoice(jiaoId);
		}
		bool isOwnedResult = jiao.LastEvolutionResult >= 0 && IsOwnedChildrenOfLoong(jiao.LastEvolutionResult);
		sbyte status = 0;
		if (GetEvolveChildOfLoongCount(jiaoId) <= 1)
		{
			status = 1;
		}
		else if (!isOwnedResult)
		{
			status = 2;
		}
		else if (!IsLoongScaleEnough(GlobalConfig.Instance.RequiredLoongScaleForEvolution))
		{
			status = 3;
		}
		return new JiaoEvolutionDisplayData(jiao.Id, jiao.LastEvolutionResult, isOwnedResult, status, DomainManager.Item.GetItemDisplayData(DomainManager.Item.GetBaseItem(jiao.Key), 1, DomainManager.Taiwu.GetTaiwuCharId(), (sbyte)GetJiaoSource(jiaoId)));
	}

	public bool JiaoFlee(DataContext context, int poolId)
	{
		if (poolId >= _jiaoPools.Count)
		{
			return false;
		}
		JiaoPool pool = _jiaoPools[poolId];
		if (pool.Jiaos.Count != 1)
		{
			return false;
		}
		if (!_jiaos.TryGetValue(pool.Jiaos[0], out var jiao) || jiao.GrowthStage != 1)
		{
			return false;
		}
		if (JiaoNurturance.Instance[jiao.NurturanceTemplateId].NurturanceCostMonth - jiao.EvolveRemainingMonth < 3)
		{
			return false;
		}
		if (!context.Random.CheckPercentProb(GetFleeChance(jiao)))
		{
			return false;
		}
		short areaId = DomainManager.Taiwu.GetTaiwuVillageLocation().AreaId;
		if (!TryGetValidCarrierLocation(context, areaId, out var location))
		{
			return false;
		}
		DomainManager.Item.RemoveOwner(jiao.Key, ItemOwnerType.Building, 44);
		pool.Jiaos.Clear();
		pool.NextPeriod = -1;
		SetJiaoPools(_jiaoPools, context);
		SetFleeCarrierLocation(context, jiao.Key, location);
		AddJiaoPoolRecord(context, poolId, new JiaoPoolRecord(15, jiao.Id));
		return true;
	}

	public void ApplyJiaoTamingResult(DataContext context, GameData.Domains.Character.Animal animal, bool isWin, Location location, ItemKey rope)
	{
		if (!isWin || !TryGetJiaoIdByItemKey(animal.ItemKey, out var id) || !TryGetJiao(id, out var jiao))
		{
			return;
		}
		if (rope.IsValid())
		{
			ChangeJiaoTamePoint(context, jiao, GlobalConfig.Instance.JiaoTamePointAddWhenCaught);
			GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
			taiwu.AddInventoryItem(context, animal.ItemKey, 1);
			return;
		}
		List<MapBlockData> blocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		blocks.Clear();
		DomainManager.Map.GetValidBlocksForRandomEnemy(location.AreaId, location.BlockId, 3, onSettlement: false, nearTaiwu: true, blocks);
		if (blocks.Count != 0)
		{
			MapBlockData selectedBlock = blocks.GetRandom(context.Random);
			Location targetLocation = new Location(selectedBlock.AreaId, selectedBlock.BlockId);
			SetAnimalLocation(context, animal, targetLocation);
		}
		ObjectPool<List<MapBlockData>>.Instance.Return(blocks);
	}

	public void JiaoEvent(DataContext context, int poolId)
	{
		if (!TryGetJiaoFromPool(poolId, out var jiao, 1) || jiao.GrowthStage != 1)
		{
			return;
		}
		if (GetIsBabysittingMode(poolId))
		{
			AutomaticProcessJiaoEvent(context, jiao, poolId);
			return;
		}
		MonthlyEventCollection monthlyEventCollection = DomainManager.World.GetMonthlyEventCollection();
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location location = taiwu.GetLocation();
		if (!location.IsValid())
		{
			location = taiwu.GetValidLocation();
		}
		monthlyEventCollection.AddJiaoGrowold(location, jiao.Id);
	}

	public void AutomaticProcessJiaoEvent(DataContext context, GameData.DLC.FiveLoong.Jiao jiao, int poolId)
	{
		RandomAddJiaoPresentProperty(context, jiao);
		short templateId = (short)context.Random.Next(0, 9);
		JiaoPropertyItem config = Config.JiaoProperty.Instance[templateId];
		sbyte attitude = 1;
		int tamePointDelta = 0;
		if (jiao.TamePoint >= 75)
		{
			tamePointDelta = config.AggressiveComfortParam;
			if (context.Random.CheckPercentProb(BringUpJiaoFailProb(jiao)))
			{
				tamePointDelta += config.AggressiveNotComfortParam;
			}
			attitude = 0;
			AddJiaoAggressiveTimes(context, jiao);
			SetJiaoLastChoiceIsAggressive(context, jiao, lastChoiceIsAggressive: true);
		}
		else if (jiao.TamePoint < 50)
		{
			tamePointDelta = config.ConservedTameParam;
			attitude = 2;
			AddJiaoNegativeTimes(context, jiao);
			SetJiaoLastChoiceIsAggressive(context, jiao, lastChoiceIsAggressive: false);
		}
		ChangeJiaoTamePoint(context, jiao, tamePointDelta);
		AddJiaoPropertyInEvent(context, jiao, templateId, attitude, poolId);
	}

	public void AddJiaoPropertyInEvent(DataContext context, GameData.DLC.FiveLoong.Jiao jiao, short jiaoPropertyTemplateId, sbyte attitudeType, int poolId)
	{
		JiaoPropertyItem jiaoPropertyConfig = Config.JiaoProperty.Instance[jiaoPropertyTemplateId];
		int[] eventChange = jiaoPropertyConfig.EventChange;
		float baseValue = context.Random.Next(eventChange[0], eventChange[1] + 1);
		switch (attitudeType)
		{
		case 0:
			baseValue = baseValue * (float)jiaoPropertyConfig.AggressivePropertyParam / 100f;
			baseValue = MathF.Ceiling(baseValue);
			break;
		case 1:
			baseValue = baseValue * (float)jiaoPropertyConfig.NeutralityPropertyParam / 100f;
			baseValue = MathF.Ceiling(baseValue);
			break;
		default:
			baseValue = baseValue * (float)jiaoPropertyConfig.ConservedPropertyParam / 100f;
			baseValue = MathF.Ceiling(baseValue);
			break;
		}
		AddJiaoProperty(context, jiao, jiaoPropertyTemplateId, (int)baseValue);
		DomainManager.Extra.AddJiaoPoolRecord(context, poolId, new JiaoPoolRecord(Config.JiaoProperty.Instance[jiaoPropertyTemplateId].JiaoRecordTemplateId, jiao.Id, (int)baseValue));
	}

	public short RandomAddJiaoPresentProperty(DataContext context, GameData.DLC.FiveLoong.Jiao jiao)
	{
		short jiaoPropertyTemplateId = (short)context.Random.Next(9, 12);
		int[] eventChange = Config.JiaoProperty.Instance[jiaoPropertyTemplateId].EventChange;
		int baseValue = context.Random.Next(eventChange[0], eventChange[1] + 1);
		AddJiaoProperty(context, jiao, jiaoPropertyTemplateId, baseValue);
		return jiaoPropertyTemplateId;
	}

