	private void RemoveJiaoFromTaiwuStorage(DataContext context, ItemKey key)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		foreach (sbyte index in taiwu.GetAnimalEquipmentIndexes())
		{
			if (key.Equals(taiwu.GetEquipment()[index]))
			{
				taiwu.ChangeEquipment(context, index, -1, ItemKey.Invalid);
			}
		}
		DomainManager.Taiwu.RemoveTaiwuItemFromTaiwuStorage(context, key, 1, deleteItem: false);
	}

	private void RemoveLoongScaleFromTaiwuStorage(DataContext context, int needToRemoveCount)
	{
		IReadOnlyDictionary<ItemKey, int> inventory = DomainManager.Taiwu.GetItems(ItemSourceType.Inventory);
		foreach (KeyValuePair<ItemKey, int> pair in inventory)
		{
			ItemKey key = pair.Key;
			if (key.ItemType == 12 && key.TemplateId == 276)
			{
				DomainManager.Taiwu.RemoveItem(context, pair.Key, Math.Min(needToRemoveCount, pair.Value), 1, deleteItem: true);
				needToRemoveCount -= pair.Value;
				break;
			}
		}
		if (needToRemoveCount <= 0)
		{
			return;
		}
		IReadOnlyDictionary<ItemKey, int> wareHouse = DomainManager.Taiwu.GetItems(ItemSourceType.Warehouse);
		foreach (KeyValuePair<ItemKey, int> pair2 in wareHouse)
		{
			ItemKey key = pair2.Key;
			if (key.ItemType == 12 && key.TemplateId == 276)
			{
				DomainManager.Taiwu.RemoveItem(context, pair2.Key, Math.Min(needToRemoveCount, pair2.Value), 2, deleteItem: true);
				needToRemoveCount -= pair2.Value;
				break;
			}
		}
		if (needToRemoveCount <= 0)
		{
			return;
		}
		IReadOnlyDictionary<ItemKey, int> treasury = DomainManager.Taiwu.GetItems(ItemSourceType.Treasury);
		foreach (KeyValuePair<ItemKey, int> pair3 in treasury)
		{
			ItemKey key = pair3.Key;
			if (key.ItemType == 12 && key.TemplateId == 276)
			{
				DomainManager.Taiwu.RemoveItem(context, pair3.Key, needToRemoveCount, 3, deleteItem: true);
				break;
			}
		}
	}

	private bool IsLoongScaleEnough(int needToRemoveCount)
	{
		IReadOnlyDictionary<ItemKey, int> inventory = DomainManager.Taiwu.GetItems(ItemSourceType.Inventory);
		foreach (KeyValuePair<ItemKey, int> pair in inventory)
		{
			ItemKey key = pair.Key;
			if (key.ItemType == 12 && key.TemplateId == 276)
			{
				needToRemoveCount -= pair.Value;
				break;
			}
		}
		if (needToRemoveCount <= 0)
		{
			return true;
		}
		IReadOnlyDictionary<ItemKey, int> wareHouse = DomainManager.Taiwu.GetItems(ItemSourceType.Warehouse);
		foreach (KeyValuePair<ItemKey, int> pair2 in wareHouse)
		{
			ItemKey key = pair2.Key;
			if (key.ItemType == 12 && key.TemplateId == 276)
			{
				needToRemoveCount -= pair2.Value;
				break;
			}
		}
		if (needToRemoveCount <= 0)
		{
			return true;
		}
		IReadOnlyDictionary<ItemKey, int> treasury = DomainManager.Taiwu.GetItems(ItemSourceType.Treasury);
		foreach (KeyValuePair<ItemKey, int> pair3 in treasury)
		{
			ItemKey key = pair3.Key;
			if (key.ItemType == 12 && key.TemplateId == 276)
			{
				needToRemoveCount -= pair3.Value;
				break;
			}
		}
		return needToRemoveCount <= 0;
	}

	private void GetAllTaiwuJiao(bool includeEquipment)
	{
		_taiwuJiaos.Clear();
		foreach (ItemKey equipment in DomainManager.Taiwu.GetTaiwu().GetValidAnimalEquipment())
		{
			if (includeEquipment && IsItemJiaoRelated(equipment) && TryGetJiaoIdByItemKey(equipment, out var equippingJiaoId) && TryGetJiao(equippingJiaoId, out var equippingJiao))
			{
				_taiwuJiaos[equippingJiao] = ItemSourceType.Equipment;
			}
		}
		IReadOnlyDictionary<ItemKey, int> inventory = DomainManager.Taiwu.GetItems(ItemSourceType.Inventory);
		foreach (ItemKey itemKey in inventory.Keys)
		{
			if (TryGetJiaoIdByItemKey(itemKey, out var id) && TryGetJiao(id, out var jiao))
			{
				_taiwuJiaos[jiao] = ItemSourceType.Inventory;
			}
		}
		IReadOnlyDictionary<ItemKey, int> warehouse = DomainManager.Taiwu.GetItems(ItemSourceType.Warehouse);
		foreach (ItemKey itemKey2 in warehouse.Keys)
		{
			if (TryGetJiaoIdByItemKey(itemKey2, out var id2) && TryGetJiao(id2, out var jiao2))
			{
				_taiwuJiaos[jiao2] = ItemSourceType.Warehouse;
			}
		}
		IReadOnlyDictionary<ItemKey, int> treasury = DomainManager.Taiwu.GetItems(ItemSourceType.Treasury);
		foreach (ItemKey itemKey3 in treasury.Keys)
		{
			if (TryGetJiaoIdByItemKey(itemKey3, out var id3) && TryGetJiao(id3, out var jiao3))
			{
				_taiwuJiaos[jiao3] = ItemSourceType.Treasury;
			}
		}
		foreach (JiaoPool pool in _jiaoPools)
		{
			foreach (int id4 in pool.Jiaos)
			{
				if (TryGetJiao(id4, out var jiao4))
				{
					_taiwuJiaos[jiao4] = ItemSourceType.JiaoPool;
				}
			}
		}
	}

	private void AddJiaoInPool(DataContext context, int poolId, GameData.DLC.FiveLoong.Jiao jiao)
	{
		JiaoPool pool = _jiaoPools[poolId];
		pool.Jiaos.Add(jiao.Id);
		DomainManager.Item.SetOwner(jiao.Key, ItemOwnerType.Building, 44);
		if (jiao.GrowthStage == 0)
		{
			pool.NextPeriod = GlobalConfig.Instance.JiaoEggIncubationTime;
		}
		else if (jiao.GrowthStage == 1)
		{
			pool.NextPeriod = -1;
			if (jiao.NextPeriod < 0)
			{
				jiao.NextPeriod = JiaoNurturance.Instance[jiao.NurturanceTemplateId].StageCostMonth;
			}
			SetJiao(context, jiao);
		}
		else if (pool.Jiaos.Count == 2)
		{
			pool.NextPeriod = GlobalConfig.Instance.JiaoBreedingTime;
		}
		SetJiaoPools(_jiaoPools, context);
	}

