	private void CheckAndInitCard(DataContext context)
	{
		List<GameData.Domains.Character.LifeSkillItem> learnedLifeSkills = DomainManager.Taiwu.GetTaiwu().GetLearnedLifeSkills();
		if (_lifeSkillCombatCardDict.Count > 0)
		{
			foreach (KeyValuePair<sbyte, LifeSkillCombatCardCollection> cardCollection in _lifeSkillCombatCardDict)
			{
				if (cardCollection.Value.CardDict == null)
				{
					foreach (GameData.Domains.Character.LifeSkillItem skillItem in learnedLifeSkills)
					{
						Config.LifeSkillItem config = LifeSkill.Instance[skillItem.SkillTemplateId];
						if (config.Type == cardCollection.Key)
						{
							CreateLifeSkillCombatCard(context, skillItem);
						}
					}
				}
			}
			return;
		}
		learnedLifeSkills.ForEach(delegate(GameData.Domains.Character.LifeSkillItem item)
		{
			CreateLifeSkillCombatCard(context, item);
		});
	}

	private void CheckAndInitUsedCard(DataContext context)
	{
		for (sbyte i = 0; i < 16; i++)
		{
			if (!_lifeSkillCombatUsedCardDict.TryGetValue(i, out var cardCollection))
			{
				cardCollection = default(LifeSkillCombatCardCollection);
				Create(ref cardCollection);
				AddElement_LifeSkillCombatUsedCardDict(i, cardCollection, context);
			}
			else if (cardCollection.CardDict == null || cardCollection.CountSum < TotalUsedCardCount)
			{
				Create(ref cardCollection);
				SetElement_LifeSkillCombatUsedCardDict(i, cardCollection, context);
			}
		}
		static void Create(ref LifeSkillCombatCardCollection reference)
		{
			reference.CardDict = new Dictionary<sbyte, int>();
			foreach (LifeSkillCombatEffectItem effectCardData in (IEnumerable<LifeSkillCombatEffectItem>)LifeSkillCombatEffect.Instance)
			{
				if (effectCardData.UsedCount > 0)
				{
					reference.CardDict[effectCardData.TemplateId] = effectCardData.UsedCount;
				}
			}
		}
	}

	public void CreateLifeSkillCombatCard(DataContext context, GameData.Domains.Character.LifeSkillItem item)
	{
		Config.LifeSkillItem skillConfig = LifeSkill.Instance[item.SkillTemplateId];
		sbyte grade = skillConfig.Grade;
		if (grade >= 0 && grade <= 2)
		{
			List<byte> pageList = new List<byte> { 1, 2, 3 };
			{
				foreach (byte page in pageList)
				{
					if (item.IsPageRead(page))
					{
						CreateCard(context, skillConfig, page, 0);
					}
				}
				return;
			}
		}
		grade = skillConfig.Grade;
		if (grade >= 3 && grade <= 5)
		{
			List<byte> pageList2 = new List<byte> { 2, 3 };
			{
				foreach (byte page2 in pageList2)
				{
					if (item.IsPageRead(page2))
					{
						CreateCard(context, skillConfig, page2, 1);
					}
				}
				return;
			}
		}
		grade = skillConfig.Grade;
		if (grade >= 6 && grade <= 8)
		{
			byte page3 = 3;
			if (item.IsPageRead(page3))
			{
				CreateCard(context, skillConfig, page3, 2);
			}
		}
	}

	private void CreateCard(DataContext context, Config.LifeSkillItem skillConfig, byte page, sbyte cardLevel)
	{
		LifeSkillCombatReadBookPageData pageData;
		bool hasPageDict = TryGetElement_LifeSkillCombatReadBookPageDict(skillConfig.TemplateId, out pageData);
		if (pageData.PageList != null && pageData.PageList.Contains(page))
		{
			return;
		}
		LifeSkillCombatCardCollection cardCollection;
		bool hasCardDict = TryGetElement_LifeSkillCombatCardDict(skillConfig.Type, out cardCollection);
		List<sbyte> keyList = LifeSkillCombatEffect.Instance.GetAllKeys();
		CollectionUtils.Shuffle(context.Random, keyList);
		LifeSkillCombatEffectItem cardConfig = null;
		foreach (sbyte key in keyList)
		{
			LifeSkillCombatEffectItem effectItem = LifeSkillCombatEffect.Instance[key];
			int count = 0;
			cardCollection.CardDict?.TryGetValue(effectItem.TemplateId, out count);
			if (effectItem.Level == cardLevel && count + effectItem.BaseAmount < effectItem.MaxAmount)
			{
				cardConfig = effectItem;
				break;
			}
		}
		if (cardConfig != null)
		{
			ref Dictionary<sbyte, int> cardDict = ref cardCollection.CardDict;
			if (cardDict == null)
			{
				cardDict = new Dictionary<sbyte, int>();
			}
			cardCollection.CardDict.TryGetValue(cardConfig.TemplateId, out var count2);
			count2 = (cardCollection.CardDict[cardConfig.TemplateId] = count2 + 1);
			if (hasCardDict)
			{
				SetElement_LifeSkillCombatCardDict(skillConfig.Type, cardCollection, context);
			}
			else
			{
				AddElement_LifeSkillCombatCardDict(skillConfig.Type, cardCollection, context);
			}
			LifeSkillCombatCardCollection newCardCollection;
			bool hasNewDict = TryGetElement_LifeSkillCombatNewCardDict(skillConfig.Type, out newCardCollection);
			cardDict = ref newCardCollection.CardDict;
			if (cardDict == null)
			{
				cardDict = new Dictionary<sbyte, int>();
			}
			newCardCollection.CardDict[cardConfig.TemplateId] = 0;
			if (hasNewDict)
			{
				SetElement_LifeSkillCombatNewCardDict(skillConfig.Type, newCardCollection, context);
			}
			else
			{
				AddElement_LifeSkillCombatNewCardDict(skillConfig.Type, newCardCollection, context);
			}
			if (pageData.PageList == null)
			{
				pageData.PageList = new List<byte>();
			}
			pageData.PageList.Add(page);
			if (hasPageDict)
			{
				SetElement_LifeSkillCombatReadBookPageDict(skillConfig.TemplateId, pageData, context);
			}
			else
			{
				AddElement_LifeSkillCombatReadBookPageDict(skillConfig.TemplateId, pageData, context);
			}
		}
	}

