	private LifeSkillCombatCardCollection GetAiLifeSkillCombatUsedCard(DataContext context, sbyte skillType, int charId)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		_aiCharId = charId;
		short morality = character.GetMorality();
		List<GameData.Domains.Character.LifeSkillItem> learnedLifeSkills = character.GetLearnedLifeSkills();
		LifeSkillCombatCardCollection cardCollection = default(LifeSkillCombatCardCollection);
		cardCollection.CardDict = new Dictionary<sbyte, int>();
		foreach (LifeSkillCombatEffectItem cardConfig in (IEnumerable<LifeSkillCombatEffectItem>)LifeSkillCombatEffect.Instance)
		{
			cardCollection.CardDict[cardConfig.TemplateId] = cardConfig.BaseAmount;
		}
		learnedLifeSkills.ForEach(delegate(GameData.Domains.Character.LifeSkillItem item)
		{
			Config.LifeSkillItem lifeSkillItem = LifeSkill.Instance[item.SkillTemplateId];
			if (skillType == lifeSkillItem.Type)
			{
				CreateAiLifeSkillCombatCard(context, item, cardCollection);
			}
		});
		Dictionary<sbyte, int> resultCardDict = new Dictionary<sbyte, int>();
		List<(sbyte, int)> rateList = new List<(sbyte, int)>();
		CalcRate(0, 18);
		CalcRate(1, 9);
		CalcRate(2, 3);
		return new LifeSkillCombatCardCollection
		{
			CardDict = resultCardDict
		};
		void CalcRate(int level, int maxUsedCount)
		{
			int levelCountSum = cardCollection.GetLevelCountSum(level);
			Dictionary<sbyte, int> levelCardDict = cardCollection.CardDict.Where((KeyValuePair<sbyte, int> p) => LifeSkillCombatEffect.Instance[p.Key].Level == level).ToDictionary((KeyValuePair<sbyte, int> p) => p.Key, (KeyValuePair<sbyte, int> p) => p.Value);
			float averageRate = 1f / (float)levelCountSum;
			int totalRate = 0;
			rateList.Clear();
			foreach (KeyValuePair<sbyte, int> pair in levelCardDict)
			{
				LifeSkillCombatEffectItem config = LifeSkillCombatEffect.Instance[pair.Key];
				int offset = GetAiBuildCardRateOffset(morality, config.Group);
				float rate = (float)pair.Value * averageRate * (100f + (float)offset / 100f);
				int intRate = (int)(rate * 100f);
				rateList.Add((pair.Key, intRate));
				totalRate += intRate;
			}
			int resultCount = 0;
			while (resultCount < maxUsedCount)
			{
				resultCount++;
				int random = context.Random.Next(totalRate);
				int tempRate = 0;
				for (int i = 0; i < rateList.Count; i++)
				{
					(sbyte, int) tuple = rateList[i];
					sbyte id = tuple.Item1;
					int rate2 = tuple.Item2;
					tempRate += rate2;
					if (random < tempRate)
					{
						resultCardDict.TryGetValue(id, out var count);
						count = (resultCardDict[id] = count + 1);
						if (count >= cardCollection.CardDict[id])
						{
							rateList.RemoveAt(i);
							totalRate -= rate2;
						}
						break;
					}
				}
			}
		}
	}

	private int GetAiBuildCardRateOffset(short morality, ELifeSkillCombatEffectGroup effectGroup)
	{
		int offset = 0;
		switch (GameData.Domains.Character.BehaviorType.GetBehaviorType(morality))
		{
		case 0:
		case 1:
			switch (effectGroup)
			{
			case ELifeSkillCombatEffectGroup.ReinforceArgument:
				offset = 35;
				break;
			case ELifeSkillCombatEffectGroup.DissembleArgument:
				offset = -35;
				break;
			}
			break;
		case 2:
			switch (effectGroup)
			{
			case ELifeSkillCombatEffectGroup.ReinforceArgument:
				offset = 20;
				break;
			case ELifeSkillCombatEffectGroup.WeakenArgument:
				offset = 20;
				break;
			case ELifeSkillCombatEffectGroup.FlexibleFall:
				offset = -20;
				break;
			case ELifeSkillCombatEffectGroup.DissembleArgument:
				offset = -20;
				break;
			}
			break;
		case 3:
		case 4:
			switch (effectGroup)
			{
			case ELifeSkillCombatEffectGroup.ReinforceArgument:
				offset = -35;
				break;
			case ELifeSkillCombatEffectGroup.WeakenArgument:
				offset = 35;
				break;
			case ELifeSkillCombatEffectGroup.FlexibleFall:
				offset = -35;
				break;
			case ELifeSkillCombatEffectGroup.DissembleArgument:
				offset = 35;
				break;
			case ELifeSkillCombatEffectGroup.EliminateArgument:
				offset = 35;
				break;
			case ELifeSkillCombatEffectGroup.RemoveEffect:
				offset = 35;
				break;
			}
			break;
		}
		return offset;
	}

	public void CreateAiLifeSkillCombatCard(DataContext context, GameData.Domains.Character.LifeSkillItem item, LifeSkillCombatCardCollection cardCollection)
	{
		Config.LifeSkillItem skillConfig = LifeSkill.Instance[item.SkillTemplateId];
		sbyte grade = skillConfig.Grade;
		if (grade >= 0 && grade <= 2)
		{
			List<byte> pageList = new List<byte> { 1, 2, 3 };
			{
				foreach (byte page in pageList)
				{
					if (item.IsPageRead(page))
					{
						CreateAiCard(context, 0, cardCollection);
					}
				}
				return;
			}
		}
		grade = skillConfig.Grade;
		if (grade >= 3 && grade <= 5)
		{
			List<byte> pageList2 = new List<byte> { 2, 3 };
			{
				foreach (byte page2 in pageList2)
				{
					if (item.IsPageRead(page2))
					{
						CreateAiCard(context, 1, cardCollection);
					}
				}
				return;
			}
		}
		grade = skillConfig.Grade;
		if (grade >= 6 && grade <= 8)
		{
			byte page3 = 3;
			if (item.IsPageRead(page3))
			{
				CreateAiCard(context, 2, cardCollection);
			}
		}
	}

	private void CreateAiCard(DataContext context, sbyte cardLevel, LifeSkillCombatCardCollection cardCollection)
	{
		List<sbyte> keyList = LifeSkillCombatEffect.Instance.GetAllKeys();
		CollectionUtils.Shuffle(context.Random, keyList);
		LifeSkillCombatEffectItem cardConfig = null;
		foreach (sbyte key in keyList)
		{
			LifeSkillCombatEffectItem effectItem = LifeSkillCombatEffect.Instance[key];
			int count = 0;
			cardCollection.CardDict?.TryGetValue(effectItem.TemplateId, out count);
			if (effectItem.Level == cardLevel && count + effectItem.BaseAmount < effectItem.MaxAmount)
			{
				cardConfig = effectItem;
				break;
			}
		}
		if (cardConfig != null)
		{
			ref Dictionary<sbyte, int> cardDict = ref cardCollection.CardDict;
			if (cardDict == null)
			{
				cardDict = new Dictionary<sbyte, int>();
			}
			cardCollection.CardDict.TryGetValue(cardConfig.TemplateId, out var count2);
			count2 = (cardCollection.CardDict[cardConfig.TemplateId] = count2 + 1);
		}
	}

