	private bool IsItemChildOfLoongRelated(ItemKey key)
	{
		int result;
		if (key.ItemType == 4)
		{
			short templateId = key.TemplateId;
			if (templateId >= 77)
			{
				result = ((templateId <= 85) ? 1 : 0);
				goto IL_0021;
			}
		}
		result = 0;
		goto IL_0021;
		IL_0021:
		return (byte)result != 0;
	}

