	public void UpdateEnemyNestInitializationDates(DataContext context, int beginDate)
	{
		if (_enemyNestInitializationDates != null && _enemyNestInitializationDates.Count > 0)
		{
			return;
		}
		_enemyNestInitializationDates = new List<IntList>();
		for (int areaId = 0; areaId < 45; areaId++)
		{
			MapAreaData areaData = DomainManager.Map.GetElement_Areas(areaId);
			MapAreaItem areaCfg = areaData.GetConfig();
			IntList dates = IntList.Create();
			_enemyNestInitializationDates.Add(dates);
			List<IntPair> enemyNestCreationDateRanges = areaCfg.EnemyNestCreationDateRanges;
			if (enemyNestCreationDateRanges == null || enemyNestCreationDateRanges.Count <= 0)
			{
				continue;
			}
			foreach (IntPair range in areaCfg.EnemyNestCreationDateRanges)
			{
				int date = ((range.First == range.Second) ? range.First : context.Random.Next(range.First, range.Second));
				date += beginDate;
				dates.Items.Add(date);
			}
		}
		SetEnemyNestInitializationDates(_enemyNestInitializationDates, context);
	}

	public int GetEnemyNestInitializationDate(short areaId, int index)
	{
		if (!_enemyNestInitializationDates.CheckIndex(areaId))
		{
			return int.MinValue;
		}
		IntList dates = _enemyNestInitializationDates[areaId];
		if (!dates.Items.CheckIndex(index))
		{
			return int.MinValue;
		}
		return dates.Items[index];
	}

