	public void SetAreaSpiritualDebt(DataContext context, short areaId, int value, bool getProfessionSeniority = true, bool addInstantNotification = true)
	{
		value = Math.Clamp(value, GlobalConfig.Instance.SpiritualDebtLimit[0], GlobalConfig.Instance.SpiritualDebtLimit[1]);
		int originalValue = GetAreaSpiritualDebt(areaId);
		if (value > originalValue)
		{
			if (addInstantNotification)
			{
				DomainManager.World.GetInstantNotifications().AddGraceIncreased(new Location(areaId, -1));
			}
			if (originalValue >= 0 && getProfessionSeniority)
			{
				ProfessionFormulaItem formula = ProfessionFormula.Instance[92];
				int addSeniority = formula.Calculate(value - originalValue);
				DomainManager.Extra.ChangeProfessionSeniority(context, 14, addSeniority);
			}
		}
		if (_areaSpiritualDebt.ContainsKey(areaId))
		{
			SetElement_AreaSpiritualDebt(areaId, value, context);
		}
		else
		{
			AddElement_AreaSpiritualDebt(areaId, value, context);
		}
	}

	public void ChangeAreaSpiritualDebt(DataContext context, short areaId, int delta, bool getProfessionSeniority = true, bool addInstantNotification = true)
	{
		SetAreaSpiritualDebt(context, areaId, GetAreaSpiritualDebt(areaId) + delta, getProfessionSeniority, addInstantNotification);
		DomainManager.Global.InvokeGuidingTrigger(context, 300);
	}

	public void CreateExtraCricketMapUnit(DataContext context, Location location, short lifeTime, bool showAsRegular = false, short wishingCricketId = -1)
	{
		CricketPlaceExtraData cricketPlaceExtraData;
		bool exist = TryGetElement_CricketPlaceExtraData(location.AreaId, out cricketPlaceExtraData);
		if (cricketPlaceExtraData == null)
		{
			cricketPlaceExtraData = new CricketPlaceExtraData();
		}
		CricketPlaceExtraData cricketPlaceExtraData2 = cricketPlaceExtraData;
		if (cricketPlaceExtraData2.ExtraMapUnits == null)
		{
			cricketPlaceExtraData2.ExtraMapUnits = new Dictionary<short, short>();
		}
		cricketPlaceExtraData.ExtraMapUnits[location.BlockId] = lifeTime;
		if (showAsRegular)
		{
			cricketPlaceExtraData2 = cricketPlaceExtraData;
			if (cricketPlaceExtraData2.RegularCrickets == null)
			{
				cricketPlaceExtraData2.RegularCrickets = new List<short>();
			}
			cricketPlaceExtraData.RegularCrickets.Add(location.BlockId);
		}
		if (wishingCricketId >= 0)
		{
			cricketPlaceExtraData2 = cricketPlaceExtraData;
			if (cricketPlaceExtraData2.WishingCrickets == null)
			{
				cricketPlaceExtraData2.WishingCrickets = new Dictionary<short, short>();
			}
			cricketPlaceExtraData.WishingCrickets[location.BlockId] = wishingCricketId;
		}
		if (exist)
		{
			SetElement_CricketPlaceExtraData(location.AreaId, cricketPlaceExtraData, context);
		}
		else
		{
			AddElement_CricketPlaceExtraData(location.AreaId, cricketPlaceExtraData, context);
		}
	}

	public void RemoveExtraCricketMapUnit(DataContext context, Location location)
	{
		if (TryGetElement_CricketPlaceExtraData(location.AreaId, out var cricketPlaceExtraData) && cricketPlaceExtraData != null && cricketPlaceExtraData.ExtraMapUnits != null)
		{
			cricketPlaceExtraData.ExtraMapUnits.Remove(location.BlockId);
			cricketPlaceExtraData.RegularCrickets?.Remove(location.BlockId);
			cricketPlaceExtraData.WishingCrickets?.Remove(location.BlockId);
			SetElement_CricketPlaceExtraData(location.AreaId, cricketPlaceExtraData, context);
			OnBuildingAreaEffectLocationChanged(context, 1, location, Location.Invalid);
		}
	}

	internal void UpdateExtraCricketMapUnit(DataContext context)
	{
		for (short areaId = 0; areaId < 141; areaId++)
		{
			if (TryGetElement_CricketPlaceExtraData(areaId, out var cricketPlaceExtraData) && cricketPlaceExtraData != null && cricketPlaceExtraData.ExtraMapUnits != null)
			{
				short[] array = cricketPlaceExtraData.ExtraMapUnits.Keys.ToArray();
				foreach (short blockId in array)
				{
					short lifeTime = cricketPlaceExtraData.ExtraMapUnits[blockId];
					lifeTime--;
					if (lifeTime <= 0)
					{
						RemoveExtraCricketMapUnit(context, new Location(areaId, blockId));
					}
					else
					{
						cricketPlaceExtraData.ExtraMapUnits[blockId] = lifeTime;
					}
				}
				SetElement_CricketPlaceExtraData(areaId, cricketPlaceExtraData, context);
			}
		}
	}

	public void CreatePickups(DataContext context)
	{
		if (_pickupDict.Count > 0)
		{
			AdaptableLog.TagWarning("Map", "Pickups already generated, skipped.");
			return;
		}
		Stopwatch sw = GlobalDomain.StartTimer();
		Dictionary<Location, MapPickupCollection> pickups = new Dictionary<Location, MapPickupCollection>();
		Stopwatch sw2 = GlobalDomain.StartTimer();
		context.SwitchRandomSource(DomainManager.World.GetWorldId());
		new MapPickupGenerator().Generate(context.Random, pickups);
		context.RestoreRandomSource();
		GlobalDomain.StopTimer(sw2, "CreatePickups.Generate");
		Stopwatch sw3 = GlobalDomain.StartTimer();
		ClearPickupDict(context);
		foreach (var (location2, pickupCollection) in pickups)
		{
			AddElement_PickupDict(location2, pickupCollection, context);
		}
		GlobalDomain.StopTimer(sw3, "CreatePickups.Save");
		RefreshPickupsVisibleByResource(context);
		GlobalDomain.StopTimer(sw, "CreatePickups");
	}

