	{
		List<(Location, MapPickupCollection)> modify = new List<(Location, MapPickupCollection)>();
		foreach (var (location2, pickupCollection) in _pickupDict)
		{
			if (pickupCollection.ClearIgnoredAndTriggered())
			{
				modify.Add((location2, pickupCollection));
			}
		}
		foreach (var (location3, pickupCollection2) in modify)
		{
			SetElement_PickupDict(location3, pickupCollection2, context);
		}
	}

	private void RefreshPickupsVisibleByResource(DataContext context)
	{
		List<(Location, MapPickupCollection)> modify = new List<(Location, MapPickupCollection)>();
		foreach (KeyValuePair<Location, MapPickupCollection> item in _pickupDict)
		{
			item.Deconstruct(out var key, out var value);
			Location location = key;
			MapPickupCollection pickupCollection = value;
			MapBlockData blockData = DomainManager.Map.GetBlock(location);
			MaterialResources resources = blockData.CurrResources;
			foreach (MapPickup pickup in pickupCollection.PickupList)
			{
				pickup.VisibleByResource = true;
				MapPickupsItem config = MapPickups.Instance[pickup.TemplateId];
				for (sbyte resourceType = 0; resourceType <= 5; resourceType++)
				{
					if (resources.Get(resourceType) < config.Resources[resourceType])
					{
						pickup.VisibleByResource = false;
						break;
					}
				}
				if (pickup.VisibleByResource)
				{
				}
			}
			modify.Add((location, pickupCollection));
		}
		foreach (var (location2, pickupCollection2) in modify)
		{
			SetElement_PickupDict(location2, pickupCollection2, context);
		}
	}

