	public bool IsMerchantFavorabilityReachProgressLimit(int merchantFavorability, out int worldProgressLimitedLevel, out int worldProgressLimitedFavor)
	{
		sbyte worldProgress = DomainManager.World.GetXiangshuProgress();
		int length = GlobalConfig.Instance.MerchantFavorabilityXiangshuLevelRequirements.Length;
		int overIndex = length;
		for (int i = 0; i < length; i++)
		{
			if (GlobalConfig.Instance.MerchantFavorabilityXiangshuLevelRequirements[i] > worldProgress)
			{
				overIndex = i;
				break;
			}
		}
		worldProgressLimitedFavor = overIndex * 10;
		worldProgressLimitedLevel = GameData.Domains.Merchant.SharedMethods.GetFavorLevel(worldProgressLimitedFavor);
		return merchantFavorability >= worldProgressLimitedFavor;
	}

	public MerchantOverFavorData GetMerchantOverFavorData(sbyte merchantType)
	{
		MerchantOverFavorData merchantOverFavorData = (_merchantOverFavorDataArray.CheckIndex(merchantType) ? GetElement_MerchantOverFavorDataArray(merchantType) : null);
		if (merchantOverFavorData == null)
		{
			merchantOverFavorData = new MerchantOverFavorData();
			merchantOverFavorData.MerchantOverFavorLevelDataArray = new MerchantOverFavorLevelData[7];
			for (int i = 0; i < merchantOverFavorData.MerchantOverFavorLevelDataArray.Length; i++)
			{
				MerchantOverFavorLevelData merchantOverFavorLevelData = new MerchantOverFavorLevelData();
				short maxBuyCount = GlobalConfig.Instance.MerchantOverFavorBuyCount[i];
				if (maxBuyCount < 0)
				{
					maxBuyCount = short.MaxValue;
				}
				merchantOverFavorLevelData.BuyCount = maxBuyCount;
				merchantOverFavorData.MerchantOverFavorLevelDataArray[i] = merchantOverFavorLevelData;
			}
		}
		int favorability = DomainManager.Merchant.GetCurFavorability(merchantType);
		int curLevel = GameData.Domains.Merchant.SharedMethods.GetFavorLevel(favorability);
		IsMerchantFavorabilityReachProgressLimit(favorability, out var limitedLevel, out var _);
		for (int j = 0; j < merchantOverFavorData.MerchantOverFavorLevelDataArray.Length; j++)
		{
			if (j < limitedLevel && j <= curLevel)
			{
				merchantOverFavorData.MerchantOverFavorLevelDataArray[j].BuyCount = short.MaxValue;
			}
		}
		return merchantOverFavorData;
	}

	public void SetMerchantOverFavorData(DataContext context, sbyte merchantType, MerchantOverFavorData merchantOverFavorData)
	{
		int merchantFavorability = DomainManager.Merchant.GetCurFavorability(merchantType);
		IsReachProgressLimit(merchantFavorability, out var _, out var worldProgressLimitedFavor);
		int realMerchantFavorability = Math.Min(worldProgressLimitedFavor, merchantFavorability);
		for (int i = 0; i < merchantOverFavorData.MerchantOverFavorLevelDataArray.Length; i++)
		{
			MerchantOverFavorLevelData merchantOverFavorLevelData = merchantOverFavorData.MerchantOverFavorLevelDataArray[i];
			if (i <= GameData.Domains.Merchant.SharedMethods.GetFavorLevel(realMerchantFavorability))
			{
				short maxBuyCount = GlobalConfig.Instance.MerchantOverFavorBuyCount[i];
				if (maxBuyCount < 0)
				{
					maxBuyCount = short.MaxValue;
				}
				merchantOverFavorLevelData.BuyCount = maxBuyCount;
				merchantOverFavorLevelData.Inventory.Items.Clear();
			}
		}
		if (_merchantOverFavorDataArray.CheckIndex(merchantType))
		{
			SetElement_MerchantOverFavorDataArray(merchantType, merchantOverFavorData, context);
		}
	}

	public bool IsReachProgressLimit(int merchantFavorability, out int worldProgressLimitedLevel, out int worldProgressLimitedFavor)
	{
		sbyte worldProgress = DomainManager.World.GetXiangshuProgress();
		int length = GlobalConfig.Instance.MerchantFavorabilityXiangshuLevelRequirements.Length;
		int overIndex = length;
		for (int i = 0; i < length; i++)
		{
			if (GlobalConfig.Instance.MerchantFavorabilityXiangshuLevelRequirements[i] > worldProgress)
			{
				overIndex = i;
				break;
			}
		}
		worldProgressLimitedFavor = overIndex * 10;
		worldProgressLimitedLevel = GameData.Domains.Merchant.SharedMethods.GetFavorLevel(worldProgressLimitedFavor);
		return merchantFavorability >= worldProgressLimitedFavor;
	}

