	public MerchantExtraGoodsData.ExtraGoodsType GetExtraGoodsType(ItemKey itemKey)
	{
		MerchantExtraGoodsData.ExtraGoodsType goodsType = MerchantExtraGoodsData.ExtraGoodsType.None;
		if (!itemKey.IsValid())
		{
			return goodsType;
		}
		if (!ModificationStateHelper.IsActive(itemKey.ModificationState, 8))
		{
			return goodsType;
		}
		foreach (var (key, merchantExtraGoods) in _merchantExtraGoods)
		{
			if (merchantExtraGoods.Check(itemKey.Id, out goodsType))
			{
				break;
			}
		}
		return goodsType;
	}

