	public int SetVillagerRoleNickName(DataContext context, short roleTemplateId, string nickName)
	{
		if (roleTemplateId < 0 || roleTemplateId >= VillagerRole.Instance.Count)
		{
			return -1;
		}
		if (string.IsNullOrEmpty(nickName))
		{
			RemoveVillagerRoleNickName(context, roleTemplateId);
			return -1;
		}
		if (_villagerRoleNickNameMap.TryGetValue(roleTemplateId, out var key))
		{
			DomainManager.World.UnregisterCustomText(context, key);
			int newKey = DomainManager.World.RegisterCustomText(context, nickName);
			SetElement_VillagerRoleNickNameMap(roleTemplateId, newKey, context);
			return newKey;
		}
		int newKey2 = DomainManager.World.RegisterCustomText(context, nickName);
		AddElement_VillagerRoleNickNameMap(roleTemplateId, newKey2, context);
		return newKey2;
	}

