	public void ChangeProfessionSeniority(DataContext context, int professionId, int baseDelta, bool withBonus = true, bool cached = false)
	{
		if (!DomainManager.World.GetWorldFunctionsStatus(27) || !DomainManager.Extra.TryGetElement_TaiwuProfessions(professionId, out var professionData))
		{
			return;
		}
		ProfessionItem professionCfg = professionData.GetConfig();
		HashSet<int> professionOldUnlockStates = new HashSet<int>();
		for (int i = 0; i <= professionCfg.ProfessionSkills.Length; i++)
		{
			if (professionData.IsSkillUnlocked(i))
			{
				professionOldUnlockStates.Add(i);
			}
		}
		int delta = baseDelta;
		if (delta > 0 && withBonus)
		{
			int bonusFactor = GetSeniorityBonusFactor(professionId);
			short worldFactor = GetWorldProfessionUpgradePercent();
			int buildingFactor = DomainManager.Building.GetBuildingBlockEffect(DomainManager.Taiwu.GetTaiwuVillageSettlementId(), EBuildingScaleEffect.ProfessionSeniorityBonus);
			delta = baseDelta * bonusFactor / 100 * worldFactor / 100;
			delta *= (CValuePercentBonus)buildingFactor;
		}
		if (delta < 0)
		{
			return;
		}
		if (delta > 0)
		{
			_addingProfessionSeniorityData.TryAdd(professionId, 0);
			_addingProfessionSeniorityData[professionId] += delta;
		}
		int prevVal = professionData.Seniority;
		professionData.Seniority += delta;
		int oldExtraSeniority = professionData.ExtraSeniority;
		CharacterDomain.OfflineNormalizeProfessionSeniority(DomainManager.Taiwu.GetTaiwuCharId(), professionData);
		DomainManager.Information.GiveProfessionInformationRemainUsableCount(context, DomainManager.Taiwu.GetTaiwuCharId(), professionId, oldExtraSeniority, professionData.ExtraSeniority);
		InstantNotificationCollection instantNotifications = DomainManager.World.GetInstantNotificationCollection();
		if (delta > 0)
		{
			bool isProfessionSkillRequiresExpEnabled = DomainManager.Taiwu.IsProfessionSkillRequiresExpEnabled();
			for (int j = 0; j <= professionCfg.ProfessionSkills.Length; j++)
			{
				if (!professionOldUnlockStates.Contains(j) && professionData.IsSkillUnlocked(j))
				{
					DomainManager.Information.GiveProfessionInformation(context, DomainManager.Taiwu.GetTaiwuCharId(), professionId);
				}
				if (!professionData.HadBeenUnlocked[j] && professionData.IsSkillUnlocked(j) && !isProfessionSkillRequiresExpEnabled)
				{
					int skillTemplateId = GameData.Domains.Taiwu.Profession.SharedMethods.GetSkillId(professionId, j);
					GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.OpenProfessionSkillUnlocked, skillTemplateId, DomainManager.World.GetAdvancingMonthState() == 0);
					instantNotifications.AddProfessionUnlockSkill(professionId, skillTemplateId);
				}
			}
			if (professionData.Seniority == 3000000 && !_isExtraProfessionSkillUnlocked)
			{
				UnlockExtraProfessionSkill(context);
			}
			OnProfessionSkillUnlocked(context, professionCfg, professionData, professionOldUnlockStates);
		}
		professionData.OfflineUpdateHadBeenUnlocked();
		DomainManager.Extra.SetProfessionData(context, professionData);
		for (int skillIndex = 0; skillIndex < professionData.HadBeenUnlocked.Length; skillIndex++)
		{
			int skillId = GameData.Domains.Taiwu.Profession.SharedMethods.GetSkillId(professionId, skillIndex);
			int skillUnlockSeniority = GameData.Domains.Taiwu.Profession.SharedMethods.GetSkillUnlockSeniority(skillId);
			bool lastUnlocked = prevVal >= skillUnlockSeniority;
			bool curLocked = professionData.Seniority >= skillUnlockSeniority;
			if (!lastUnlocked && curLocked)
			{
				Events.RaiseTaiwuUnlockNewProfessionSkill(context, professionId, skillIndex);
			}
		}
	}

	private void OnProfessionSkillUnlocked(DataContext context, ProfessionItem professionCfg, ProfessionData professionData, HashSet<int> oldUnlockStates)
	{
		bool anyNewSkillUnlocked = false;
		bool allSkillsUnlocked = true;
		for (int i = 0; i <= professionCfg.ProfessionSkills.Length; i++)
		{
			if (!oldUnlockStates.Contains(i) && professionData.IsSkillUnlocked(i))
			{
				anyNewSkillUnlocked = true;
			}
			if (!professionData.IsSkillUnlocked(i))
			{
				allSkillsUnlocked = false;
			}
		}
		if (anyNewSkillUnlocked)
		{
			AchievementManager.RequestSetStat(context, 62, 1);
		}
		if (allSkillsUnlocked)
		{
			short statDefKey = GetProfessionAllSkillUnlockedStatDefKey(professionCfg.TemplateId);
			if (statDefKey >= 0)
			{
				AchievementManager.RequestSetStat(context, statDefKey, 1);
			}
			AchievementManager.RequestSetStat(context, 63, 1);
			CheckAllProfessionsAllSkillUnlocked(context);
		}
	}

	private static short GetProfessionAllSkillUnlockedStatDefKey(int professionId)
	{
		if (1 == 0)
		{
		}
		short result = professionId switch
		{
			0 => 64, 
			1 => 65, 
			2 => 66, 
			3 => 67, 
			4 => 68, 
			5 => 69, 
			6 => 70, 
			7 => 71, 
			8 => 72, 
			9 => 73, 
			10 => 74, 
			11 => 75, 
			12 => 76, 
			13 => 77, 
			14 => 78, 
			15 => 79, 
			16 => 80, 
			17 => 81, 
			_ => -1, 
		};
		if (1 == 0)
		{
		}
		return result;
	}

	private void CheckAllProfessionsAllSkillUnlocked(DataContext context)
	{
		foreach (ProfessionItem profCfg in (IEnumerable<ProfessionItem>)Profession.Instance)
		{
			if (!_taiwuProfessions.TryGetValue(profCfg.TemplateId, out var pd))
			{
				return;
			}
			ProfessionItem pcfg = pd.GetConfig();
			for (int si = 0; si <= pcfg.ProfessionSkills.Length; si++)
			{
				if (!pd.IsSkillUnlocked(si))
				{
					return;
				}
			}
		}
		AchievementManager.RequestSetStat(context, 82, 1);
	}

	public int GetSeniorityBonusFactor(int professionId)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		int factor = 100;
		short bestAttainment = taiwu.GetProfessionBestAttainment(professionId);
		factor += bestAttainment / 3;
		ItemKey clothingKey = taiwu.GetEquipment()[4];
		if (clothingKey.IsValid() && DomainManager.Item.TryGetElement_Clothing(clothingKey.Id, out var clothing) && clothing.GetEquipmentEffectId() == 66)
		{
			factor += 20;
		}
		return factor;
	}

