	public TasterUltimateResult CastTasterUltimateSkill(DataContext context, List<int> charIds, List<int> bookIds, bool isCombatSkill)
	{
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		TasterUltimateResult result = null;
		foreach (int bookId in bookIds)
		{
			ReadBook(context, bookId, charIds, isCombatSkill, ref result);
		}
		charIds.Sort();
		for (int i = 0; i < charIds.Count; i++)
		{
			int charIdA = charIds[i];
			result.Characters.Add(charIdA, DomainManager.Character.GetCharacterDisplayData(charIdA));
			GameData.Domains.Character.Character charA = DomainManager.Character.GetElement_Objects(charIdA);
			sbyte behaviorTypeA = charA.GetBehaviorType();
			for (int j = i + 1; j < charIds.Count; j++)
			{
				int charIdB = charIds[j];
				GameData.Domains.Character.Character charB = DomainManager.Character.GetElement_Objects(charIdB);
				sbyte behaviorTypeB = charB.GetBehaviorType();
				int behaviorTypeEffect = 50;
				if (GameData.Domains.Character.BehaviorType.IsContradictory(behaviorTypeA, behaviorTypeB))
				{
					behaviorTypeEffect = 20;
				}
				else if (behaviorTypeA == behaviorTypeB)
				{
					behaviorTypeEffect = 80;
				}
				bool isAdd = context.Random.CheckPercentProb(behaviorTypeEffect);
				int delta = 15000 * (isAdd ? 1 : (-1));
				DomainManager.Character.ChangeFavorabilityOptional(context, charA, charB, delta, 3);
				DomainManager.Character.ChangeFavorabilityOptional(context, charB, charA, delta, 3);
				result.FavorabilityChangeData.Add(new IntPair(charIdA, charIdB), isAdd);
				if (charIdA == taiwuCharId && charIdB != taiwuCharId)
				{
					if (isCombatSkill)
					{
						EventHelper.ChangeAlertnessOnProfessionWineTasterSkill3(charIdB, delta);
					}
					else
					{
						EventHelper.ChangeAlertnessOnProfessionTeaTasterSkill3(charIdB, delta);
					}
				}
				else if (charIdA != taiwuCharId && charIdB == taiwuCharId)
				{
					if (isCombatSkill)
					{
						EventHelper.ChangeAlertnessOnProfessionWineTasterSkill3(charIdA, delta);
					}
					else
					{
						EventHelper.ChangeAlertnessOnProfessionTeaTasterSkill3(charIdA, delta);
					}
				}
			}
		}
		int half = charIds.Count / 2;
		CollectionUtils.Shuffle(context.Random, charIds);
		for (int k = 0; k < half; k++)
		{
			foreach (var (idPair, isAdd2) in result.FavorabilityChangeData)
			{
				if ((idPair.First != charIds[k] && idPair.Second != charIds[k]) || result.RelationChangeData.ContainsKey(idPair))
				{
					continue;
				}
				GameData.Domains.Character.Character charA2 = DomainManager.Character.GetElement_Objects(idPair.First);
				bool charAIsTaiwuPeople = DomainManager.Character.IsTaiwuPeople(idPair.First);
				sbyte behaviorTypeA2 = charA2.GetBehaviorType();
				GameData.Domains.Character.Character charB2 = DomainManager.Character.GetElement_Objects(idPair.Second);
				bool charBIsTaiwuPeople = DomainManager.Character.IsTaiwuPeople(idPair.Second);
				sbyte behaviorTypeB2 = charB2.GetBehaviorType();
				RelatedCharacter selfToTarget = DomainManager.Character.GetRelation(idPair.First, idPair.Second);
				RelatedCharacter targetToSelf = DomainManager.Character.GetRelation(idPair.Second, idPair.First);
				short charAAge = charA2.GetCurrAge();
				short charBAge = charB2.GetCurrAge();
				if (isAdd2)
				{
					if (charA2.GetAgeGroup() == 2 && charB2.GetAgeGroup() == 2)
					{
						if (AiHelper.Relation.CanStartRelation_BoyOrGirlFriend(selfToTarget, behaviorTypeA2, targetToSelf, behaviorTypeB2) && context.Random.CheckPercentProb(AiHelper.Relation.GetStartRelationSuccessRate_BoyOrGirlFriend(charA2, charB2, selfToTarget, targetToSelf)))
						{
							GameData.Domains.Character.Character.ApplyBecomeBoyOrGirlFriend(context, charA2, charB2, behaviorTypeA2, succeed: true, charAIsTaiwuPeople, charBIsTaiwuPeople);
							result.RelationChangeData.Add(idPair, 16384);
							continue;
						}
						if (AiHelper.Relation.CanStartRelation_Adored(selfToTarget, behaviorTypeA2) && context.Random.CheckPercentProb(AiHelper.Relation.GetStartRelationSuccessRate_Adored(charA2, charB2, selfToTarget, targetToSelf)))
						{
							GameData.Domains.Character.Character.ApplyAddRelation_Adore(context, charA2, charB2, behaviorTypeA2, targetLovesBack: true, charAIsTaiwuPeople, charBIsTaiwuPeople);
							result.RelationChangeData.Add(idPair, 16384);
							continue;
						}
					}
					if (AiHelper.Relation.CanStartRelation_SwornBrotherOrSister(selfToTarget, behaviorTypeA2, targetToSelf, behaviorTypeB2))
					{
						GameData.Domains.Character.Character.ApplyBecomeSwornBrotherOrSister(context, charA2, charB2, behaviorTypeA2, charAIsTaiwuPeople, charBIsTaiwuPeople);
						result.RelationChangeData.Add(idPair, 512);
					}
					else if (AiHelper.Relation.CanStartRelation_AdoptiveChild(idPair.First, selfToTarget, charAAge, idPair.Second, targetToSelf, charBAge) && charAAge - charBAge > 25)
					{
						GameData.Domains.Character.Character.ApplyAddRelation_AdoptiveChild(context, charA2, charB2, behaviorTypeA2, charAIsTaiwuPeople, charBIsTaiwuPeople);
						result.RelationChangeData.Add(idPair, 128);
					}
					else if (AiHelper.Relation.CanStartRelation_AdoptiveParent(idPair.Second, targetToSelf, charBAge, idPair.First, selfToTarget, charAAge) && charBAge - charAAge > 25)
					{
						GameData.Domains.Character.Character.ApplyAddRelation_AdoptiveParent(context, charA2, charB2, behaviorTypeA2, charAIsTaiwuPeople, charBIsTaiwuPeople);
						result.RelationChangeData.Add(idPair, 64);
					}
					else if (AiHelper.Relation.CanStartRelation_Friend(selfToTarget, behaviorTypeA2, targetToSelf, behaviorTypeB2))
					{
						GameData.Domains.Character.Character.ApplyBecomeFriend(context, charA2, charB2, behaviorTypeA2, charAIsTaiwuPeople, charBIsTaiwuPeople);
						result.RelationChangeData.Add(idPair, 8192);
					}
				}
				else if (AiHelper.Relation.CanStartRelation_Enemy(selfToTarget, behaviorTypeA2))
				{
					GameData.Domains.Character.Character.ApplyAddRelation_Enemy(context, charA2, charB2, charAIsTaiwuPeople, 0);
					result.RelationChangeData.Add(idPair, 32768);
				}
			}
		}
		return result;
	}

	public void ReadBook(DataContext context, int bookId, List<int> charIds, bool isCombatSkill, ref TasterUltimateResult result)
	{
		if (result == null)
		{
			result = new TasterUltimateResult();
		}
		int taiwuId = DomainManager.Taiwu.GetTaiwuCharId();
		GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(bookId);
		byte pageTypes = book.GetPageTypes();
		short attainment = 0;
		sbyte lifeSkillType = 0;
		sbyte bookGrade = book.GetGrade();
		result.Books.Add(book.GetTemplateId());
		short skillTemplateId;
		if (isCombatSkill)
		{
			skillTemplateId = book.GetCombatSkillTemplateId();
			foreach (int charId in charIds)
			{
				GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
				if (!character.GetLearnedCombatSkills().Contains(skillTemplateId))
				{
					character.LearnNewCombatSkill(context, skillTemplateId, 0);
				}
				attainment += character.GetCombatSkillAttainment(book.GetCombatSkillType());
			}
		}
		else
		{
			skillTemplateId = book.GetLifeSkillTemplateId();
			foreach (int charId2 in charIds)
			{
				GameData.Domains.Character.Character character2 = DomainManager.Character.GetElement_Objects(charId2);
				if (character2.FindLearnedLifeSkillIndex(skillTemplateId) < 0)
				{
					character2.LearnNewLifeSkill(context, skillTemplateId, 0);
				}
				lifeSkillType = book.GetLifeSkillType();
				attainment += character2.GetLifeSkillAttainment(lifeSkillType);
			}
		}
		int completedReaderCount = 0;
		foreach (int charId3 in charIds)
		{
			GameData.Domains.Character.Character character3 = DomainManager.Character.GetElement_Objects(charId3);
			int remainingSpeedPercent = 100 * charIds.Count;
			byte readingPage = 0;
			byte readPageResult = 0;
			byte pageCountLimit = book.GetPageCount();
			GameData.Domains.CombatSkill.CombatSkill combatSkill = null;
			character3.TryApplyAttachedPoison(context, book.GetItemKey());
			if (isCombatSkill)
			{
				combatSkill = DomainManager.CombatSkill.GetElement_CombatSkills(new CombatSkillKey(charId3, skillTemplateId));
			}
			while (remainingSpeedPercent > 0 && readingPage < pageCountLimit)
			{
				ushort readingState = 0;
				int learnedIndex = 0;
				byte pageInternalIndex;
				bool isPageRead;
				if (isCombatSkill)
				{
					readingState = combatSkill.GetReadingState();
					sbyte outlinePageType = SkillBookStateHelper.GetOutlinePageType(pageTypes);
					sbyte normalPageType = SkillBookStateHelper.GetNormalPageType(pageTypes, readingPage);
					pageInternalIndex = CombatSkillStateHelper.GetPageInternalIndex(outlinePageType, normalPageType, readingPage);
					isPageRead = CombatSkillStateHelper.IsPageRead(readingState, pageInternalIndex);
				}
				else
				{
					learnedIndex = character3.FindLearnedLifeSkillIndex(skillTemplateId);
					pageInternalIndex = readingPage;
					isPageRead = character3.GetLearnedLifeSkills()[learnedIndex].IsPageRead(readingPage);
				}
				if (isPageRead)
				{
					readingPage++;
					continue;
				}
				sbyte incompleteState = SkillBookStateHelper.GetPageIncompleteState(book.GetPageIncompleteState(), readingPage);
				sbyte baseSpeed = SkillBookPageIncompleteState.BaseReadingSpeed[incompleteState];
				int bonusSpeed = GetTasterUltimateReadingSpeedBonus(book, attainment, character3, readingPage, skillTemplateId, completedReaderCount);
				int readingSpeed = baseSpeed * bonusSpeed / 100;
				if (readingSpeed == 0)
				{
					break;
				}
				if (charId3 == taiwuId)
				{
					if (!DomainManager.Taiwu.ReadSkillBookPage(context, book, pageInternalIndex, readingSpeed, isCombatSkill, ref remainingSpeedPercent, ref readingPage).Item1)
					{
						break;
					}
					if (!isCombatSkill)
					{
						switch (lifeSkillType)
						{
						case 13:
						{
							int addSeniority2 = ProfessionFormulaImpl.Calculate(43, bookGrade);
							DomainManager.Extra.ChangeProfessionSeniority(context, 6, addSeniority2);
							break;
						}
						case 12:
						{
							int addSeniority = ProfessionFormulaImpl.Calculate(37, bookGrade);
							DomainManager.Extra.ChangeProfessionSeniority(context, 5, addSeniority);
							break;
						}
						}
					}
				}
				else
				{
					int cost = 10000 / readingSpeed;
					if (remainingSpeedPercent < cost)
					{
						break;
					}
					if (isCombatSkill)
					{
						DomainManager.CombatSkill.SetCombatSkillReadingState(context, combatSkill, CombatSkillStateHelper.SetPageRead(readingState, pageInternalIndex));
						DomainManager.CombatSkill.TryActivateCombatSkillBookPageWhenSetReadingState(context, charId3, skillTemplateId, pageInternalIndex);
					}
					else
					{
						character3.ReadLifeSkillPage(context, learnedIndex, readingPage);
					}
					remainingSpeedPercent -= cost;
					readingPage++;
				}
				readPageResult = (byte)(readPageResult | (1 << (int)readingPage));
			}
			if (readingPage == pageCountLimit)
			{
				completedReaderCount++;
				int pageCount = GetReadPageCountByTasterUltimateRereading(book, attainment, character3, skillTemplateId, remainingSpeedPercent, completedReaderCount - 1);
				character3.ChangeExp(context, SkillGradeData.Instance[bookGrade].ReadingExpGainPerPage * GlobalConfig.Instance.ReadingFinishedBookExpGainPercent * pageCount / 100);
				if (charId3 == taiwuId && !isCombatSkill)
				{
					switch (lifeSkillType)
					{
					case 13:
					{
						int addSeniority4 = ProfessionFormulaImpl.Calculate(44, bookGrade) * pageCount;
						DomainManager.Extra.ChangeProfessionSeniority(context, 6, addSeniority4);
						break;
					}
					case 12:
					{
						int addSeniority3 = ProfessionFormulaImpl.Calculate(38, bookGrade) * pageCount;
						DomainManager.Extra.ChangeProfessionSeniority(context, 5, addSeniority3);
						break;
					}
					}
				}
			}
			result.ReadBookPageData.Add(new IntPair(charId3, bookId), readPageResult);
		}
		Events.RaiseTaiwuReadBook(context, book);
		book.ChangeCurrDurability(context, -charIds.Count);
		if (book.GetCurrDurability() <= 0)
		{
			ItemKey itemKey = book.GetItemKey();
			DomainManager.Taiwu.RemoveTaiwuItemFromTaiwuStorage(context, itemKey, 1, deleteItem: true);
			if (itemKey == DomainManager.Taiwu.GetCurReadingBook())
			{
				DomainManager.Taiwu.SetReadingBook(context, ItemKey.Invalid);
			}
		}
	}

	private int GetReadPageCountByTasterUltimateRereading(GameData.Domains.Item.SkillBook book, short skillAttainment, GameData.Domains.Character.Character character, short skillTemplateId, int remainingSpeedPercent, int completedReaderCount)
	{
		int readPageCount = 0;
		byte limit = book.GetPageCount();
		byte readingPage = 0;
		while (readingPage < limit)
		{
			int bonusSpeed = GetTasterUltimateReadingSpeedBonus(book, skillAttainment, character, readingPage, skillTemplateId, completedReaderCount);
			int readingSpeed = SkillBookPageIncompleteState.BaseReadingSpeed[0] * bonusSpeed / 100;
			int addingProgress = readingSpeed * remainingSpeedPercent / 100;
			if (addingProgress >= 100)
			{
				readPageCount++;
				remainingSpeedPercent -= 10000 / readingSpeed;
				readingPage++;
				continue;
			}
			break;
		}
		return readPageCount;
	}

	private int GetTasterUltimateReadingSpeedBonus(GameData.Domains.Item.SkillBook book, short skillAttainment, GameData.Domains.Character.Character character, byte readingPage, short skillTemplateId, int completedReaderCount)
	{
		int buildingBonusSpeed = 0;
		int sectApprovalFactor = 0;
		int professionBonus = 0;
		int permanentBonus = 0;
		int completionBonus = completedReaderCount * 20;
		byte pageTypes = book.GetPageTypes();
		bool isCombatSkill = book.IsCombatSkillBook();
		if (character.GetId() == DomainManager.Taiwu.GetTaiwuCharId())
		{
			Location location = character.GetLocation();
			if (DomainManager.Extra.IsProfessionalSkillUnlocked(4, 1))
			{
				int seniority = DomainManager.Extra.GetProfessionData(4).Seniority;
				int maxSeniority = 3000000;
				professionBonus = 30 + 30 * seniority / maxSeniority;
			}
			if (isCombatSkill)
			{
				sbyte sectId = Config.CombatSkill.Instance[skillTemplateId].SectId;
				sbyte direction = ((readingPage == 0) ? SkillBookStateHelper.GetOutlinePageType(pageTypes) : SkillBookStateHelper.GetNormalPageType(pageTypes, readingPage));
				sectApprovalFactor = DomainManager.Taiwu.CalcReadingSpeedSectApprovalFactor(sectId, direction, (sbyte)readingPage, isInBattle: false);
				sbyte combatSkillType = book.GetCombatSkillType();
				buildingBonusSpeed += DomainManager.Building.GetBuildingBlockEffect(location, EBuildingScaleEffect.CombatSkillReadingSpeedBonusFactor, combatSkillType);
			}
			else
			{
				sbyte lifeSkillType = book.GetLifeSkillType();
				buildingBonusSpeed += DomainManager.Building.GetBuildingBlockEffect(location, EBuildingScaleEffect.LifeSkillReadingSpeedBonusFactor, lifeSkillType);
			}
		}
		if (character.IsTaiwu())
		{
			ECharacterPropertyReferencedType propertyType = (isCombatSkill ? ECharacterPropertyReferencedType.CombatSkillBookReadEfficiency : ECharacterPropertyReferencedType.LifeSkillBookReadEfficiency);
			permanentBonus = DomainManager.Taiwu.GetTaiwuPropertyPermanentBonus(propertyType).AddPercent;
		}
		int readingSpeedAttainmentFactor = TaiwuDomain.CalcReadingSpeedAttainmentFactor(skillAttainment, book.GetGrade());
		byte difficulty = DomainManager.World.GetReadingDifficulty();
		short difficultyBonus = WorldCreation.Instance[(byte)2].InfluenceFactors[difficulty];
		int speedMultiplier = 100 + permanentBonus + buildingBonusSpeed + professionBonus + completionBonus;
		speedMultiplier = speedMultiplier * (100 + readingSpeedAttainmentFactor) / 100;
		speedMultiplier = speedMultiplier * (100 + sectApprovalFactor) / 100;
		speedMultiplier = speedMultiplier * difficultyBonus / 100;
		return Math.Max(speedMultiplier, 0);
	}

	[DomainMethod]
	public int CheckTasterUltimateSpecialCondition(bool isCombatSkill)
	{
		int res = 0;
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location location = taiwu.GetLocation();
		if (!location.IsValid())
		{
			res = ProfessionSkillInvalidType.Add(res, 1);
		}
		else
		{
			MapBlockData belongSettlementBlock = DomainManager.Map.GetBelongSettlementBlock(location);
			if (belongSettlementBlock == null)
			{
				res = ProfessionSkillInvalidType.Add(res, 1);
			}
			else
			{
				List<short> blockIds = ObjectPool<List<short>>.Instance.Get();
				DomainManager.Map.GetSettlementBlocksAndAffiliatedBlocks(belongSettlementBlock.AreaId, belongSettlementBlock.BlockId, blockIds);
				bool hasCharacter = false;
				foreach (short blockId in blockIds)
				{
					MapBlockData block = DomainManager.Map.GetBlock(location.AreaId, blockId);
					if (block.CharacterSet != null && block.CharacterSet.Count > 0)
					{
						hasCharacter = true;
						break;
					}
				}
				ObjectPool<List<short>>.Instance.Return(blockIds);
				if (!hasCharacter)
				{
					res = ProfessionSkillInvalidType.Add(res, 2);
				}
			}
		}
		Span<ItemSourceType> sourceTypes = stackalloc ItemSourceType[3]
		{
			ItemSourceType.Warehouse,
			ItemSourceType.Inventory,
			ItemSourceType.Treasury
		};
		bool hasBook = false;
		short subType = (short)(isCombatSkill ? 1001 : 1000);
		Span<ItemSourceType> span = sourceTypes;
		for (int i = 0; i < span.Length; i++)
		{
			ItemSourceType sourceType = span[i];
			IReadOnlyDictionary<ItemKey, int> items = DomainManager.Taiwu.GetItems(sourceType);
			foreach (ItemKey itemKey in items.Keys)
			{
				if (ItemTemplateHelper.GetItemSubType(itemKey.ItemType, itemKey.TemplateId) == subType)
				{
					hasBook = true;
					break;
				}
			}
			if (hasBook)
			{
				break;
			}
		}
		if (!hasBook)
		{
			res = ProfessionSkillInvalidType.Add(res, 4);
		}
		return res;
	}

	[DomainMethod]
	public int CheckBeggarUltimateSpecialCondition()
	{
		int res = 0;
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location location = taiwu.GetLocation();
		if (!location.IsValid())
		{
			res = ProfessionSkillInvalidType.Add(res, 1);
		}
		else
		{
			MapBlockData blockData = DomainManager.Map.GetBlock(location);
			if (blockData.CharacterSet == null || blockData.CharacterSet.Count == 0)
			{
				res = ProfessionSkillInvalidType.Add(res, 1);
			}
			else
			{
				bool success = false;
				foreach (int id in blockData.CharacterSet)
				{
					if (!DomainManager.Character.TryGetElement_Objects(id, out var character))
					{
						continue;
					}
					Inventory inventory = character.GetInventory();
					foreach (KeyValuePair<ItemKey, int> pair in inventory.Items)
					{
						if ((pair.Key.ItemType == 8 || pair.Key.ItemType == 7 || pair.Key.ItemType == 9 || ItemTemplateHelper.IsTianJieFuLu(pair.Key.ItemType, pair.Key.TemplateId) || (pair.Key.ItemType == 12 && Config.Misc.Instance[pair.Key.TemplateId].Neili > 0)) && pair.Value > 0)
						{
							success = true;
							break;
						}
						if (pair.Key.ItemType == 5 && IsProfessionalSkillUnlockedAndEquipped(54) && Config.Material.Instance[pair.Key.TemplateId].Grade > 6 && Config.Material.Instance[pair.Key.TemplateId].ItemSubType == 505)
						{
							success = true;
							break;
						}
					}
					if (success)
					{
						break;
					}
				}
				if (!success)
				{
					res = ProfessionSkillInvalidType.Add(res, 1);
				}
			}
		}
		if (taiwu.GetEatingItems().GetAvailableEatingSlot(taiwu.GetCurrMaxEatingSlotsCount()) < 0)
		{
			res = ProfessionSkillInvalidType.Add(res, 16);
		}
		return res;
	}

	[DomainMethod]
	public int CheckAristocratUltimateSpecialCondition()
	{
		int res = 0;
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location location = taiwu.GetLocation();
		if (!location.IsValid())
		{
			res = ProfessionSkillInvalidType.Add(res, 1);
		}
		else
		{
			MapBlockData currBlock = DomainManager.Map.GetBlock(location);
			if (!currBlock.IsCityTown())
			{
				return ProfessionSkillInvalidType.Add(res, 1);
			}
			MapBlockData blockData = currBlock.GetRootBlock();
			Settlement settlement = DomainManager.Organization.GetSettlementByLocation(blockData.GetLocation());
			sbyte orgTemplateId = settlement.GetOrgTemplateId();
			if (!OrganizationDomain.IsSect(orgTemplateId))
			{
				return ProfessionSkillInvalidType.Add(res, 1);
			}
			if (settlement is Sect sect)
			{
				if (sect.Prison.Prisoners.Count == 0)
				{
					return ProfessionSkillInvalidType.Add(res, 8);
				}
				bool count = false;
				foreach (SettlementPrisoner prisoner in sect.Prison.Prisoners)
				{
					if (DomainManager.Character.TryGetElement_Objects(prisoner.CharId, out var character) && !character.IsCompletelyInfected())
					{
						count = true;
						break;
					}
				}
				if (!count)
				{
					res = ProfessionSkillInvalidType.Add(res, 8);
				}
			}
		}
		return res;
	}

	[DomainMethod]
	public bool CheckSpecialCondition_SavageSkill_1(ProfessionData professionData)
	{
		MapDomain mapDomain = DomainManager.Map;
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		foreach (Location blockLocation in ProfessionSkillHandle.GetSavageSkill_1_EffectRange(taiwu.GetLocation()))
		{
			if (!blockLocation.IsValid())
			{
				continue;
			}
			MapBlockData blockData = mapDomain.GetBlock(blockLocation);
			if (blockData.IsCityTown())
			{
				continue;
			}
			MapBlockItem mapBlockConfig = blockData.GetConfig();
			if (mapBlockConfig.Type != EMapBlockType.Station && mapBlockConfig.ResourceCollectionType >= 0)
			{
				MapBlockData block = mapDomain.GetBlock(blockLocation);
				if (block.MaxResources.GetSum() >= 0)
				{
					return true;
				}
			}
		}
		return false;
	}

	[DomainMethod]
	public void EatTianJieFuLu(DataContext context, int charId, ItemKey itemKey, int amount)
	{
