	public void MartialArtistSkill3Execute(DataContext context, bool updateData)
	{
		List<short> combatBlockIds = new List<short>();
		if (updateData)
		{
			UpdateDataForMartialArtistSkill3(context);
		}
		if (MartialArtistCreateRandomEnemyDict == null || MartialArtistCreateRandomEnemyDict.Count == 0)
		{
			return;
		}
		List<short> defeatedTemplateIds = ObjectPool<List<short>>.Instance.Get();
		CombatResultDisplayData combatResultData = new CombatResultDisplayData();
		CombatResultSnapshot snapshotBeforeInitialized = combatResultData.SnapshotBeforeCombat;
		snapshotBeforeInitialized.EatingItemList.Initialize();
		combatResultData.SnapshotBeforeCombat = snapshotBeforeInitialized;
		CombatResultSnapshot snapshotAfterInitialized = combatResultData.SnapshotAfterCombat;
		snapshotAfterInitialized.EatingItemList.Initialize();
		combatResultData.SnapshotAfterCombat = snapshotAfterInitialized;
		List<ItemDisplayData> lootItemList = new List<ItemDisplayData>();
		List<(MapTemplateEnemyInfo, Location)> enemyInfos = new List<(MapTemplateEnemyInfo, Location)>();
		foreach (KeyValuePair<Location, List<short>> item in MartialArtistCreateRandomEnemyDict)
		{
			item.Deconstruct(out var key, out var value);
			Location location = key;
			List<short> templateIds = value;
			MapBlockData mapBlockData = DomainManager.Map.GetBlockData(location.AreaId, location.BlockId);
			for (int i = templateIds.Count - 1; i >= 0; i--)
			{
				short createdTemplateId = templateIds[i];
				MapTemplateEnemyInfo mapRandomEnemyInfo = MapTemplateEnemyInfo.CreateDefault(createdTemplateId, location.BlockId, 1);
				bool exit = mapBlockData.TemplateEnemyList != null && mapBlockData.TemplateEnemyList.Contains(mapRandomEnemyInfo);
				if (updateData || exit)
				{
					GameData.Domains.Character.Character createRandomEnemy = DomainManager.Character.CreateRandomEnemy(context, createdTemplateId, isTemporary: true);
					int createRandomEnemyId = createRandomEnemy.GetId();
					DomainManager.Character.CompleteCreatingCharacter(createRandomEnemyId);
					int[] enemyTeam = new int[1] { -1 };
					int attackedNpcId = GetMapBlockAttackedNpc(context, createdTemplateId, mapBlockData);
					bool fightWin = false;
					if (attackedNpcId >= 0)
					{
						GameData.Domains.Character.Character attackedNpc = DomainManager.Character.GetElement_Objects(attackedNpcId);
						AiHelper.NpcCombatResultType combatResultType = DomainManager.Character.SimulateCharacterCombat(context, createRandomEnemy, attackedNpc, CombatType.Beat);
						combatBlockIds.Add(location.BlockId);
						fightWin = combatResultType <= AiHelper.NpcCombatResultType.MinorVictory;
						enemyTeam[0] = attackedNpcId;
					}
					else
					{
						MapTemplateEnemyInfo originalEnemyInfo = GetMapBlockAttackedRandomEnemy(context, createdTemplateId, mapBlockData);
						if (originalEnemyInfo.IsValid())
						{
							GameData.Domains.Character.Character originalRandomEnemy = DomainManager.Character.CreateRandomEnemy(context, originalEnemyInfo.TemplateId, isTemporary: true);
							int originalRandomEnemyId = originalRandomEnemy.GetId();
							DomainManager.Character.CompleteCreatingCharacter(originalRandomEnemyId);
							AiHelper.NpcCombatResultType combatResultType2 = DomainManager.Character.SimulateCharacterCombat(context, createRandomEnemy, originalRandomEnemy, CombatType.Beat);
							combatBlockIds.Add(location.BlockId);
							fightWin = combatResultType2 <= AiHelper.NpcCombatResultType.MinorVictory;
							enemyTeam[0] = originalRandomEnemyId;
							if (fightWin)
							{
								Events.RaiseTemplateEnemyLocationChanged(context, originalEnemyInfo, location, Location.Invalid);
								defeatedTemplateIds.Add(originalEnemyInfo.TemplateId);
							}
						}
						else
						{
							fightWin = true;
						}
					}
					if (updateData)
					{
						if (fightWin && DomainManager.Character.TryGetElement_Objects(enemyTeam[0], out var enemyChar))
						{
							CombatConfigItem combatConfig = CombatConfig.Instance[(short)1];
							combatResultData.CombatStatus = 3;
							CombatDomain.ResultCalcExp(combatConfig, isPlaygroundCombat: false, createRandomEnemy, enemyTeam, combatResultData);
							CombatDomain.ResultCalcResource(combatConfig, isPlaygroundCombat: false, createRandomEnemy, enemyTeam, combatResultData);
							CombatDomain.ResultCalcAreaSpiritualDebt(isWin: true, createRandomEnemy, enemyTeam, combatResultData);
							CombatDomain.ResultCalcLootItem(context.Random, 50, combatConfig.CombatType, combatResultData.CombatStatus, isPuppetCombat: false, combatConfig, createRandomEnemy, enemyTeam, Array.Empty<int>(), combatResultData);
							ItemKey[] enemyEquips = enemyChar.GetEquipment();
							foreach (ItemDisplayData itemKey in combatResultData.ItemList)
							{
								ItemKey key2 = itemKey.Key;
								sbyte slotIndex = (sbyte)enemyEquips.IndexOf(key2);
								if (slotIndex >= 0)
								{
									enemyChar.ChangeEquipment(context, slotIndex, -1, ItemKey.Invalid);
								}
								enemyChar.RemoveInventoryItem(context, key2, itemKey.Amount, deleteItem: false);
								lootItemList.Add(itemKey);
								if (GameData.Domains.Character.Character.IsCharacterIdValid(attackedNpcId))
								{
									LifeRecordCollection c = DomainManager.LifeRecord.GetLifeRecordCollection();
									int date = DomainManager.World.GetCurrDate();
									if (createRandomEnemyId >= 375 && createRandomEnemyId <= 383)
									{
										c.AddMartialArtistSkill3NPCItemDropCaseB(attackedNpcId, date, enemyChar.GetValidLocation(), createRandomEnemyId, key2.ItemType, key2.TemplateId);
									}
									else
									{
										c.AddMartialArtistSkill3NPCItemDropCaseA(attackedNpcId, date, enemyChar.GetValidLocation(), createRandomEnemyId, key2.ItemType, key2.TemplateId);
									}
								}
							}
							combatResultData.ItemList.Clear();
						}
						if (fightWin)
						{
							enemyInfos.Add((mapRandomEnemyInfo, location));
						}
						else
						{
							templateIds.RemoveAt(i);
						}
					}
				}
			}
		}
		foreach (var info in enemyInfos)
		{
			Events.RaiseTemplateEnemyLocationChanged(context, info.Item1, Location.Invalid, info.Item2);
		}
		if (!updateData)
		{
			ClearMartialArtistCreateRandomEnemyDict(context);
		}
		else
		{
			DomainManager.Combat.GetExpAndAuthorityAndAreaSpiritualDebtOutOfCombat(context, defeatedTemplateIds, 3);
			combatResultData.ItemList.Clear();
			MergeKeyForItemDisplayDataList(lootItemList);
			combatResultData.ItemList.AddRange(lootItemList);
			ProfessionSkillArg professionSkillArg = new ProfessionSkillArg
			{
				ProfessionId = 3,
				SkillId = 15,
				IsSuccess = false,
				EffectBlocks = combatBlockIds,
				SkipAnimation = false,
				CombatResultData = combatResultData
			};
			GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.ConfirmSkillExecuteAndPlayAnim, professionSkillArg, arg2: false);
		}
		ObjectPool<List<short>>.Instance.Return(defeatedTemplateIds);
	}

	internal static void MergeKeyForItemDisplayDataList(List<ItemDisplayData> itemDisplayDataList)
	{
		for (int index = 0; index < itemDisplayDataList.Count; index++)
		{
			ItemDisplayData itemDisplayData = itemDisplayDataList[index];
			ItemKey key = itemDisplayData.Key;
			int amount = itemDisplayData.Amount;
			for (int i = index + 1; i < itemDisplayDataList.Count; i++)
			{
				if (itemDisplayDataList[i].Key == key)
				{
					amount += itemDisplayDataList[i].Amount;
					itemDisplayDataList.RemoveAt(i);
					i--;
				}
			}
			itemDisplayDataList[index].Amount = amount;
		}
	}

	public void UpdateDataForMartialArtistSkill3(DataContext context)
	{
		ClearMartialArtistCreateRandomEnemyDict(context);
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location taiwuLocation = taiwu.GetLocation();
		List<MapBlockData> mapBlockList = ObjectPool<List<MapBlockData>>.Instance.Get();
		DomainManager.Map.GetLocationByDistance(taiwuLocation, 0, 3, ref mapBlockList);
		CollectionUtils.Shuffle(context.Random, mapBlockList);
		foreach (MapBlockData mapBlockData in mapBlockList)
		{
			if (!mapBlockData.Visible)
			{
				mapBlockData.SetVisible(visible: true, context);
			}
		}
		int goodCount = GetMartialArtistCreateGoodRandomEnemyCount();
		int badCount = GetMartialArtistCreateBadRandomEnemyCount();
		short goodTemplateId = GetMartialArtistCreateGoodRandomEnemyTemplateId(context);
		short badTemplateId = GetMartialArtistCreateBadRandomEnemyTemplateId(context);
		DomainManager.World.GetInstantNotificationCollection().AddGatherCompanions(goodCount, badCount);
		for (int i = 0; i < goodCount; i++)
		{
			int mapBlockIndex = i % mapBlockList.Count;
			Location location = mapBlockList[mapBlockIndex].GetLocation();
			DomainManager.Extra.AddMartialArtistCreateRandomEnemyDict(location, goodTemplateId);
		}
		CollectionUtils.Shuffle(context.Random, mapBlockList);
		for (int j = 0; j < badCount; j++)
		{
			int mapBlockIndex2 = j % mapBlockList.Count;
			Location location2 = mapBlockList[mapBlockIndex2].GetLocation();
			DomainManager.Extra.AddMartialArtistCreateRandomEnemyDict(location2, badTemplateId);
		}
		ObjectPool<List<MapBlockData>>.Instance.Return(mapBlockList);
	}

	private int GetMapBlockAttackedNpc(DataContext context, short templateId, MapBlockData mapBlockData)
	{
		if (mapBlockData.CharacterSet == null || mapBlockData.CharacterSet.Count == 0)
		{
			return -1;
		}
		bool isRighteous = CharacterDomain.TemplateIdIsRighteous(templateId);
		List<int> charIds = mapBlockData.CharacterSet.ToArray().ToList();
		CollectionUtils.Shuffle(context.Random, charIds);
		foreach (int charId in charIds)
		{
			if (charId == DomainManager.Taiwu.GetTaiwuCharId())
			{
				continue;
			}
			DomainManager.Character.TryGetElement_Objects(charId, out var character);
			if (character == null)
			{
				continue;
			}
			sbyte fameType = character.GetFameType();
			if (isRighteous)
			{
				if (fameType < 3 && fameType != -1)
				{
					return charId;
				}
			}
			else if (fameType > 3 || fameType == -2)
			{
				return charId;
			}
		}
		return -1;
	}

	private MapTemplateEnemyInfo GetMapBlockAttackedRandomEnemy(DataContext context, short templateId, MapBlockData mapBlockData)
	{
		if (mapBlockData.TemplateEnemyList == null || mapBlockData.TemplateEnemyList.Count == 0)
		{
			return MapTemplateEnemyInfo.Invalid;
		}
		bool isRighteous = CharacterDomain.TemplateIdIsRighteous(templateId);
		List<MapTemplateEnemyInfo> mapTemplateEnemyInfos = mapBlockData.TemplateEnemyList.ToArray().ToList();
		foreach (MapTemplateEnemyInfo templateEnemyInfo in mapTemplateEnemyInfos)
		{
			short templateId2 = templateEnemyInfo.TemplateId;
			if (templateId2 >= 366 && templateId2 <= 372)
			{
				return templateEnemyInfo;
			}
			bool enemyIsRighteous = CharacterDomain.TemplateIdIsRighteous(templateEnemyInfo.TemplateId);
			if (templateEnemyInfo.SourceAdventureBlockId == Location.Invalid.BlockId || isRighteous == enemyIsRighteous)
			{
				continue;
			}
			return templateEnemyInfo;
		}
		return MapTemplateEnemyInfo.Invalid;
	}

	private static int GetMartialArtistCreateRandomEnemyCount()
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		int fame = taiwu.GetFame();
		return Math.Abs(fame) * 36 / 100 + 12;
	}

	private static int GetMartialArtistCreateGoodRandomEnemyCount()
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		int fame = taiwu.GetFame();
		int fameType = taiwu.GetFameType();
		int totalCount = GetMartialArtistCreateRandomEnemyCount();
		if (fameType == -2 || fameType == 3)
		{
			return totalCount / 2;
		}
		switch (fameType)
		{
		case 6:
			return totalCount;
		case 0:
			return 0;
		default:
			if (fame > 25)
			{
				return (int)((float)(fame + 100) / 200f * (float)totalCount);
			}
			return (int)((float)totalCount - (float)Math.Abs(fame) / 100f * (float)totalCount);
		}
	}

	private static int GetMartialArtistCreateBadRandomEnemyCount()
	{
		return GetMartialArtistCreateRandomEnemyCount() - GetMartialArtistCreateGoodRandomEnemyCount();
	}

	private static short GetMartialArtistCreateGoodRandomEnemyTemplateId(DataContext context)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		sbyte consummateLevel = taiwu.GetConsummateLevel();
		for (short templateId = 375; templateId <= 383; templateId++)
		{
			CharacterItem config = Config.Character.Instance.GetItem(templateId);
			if (config.ConsummateLevel == consummateLevel)
			{
				return templateId;
			}
		}
		for (short templateId2 = 375; templateId2 <= 383; templateId2++)
		{
			CharacterItem config2 = Config.Character.Instance.GetItem(templateId2);
			if (config2.ConsummateLevel >= consummateLevel)
			{
				return context.Random.CheckPercentProb(50) ? templateId2 : ((short)(templateId2 - 1));
			}
		}
		return 383;
	}

	private static short GetMartialArtistCreateBadRandomEnemyTemplateId(DataContext context)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		sbyte consummateLevel = taiwu.GetConsummateLevel();
		List<short> templateIds = ObjectPool<List<short>>.Instance.Get();
		for (short templateId = 296; templateId <= 365; templateId++)
		{
			CharacterItem config = Config.Character.Instance.GetItem(templateId);
			if (config.ConsummateLevel == consummateLevel)
			{
				templateIds.Add(templateId);
			}
		}
		short targetTemplateId = templateIds.GetRandom(context.Random);
		ObjectPool<List<short>>.Instance.Return(templateIds);
		return targetTemplateId;
	}

