	public void InitializeResourceBlockExtraData(DataContext context, Location location)
	{
		List<ulong> keys = new List<ulong>();
		foreach (ulong key in _resourceBlockExtraData.Keys)
		{
			keys.Add(key);
		}
		foreach (ulong key2 in keys)
		{
			RemoveElement_ResourceBlockExtraData(key2, context);
		}
		IEnumerable<BuildingBlockData> blocks = DomainManager.Building.GetBuildingBlocksAtLocation(location);
		foreach (BuildingBlockData block in blocks)
		{
			EBuildingBlockType? eBuildingBlockType = block?.ConfigData?.Type;
			bool flag;
			if (eBuildingBlockType.HasValue)
			{
				EBuildingBlockType valueOrDefault = eBuildingBlockType.GetValueOrDefault();
				if ((uint)valueOrDefault <= 1u)
				{
					flag = true;
					goto IL_00f5;
				}
			}
			flag = false;
			goto IL_00f5;
			IL_00f5:
			if (flag)
			{
				DomainManager.Extra.SetResourceBlockExtraData(context, new ResourceBlockExtraData(new BuildingBlockKey(location.AreaId, location.BlockId, block.BlockIndex)));
			}
		}
	}

	public void ExchangeResourceBlockExtraData(DataContext context, BuildingBlockKey keyA, BuildingBlockKey keyB)
	{
		ulong idA = (ulong)keyA;
		ulong idB = (ulong)keyB;
		ResourceBlockExtraData dataA;
		bool hasA = TryGetElement_ResourceBlockExtraData(idA, out dataA);
		ResourceBlockExtraData dataB;
		bool hasB = TryGetElement_ResourceBlockExtraData(idB, out dataB);
		if (hasA && hasB)
		{
			RemoveElement_ResourceBlockExtraData(idA, context);
			RemoveElement_ResourceBlockExtraData(idB, context);
			dataA.BuildingBlockKey = keyB;
			dataB.BuildingBlockKey = keyA;
			AddElement_ResourceBlockExtraData(idB, dataA, context);
			AddElement_ResourceBlockExtraData(idA, dataB, context);
		}
		else if (hasA)
		{
			RemoveElement_ResourceBlockExtraData(idA, context);
			dataA.BuildingBlockKey = keyB;
			AddElement_ResourceBlockExtraData(idB, dataA, context);
		}
		else if (hasB)
		{
			RemoveElement_ResourceBlockExtraData(idB, context);
			dataB.BuildingBlockKey = keyA;
			AddElement_ResourceBlockExtraData(idA, dataB, context);
		}
	}

