			RemoveElement_ResourceBlockExtraData(buildingId, context);
		}
	}

	public void UpdateResourceBlockBuildingCoreProducing(DataContext context)
	{
		int currDate = DomainManager.World.GetCurrDate();
		Dictionary<BuildingBlockKey, IntPair> tempDict = new Dictionary<BuildingBlockKey, IntPair>();
		BuildingAreaData areaData = DomainManager.Building.GetElement_BuildingAreas(DomainManager.Taiwu.GetTaiwuVillageLocation());
		List<short> neighborList = ObjectPool<List<short>>.Instance.Get();
		List<int> neighborDistanceList = ObjectPool<List<int>>.Instance.Get();
		List<(BuildingBlockKey, IntPair)> chanceData = new List<(BuildingBlockKey, IntPair)>();
		foreach (ResourceBlockExtraData data in _resourceBlockExtraData.Values)
		{
			if (data.Cooldown >= currDate)
			{
				continue;
			}
			sbyte resourceBlockLevel = DomainManager.Building.BuildingBlockLevel(data.BuildingBlockKey);
			if (resourceBlockLevel <= 0)
			{
				continue;
			}
			int baseChanceDelta = resourceBlockLevel * resourceBlockLevel;
			short blockTemplateId = DomainManager.Building.GetBuildingBlockData(data.BuildingBlockKey).TemplateId;
			BuildingBlockItem config = BuildingBlock.Instance[blockTemplateId];
			if (config == null)
			{
				continue;
			}
			int productivityIndex = 0;
			GetResourceBlockCollectingBuildings(areaData, data.BuildingBlockKey, config.Width, config.ExpandBuildings, neighborList, neighborDistanceList, tempDict, chanceData);
			foreach (var item in chanceData)
			{
				BuildingBlockKey neighBlockKey = item.Item1;
				IntPair productivityData = item.Item2;
				BuildingBlockData blockData = DomainManager.Building.GetBuildingBlockData(neighBlockKey);
				sbyte count = GameData.Domains.Building.SharedMethods.GetBuildingSlotCount(blockData.TemplateId);
				if (DomainManager.Building.TryGetElement_CollectBuildingEarningsData(neighBlockKey, out var earningsData) && earningsData != null && count <= earningsData.CollectionItemList.Count + earningsData.CollectionResourceList.Count)
				{
					continue;
				}
				List<short> eventTemplateIds = blockData.ConfigData.SuccesEvent;
				if (eventTemplateIds == null || eventTemplateIds.Count == 0)
				{
					continue;
				}
				ShopEventItem successShopEventConfig = ShopEvent.Instance[eventTemplateIds[0]];
				if (successShopEventConfig.BuildingCore < 0)
				{
					continue;
				}
				int[] productivityConfig = GlobalConfig.Instance.CollectResourceBuildingProductivityDistanceOne;
				int length = productivityConfig.Length;
				int productivity = ((productivityData.First == 1) ? productivityConfig[(productivityIndex >= length) ? (length - 1) : productivityIndex++] : GlobalConfig.Instance.CollectResourceBuildingProductivityDistanceMore);
				int delta = (productivityData.Second + GlobalConfig.Instance.AddOnAttainmentOfLeader) * baseChanceDelta / 100 * productivity / 100;
				int index = ((Config.Misc.Instance[successShopEventConfig.BuildingCore].Grade >= 4) ? 1 : 0);
				int maxChance = GlobalConfig.Instance.ResourceBlockBuildingCoreProducingMaxChance[index];
				data.Progress += delta;
				if (!context.Random.CheckPercentProb(data.Progress * 100 / maxChance))
				{
					SetResourceBlockExtraData(context, data);
					continue;
				}
				ItemKey itemKey = DomainManager.Item.CreateItem(context, 12, successShopEventConfig.BuildingCore);
				DomainManager.Item.SetOwner(itemKey, ItemOwnerType.Building, blockData.TemplateId);
				if (earningsData == null)
				{
					earningsData = new BuildingEarningsData();
				}
				earningsData.CollectionItemList.Add(itemKey);
				data.Cooldown = currDate + GlobalConfig.Instance.ResourceBlockBuildingCoreProducingCooldown[index];
				data.Progress = 0;
				DomainManager.Building.SetCollectBuildingEarningsData(context, neighBlockKey, earningsData);
				SetResourceBlockExtraData(context, data);
				DomainManager.World.GetMonthlyNotificationCollection().AddCoreMaterialIncome(blockTemplateId, itemKey.ItemType, itemKey.TemplateId);
				break;
			}
		}
		ObjectPool<List<short>>.Instance.Return(neighborList);
		ObjectPool<List<int>>.Instance.Return(neighborDistanceList);
	}

	private void GetResourceBlockCollectingBuildings(BuildingAreaData areaData, BuildingBlockKey blockKey, sbyte width, List<short> expandBuildings, List<short> neighborList, List<int> neighborDistanceList, Dictionary<BuildingBlockKey, IntPair> tempDict, List<(BuildingBlockKey, IntPair)> res)
	{
		neighborList.Clear();
		neighborDistanceList.Clear();
		tempDict.Clear();
		res.Clear();
		areaData.GetNeighborBlocks(blockKey.BuildingBlockIndex, width, neighborList, neighborDistanceList, 2);
		for (int i = 0; i < neighborList.Count; i++)
		{
			BuildingBlockKey neighborKey = new BuildingBlockKey(blockKey.AreaId, blockKey.BlockId, neighborList[i]);
			if (!DomainManager.Building.TryGetElement_BuildingBlocks(neighborKey, out var neighborBlock) || !expandBuildings.Contains(neighborBlock.TemplateId))
			{
				continue;
			}
			if (neighborBlock.RootBlockIndex >= 0)
			{
				neighborKey = new BuildingBlockKey(blockKey.AreaId, blockKey.BlockId, neighborBlock.RootBlockIndex);
			}
			GameData.Domains.Character.Character leader = DomainManager.Building.GetShopManagerLeader(neighborKey);
			if (leader != null)
			{
				BuildingBlockData blockData = DomainManager.Building.GetBuildingBlockData(neighborKey);
				sbyte lifeSkillType = blockData.ConfigData.RequireLifeSkillType;
				int distance = neighborDistanceList[i];
				if (tempDict.TryGetValue(neighborKey, out var data))
				{
					distance = Math.Min(distance, data.First);
				}
				tempDict[neighborKey] = new IntPair(distance, leader.GetLifeSkillAttainment(lifeSkillType));
			}
		}
		foreach (var (key, value) in tempDict)
		{
			res.Add((key, value));
		}
		res.Sort(CompareCollectBuildingBlock);
	}

	private int CompareCollectBuildingBlock((BuildingBlockKey, IntPair) a, (BuildingBlockKey, IntPair) b)
	{
		return (a.Item2.First == b.Item2.First) ? (-a.Item2.Second.CompareTo(b.Item2.Second)) : a.Item2.First.CompareTo(b.Item2.First);
	}

