	public void GenerateRandomBloodLightInXuehou(DataContext context)
	{
		Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(15);
		Location location = settlement.GetLocation();
		List<MapBlockData> belongBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		DomainManager.Map.QueryRegularBelongBlocks(belongBlocks, location, false);
		CollectionUtils.Shuffle(context.Random, belongBlocks);
		if (belongBlocks.Count < 3)
		{
			throw new Exception($"GenerateRandomBloodLightInXuehou() count out of belongs range: count={3}, belongs={belongBlocks.Count}");
		}
		List<MapBlockData> bloodLightNeighborBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		for (int i = 0; i < 3; i++)
		{
			MapBlockData block = belongBlocks[i];
			if (block.GetConfig().SubType == EMapBlockSubType.DLCLoong)
			{
				continue;
			}
			_sectXuehouBloodLightLocations.Add(block.GetLocation());
			DomainManager.Map.GetRealNeighborBlocks(block.AreaId, block.BlockId, bloodLightNeighborBlocks, 1, includeCenter: true);
			foreach (MapBlockData neighborBlock in bloodLightNeighborBlocks)
			{
				if (!neighborBlock.Visible)
				{
					neighborBlock.SetVisible(visible: true, context);
				}
			}
		}
		ObjectPool<List<MapBlockData>>.Instance.Return(belongBlocks);
		ObjectPool<List<MapBlockData>>.Instance.Return(bloodLightNeighborBlocks);
		SetSectXuehouBloodLightLocations(_sectXuehouBloodLightLocations, context);
	}

	public bool IsLocationContainsBloodLight(Location location)
	{
		return _sectXuehouBloodLightLocations.Contains(location);
	}

	public void RemoveBloodLightInLocation(DataContext context, Location location)
	{
		if (_sectXuehouBloodLightLocations.Contains(location))
		{
			_sectXuehouBloodLightLocations.Remove(location);
			SetSectXuehouBloodLightLocations(_sectXuehouBloodLightLocations, context);
		}
	}

