	[DomainMethod]
	public void TaiwuTransferNeiliAllocToJixi(DataContext context, int amount, byte neiliType)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		GameData.Domains.Character.Character jixi = DomainManager.Story.TryGetJixi();
		int taiwuProgressAmount = amount * 100;
		int[] taiwuProgress = taiwu.GetExtraNeiliAllocationProgress();
		if (taiwuProgress[neiliType] < taiwuProgressAmount)
		{
			throw new Exception("TaiwuTransferNeiliAllocToJixi: not enough neili allocation progress");
		}
		taiwuProgress[neiliType] -= taiwuProgressAmount;
		taiwu.SetExtraNeiliAllocationAndProgress(context, taiwuProgress);
		_jixiData.JixiTempNeiliAllocationProgressFromTaiwuAmount += amount;
		_jixiData.NeiliAllocProgressDrainedTotal.Items[neiliType] += amount;
		_jixiData.TransferFromTaiwuTotal += amount;
		int favordelta = amount * 2000 / 55;
		DomainManager.Character.DirectlyChangeFavorabilityOptional(context, jixi, taiwu, favordelta, 1);
		CalculateJixiGrow(context, jixi);
	}

	[DomainMethod]
	public void JixiTransferNeiliAllocToTaiwu(DataContext context, int amount, byte neiliType)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		GameData.Domains.Character.Character jixi = DomainManager.Story.TryGetJixi();
		IntList jixiProgress = _jixiData.NeiliAllocProgressDrained;
		if (jixiProgress.Items[neiliType] < amount)
		{
			throw new Exception("JixiTransferNeiliAllocToTaiwu: not enough neili allocation progress");
		}
		jixiProgress.Items[neiliType] -= amount;
		_jixiData.NeiliAllocProgressDrained = jixiProgress;
		_jixiData.TransferToTaiwuTotal += amount;
		int neiliAllocAdded = amount / 55;
		int neiliAllocRemain = amount % 55;
		int[] taiwuProgress = taiwu.GetExtraNeiliAllocationProgress();
		int maxProgress = GameData.Domains.Character.Character.GetNeiliAllocationMaxProgress();
		int currentAlloc = GameData.Domains.Character.Character.GetExtraNeiliAllocationByProgress(taiwuProgress[neiliType]);
		int currentAllocProgress = GameData.Domains.Character.Character.GetExtraNeiliAllocationProgressByExtraNeiliAllocation(currentAlloc);
		if (currentAlloc < GlobalConfig.Instance.MaxExtraNeiliAllocation)
		{
			currentAlloc += neiliAllocAdded;
			if (currentAlloc > GlobalConfig.Instance.MaxExtraNeiliAllocation)
			{
				currentAlloc = GlobalConfig.Instance.MaxExtraNeiliAllocation;
				taiwuProgress[neiliType] = GameData.Domains.Character.Character.GetNeiliAllocationMaxProgress();
			}
			else
			{
				int remain = taiwuProgress[neiliType] - currentAllocProgress;
				taiwuProgress[neiliType] = GameData.Domains.Character.Character.GetExtraNeiliAllocationProgressByExtraNeiliAllocation(currentAlloc) + remain;
				int basic = GlobalConfig.Instance.ExtraNeiliAllocationFromProgressRatio * 100;
				int delta = GlobalConfig.Instance.ExtraNeiliAllocationFromProgressRatioGrowth * 100;
				int progressSpan = basic + delta * currentAlloc;
				float progressIncrement = (float)neiliAllocRemain * (float)progressSpan / 55f + _jixiData.NeiliAllocProgressTransferRemain[neiliType];
				taiwuProgress[neiliType] += (int)progressIncrement;
				_jixiData.NeiliAllocProgressTransferRemain[neiliType] = progressIncrement % 1f;
			}
			taiwu.SetExtraNeiliAllocationAndProgress(context, taiwuProgress);
		}
		CalculateJixiGrow(context, jixi);
	}

