	public void JixiRescueTaiwu(DataContext context, GameData.Domains.Character.Character character)
	{
		if (character != null && character.GetTemplateId() != 877)
		{
			GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
			short taiwuMaxHealth = taiwu.GetLeftMaxHealth();
			short templateId = character.GetTemplateId();
			if (1 == 0)
			{
			}
			sbyte b = templateId switch
			{
				878 => 50, 
				879 => 100, 
				_ => throw new Exception($"Template out of range: charId={character.GetId()}, templateId={character.GetTemplateId()}"), 
			};
			if (1 == 0)
			{
			}
			sbyte rescueHealthPercent = b;
			short rescueHealthValue = (short)(taiwuMaxHealth * rescueHealthPercent / 100);
			taiwu.ChangeHealth(context, rescueHealthValue);
			int totalValue = GetJixiTotalGrowValue(character);
			SectStoryJixiData jixiData = _jixiData;
			SectStoryJixiData sectStoryJixiData = jixiData;
			int costedGrowthValue = jixiData.CostedGrowthValue;
			short templateId2 = character.GetTemplateId();
			if (1 == 0)
			{
			}
			int num = templateId2 switch
			{
				878 => totalValue, 
				879 => totalValue, 
				_ => 0, 
			};
			if (1 == 0)
			{
			}
			sectStoryJixiData.CostedGrowthValue = costedGrowthValue + num;
			CalculateJixiGrow(context, character);
			int currDate = DomainManager.World.GetCurrDate();
			LifeRecordCollection lifeRecord = DomainManager.LifeRecord.GetLifeRecordCollection();
			lifeRecord.AddSectMainStoryXuehouJixiRescueTaiwu(taiwu.GetId(), currDate, taiwu.GetLocation());
			_jixiData.RescueTaiwuTimes++;
		}
	}

