	public void CalculateJixiGrow(DataContext context, GameData.Domains.Character.Character character)
	{
		int totalValue = GetJixiTotalGrowValue(character);
		if (1 == 0)
		{
		}
		short num = (short)((totalValue < 770) ? 877 : ((totalValue >= 1540) ? 879 : 878));
		if (1 == 0)
		{
		}
		short templateId = num;
		if (character.GetTemplateId() != templateId)
		{
			List<NpcTravelTarget> travelTargets = character.GetNpcTravelTargets();
			DomainManager.Story.JixiGrowUp(context, character.GetTemplateId(), templateId);
			character = DomainManager.Character.GetOrCreateFixedCharacterByTemplateId(context, templateId);
			character.SetNpcTravelTargets(travelTargets, context);
		}
	}

	public int GetJixiTotalGrowValue(GameData.Domains.Character.Character character)
	{
		int killedCount = DomainManager.Extra.GetJixiData().JixiTempKillAmount;
		int tempNeiliAlloc = DomainManager.Extra.GetJixiData().JixiTempNeiliAllocationProgressFromTaiwuAmount;
		IntList extraNeiliAlloc = _jixiData.NeiliAllocProgressDrained;
		int totalExtraNeiliAlloc = 0;
		for (int i = 0; i < extraNeiliAlloc.Items.Count; i++)
		{
			totalExtraNeiliAlloc += extraNeiliAlloc.Items[i];
		}
		int totalGrowValue = killedCount * 110 + tempNeiliAlloc + totalExtraNeiliAlloc;
		DomainManager.Extra.GetJixiData().CostedGrowthValue = Math.Min(totalGrowValue, DomainManager.Extra.GetJixiData().CostedGrowthValue);
		return totalGrowValue - DomainManager.Extra.GetJixiData().CostedGrowthValue;
	}

	public int SetJixiGrowByEvent(DataContext context, short templateId)
	{
		if (templateId < 877 || templateId > 879)
		{
			AdaptableLog.Warning($"SetJixiGrowByEvent: templateId out of range: {templateId}");
			return -1;
		}
		GameData.Domains.Character.Character jixi = DomainManager.Story.TryGetJixi();
		if (jixi == null)
		{
			AdaptableLog.Warning("SetJixiGrowByEvent: jixi is null");
			return -1;
		}
		if (jixi.GetTemplateId() == templateId)
		{
			return jixi.GetId();
		}
		InitJixiSpecialInteractData();
		int currentGrowValue = GetJixiTotalGrowValue(jixi);
		if (1 == 0)
		{
		}
		int num = templateId switch
		{
			877 => 0, 
			878 => 770, 
			879 => 1540, 
			_ => 0, 
		};
		if (1 == 0)
		{
		}
		int targetValue = num;
		if (targetValue < currentGrowValue)
		{
			ClearJixiNeiliData();
			currentGrowValue = GetJixiTotalGrowValue(jixi);
		}
		int extraNeiliAllocCount = (targetValue - currentGrowValue) / 1;
		if (_jixiData.NeiliAllocProgressDrained.Items.Count == 0)
		{
			return -1;
		}
		int itemCount = _jixiData.NeiliAllocProgressDrained.Items.Count;
		int baseValue = extraNeiliAllocCount / itemCount;
		int remainder = extraNeiliAllocCount % itemCount;
		for (int i = 0; i < itemCount; i++)
		{
			_jixiData.NeiliAllocProgressDrained.Items[i] = baseValue + ((i < remainder) ? 1 : 0);
		}
		CalculateJixiGrow(context, jixi);
		return DomainManager.Story.TryGetJixi().GetId();
	}

