	public int HeavenlyTreeGrewUp(DataContext context, int id, int delta, bool showUI, out bool eventTriggered)
	{
		eventTriggered = false;
		if (!DomainManager.Extra.TryGetHeavenlyTreeById(id, out var tree))
		{
			return id;
		}
		tree.GrowPoint += (ushort)delta;
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(id);
		short templateId = GetHeavenlyTreeTemplateIdByGrowValue(tree.GrowPoint);
		Location location = character.GetLocation();
		int res = id;
		int sum = tree.GrowPoint / 100;
		if (sum > tree.TriggerRandomEnemyCount)
		{
			eventTriggered = true;
			tree.TriggerRandomEnemyCount = (ushort)sum;
			int count = 3;
			int range = 2;
			if (sum < 4)
			{
				count = 1;
				range = 3;
			}
			else if (sum < 7)
			{
				count = 2;
				range = (context.Random.NextBool() ? 2 : 3);
			}
			CreateRandomEnemyAroundHeavenlyTree(context, count, range, tree.Location, showUI);
		}
		if (character.GetTemplateId() != templateId)
		{
			GameData.Domains.Character.Character newCharacter = DomainManager.Character.CreateFixedEnemy(context, templateId, isTemporary: false);
			DomainManager.Character.RemoveNonIntelligentCharacter(context, character);
			DomainManager.Character.CompleteCreatingCharacter(newCharacter.GetId());
			newCharacter.SetLocation(location, context);
			tree.Id = newCharacter.GetId();
			res = tree.Id;
			MapBlockData mapBlockData = DomainManager.Map.GetBlockData(location.AreaId, location.BlockId);
			DomainManager.Map.SetBlockData(context, mapBlockData);
			if (templateId == 602)
			{
				ProfessionFormulaItem formulaItem = ProfessionFormula.Instance[3];
				DomainManager.Extra.ChangeProfessionSeniority(context, 0, formulaItem.Calculate());
				RemoveRandomEnemyAroundHeavenlyTree(context, location);
				if (DomainManager.Story.GetSectMainStoryTaskStatus(4) == 0 && !ItemTemplateHelper.CheckIsHeavenlyNormalTreeSeeds(12, tree.TemplateId))
				{
					DomainManager.World.TriggerExtraTask(context, 36, 180);
				}
				if (GetGrowingHeavenlyTreeCount() == 0)
				{
					DomainManager.World.FinishTriggeredExtraTask(context, 36, 174);
				}
				if (GetNormalSeedAndTreeCount() == 0)
				{
					DomainManager.World.FinishTriggeredExtraTask(context, 51, 364);
				}
			}
		}
		SetSectWudangHeavenlyTreeList(_sectWudangHeavenlyTreeList, context);
		return res;
	}

	private void CreateRandomEnemyAroundHeavenlyTree(DataContext context, int count, int range, Location treeLocation, bool showUI)
	{
		sbyte xiangshuLevel = DomainManager.World.GetXiangshuLevel();
		if (xiangshuLevel > 8)
		{
			xiangshuLevel = 8;
		}
		int templateId = xiangshuLevel + 366;
		List<MapBlockData> mapBlockDataList = new List<MapBlockData>();
		DomainManager.Map.GetLocationByDistance(treeLocation, range, range, ref mapBlockDataList);
		DomainManager.Map.CreateRandomEnemiesOnValidBlocks(context, 2, treeLocation, (short)templateId, count, mapBlockDataList);
		if (showUI)
		{
			DomainManager.TaiwuEvent.CloseUI("CreateRandomEnemyAroundHeavenlyTree");
		}
	}

	private void RemoveRandomEnemyAroundHeavenlyTree(DataContext context, Location location)
	{
		List<MapBlockData> blockDataList = ObjectPool<List<MapBlockData>>.Instance.Get();
		DomainManager.Map.GetRealNeighborBlocks(location.AreaId, location.BlockId, blockDataList, 3);
		MapBlockData centerBlockData = DomainManager.Map.GetBlockData(location.AreaId, location.BlockId);
		blockDataList.Add(centerBlockData);
		foreach (MapBlockData blockData in blockDataList)
		{
			List<MapTemplateEnemyInfo> enemyInfos = ObjectPool<List<MapTemplateEnemyInfo>>.Instance.Get();
			List<short> enemyTemplateIdList = ObjectPool<List<short>>.Instance.Get();
			if (blockData.TemplateEnemyList != null && blockData.TemplateEnemyList.Count > 0)
			{
				foreach (MapTemplateEnemyInfo enemyInfo in blockData.TemplateEnemyList)
				{
					CharacterItem characterConfig = Config.Character.Instance[enemyInfo.TemplateId];
					if (characterConfig.GroupId != 375)
					{
						enemyInfos.Add(enemyInfo);
						enemyTemplateIdList.Add(enemyInfo.TemplateId);
					}
				}
				foreach (MapTemplateEnemyInfo randEnemy in enemyInfos)
				{
					Events.RaiseTemplateEnemyLocationChanged(context, randEnemy, blockData.GetLocation(), Location.Invalid);
				}
				DomainManager.Combat.GetExpAndAuthorityAndAreaSpiritualDebtOutOfCombat(context, enemyTemplateIdList);
			}
			ObjectPool<List<MapTemplateEnemyInfo>>.Instance.Return(enemyInfos);
			ObjectPool<List<short>>.Instance.Return(enemyTemplateIdList);
		}
		ObjectPool<List<MapBlockData>>.Instance.Return(blockDataList);
	}

	public int GetGrowingHeavenlyTreeCount()
	{
		int count = 0;
		List<SectStoryHeavenlyTreeExtendable> trees = GetAllHeavenlyTrees();
		foreach (SectStoryHeavenlyTreeExtendable tree in trees)
		{
			if (!ItemTemplateHelper.CheckIsHeavenlyNormalTreeSeeds(12, tree.TemplateId))
			{
				GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(tree.Id);
				if (character.GetTemplateId() != 602)
				{
					count++;
				}
			}
		}
		return count;
	}

	public int GetNormalSeedAndTreeCount()
	{
		int treeCount = 0;
		List<SectStoryHeavenlyTreeExtendable> trees = GetAllHeavenlyTrees();
		foreach (SectStoryHeavenlyTreeExtendable tree in trees)
		{
			if (ItemTemplateHelper.CheckIsHeavenlyNormalTreeSeeds(12, tree.TemplateId))
			{
				GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(tree.Id);
				if (character.GetTemplateId() != 602)
				{
					treeCount++;
				}
			}
		}
		int seedCount = 0;
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		for (short seedTemplateId = 304; seedTemplateId <= 315; seedTemplateId++)
		{
			seedCount += taiwu.GetInventory().GetInventoryItemCount(12, seedTemplateId);
		}
		return seedCount + treeCount;
	}

