	[DomainMethod]
	public List<SectStoryHeavenlyTreeExtendable> GetAllHeavenlyTrees()
	{
		return _sectWudangHeavenlyTreeList.OrderBy((SectStoryHeavenlyTreeExtendable item) => NegativeEnemies(item)).ToList();
		static int NegativeEnemies(SectStoryHeavenlyTreeExtendable tree)
		{
			List<MapBlockData> mapBlockDataList = new List<MapBlockData>();
			DomainManager.Map.GetLocationByDistance(tree.Location, 0, 3, ref mapBlockDataList);
			int count = 0;
			foreach (MapBlockData block in mapBlockDataList)
			{
				count += block.TemplateEnemyList?.Count(delegate(MapTemplateEnemyInfo x)
				{
					short templateId = x.TemplateId;
					return templateId >= 366 && templateId <= 374;
				}) ?? 0;
			}
			return -count;
		}
	}

