	[DomainMethod]
	public List<MapBlockData> GetHeavenlyTreeNearBlocks(int id, int maxSteps)
	{
		List<MapBlockData> blockList = new List<MapBlockData>();
		if (TryGetHeavenlyTreeById(id, out var tree))
		{
			DomainManager.Map.GetRealNeighborBlocks(tree.Location.AreaId, tree.Location.BlockId, blockList, maxSteps, includeCenter: true);
		}
		blockList.Sort(delegate(MapBlockData a, MapBlockData b)
		{
			ByteCoordinate blockPos = a.GetBlockPos();
			ByteCoordinate blockPos2 = b.GetBlockPos();
			if (blockPos.X != blockPos2.X)
			{
				return blockPos.X.CompareTo(blockPos2.X);
			}
			return (blockPos.Y != blockPos2.Y) ? blockPos2.Y.CompareTo(blockPos.Y) : 0;
		});
		return blockList;
	}

