	public void UpdateThreeVitalsInfection(DataContext context)
	{
		bool modified = false;
		bool vitalIsDemon = AreVitalsDemon();
		int value = (vitalIsDemon ? (-GlobalConfig.Instance.ThreeVitalsInfectionDelta) : GlobalConfig.Instance.ThreeVitalsInfectionDelta);
		foreach (SectStoryThreeVitalsCharacter vital in _sectYuanshanThreeVitals)
		{
			if (!vital.IsInPrison)
			{
				vital.Infection = Math.Clamp(vital.Infection + value, 0, GlobalConfig.Instance.ThreeVitalsMaxInfection);
				modified = true;
			}
		}
		if (modified)
		{
			SetSectYuanshanThreeVitals(_sectYuanshanThreeVitals, context);
		}
		MonthlyNotificationCollection monthlyNotifications = DomainManager.World.GetMonthlyNotificationCollection();
		SectStoryThreeVitalsCharacterType[] values = Enum.GetValues<SectStoryThreeVitalsCharacterType>();
		foreach (SectStoryThreeVitalsCharacterType type in values)
		{
			SectStoryThreeVitalsCharacter vital2 = DomainManager.Extra.GetVitalByType(type);
			if (vital2 == null || vital2.IsInPrison)
			{
				continue;
			}
			if (vitalIsDemon)
			{
				if (vital2.Infection <= GlobalConfig.Instance.ThreeVitalsThresholdLow)
				{
					monthlyNotifications.AddYuanshanDemonCrisis(type.GetVitalTemplateId(vitalIsDemon));
				}
			}
			else if (vital2.Infection >= GlobalConfig.Instance.ThreeVitalsThresholdHigh)
			{
				monthlyNotifications.AddYuanshanSpiritCrisis(type.GetVitalTemplateId(vitalIsDemon));
			}
		}
	}

	[DomainMethod]
	public List<CharacterDisplayDataForInfect> GetThreeVitalsTargetCharDataList()
	{
		List<CharacterDisplayDataForInfect> resultList = new List<CharacterDisplayDataForInfect>();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		HashSet<int> charIds = DomainManager.Taiwu.GetGroupCharIds().GetCollection();
		foreach (int charId in charIds)
		{
			GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
			if (character.GetCreatingType() == 1 && character.GetAgeGroup() == 2)
			{
				CharacterDisplayDataForInfect data = new CharacterDisplayDataForInfect
				{
					DataForTooltip = DomainManager.Character.GetCharacterDisplayDataForTooltip(character),
					Infection = character.GetXiangshuInfection(),
					IsTaiwu = (charId == taiwuCharId),
					IsTeammate = (charId != taiwuCharId)
				};
				resultList.Add(data);
			}
		}
		KidnappedCharacterList kidnapCharacters = DomainManager.Character.GetSomeoneKidnapCharacters(taiwuCharId);
		if (kidnapCharacters != null)
		{
			foreach (KidnappedCharacter kidnappedCharacter in kidnapCharacters.GetCollection())
			{
				GameData.Domains.Character.Character character2 = DomainManager.Character.GetElement_Objects(kidnappedCharacter.CharId);
				if (character2.GetCreatingType() == 1 && character2.GetAgeGroup() == 2)
				{
					CharacterDisplayDataForInfect data2 = new CharacterDisplayDataForInfect
					{
						DataForTooltip = DomainManager.Character.GetCharacterDisplayDataForTooltip(character2),
						Infection = character2.GetXiangshuInfection(),
						IsKidnapped = true
					};
					resultList.Add(data2);
				}
			}
		}
		return resultList;
	}

