	private void UnlockSectXuannvMusic(DataContext context, short musicId)
	{
		if (!DomainManager.World.GetWorldFunctionsStatus(28))
		{
			return;
		}
		List<short> list = GetSectXuannvUnlockedMusicList();
		if (list.Contains(musicId))
		{
			return;
		}
		list.Add(musicId);
		SetSectXuannvUnlockedMusicList(list, context);
		InstantNotificationCollection instantNotifications = DomainManager.World.GetInstantNotificationCollection();
		MusicItem music = Music.Instance[musicId];
		if (music.MapState > -1)
		{
			if (music.MapState == 0)
			{
				short settlementId = DomainManager.Taiwu.GetTaiwuVillageSettlementId();
				instantNotifications.AddXuannvBlockMusicTranscribe(settlementId, musicId);
			}
			else
			{
				instantNotifications.AddXuannvStateMusicTranscribe(music.MapState, musicId);
			}
		}
		else if (music.MapBlock > -1)
		{
			MapBlockItem mapBlockConfig = MapBlock.Instance[music.MapBlock];
			OrganizationItem targetOrg = null;
			Config.Organization.Instance.Iterate(delegate(OrganizationItem org)
			{
				if (org.Name == mapBlockConfig.Name)
				{
					targetOrg = org;
					return false;
				}
				return true;
			});
			if (targetOrg != null)
			{
				short settlementId2 = DomainManager.Organization.GetSettlementIdByOrgTemplateId(targetOrg.TemplateId);
				instantNotifications.AddXuannvBlockMusicTranscribe(settlementId2, musicId);
			}
		}
		if (DomainManager.World.IsExtraTaskChainInProgress(37) && list.Count >= Music.Instance.CountWithExtra)
		{
			DomainManager.World.FinishAllTaskInChain(context, 37);
		}
	}

