	[DomainMethod]
	public void SetRanshanThreeCorpsesCharacterTarget(DataContext context, short templateId, sbyte targetId, sbyte notch)
	{
		SectStoryThreeCorpsesCharacter character = GetRanshanThreeCorpsesCharacterByTemplateId(templateId);
		if (character == null)
		{
			return;
		}
		RanshanGiveupLegendaryBookItem notchConfig = GetRanshanGiveUpLegendaryBookItem(templateId, notch);
		int currDate = DomainManager.World.GetCurrDate();
		if (SectStoryThreeCorpsesCharacterNotch.IsValid(notch))
		{
			GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
			if (notchConfig.ExpCost > 0)
			{
				taiwu.ChangeExp(context, -notchConfig.ExpCost);
			}
			if (notchConfig.ResourceType != -1)
			{
				taiwu.ChangeResource(context, notchConfig.ResourceType, -notchConfig.ResourceCost);
			}
		}
		character.Target = targetId;
		character.TargetOwner = DomainManager.LegendaryBook.GetOwner(targetId);
		character.Notch = notch;
		character.EndDate = currDate + notchConfig.FollowDuration;
		character.NextDate = currDate + notchConfig.ResponseCycle;
		SectStoryThreeCorpsesCharacter sectStoryThreeCorpsesCharacter = character;
		if (sectStoryThreeCorpsesCharacter.GiveUpCount == null)
		{
			sectStoryThreeCorpsesCharacter.GiveUpCount = new Dictionary<int, int>();
		}
		character.GiveUpCount.TryAdd(character.TargetOwner, 0);
		character.GiveUpCount[character.TargetOwner]++;
		SetRanshanThreeCorpsesCharacterLocation(context, templateId);
		SetSectRanshanThreeCorpses(_sectRanshanThreeCorpses, context);
	}

	public void SetRanshanThreeCorpsesCharacterLocation(DataContext context, short templateId)
	{
		if (DomainManager.Taiwu.AtPastTaiwuVillage())
		{
			return;
		}
		SectStoryThreeCorpsesCharacter extraData = GetRanshanThreeCorpsesCharacterByTemplateId(templateId);
		if (extraData != null)
		{
			GameData.Domains.Character.Character character = DomainManager.Character.GetOrCreateFixedCharacterByTemplateId(context, templateId);
			if (!extraData.IsAroundTaiwu || !character.IsActiveExternalRelationState(64uL))
			{
				List<MapBlockData> neighborBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
				GameData.Domains.Character.Character target;
				Location location = ((GameData.Domains.Character.Character.IsCharacterIdValid(extraData.TargetOwner) && DomainManager.Character.TryGetElement_Objects(extraData.TargetOwner, out target) && target.GetLocation().IsValid()) ? target.GetLocation() : (extraData.IsAroundTaiwu ? DomainManager.Taiwu.GetTaiwu().GetValidLocation() : DomainManager.Organization.GetSettlementByOrgTemplateId(7).GetLocation()));
				DomainManager.Map.GetRealNeighborBlocks(location.AreaId, location.BlockId, neighborBlocks, 2);
				Location targetLocation = neighborBlocks.GetRandom(context.Random).GetLocation();
				Events.RaiseFixedCharacterLocationChanged(context, character.GetId(), character.GetLocation(), targetLocation);
				character.SetLocation(targetLocation, context);
				ObjectPool<List<MapBlockData>>.Instance.Return(neighborBlocks);
			}
		}
	}

