	[DomainMethod]
	public void ApplyRanshanThreeCorpsesLegendaryBookKeepingResult(DataContext context, List<sbyte> huajuBooks, List<sbyte> xuanzhiBooks, List<sbyte> yingjiaoBooks)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		int previousThreeCorpsesBooks = GetThreeCorpsesOwnedLegendaryBookTypes();
		int currentThreeCorpsesBooks = 0;
		if (huajuBooks != null)
		{
			foreach (sbyte book in huajuBooks)
			{
				if (book != -1)
				{
					currentThreeCorpsesBooks |= 1 << (int)book;
				}
			}
		}
		if (xuanzhiBooks != null)
		{
			foreach (sbyte book2 in xuanzhiBooks)
			{
				if (book2 != -1)
				{
					currentThreeCorpsesBooks |= 1 << (int)book2;
				}
			}
		}
		if (yingjiaoBooks != null)
		{
			foreach (sbyte book3 in yingjiaoBooks)
			{
				if (book3 != -1)
				{
					currentThreeCorpsesBooks |= 1 << (int)book3;
				}
			}
		}
		for (sbyte i = 0; i < 14; i++)
		{
			int iMask = 1 << (int)i;
			if ((previousThreeCorpsesBooks & iMask) != 0 && (currentThreeCorpsesBooks & iMask) == 0)
			{
				ItemKey item = DomainManager.LegendaryBook.GetLegendaryBookItem(i);
				taiwu.AddInventoryItem(context, item, 1);
			}
			else if ((previousThreeCorpsesBooks & iMask) == 0 && (currentThreeCorpsesBooks & iMask) != 0)
			{
				ItemKey item2 = DomainManager.LegendaryBook.GetLegendaryBookItem(i);
				taiwu.RemoveInventoryItem(context, item2, 1, deleteItem: false);
				DomainManager.Item.SetOwner(item2, ItemOwnerType.System, 11);
			}
		}
		GetRanshanThreeCorpsesCharacterByTemplateId(698).LegendaryBooks = huajuBooks;
		GetRanshanThreeCorpsesCharacterByTemplateId(699).LegendaryBooks = xuanzhiBooks;
		GetRanshanThreeCorpsesCharacterByTemplateId(700).LegendaryBooks = yingjiaoBooks;
		SetSectRanshanThreeCorpses(_sectRanshanThreeCorpses, context);
	}

	public void AddDisplayEventLegendaryBookKeeping(DataContext context)
	{
		LegendaryBookOwnerData legendaryBookOwnerData = new LegendaryBookOwnerData();
		for (sbyte i = 0; i < 14; i++)
		{
			int ownerId = DomainManager.LegendaryBook.GetOwner(i);
			if (GameData.Domains.Character.Character.IsCharacterIdValid(ownerId) && DomainManager.Character.TryGetElement_Objects(ownerId, out var owner))
			{
				legendaryBookOwnerData.BookMap.Add(i, ownerId);
				legendaryBookOwnerData.CharacterDisplayDataMap.TryAdd(ownerId, DomainManager.Character.GetCharacterDisplayData(ownerId));
				legendaryBookOwnerData.CharacterHappinessMap.TryAdd(ownerId, owner.GetHappiness());
				legendaryBookOwnerData.CharacterAttributeMap.TryAdd(ownerId, owner.GetCurrMainAttributes());
				legendaryBookOwnerData.CharacterHealthMap.TryAdd(ownerId, owner.GetHealth());
				legendaryBookOwnerData.CharacterLeftMaxHealthMap.TryAdd(ownerId, owner.GetLeftMaxHealth());
			}
		}
		DomainManager.LegendaryBook.SetLegendaryBookOwnerData(legendaryBookOwnerData, context);
		GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.RanshanLegendaryBookKeeping);
	}

