	public bool IsRanshanMenteeGoodStoryEnding()
	{
		foreach (short templateId in SectMainStoryRelatedConstants.RanshanThreeCorpsesCharacterTemplateIdList)
		{
			if (GetRanshanThreeCorpsesCharacterByTemplateId(templateId).IsGoodEnd)
			{
				return true;
			}
		}
		return false;
	}

	public bool GetRanshanThreeCorpsesActionSucceed(DataContext context, short templateId)
	{
		SectStoryThreeCorpsesCharacter character = GetRanshanThreeCorpsesCharacterByTemplateId(templateId);
		GameData.Domains.Character.Character targetOwner = DomainManager.Character.GetElement_Objects(character.TargetOwner);
		sbyte happinessType = targetOwner.GetHappinessType();
		OrganizationInfo orgInfo = targetOwner.GetOrganizationInfo();
		OrganizationItem orgConfig = Config.Organization.Instance[orgInfo.OrgTemplateId];
		short memberId = orgConfig.Members[orgInfo.Grade];
		OrganizationMemberItem memberConfig = OrganizationMember.Instance[memberId];
		int randMax = 0;
		RanshanGiveupLegendaryBookItem notchConfig = GetRanshanGiveUpLegendaryBookItem(templateId, character.Notch);
		if (happinessType > 3)
		{
			targetOwner.ChangeHappiness(context, notchConfig.MoodChange);
		}
		else if (happinessType < 3)
		{
			targetOwner.ChangeHappiness(context, -notchConfig.MoodChange);
		}
		foreach (sbyte attributeType in notchConfig.JudgeAttribute)
		{
			randMax += targetOwner.GetMaxMainAttribute(attributeType);
		}
		switch (templateId)
		{
		case 698:
			randMax = randMax * (350 - memberConfig.ResourceSatisfyingThreshold * 100 / OrganizationMember.Instance[Config.Organization.Instance[(sbyte)1].Members[8]].ResourceSatisfyingThreshold) / 100;
			break;
		case 699:
			randMax = randMax * (350 - memberConfig.ResourceSatisfyingThreshold * 100 / OrganizationMember.Instance[Config.Organization.Instance[(sbyte)1].Members[8]].ResourceSatisfyingThreshold) / 100;
			break;
		case 700:
			randMax = randMax * Math.Max(350 - targetOwner.GetFertility() * 2, 50) / 100;
			break;
		}
		return context.Random.CheckProb(targetOwner.GetHappiness() / 5, randMax);
	}

	private int GetThreeCorpsesOwnedLegendaryBookTypes()
	{
		int res = 0;
		foreach (short templateId in SectMainStoryRelatedConstants.RanshanThreeCorpsesCharacterTemplateIdList)
		{
			SectStoryThreeCorpsesCharacter character = GetRanshanThreeCorpsesCharacterByTemplateId(templateId);
			if (character?.LegendaryBooks == null)
			{
				continue;
			}
			foreach (sbyte book in character.LegendaryBooks)
			{
				if (book != -1)
				{
					res |= 1 << (int)book;
				}
			}
		}
		return res;
	}

	private RanshanGiveupLegendaryBookItem GetRanshanGiveUpLegendaryBookItem(short templateId, sbyte notch)
	{
		RanshanGiveupLegendaryBook instance = RanshanGiveupLegendaryBook.Instance;
		if (1 == 0)
		{
		}
		byte b = templateId switch
		{
			698 => 0, 
			699 => 3, 
			_ => 6, 
		};
		if (1 == 0)
		{
		}
		return instance[b + notch];
	}

