	[DomainMethod]
	public SectRanshanThreeCorpsesData GetSectRanshanThreeCorpsesData()
	{
		SectRanshanThreeCorpsesData res = new SectRanshanThreeCorpsesData
		{
			ThreeCorpses = _sectRanshanThreeCorpses,
			CharacterDisplayData = new Dictionary<int, CharacterDisplayData>(),
			CharacterAttributes = new Dictionary<int, MainAttributes>(),
			LegendaryBookOwners = new Dictionary<int, sbyte>(),
			CanKeepBooks = new List<sbyte>()
		};
		int taiwuId = DomainManager.Taiwu.GetTaiwuCharId();
		res.CharacterDisplayData[taiwuId] = DomainManager.Character.GetCharacterDisplayData(taiwuId);
		for (sbyte bookType = 0; bookType < 14; bookType++)
		{
			if (IsBookOwnedByTaiwu(bookType))
			{
				res.CanKeepBooks.Add(bookType);
			}
			else
			{
				int ownerId = DomainManager.LegendaryBook.GetOwner(bookType);
				if (GameData.Domains.Character.Character.IsCharacterIdValid(ownerId) && DomainManager.Character.TryGetElement_Objects(ownerId, out var owner))
				{
					res.CharacterDisplayData[ownerId] = DomainManager.Character.GetCharacterDisplayData(ownerId);
					res.CharacterAttributes[ownerId] = owner.GetMaxMainAttributes();
					res.LegendaryBookOwners[ownerId] = bookType;
				}
			}
		}
		foreach (SectStoryThreeCorpsesCharacter corpse in _sectRanshanThreeCorpses)
		{
			res.CharacterDisplayData[corpse.Id] = DomainManager.Character.GetCharacterDisplayData(corpse.Id);
			if (corpse.TargetOwner >= 0)
			{
				res.CharacterDisplayData[corpse.TargetOwner] = DomainManager.Character.GetCharacterDisplayData(corpse.TargetOwner);
			}
		}
		return res;
	}

	[DomainMethod]
	public List<ItemDisplayData> GetItemListForRanshanTreeCorpsesLegendaryBookKeeping(int corpseId)
	{
		List<ItemDisplayData> result = new List<ItemDisplayData>();
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		List<ItemDisplayData> allItems = DomainManager.Character.GetAllInventoryItems(taiwu.GetId());
		foreach (ItemDisplayData item in allItems)
		{
			if (item.Key.ItemType == 12)
			{
				short templateId = item.Key.TemplateId;
				if (templateId >= 240 && templateId < 254)
				{
					result.Add(item);
				}
			}
		}
		List<SectStoryThreeCorpsesCharacter> corpses = _sectRanshanThreeCorpses;
		foreach (SectStoryThreeCorpsesCharacter corpse in corpses)
		{
			if (corpse.Id == corpseId || corpse.LegendaryBooks == null || corpse.LegendaryBooks.Count == 0)
			{
				continue;
			}
			foreach (sbyte book in corpse.LegendaryBooks)
			{
				if (book >= 0)
				{
					ItemKey itemKey = DomainManager.LegendaryBook.GetLegendaryBookItem(book);
					ItemDisplayData displayData = DomainManager.Item.GetItemDisplayData(DomainManager.Item.GetBaseItem(itemKey), 1, corpse.Id, -1);
					result.Add(displayData);
				}
			}
		}
		return result;
	}

	public bool IsThreeCorpseKeepingLegendaryBook(ItemKey itemKey)
	{
		if (!itemKey.IsValid())
		{
			return false;
		}
		if (itemKey.ItemType != 12)
		{
			return false;
		}
		short templayteId = itemKey.TemplateId;
		if ((templayteId < 240 || templayteId >= 254) ? true : false)
		{
			return false;
		}
		int legendaryBookType = templayteId - 240;
		List<SectStoryThreeCorpsesCharacter> corpses = _sectRanshanThreeCorpses;
		if (corpses == null || corpses.Count < 0)
		{
			return false;
		}
		foreach (SectStoryThreeCorpsesCharacter corpse in corpses)
		{
			if (corpse.LegendaryBooks == null || corpse.LegendaryBooks.Count == 0 || !corpse.LegendaryBooks.Contains((sbyte)legendaryBookType))
			{
				continue;
			}
			return true;
		}
		return false;
	}

