	public void GenerateFulongInFlameArea(DataContext context, int range, int mineCount, bool isBig)
	{
		short areaId = DomainManager.Organization.GetSettlementByOrgTemplateId(14).GetLocation().AreaId;
		List<MapBlockData> blocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		byte areaSize = DomainManager.Map.GetAreaSize(areaId);
		if (DomainManager.Map.TryGetAvailableBlockIdInRange(areaId, range, blocks))
		{
			Dictionary<short, sbyte> edgeBlocks = new Dictionary<short, sbyte>();
			Dictionary<short, int> lightedBlocks = new Dictionary<short, int>();
			List<short> mineBlocks = new List<short>();
			CollectionUtils.Shuffle(context.Random, blocks);
			foreach (MapBlockData block in blocks)
			{
				lightedBlocks.Add(block.BlockId, 0);
				if (!block.Visible)
				{
					block.SetVisible(visible: true, context);
				}
				DomainManager.Map.SplitMultiBlock(context, block);
			}
			for (int i = 0; i < mineCount; i++)
			{
				mineBlocks.Add(blocks[i].BlockId);
				lightedBlocks[blocks[i].BlockId]++;
				foreach (MapBlockData block2 in blocks)
				{
					if (FulongInFlameArea.IsAdjacent(blocks[i], block2))
					{
						lightedBlocks[block2.BlockId]++;
					}
				}
			}
			foreach (MapBlockData block3 in blocks)
			{
				edgeBlocks[block3.BlockId] = MapBlockEightDirectionType.GetDirectionType(lightedBlocks, areaSize, block3.BlockId);
			}
			_sectFulongInFlameAreas.Add(new FulongInFlameArea(lightedBlocks, mineBlocks, edgeBlocks, isBig, areaId, mineCount));
			SetSectFulongInFlameAreas(_sectFulongInFlameAreas, context);
			DomainManager.Map.RemoveTrivialObjectsOnBlocks(context, blocks);
		}
		DomainManager.Map.UpdateFulongFlameLocations();
		DomainManager.Map.UpdateIsTaiwuInFulongFlameArea(context);
		ObjectPool<List<MapBlockData>>.Instance.Return(blocks);
	}

	[DomainMethod]
	public int ExtinguishFulongInFlameArea(DataContext context, short blockId, bool isEvent = false)
	{
		if (!isEvent)
		{
			DomainManager.Extra.SaveArgToSectMainStoryEventArgBox(context, 14, SectMainStoryEventArgKey.DefValue.FulongPutOutFire, value: true);
			DomainManager.Extra.SaveArgToSectMainStoryEventArgBox(context, 14, SectMainStoryEventArgKey.DefValue.FulongPutOutFireOnce, value: true);
		}
		int res = -1;
		if (DomainManager.Taiwu.GetTaiwu().GetLocation().BlockId != blockId && !isEvent)
		{
			GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.SetEventLockInputState, arg1: false);
			return res;
		}
		for (int index = 0; index < _sectFulongInFlameAreas.Count; index++)
		{
			FulongInFlameArea area = _sectFulongInFlameAreas[index];
			if (area.LightedBlocks.ContainsKey(blockId))
			{
				ExtinguishFulongInFlameArea(context, blockId, area);
				if (area.IsFullyExtinguished())
				{
					res = index;
				}
				break;
			}
		}
		GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.SetEventLockInputState, arg1: false);
		return res;
	}

	[DomainMethod]
	public unsafe void TriggerFulongInFlameAreaMine(DataContext context, short blockId)
	{
		if (DomainManager.Taiwu.GetTaiwu().GetLocation().BlockId != blockId)
		{
			GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.SetEventLockInputState, arg1: false);
			return;
		}
		HashSet<int> groupCharIds = DomainManager.Taiwu.GetGroupCharIds().GetCollection();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		List<sbyte> bodyPartRandomPool = ObjectPool<List<sbyte>>.Instance.Get();
		short areaId = DomainManager.Organization.GetSettlementByOrgTemplateId(14).GetLocation().AreaId;
		MapBlockData block = DomainManager.Map.GetBlockData(areaId, blockId);
		foreach (FulongInFlameArea area in _sectFulongInFlameAreas)
		{
			if (!area.MineBlocks.Contains(blockId))
			{
				continue;
			}
			area.TriggeredMineBlocks.Add(blockId);
			area.ExtinguishedBlocks.Add(blockId);
			Span<MapBlockData> blocks = DomainManager.Map.GetAreaBlocks(areaId);
			Span<MapBlockData> span = blocks;
			for (int i = 0; i < span.Length; i++)
			{
				MapBlockData neighbor = span[i];
				if (area.LightedBlocks.ContainsKey(neighbor.BlockId) && (blockId == neighbor.BlockId || FulongInFlameArea.IsAdjacent(neighbor, block)))
				{
					area.LightedBlocks[neighbor.BlockId]--;
				}
			}
		}
		for (int resourceType = 0; resourceType < 6; resourceType++)
		{
			block.CurrResources.Items[resourceType] = 0;
		}
		if (DomainManager.Character.TryGetKidnappedCharacters(taiwuCharId, out var list))
		{
			foreach (KidnappedCharacter kidnappedCharacter in list.GetCollection())
			{
				ApplyCharacterGetRandomPartDamaged(context, kidnappedCharacter.CharId, GlobalConfig.Instance.FulongMineDamage, bodyPartRandomPool);
			}
		}
		foreach (int charId in groupCharIds)
		{
			ApplyCharacterGetRandomPartDamaged(context, charId, (charId == taiwuCharId) ? GlobalConfig.Instance.FulongMineDamageTaiwu : GlobalConfig.Instance.FulongMineDamage, bodyPartRandomPool);
		}
		if (block.CharacterSet != null)
		{
			foreach (int charId2 in block.CharacterSet)
			{
				ApplyCharacterGetRandomPartDamaged(context, charId2, GlobalConfig.Instance.FulongMineDamage, bodyPartRandomPool);
			}
		}
		ObjectPool<List<sbyte>>.Instance.Return(bodyPartRandomPool);
		SetSectFulongInFlameAreas(_sectFulongInFlameAreas, context);
		DomainManager.Map.SetBlockData(context, block);
		DomainManager.Map.UpdateIsTaiwuInFulongFlameArea(context);
		DomainManager.World.GetInstantNotificationCollection().AddMechanismOfDetonation();
		GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.SetEventLockInputState, arg1: false);
	}

	public void ApplyCharacterGetRandomPartDamaged(DataContext context, int charId, sbyte delta, List<sbyte> bodyPartRandomPool)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		Injuries injuries = character.GetInjuries();
		bodyPartRandomPool.Clear();
		bodyPartRandomPool.AddRange(BodyPart.Instance.GetAllKeys());
		bodyPartRandomPool.RemoveAll((sbyte part) => injuries.Get(part, isInnerInjury: false) >= 6);
		if (bodyPartRandomPool.Count > 0)
		{
			injuries.Change(bodyPartRandomPool[context.Random.Next(bodyPartRandomPool.Count)], isInnerInjury: true, delta);
			injuries.Change(bodyPartRandomPool[context.Random.Next(bodyPartRandomPool.Count)], isInnerInjury: false, delta);
			character.SetInjuries(injuries, context);
		}
	}

	[DomainMethod]
	public void ApplyFulongInFlameAreaFullyExtinguished(DataContext context, int index, bool triggerEvent = true)
	{
		FulongInFlameArea area = _sectFulongInFlameAreas[index];
		_sectFulongInFlameAreas.Remove(area);
		SetSectFulongInFlameAreas(_sectFulongInFlameAreas, context);
		DomainManager.Map.UpdateFulongFlameLocations();
		DomainManager.Map.UpdateIsTaiwuInFulongFlameArea(context);
		if (triggerEvent)
		{
			DomainManager.TaiwuEvent.CloseUI("PutOutFire");
		}
		if (_sectFulongInFlameAreas.Count != 0)
		{
			return;
		}
		IEnumerable<AdventureMajorEvent> majorEvents = DomainManager.Adventure.QueryMajorEventsInArea(area.AreaId);
		List<short> existBlockIds = majorEvents.Select((AdventureMajorEvent x) => x.MapLocation.BlockId).ToList();
		List<short> lightedBlocks = area.LightedBlocks.Keys.ToList();
		for (int i = 0; i < lightedBlocks.Count; i++)
		{
			if (!existBlockIds.Contains(lightedBlocks[i]))
			{
				Location location = new Location(area.AreaId, lightedBlocks[i]);
				if (DomainManager.Adventure.GenerateMajorEvent(context, 448666234, location))
				{
					DomainManager.World.TriggerExtraTask(context, 47, 296);
					DomainManager.Extra.SaveArgToSectMainStoryEventArgBox(context, 14, SectMainStoryEventArgKey.DefValue.FulongAdventureStartTime, DomainManager.World.GetCurrDate());
					break;
				}
			}
		}
	}

	public unsafe void ApplyFulongInFlameAreaAdvanceMonth(DataContext context)
	{
		HashSet<int> groupCharIds = DomainManager.Taiwu.GetGroupCharIds().GetCollection();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		List<sbyte> bodyPartRandomPool = ObjectPool<List<sbyte>>.Instance.Get();
		short areaId = DomainManager.Organization.GetSettlementByOrgTemplateId(14).GetLocation().AreaId;
		Location taiwuLocation = DomainManager.Taiwu.GetTaiwu().GetLocation();
		foreach (FulongInFlameArea area in _sectFulongInFlameAreas)
		{
			foreach (short blockId in area.LightedBlocks.Keys)
			{
				if (area.ExtinguishedBlocks.Contains(blockId))
				{
					continue;
				}
				MapBlockData block = DomainManager.Map.GetBlockData(areaId, blockId);
				for (int resourceType = 0; resourceType < 6; resourceType++)
				{
					block.CurrResources.Items[resourceType] = (short)Math.Max(0, block.CurrResources.Items[resourceType] - block.MaxResources.Items[resourceType] / 4);
				}
				if (block.CharacterSet != null)
				{
					foreach (int charId in block.CharacterSet)
					{
						ApplyCharacterGetRandomPartDamaged(context, charId, GlobalConfig.Instance.FulongFlameDamage, bodyPartRandomPool);
					}
				}
				DomainManager.Map.SetBlockData(context, block);
				if (!(taiwuLocation == block.GetLocation()))
				{
					continue;
				}
				if (DomainManager.Character.TryGetKidnappedCharacters(taiwuCharId, out var list))
				{
					foreach (KidnappedCharacter kidnappedCharacter in list.GetCollection())
					{
						ApplyCharacterGetRandomPartDamaged(context, kidnappedCharacter.CharId, GlobalConfig.Instance.FulongFlameDamage, bodyPartRandomPool);
					}
				}
				foreach (int charId2 in groupCharIds)
				{
					ApplyCharacterGetRandomPartDamaged(context, charId2, GlobalConfig.Instance.FulongFlameDamage, bodyPartRandomPool);
				}
			}
		}
		ObjectPool<List<sbyte>>.Instance.Return(bodyPartRandomPool);
		SetSectFulongInFlameAreas(_sectFulongInFlameAreas, context);
	}

