	public void ApplyTaiwuGetRobbedByFulongOutLaws(DataContext context, sbyte resourceType, int resourceValue, int robberId, int victimId)
	{
		Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(14);
		SettlementLayeredTreasuries treasuries = settlement.Treasuries;
		SettlementTreasury treasury = treasuries.GetTreasury(SettlementTreasuryLayers.Deep);
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		int taiwuId = taiwu.GetId();
		Location location = taiwu.GetLocation();
		int currDate = DomainManager.World.GetCurrDate();
		treasury.Resources.Add(resourceType, resourceValue);
		SetTreasuries(context, settlement.GetId(), treasuries, needUpdateTotalValue: true);
		SetElement_SectFulongOutLaws(robberId, new IntPair(currDate, _sectFulongOutLaws[robberId].Second), context);
		if (GameData.Domains.Character.Character.IsCharacterIdValid(victimId))
		{
			ushort relationType = DomainManager.Character.GetRelation(taiwuId, victimId).RelationType;
			bool isFriendOrFamily = RelationType.IsFamilyRelation(relationType) || RelationType.IsFriendRelation(relationType);
			GameData.Domains.Character.Character victim = DomainManager.Character.GetElement_Objects(victimId);
			int delta = (isFriendOrFamily ? 8000 : 6000);
			DomainManager.Character.DirectlyChangeFavorabilityOptional(context, victim, taiwu, delta, 4);
			DomainManager.LifeRecord.GetLifeRecordCollection().AddSectMainStoryFulongProtect(victimId, currDate, taiwuId, location);
		}
	}

