	public void RemoveAllFulongOutLaws(DataContext context)
	{
		List<int> robberIds = ObjectPool<List<int>>.Instance.Get();
		foreach (int robberId in _sectFulongOutLaws.Keys)
		{
			robberIds.Add(robberId);
		}
		foreach (int robberId2 in robberIds)
		{
			RemoveElement_SectFulongOutLaws(robberId2, context);
			if (DomainManager.Character.TryGetElement_Objects(robberId2, out var robber))
			{
				DomainManager.Character.RemoveNonIntelligentCharacter(context, robber);
			}
		}
		ObjectPool<List<int>>.Instance.Return(robberIds);
	}

	public void ApplyFulongOutLawAdvanceMonth(DataContext context, int startDate)
	{
		Span<sbyte> resourceTypes = stackalloc sbyte[8] { 0, 1, 2, 3, 4, 5, 6, 7 };
		MonthlyNotificationCollection monthlyNotificationCollection = DomainManager.World.GetMonthlyNotificationCollection();
		MonthlyEventCollection monthlyEventCollection = DomainManager.World.GetMonthlyEventCollection();
		int taiwuId = DomainManager.Taiwu.GetTaiwuCharId();
		Location location = DomainManager.Taiwu.GetTaiwu().GetValidLocation();
		MapBlockData taiwuBlock = DomainManager.Map.GetBlock(location);
		HashSet<int> groupIds = DomainManager.Taiwu.GetGroupCharIds().GetCollection();
		int currDate = DomainManager.World.GetCurrDate();
		Dictionary<int, int> currCount = new Dictionary<int, int>();
		Dictionary<int, List<int>> potentialVictims = new Dictionary<int, List<int>>();
		List<int> succeedIds = ObjectPool<List<int>>.Instance.Get();
		List<int> failedIds = ObjectPool<List<int>>.Instance.Get();
		List<short> blockIds = ObjectPool<List<short>>.Instance.Get();
		bool resupplyOutLaws = false;
		sbyte[] fulongOutLawDestination = SectMainStoryRelatedConstants.FulongOutLawDestination;
		foreach (sbyte orgTemplateId in fulongOutLawDestination)
		{
			Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(orgTemplateId);
			short settlementId = settlement.GetId();
			Location settlementLocation = settlement.GetLocation();
			blockIds.Clear();
			DomainManager.Map.GetSettlementBlocksAndAffiliatedBlocks(settlementLocation.AreaId, settlementLocation.BlockId, blockIds);
			potentialVictims.Add(settlementId, new List<int>());
			foreach (short blockId in blockIds)
			{
				MapBlockData block = DomainManager.Map.GetBlock(settlementLocation.AreaId, blockId);
				if (block.CharacterSet == null)
				{
					continue;
				}
				foreach (int id in block.CharacterSet)
				{
					if (DomainManager.Character.TryGetElement_Objects(id, out var character) && character.GetAgeGroup() == 2)
					{
						potentialVictims[settlementId].Add(id);
					}
				}
			}
			currCount.Add(settlementId, 0);
		}
		short taiwuAreaId = DomainManager.Taiwu.GetTaiwu().GetLocation().AreaId;
		foreach (int settlementId2 in potentialVictims.Keys)
		{
			short settlementAreaId = DomainManager.Organization.GetSettlement((short)settlementId2).GetLocation().AreaId;
			if (settlementAreaId != taiwuAreaId)
			{
				continue;
			}
			HashSet<int> groupCharIds = DomainManager.Taiwu.GetGroupCharIds().GetCollection();
			foreach (int id2 in groupCharIds)
			{
				if (DomainManager.Character.TryGetElement_Objects(id2, out var character2) && character2.GetAgeGroup() == 2)
				{
					potentialVictims[settlementId2].Add(id2);
				}
			}
		}
		int key;
		IntPair value;
		foreach (KeyValuePair<int, IntPair> sectFulongOutLaw in _sectFulongOutLaws)
		{
			sectFulongOutLaw.Deconstruct(out key, out value);
			int id3 = key;
			IntPair data = value;
			Dictionary<int, int> dictionary = currCount;
			key = data.Second;
			dictionary[key]++;
			if (potentialVictims[data.Second].Count > 0)
			{
				int victimId = potentialVictims[data.Second][context.Random.Next(potentialVictims[data.Second].Count)];
				GameData.Domains.Character.Character robber = DomainManager.Character.GetElement_Objects(id3);
				Location targetLocation = DomainManager.Character.GetElement_Objects(victimId).GetLocation();
				Events.RaiseEnemyCharacterLocationChanged(context, id3, robber.GetLocation(), targetLocation);
				robber.SetLocation(targetLocation, context);
			}
		}
		int key2;
		if ((DomainManager.World.GetCurrDate() - startDate - SectMainStoryRelatedConstants.FulongZealotStartRobTime) % 6 == 0)
		{
			foreach (KeyValuePair<int, int> item in currCount)
			{
				item.Deconstruct(out key, out key2);
				int settlementId3 = key;
				int count = key2;
				bool isTaiwuVillage = settlementId3 == DomainManager.Organization.GetSettlementByOrgTemplateId(16).GetId();
				int upperLimit = (isTaiwuVillage ? 6 : 9);
				int lowerLimit = (isTaiwuVillage ? 3 : 5);
				if (count < lowerLimit)
				{
					int dest = context.Random.Next(lowerLimit, upperLimit);
					short templateId = SectMainStoryRelatedConstants.GetTemplateIdOfFixedCharacterCombatWith(841, 5);
					Settlement settlement2 = DomainManager.Organization.GetSettlement((short)settlementId3);
					Location settlementLocation2 = settlement2.GetLocation();
					blockIds.Clear();
					DomainManager.Map.GetSettlementBlocksAndAffiliatedBlocks(settlementLocation2.AreaId, settlementLocation2.BlockId, blockIds);
					for (int j = count; j < dest; j++)
					{
						GameData.Domains.Character.Character character3 = DomainManager.Character.CreateFixedEnemy(context, templateId, isTemporary: false);
						int id4 = character3.GetId();
						Location targetLocation2 = new Location(settlementLocation2.AreaId, blockIds[context.Random.Next(blockIds.Count)]);
						DomainManager.Character.CompleteCreatingCharacter(id4);
						AddElement_SectFulongOutLaws(id4, new IntPair(0, settlementId3), context);
						Events.RaiseEnemyCharacterLocationChanged(context, character3.GetId(), character3.GetLocation(), targetLocation2);
						character3.SetLocation(targetLocation2, context);
						Dictionary<int, int> dictionary = currCount;
						key2 = settlementId3;
						dictionary[key2]++;
					}
					resupplyOutLaws = true;
				}
			}
		}
		if (resupplyOutLaws)
		{
			monthlyNotificationCollection.AddSectMainStoryFulongLooting();
		}
		foreach (KeyValuePair<int, int> item2 in currCount)
		{
			item2.Deconstruct(out key2, out key);
			int settlementId4 = key2;
			int count2 = key;
			currCount[settlementId4] = context.Random.Next(0, count2 * 3 / 10 + 2);
		}
		succeedIds.Clear();
		failedIds.Clear();
		foreach (KeyValuePair<int, IntPair> sectFulongOutLaw2 in _sectFulongOutLaws)
		{
			sectFulongOutLaw2.Deconstruct(out key, out value);
			int id5 = key;
			IntPair data2 = value;
			short settlementId5 = (short)data2.Second;
			if (currCount[settlementId5] == 0 || currDate - data2.First <= 1 || potentialVictims[settlementId5].Count <= 0)
			{
				continue;
			}
			int victimId2 = potentialVictims[settlementId5][context.Random.Next(potentialVictims[settlementId5].Count)];
			RelatedCharacter relationType;
			bool isFriendOrFamily = DomainManager.Character.TryGetRelation(taiwuId, victimId2, out relationType) && (RelationType.IsFamilyRelation(relationType.RelationType) || RelationType.IsFriendRelation(relationType.RelationType));
			GameData.Domains.Character.Character robber2 = DomainManager.Character.GetElement_Objects(id5);
			Location targetLocation3 = DomainManager.Character.GetElement_Objects(victimId2).GetLocation();
			Events.RaiseEnemyCharacterLocationChanged(context, id5, robber2.GetLocation(), targetLocation3);
			robber2.SetLocation(targetLocation3, context);
			if (victimId2 == taiwuId)
			{
				monthlyEventCollection.AddSectMainStoryFulongRobTaiwu(location, id5);
				_sectFulongOutLawInEvent = new IntPair(id5, -1);
			}
			else if (groupIds.Contains(victimId2))
			{
				monthlyEventCollection.AddSectMainStoryFulongProtect(victimId2, location, taiwuId, id5);
				_sectFulongOutLawInEvent = new IntPair(id5, victimId2);
			}
			else if (taiwuBlock.CharacterSet != null && taiwuBlock.CharacterSet.Contains(victimId2))
			{
				if (isFriendOrFamily)
				{
					monthlyEventCollection.AddSectMainStoryFulongProtect(victimId2, location, taiwuId, id5);
				}
				else
				{
					monthlyEventCollection.AddSectMainStoryFulongInterfereRobbery(victimId2, location, id5);
				}
				_sectFulongOutLawInEvent = new IntPair(id5, victimId2);
			}
			else
			{
				switch (ProcessFulongOutLawRobbing(context, id5, victimId2, resourceTypes))
				{
				case 348:
					DomainManager.Character.RemoveNonIntelligentCharacter(context, robber2);
					monthlyNotificationCollection.AddSectMainStoryFulongFightSucceed(victimId2, settlementId5);
					failedIds.Add(id5);
					break;
				case 349:
					if (isFriendOrFamily)
					{
						monthlyNotificationCollection.AddSectMainStoryFulongFamilyFightFail(victimId2, settlementId5);
					}
					else
					{
						monthlyNotificationCollection.AddSectMainStoryFulongFightFail(victimId2, settlementId5);
					}
					succeedIds.Add(id5);
					break;
				case 351:
					if (isFriendOrFamily)
					{
						monthlyNotificationCollection.AddSectMainStoryFulongFamilyRobbery(victimId2, settlementId5);
					}
					else
					{
						monthlyNotificationCollection.AddSectMainStoryFulongRobbery(victimId2, settlementId5);
					}
					succeedIds.Add(id5);
					break;
				}
			}
			Dictionary<int, int> dictionary = currCount;
			key = settlementId5;
			dictionary[key]--;
		}
		foreach (int failedId in failedIds)
		{
			RemoveElement_SectFulongOutLaws(failedId, context);
		}
		foreach (int succeedId in succeedIds)
		{
			SetElement_SectFulongOutLaws(succeedId, new IntPair(currDate, _sectFulongOutLaws[succeedId].Second), context);
		}
		ObjectPool<List<int>>.Instance.Return(succeedIds);
		ObjectPool<List<int>>.Instance.Return(failedIds);
		ObjectPool<List<short>>.Instance.Return(blockIds);
	}

	public short ProcessFulongOutLawRobbing(DataContext context, int robberId, int victimId, Span<sbyte> resourceTypes)
	{
		int currDate = DomainManager.World.GetCurrDate();
		short settlementId = DomainManager.Organization.GetSettlementByOrgTemplateId(14).GetId();
		SettlementTreasuryRecordCollection treasuryRecordCollection = DomainManager.Organization.GetSettlementTreasuryRecordCollection(context, settlementId);
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		GameData.Domains.Character.Character victim = DomainManager.Character.GetElement_Objects(victimId);
		GameData.Domains.Character.Character robber = DomainManager.Character.GetElement_Objects(robberId);
		int fightPercent = (victim.GetConsummateLevel() - robber.GetConsummateLevel()) * 10 + victim.GetPersonality(3) + SectMainStoryRelatedConstants.FulongOutLawFightBehaviorBonus[victim.GetBehaviorType()];
		Span<int> resourceResults = stackalloc int[2];
		if (context.Random.CheckPercentProb(fightPercent))
		{
			AiHelper.NpcCombatResultType result = DomainManager.Character.SimulateCharacterCombat(context, victim, robber, CombatType.Die);
			if ((uint)result <= 1u)
			{
				DomainManager.Character.RemoveNonIntelligentCharacter(context, robber);
				lifeRecordCollection.AddSectMainStoryFulongFightSucceed(victimId, currDate, victim.GetLocation());
				return 348;
			}
			ApplyFulongOutLawRobSucceed(context, victim, resourceTypes, resourceResults);
			treasuryRecordCollection.AddSectStoryFulongLooting(currDate, settlementId, resourceTypes[0], resourceResults[0], resourceTypes[1], resourceResults[1]);
			lifeRecordCollection.AddSectMainStoryFulongFightFail(victimId, currDate, victim.GetLocation(), resourceTypes[0], resourceResults[0], resourceTypes[1], resourceResults[1]);
			return 349;
		}
		ApplyFulongOutLawRobSucceed(context, victim, resourceTypes, resourceResults);
		treasuryRecordCollection.AddSectStoryFulongLooting(currDate, settlementId, resourceTypes[0], resourceResults[0], resourceTypes[1], resourceResults[1]);
		lifeRecordCollection.AddSectMainStoryFulongRobbery(victimId, currDate, victim.GetLocation(), resourceTypes[0], resourceResults[0], resourceTypes[1], resourceResults[1]);
		return 351;
	}

	private void ApplyFulongOutLawRobSucceed(DataContext context, GameData.Domains.Character.Character victim, Span<sbyte> resourceTypes, Span<int> resourceResults)
	{
		Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(14);
		SettlementLayeredTreasuries treasuries = settlement.Treasuries;
		SettlementTreasury treasury = treasuries.GetTreasury(SettlementTreasuryLayers.Deep);
		CollectionUtils.Shuffle(context.Random, resourceTypes, 8);
		for (int i = 0; i < 2; i++)
		{
			int value = victim.GetResource(resourceTypes[i]) / 2;
			victim.ChangeResource(context, resourceTypes[i], -value);
			treasury.Resources.Add(resourceTypes[i], value);
			resourceResults[i] = value;
		}
		SetTreasuries(context, settlement.GetId(), treasuries, needUpdateTotalValue: true);
	}

	private void ExtinguishFulongInFlameArea(DataContext context, short blockId, FulongInFlameArea area)
	{
		area.ExtinguishedBlocks.Add(blockId);
		if (area.LightedBlocks[blockId] == 0)
		{
			short areaId = DomainManager.Organization.GetSettlementByOrgTemplateId(14).GetLocation().AreaId;
			foreach (short otherBlockId in area.LightedBlocks.Keys)
			{
				if (!area.ExtinguishedBlocks.Contains(otherBlockId) && FulongInFlameArea.IsAdjacent(DomainManager.Map.GetBlockData(areaId, blockId), DomainManager.Map.GetBlockData(areaId, otherBlockId)))
				{
					ExtinguishFulongInFlameArea(context, otherBlockId, area);
				}
			}
		}
		SetSectFulongInFlameAreas(_sectFulongInFlameAreas, context);
		DomainManager.Map.UpdateIsTaiwuInFulongFlameArea(context);
	}

	private bool IsAdjacentBlockInFulongFlameArea(Dictionary<short, int> blocks, byte areaSize, int coordinateX, int coordinateY)
	{
		return MapBlockEightDirectionType.IsBlockInArea(blocks, areaSize, coordinateX, coordinateY);
	}

