	public void GearMateUpdateStatus(DataContext context)
	{
		GearMateUpgradeFeature(context);
	}

	private void GearMateUpgradeFeature(DataContext context)
	{
		Dictionary<short, short> featureIdData = ObjectPool<Dictionary<short, short>>.Instance.Get();
		List<int> potentialFeatureIds = context.AdvanceMonthRelatedData.IntList.Occupy();
		List<int> charIds = context.AdvanceMonthRelatedData.CharIdList.Occupy();
		int taiwuId = DomainManager.Taiwu.GetTaiwuCharId();
		foreach (KeyValuePair<int, GearMate> sectZhujianGearMate in _sectZhujianGearMates)
		{
			sectZhujianGearMate.Deconstruct(out var key, out var value);
			int gearMateId = key;
			GearMate gearMate = value;
			GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(gearMateId);
			Location location = character.GetLocation();
			bool check = true;
			while (check)
			{
				List<short> ownedFeatures = character.GetFeatureIds();
				int requirement = 1;
				int highestLevel = 0;
				check = false;
				featureIdData.Clear();
				foreach (short featureId in ownedFeatures)
				{
					CharacterFeatureItem config = CharacterFeature.Instance[featureId];
					featureIdData[config.MutexGroupId] = featureId;
					ECharacterFeatureType type = config.Type;
					if ((uint)(type - 1) <= 1u)
					{
						requirement += config.Level;
					}
				}
				requirement *= 10;
				if (gearMate.FeatureProgress < requirement)
				{
					continue;
				}
				charIds.Clear();
				if (location.IsValid())
				{
					MapBlockData blockData = DomainManager.Map.GetBlock(location);
					if (blockData.CharacterSet != null)
					{
						foreach (int charId in blockData.CharacterSet)
						{
							charIds.Add(charId);
						}
					}
				}
				IReadOnlySet<int> group = DomainManager.Character.GetSpecialGroup(taiwuId);
				if (group.Contains(gearMateId))
				{
					foreach (int charId2 in DomainManager.Taiwu.GetGroupCharIds().GetCollection())
					{
						charIds.Add(charId2);
					}
					foreach (int charId3 in group)
					{
						if (charId3 != gearMateId)
						{
							charIds.Add(charId3);
						}
					}
				}
				potentialFeatureIds.Clear();
				foreach (int charId4 in charIds)
				{
					List<short> targetFeatureIds = DomainManager.Character.GetElement_Objects(charId4).GetFeatureIds();
					foreach (short featureId2 in targetFeatureIds)
					{
						if (ownedFeatures.Contains(featureId2))
						{
							continue;
						}
						CharacterFeatureItem config2 = CharacterFeature.Instance[featureId2];
						if (config2.Type != ECharacterFeatureType.Good)
						{
							continue;
						}
						short currFeatureId;
						int currLevel = (featureIdData.TryGetValue(config2.MutexGroupId, out currFeatureId) ? CharacterFeature.Instance[currFeatureId].Level : 0);
						if (currLevel < highestLevel || currLevel > config2.Level)
						{
							continue;
						}
						short potentialFeatureId = ((currLevel == 0) ? config2.MutexGroupId : CharacterFeature.Instance[currFeatureId].Upgrade().TemplateId);
						if (!potentialFeatureIds.Contains(potentialFeatureId))
						{
							if (highestLevel < currLevel)
							{
								potentialFeatureIds.Clear();
							}
							highestLevel = currLevel;
							potentialFeatureIds.Add(potentialFeatureId);
						}
					}
				}
				if (potentialFeatureIds.Count > 0)
				{
					character.AddFeature(context, (short)potentialFeatureIds[context.Random.Next(potentialFeatureIds.Count)], removeMutexFeature: true);
					gearMate.FeatureProgress -= requirement;
					SetGearMate(context, gearMate);
					check = true;
				}
			}
		}
		context.AdvanceMonthRelatedData.CharIdList.Release(ref charIds);
		context.AdvanceMonthRelatedData.IntList.Release(ref potentialFeatureIds);
		ObjectPool<Dictionary<short, short>>.Instance.Return(featureIdData);
	}

