	[DomainMethod]
	public GearMateRepairCount GetGearMateAvailableRepairCount(int artisanId)
	{
		GameData.Domains.Character.Character artisan = DomainManager.Character.GetElement_Objects(artisanId);
		GearMateRepairCount maxCount = new GearMateRepairCount
		{
			OuterInjuryHealingCount = (sbyte)Math.Min(99, 1 + artisan.GetLifeSkillAttainment(6) / 60),
			InnerInjuryHealingCount = (sbyte)Math.Min(99, 1 + artisan.GetLifeSkillAttainment(7) / 60),
			DetoxCount = (sbyte)Math.Min(99, 1 + artisan.GetLifeSkillAttainment(11) / 60),
			BreathingCount = (sbyte)Math.Min(99, 1 + artisan.GetLifeSkillAttainment(10) / 60)
		};
		return maxCount.Sub(GetGearMateUsedRepairCount(artisanId));
	}

	[DomainMethod]
	public int GetGearMateRepairRequirement(int gearMateId, int artisanId, sbyte type, ItemKey toolKey)
	{
		int res = 0;
		GameData.Domains.Character.Character gearMate = DomainManager.Character.GetElement_Objects(gearMateId);
		GameData.Domains.Character.Character artisan = DomainManager.Character.GetElement_Objects(artisanId);
		var (resourceType, resourceCost, lifeSkillType, requiredAttainment, _) = GetRepairGearMateRequirement(gearMateId, type);
		if (1 == 0)
		{
		}
		bool flag = type switch
		{
			0 => !gearMate.GetInjuries().HasAnyInjury(isInnerInjury: false), 
			1 => !gearMate.GetInjuries().HasAnyInjury(isInnerInjury: true), 
			2 => !gearMate.GetPoisoned().IsNonZero(), 
			3 => gearMate.GetDisorderOfQi() <= 0, 
			_ => false, 
		};
		if (1 == 0)
		{
		}
		if (flag)
		{
			res |= 1;
		}
		if (DomainManager.Taiwu.GetTaiwu().GetResource(resourceType) < resourceCost)
		{
			res |= 2;
		}
		if (toolKey.IsValid() && !ItemTemplateHelper.IsEmptyTool(toolKey.ItemType, toolKey.TemplateId) && (!artisan.GetInventory().Items.ContainsKey(toolKey) || !Config.CraftTool.Instance[toolKey.TemplateId].RequiredLifeSkillTypes.Contains(lifeSkillType)))
		{
			res |= 4;
		}
		if (DomainManager.Building.GetLifeSkillTotalAttainment(artisanId, lifeSkillType, toolKey) < requiredAttainment)
		{
			res |= 8;
		}
		return res;
	}

	[DomainMethod]
	public List<GearMateRepairRequirementDisplayData> GetGearMateRepairRequirementDisplayDatas(int gearMateId)
	{
		List<GearMateRepairRequirementDisplayData> result = new List<GearMateRepairRequirementDisplayData>();
		for (sbyte type = 0; type <= 3; type++)
		{
			(sbyte, int, sbyte, short, sbyte) repairGearMateRequirement = GetRepairGearMateRequirement(gearMateId, type);
			sbyte resourceType = repairGearMateRequirement.Item1;
			int resourceCost = repairGearMateRequirement.Item2;
			sbyte lifeSkillType = repairGearMateRequirement.Item3;
			short requiredAttainment = repairGearMateRequirement.Item4;
			sbyte itemGrade = repairGearMateRequirement.Item5;
			GearMateRepairRequirementDisplayData displayData = new GearMateRepairRequirementDisplayData
			{
				GearMateId = gearMateId,
				RepairType = type,
				ResourceType = resourceType,
				ResourceCost = resourceCost,
				LifeSkillType = lifeSkillType,
				AttainmentCount = requiredAttainment,
				ItemGrade = itemGrade
			};
			result.Add(displayData);
		}
		return result;
	}

