	public BoolArray16 GetGearMateBreakoutCombatSkillBanReason(int gearMateId, short skillId)
	{
		BoolArray16 array = default(BoolArray16);
		GearMate gearMate = _sectZhujianGearMates[gearMateId];
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(gearMateId);
		CombatSkillKey taiwuSkillKey = new CombatSkillKey(DomainManager.Taiwu.GetTaiwuCharId(), skillId);
		CombatSkillKey gearMateSkillKey = new CombatSkillKey(gearMateId, skillId);
		if (!character.GetLearnedCombatSkills().Contains(skillId))
		{
			array[0] = true;
			return array;
		}
		if (!DomainManager.CombatSkill.TryGetElement_CombatSkills(taiwuSkillKey, out var taiwuSkill))
		{
			array[0] = true;
			return array;
		}
		GameData.Domains.CombatSkill.CombatSkill gearMateSkill = DomainManager.CombatSkill.GetElement_CombatSkills(gearMateSkillKey);
		ushort taiwuState = taiwuSkill.GetActivationState();
		ushort readingState = gearMateSkill.GetReadingState();
		int count = BitOperation.CountBits((uint)(taiwuState & readingState));
		if (count < 6)
		{
			array[0] = true;
			return array;
		}
		if (gearMateSkill.GetActivationState() != taiwuState)
		{
			return array;
		}
		sbyte taiwuLuohanId = DomainManager.Taiwu.GetCombatSkillLuohanId(skillId);
		sbyte gearMateLuohanId = -1;
		bool gearMateHasLuohan = gearMate.LuohanBreakDict != null && gearMate.LuohanBreakDict.TryGetValue(skillId, out gearMateLuohanId);
		if (taiwuLuohanId >= 0 && !gearMateHasLuohan)
		{
			return array;
		}
		if (gearMateHasLuohan && gearMateLuohanId != taiwuLuohanId)
		{
			return array;
		}
		GameData.Domains.Taiwu.SkillBreakPlate plate;
		bool taiwuHasPlate = DomainManager.Taiwu.TryGetElement_CombatSkillBreakPlates(skillId, out plate);
		bool taiwuAnyBonus = taiwuHasPlate && plate.AnyBonus;
		SkillBreakPlateBonusList gearMateBonus;
		bool gearMateAnyBonus = gearMate.SkillBreakBonusDict.TryGetValue(skillId, out gearMateBonus);
		if (gearMateAnyBonus != taiwuAnyBonus)
		{
			return array;
		}
		if (gearMateAnyBonus)
		{
			int index = 0;
			foreach (SkillBreakPlateBonus bonus in plate.GetBonuses())
			{
				if (!gearMateBonus.CheckIndex(index) || !bonus.Equals(gearMateBonus[index]))
				{
					return array;
				}
				index++;
			}
			if (index != gearMateBonus.Count)
			{
				return array;
			}
		}
		int maxPower;
		bool gearMateHasMaxPower = gearMate.SkillBreakMaxPowerDict.TryGetValue(skillId, out maxPower);
		if (taiwuHasPlate != gearMateHasMaxPower)
		{
			return array;
		}
		if (gearMateHasMaxPower && maxPower != taiwuSkill.GetPlateAddMaxPower())
		{
			return array;
		}
		array[1] = true;
		return array;
	}

	[DomainMethod]
	public void RepairGearMate(DataContext context, int gearMateId, int artisanId, sbyte type, ItemKey toolKey)
	{
		if (GetGearMateRepairRequirement(gearMateId, artisanId, type, toolKey) != 0)
		{
			return;
		}
		GameData.Domains.Character.Character gearMate = DomainManager.Character.GetElement_Objects(gearMateId);
		GameData.Domains.Character.Character artisan = DomainManager.Character.GetElement_Objects(artisanId);
		var (resourceType, resourceCost, _, _, grade) = GetRepairGearMateRequirement(gearMateId, type);
		switch (type)
		{
		case 0:
		case 1:
		{
			Injuries injuries = gearMate.GetInjuries();
			RepairGearMateInjuries(artisanId, type, toolKey, ref injuries);
			gearMate.SetInjuries(injuries, context);
			break;
		}
		case 2:
		{
			PoisonInts poisons = gearMate.GetPoisoned();
			RepairGearMatePoisoned(artisanId, toolKey, ref poisons);
			gearMate.SetPoisoned(ref poisons, context);
			break;
		}
		case 3:
		{
			short qiDisorder = gearMate.GetDisorderOfQi();
			RepairGearMateDisorderOfQi(artisanId, toolKey, ref qiDisorder);
			gearMate.SetDisorderOfQi(qiDisorder, context);
			break;
		}
		}
		ConsumeGearMateUsedRepairCount(artisanId, type);
		DomainManager.Taiwu.GetTaiwu().ChangeResource(context, resourceType, -resourceCost);
		if (toolKey.IsValid() && !ItemTemplateHelper.IsEmptyTool(toolKey.ItemType, toolKey.TemplateId))
		{
			short cost = Config.CraftTool.Instance[toolKey.TemplateId].DurabilityCost[grade];
			GameData.Domains.Item.CraftTool tool = DomainManager.Item.GetElement_CraftTools(toolKey.Id);
			tool.ChangeCurrDurability(context, -cost);
			if (tool.GetCurrDurability() <= 0)
			{
				artisan.RemoveInventoryItem(context, toolKey, 1, deleteItem: true);
			}
		}
	}

	[DomainMethod]
	public void UpgradeGearMate(DataContext context, int charId, sbyte type, ItemKey itemKey, int count = 1, ItemSourceType sourceType = ItemSourceType.Inventory)
	{
		int value = (itemKey.IsValid() ? (ItemTemplateHelper.GetGearMateUpgradeProgress(itemKey.ItemType, itemKey.TemplateId) * count) : count);
		int exp = 0;
		sbyte b = type;
		sbyte b2 = b;
		if (b2 > 5)
		{
			switch (b2)
			{
			case 6:
				GearMateUpgradeConsummateLevel(context, charId, value);
				break;
			case 7:
				_sectZhujianGearMates[charId].FeatureProgress += value;
				break;
			case 8:
				exp = GearMateReadCombatSKillBook(context, charId, itemKey, value);
				break;
			case 9:
				exp = GearMateReadLifeSkillBook(context, charId, itemKey, value);
				break;
			case 10:
				exp = GearMateBreakCombatSkill(context, charId, value);
				break;
			case 11:
				GearMateAddNeili(context, charId, value);
				break;
			case 12:
				GearMateChangeNeiliType(context, charId, value);
				break;
			default:
				GearMateTransferNeiliAllocationProgress(context, charId, type, value);
				break;
			}
		}
		else
		{
			GearMateUpgradeMainAttribute(context, charId, type, value);
		}
		if (itemKey.IsValid())
		{
			switch (sourceType)
			{
			case ItemSourceType.Inventory:
			{
				if (DomainManager.Taiwu.GetTaiwu().GetEquipment().Any((ItemKey e) => e.Equals(itemKey)))
				{
					DomainManager.Taiwu.RemoveItem(context, itemKey, count, (sbyte)0, true, false);
					break;
				}
				if (DomainManager.Taiwu.GetItems(ItemSourceType.Inventory).TryGetValue(itemKey, out var amount3))
				{
					DomainManager.Taiwu.RemoveItem(context, itemKey, count, 1, amount3 == count);
					break;
				}
				throw new Exception($"item not found in inventory: {itemKey}");
			}
			case ItemSourceType.Warehouse:
			{
				if (DomainManager.Taiwu.GetItems(ItemSourceType.Warehouse).TryGetValue(itemKey, out var amount2))
				{
					DomainManager.Taiwu.RemoveItem(context, itemKey, count, 2, amount2 == count);
					break;
				}
				throw new Exception($"item not found in warehouse: {itemKey}");
			}
			case ItemSourceType.Treasury:
			{
				if (DomainManager.Taiwu.GetItems(ItemSourceType.Treasury).TryGetValue(itemKey, out var amount))
				{
					DomainManager.Taiwu.RemoveItem(context, itemKey, count, 3, amount == count);
					break;
				}
				throw new Exception($"item not found in treasury: {itemKey}");
			}
			}
		}
		if (exp != 0)
		{
			DomainManager.Taiwu.GetTaiwu().ChangeExp(context, exp);
		}
		SetGearMate(context, _sectZhujianGearMates[charId]);
	}

	private void GearMateUpgradeMainAttribute(DataContext context, int charId, sbyte type, int value)
	{
		GearMate gearMate = _sectZhujianGearMates[charId];
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		bool needCheck = true;
		gearMate.MainAttributeProgress[type] += value;
		while (needCheck)
		{
			int requirement = (character.GetBaseMainAttributes().Get(type) + 1) * 10;
			if (gearMate.MainAttributeProgress[type] >= requirement)
			{
				gearMate.MainAttributeProgress[type] -= requirement;
				character.ChangeBaseMainAttribute(context, type, 1);
			}
			else
			{
				needCheck = false;
			}
		}
	}

	private void GearMateUpgradeConsummateLevel(DataContext context, int charId, int value)
	{
		GearMate gearMate = _sectZhujianGearMates[charId];
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		bool needCheck = true;
		gearMate.ConsummateLevelProgress += value;
		while (needCheck)
		{
			sbyte consummateLevel = character.GetConsummateLevel();
			if (1 == 0)
			{
			}
			int num = consummateLevel switch
			{
				0 => 30, 
				1 => 60, 
				2 => 120, 
				_ => 240 * (consummateLevel - 2), 
			};
			if (1 == 0)
			{
			}
			int requirement = num;
			if (gearMate.ConsummateLevelProgress >= requirement)
			{
				gearMate.ConsummateLevelProgress -= requirement;
				character.ChangeConsummateLevel(context, 1);
				if (character.GetConsummateLevel() >= GlobalConfig.Instance.MaxConsummateLevel)
				{
					gearMate.ConsummateLevelProgress = 0;
				}
			}
			else
			{
				needCheck = false;
			}
		}
	}

	private int GearMateReadCombatSKillBook(DataContext context, int charId, ItemKey itemKey, int value)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		GearMate gearMate = _sectZhujianGearMates[charId];
		SkillBookItem config = Config.SkillBook.Instance[itemKey.TemplateId];
		short templateId = config.CombatSkillTemplateId;
		sbyte skillType = config.CombatSkillType;
		sbyte grade = ItemTemplateHelper.GetGrade(itemKey.ItemType, itemKey.TemplateId);
		GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(itemKey.Id);
		byte pageTypes = book.GetPageTypes();
		int pageExp = -SkillGradeData.Instance[grade].ReadingExpGainPerPage;
		int pageCount = 0;
		if (!character.GetLearnedCombatSkills().Contains(templateId))
		{
			character.LearnNewCombatSkill(context, templateId, 0);
		}
		if (!gearMate.CombatSkillReadingProgress.TryGetValue(templateId, out var skill))
		{
			skill = new TaiwuCombatSkill();
		}
		GameData.Domains.CombatSkill.CombatSkill combatSkill = DomainManager.CombatSkill.GetElement_CombatSkills(new CombatSkillKey(charId, templateId));
		for (byte i = 0; i < 6; i++)
		{
			ushort readingState = combatSkill.GetReadingState();
			byte page = CombatSkillStateHelper.GetPageInternalIndex(SkillBookStateHelper.GetOutlinePageType(pageTypes), SkillBookStateHelper.GetNormalPageType(pageTypes, i), i);
			if (!CombatSkillStateHelper.IsPageRead(readingState, page))
			{
				sbyte incompleteState = SkillBookStateHelper.GetPageIncompleteState(book.GetPageIncompleteState(), i);
				sbyte speed = SkillBookPageIncompleteState.GearMateReadingSpeed[incompleteState];
				sbyte progress = skill.GetBookPageReadingProgress(page);
				progress = (sbyte)Math.Min(100, progress + speed);
				skill.SetBookPageReadingProgress(page, progress);
				if (progress == 100)
				{
					DomainManager.CombatSkill.SetCombatSkillReadingState(context, combatSkill, CombatSkillStateHelper.SetPageRead(readingState, page));
					DomainManager.CombatSkill.TryActivateCombatSkillBookPageWhenSetReadingState(context, charId, templateId, page);
				}
				pageCount++;
			}
		}
		gearMate.CombatSkillReadingProgress[templateId] = skill;
		int finished = 0;
		ushort state = combatSkill.GetReadingState();
		for (byte i2 = 0; i2 < 6; i2++)
		{
			byte page2 = CombatSkillStateHelper.GetPageInternalIndex(SkillBookStateHelper.GetOutlinePageType(pageTypes), 0, i2);
			byte page3 = CombatSkillStateHelper.GetPageInternalIndex(SkillBookStateHelper.GetOutlinePageType(pageTypes), 1, i2);
			if (CombatSkillStateHelper.IsPageRead(state, page2) || CombatSkillStateHelper.IsPageRead(state, page3))
			{
				finished++;
			}
		}
		if (finished == 6 && !gearMate.IsCombatSkillBuffed(skillType, grade))
		{
			character.ChangeBaseCombatSkillQualification(context, skillType, value);
			gearMate.SetCombatSkillBuffed(skillType, grade);
		}
		return pageExp * pageCount;
	}

	private int GearMateReadLifeSkillBook(DataContext context, int charId, ItemKey itemKey, int value)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		GearMate gearMate = _sectZhujianGearMates[charId];
		SkillBookItem config = Config.SkillBook.Instance[itemKey.TemplateId];
		short templateId = config.LifeSkillTemplateId;
		sbyte skillType = config.LifeSkillType;
		sbyte grade = ItemTemplateHelper.GetGrade(itemKey.ItemType, itemKey.TemplateId);
		int pageExp = -SkillGradeData.Instance[grade].ReadingExpGainPerPage;
		GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(itemKey.Id);
		int pageCount = 0;
		int finished = 0;
		if (character.FindLearnedLifeSkillIndex(templateId) < 0)
		{
			character.LearnNewLifeSkill(context, templateId, 0);
		}
		if (!gearMate.LifeSkillReadingProgress.TryGetValue(templateId, out var skill))
		{
			skill = new TaiwuLifeSkill();
		}
		for (byte page = 0; page < 5; page++)
		{
			int learnedIndex = character.FindLearnedLifeSkillIndex(templateId);
			if (character.GetLearnedLifeSkills()[learnedIndex].IsPageRead(page))
			{
				finished++;
			}
			else
			{
				sbyte incompleteState = SkillBookStateHelper.GetPageIncompleteState(book.GetPageIncompleteState(), page);
				sbyte speed = SkillBookPageIncompleteState.GearMateReadingSpeed[incompleteState];
				sbyte progress = skill.GetBookPageReadingProgress(page);
				progress = (sbyte)Math.Min(100, progress + speed);
				skill.SetBookPageReadingProgress(page, progress);
				if (progress == 100)
				{
					character.ReadLifeSkillPage(context, learnedIndex, page);
					finished++;
				}
				pageCount++;
			}
		}
		if (finished == 5 && !gearMate.IsLifeSkillBuffed(skillType, grade))
		{
			character.ChangeBaseLifeSkillQualification(context, skillType, value);
			gearMate.SetLifeSkillBuffed(skillType, grade);
		}
		gearMate.LifeSkillReadingProgress[templateId] = skill;
		return pageExp * pageCount;
	}

	private int GearMateBreakCombatSkill(DataContext context, int charId, int value)
	{
		GearMate gearMate = _sectZhujianGearMates[charId];
		short templateId = (short)value;
		GameData.Domains.Taiwu.SkillBreakPlate plate;
		bool taiwuHasPlate = DomainManager.Taiwu.TryGetElement_CombatSkillBreakPlates(templateId, out plate);
		if (taiwuHasPlate && plate.AnyBonus)
		{
			gearMate.SkillBreakBonusDict[templateId] = new SkillBreakPlateBonusList(plate.GetBonuses());
		}
		if (taiwuHasPlate)
		{
			gearMate.SkillBreakMaxPowerDict[templateId] = plate.AddMaxPower;
		}
		sbyte luohanId = DomainManager.Taiwu.GetCombatSkillLuohanId(templateId);
		if (luohanId >= 0)
		{
			gearMate.LuohanBreakDict[templateId] = luohanId;
		}
		else
		{
			gearMate.LuohanBreakDict.Remove(templateId);
		}
		SkillBreakBonusCollection emeiBonus = DomainManager.Story.GetEmeiBreakBonusCollection(templateId);
		if (emeiBonus != null)
		{
			gearMate.SectEmeiSkillBreakBonus[templateId] = emeiBonus;
		}
		else
		{
			gearMate.SectEmeiSkillBreakBonus.Remove(templateId);
		}
		CombatSkillKey gearMateSkillKey = new CombatSkillKey(charId, templateId);
		CombatSkillKey taiwuSkillKey = new CombatSkillKey(DomainManager.Taiwu.GetTaiwuCharId(), templateId);
		if (DomainManager.CombatSkill.TryGetElement_CombatSkills(gearMateSkillKey, out var gearMateSkill) && DomainManager.CombatSkill.TryGetElement_CombatSkills(taiwuSkillKey, out var taiwuSkill))
		{
			gearMateSkill.SetActivationState(taiwuSkill.GetActivationState(), context);
			gearMate.SkillBreakMaxPowerDict[templateId] = taiwuSkill.GetPlateAddMaxPower();
		}
		return -Config.SkillBreakPlate.Instance[Config.CombatSkill.Instance[templateId].Grade].CostExp * 25;
	}

