	private void GearMateTransferNeiliAllocationProgress(DataContext context, int charId, sbyte type, int delta)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		NeiliAllocation neiliAllocation = character.GetExtraNeiliAllocation();
		short value = neiliAllocation[(byte)(type - 13)];
		int neili = _sectZhujianGearMates[charId].Neili;
		short cost = GlobalConfig.Instance.ExtraNeiliAllocationFromProgressRatio;
		short usedCount = neiliAllocation.GetTotal();
		int maxCount = 0;
		while (neili > cost)
		{
			neili -= cost;
			maxCount++;
			if (maxCount % 4 == 0)
			{
				cost += GlobalConfig.Instance.ExtraNeiliAllocationFromProgressRatioGrowth;
			}
		}
		if (delta > 0)
		{
			if (value < GlobalConfig.Instance.MaxExtraNeiliAllocation && usedCount < maxCount)
			{
				character.ChangeExtraNeiliAllocation(context, (byte)(type - 13), (short)delta);
				_sectZhujianGearMates[charId].NeiliAllocation = character.GetExtraNeiliAllocation();
			}
		}
		else if (value > 0)
		{
			character.ChangeExtraNeiliAllocation(context, (byte)(type - 13), (short)delta);
			_sectZhujianGearMates[charId].NeiliAllocation = character.GetExtraNeiliAllocation();
		}
	}

	private unsafe (sbyte, int, sbyte, short, sbyte) GetRepairGearMateRequirement(int gearMateId, sbyte type)
	{
		int cost = GlobalConfig.Instance.HealInjuryBaseHerb;
		sbyte resourceType = -1;
		sbyte lifeSkillType = -1;
		short attainment = 0;
		sbyte maxGrade = 0;
		GameData.Domains.Character.Character gearMate = DomainManager.Character.GetElement_Objects(gearMateId);
		switch (type)
		{
		case 0:
		{
			Injuries injuries2 = gearMate.GetInjuries();
			resourceType = 2;
			lifeSkillType = 6;
			for (sbyte bodyPart2 = 0; bodyPart2 < 7; bodyPart2++)
			{
				(sbyte, sbyte) injury2 = injuries2.Get(bodyPart2);
				if (injury2.Item1 > 0)
				{
					sbyte grade4 = (sbyte)(injury2.Item1 - 1);
					cost += GetRepairGearMateMaterialConfig(resourceType, injury2.Item1).ResourceAmount * 3;
					attainment = Math.Max(attainment, GlobalConfig.Instance.GearMateRepairInjuryAttainmentRequirement[injury2.Item1 - 1]);
					maxGrade = Math.Max(grade4, maxGrade);
				}
			}
			break;
		}
		case 1:
		{
			Injuries injuries = gearMate.GetInjuries();
			resourceType = 1;
			lifeSkillType = 7;
			for (sbyte bodyPart = 0; bodyPart < 7; bodyPart++)
			{
				(sbyte, sbyte) injury = injuries.Get(bodyPart);
				if (injury.Item2 > 0)
				{
					sbyte grade2 = (sbyte)(injury.Item2 - 1);
					cost += GetRepairGearMateMaterialConfig(resourceType, injury.Item2).ResourceAmount * 3;
					attainment = Math.Max(attainment, GlobalConfig.Instance.GearMateRepairInjuryAttainmentRequirement[injury.Item2 - 1]);
					maxGrade = Math.Max(grade2, maxGrade);
				}
			}
			break;
		}
		case 2:
		{
			PoisonInts poisons = gearMate.GetPoisoned();
			resourceType = 3;
			lifeSkillType = 11;
			for (sbyte poisonType = 0; poisonType < 6; poisonType++)
			{
				sbyte poisonLevel = PoisonsAndLevels.CalcPoisonedLevel(poisons.Items[poisonType]);
				if (poisonLevel > 0)
				{
					sbyte grade3 = (sbyte)(poisonLevel * 2 - 1);
					cost += GetRepairGearMateMaterialConfig(resourceType, (sbyte)(poisonLevel * 2)).ResourceAmount * 3;
					attainment = Math.Max(attainment, GlobalConfig.Instance.GearMateRepairPoisonAttainmentRequirement[poisonLevel - 1]);
					maxGrade = Math.Max(grade3, maxGrade);
				}
			}
			break;
		}
		case 3:
		{
			short disorderOfQi = gearMate.GetDisorderOfQi();
			resourceType = 4;
			lifeSkillType = 10;
			if (disorderOfQi > 0)
			{
				sbyte grade = DisorderLevelOfQi.GetDisorderLevelOfQi(disorderOfQi);
				cost += GetRepairGearMateMaterialConfig(resourceType, (sbyte)(grade + 1)).ResourceAmount * 3;
				attainment = Math.Max(attainment, GlobalConfig.Instance.GearMateRepairDisorderOfQiAttainmentRequirement[grade]);
				maxGrade = Math.Max(grade, maxGrade);
			}
			break;
		}
		}
		return (resourceType, cost, lifeSkillType, attainment, maxGrade);
	}

	private int RepairGearMateInjuries(int artisanId, sbyte type, ItemKey toolKey, ref Injuries injuries)
	{
		bool isInner = type == 1;
		sbyte lifeSkillType = (sbyte)(isInner ? 7 : 6);
		short attainment = DomainManager.Building.GetLifeSkillTotalAttainment(artisanId, lifeSkillType, toolKey);
		int totalHealCount = 0;
		for (sbyte bodyPart = 0; bodyPart < 7; bodyPart++)
		{
			sbyte injuryCount = injuries.Get(bodyPart, isInner);
			if (injuryCount > 0)
			{
				short requireAttainment = GlobalConfig.Instance.GearMateRepairInjuryAttainmentRequirement[injuryCount - 1];
				if (attainment >= requireAttainment)
				{
					int healCount = Math.Min((attainment - requireAttainment) / 100 + 1, injuryCount);
					injuries.Change(bodyPart, isInner, (sbyte)(-healCount));
					totalHealCount += healCount;
				}
			}
		}
		return totalHealCount;
	}

	private int RepairGearMatePoisoned(int artisanId, ItemKey toolKey, ref PoisonInts poisons)
	{
		short attainment = DomainManager.Building.GetLifeSkillTotalAttainment(artisanId, 11, toolKey);
		int totalHealCount = 0;
		for (sbyte type = 0; type < 6; type++)
		{
			int poison = poisons[type];
			if (poison > 0)
			{
				sbyte poisonLevel = PoisonsAndLevels.CalcPoisonedLevel(poison);
				int requireAttainment = ((poisonLevel > 0) ? GlobalConfig.Instance.GearMateRepairPoisonAttainmentRequirement[poisonLevel - 1] : 0);
				if (attainment >= requireAttainment)
				{
					int healCount = Math.Min(attainment * GlobalConfig.Instance.HealPoisonAttainmentPercent / 100, poison);
					poisons[type] -= healCount;
					totalHealCount += healCount;
				}
			}
		}
		return totalHealCount;
	}

	private int RepairGearMateDisorderOfQi(int artisanId, ItemKey toolKey, ref short qiDisorder)
	{
		short attainment = DomainManager.Building.GetLifeSkillTotalAttainment(artisanId, 10, toolKey);
		sbyte qiDisorderLevel = DisorderLevelOfQi.GetDisorderLevelOfQi(qiDisorder);
		short requireAttainment = GlobalConfig.Instance.GearMateRepairDisorderOfQiAttainmentRequirement[qiDisorderLevel];
		if (attainment < requireAttainment)
		{
			return 0;
		}
		short healCount = (short)Math.Min(attainment * GlobalConfig.Instance.HealPoisonAttainmentPercent / 100, qiDisorder);
		qiDisorder -= healCount;
		return healCount;
	}

