	[DomainMethod]
	public void BuildExtraLegacyBuilding(DataContext context, BuildingBlockKey blockKey)
	{
		DomainManager.Building.ResetAllChildrenBlocks(context, blockKey, 275, 1);
		BuildingBlockItem configData = BuildingBlock.Instance[(short)275];
		if (!BuildingBlockData.CanUpgrade(configData.Type) || !GameData.Domains.Building.SharedMethods.NeedCostResourceToBuild(configData))
		{
			return;
		}
		for (sbyte type = 0; type < 8; type++)
		{
			if (configData.BaseBuildCost[type] > 0)
			{
				DomainManager.Building.ConsumeResource(context, type, configData.BaseBuildCost[type]);
			}
		}
	}

	[DomainMethod]
	public void RemoveSectExtraLegacyBuilding(DataContext context, sbyte orgTemplateId)
	{
		Location location = DomainManager.Organization.GetSettlementByOrgTemplateId(orgTemplateId).GetLocation();
		IEnumerable<BuildingBlockData> blocks = DomainManager.Building.GetBuildingBlocksAtLocation(location);
		foreach (BuildingBlockData block in blocks)
		{
			if (block.TemplateId == 275)
			{
				ResourceInts resourceInts = default(ResourceInts);
				for (sbyte type = 0; type < 8; type++)
				{
					int returnCount = GameData.Domains.Building.SharedMethods.GetResourceReturnOfRemoveBuilding(BuildingBlock.DefValue.QiWenXingTai, 1, type, block);
					resourceInts[type] = returnCount;
				}
				DomainManager.Taiwu.AddResource(context, ItemSourceType.Inventory, ref resourceInts);
				DomainManager.Building.ResetAllChildrenBlocks(context, new BuildingBlockKey(location.AreaId, location.BlockId, block.BlockIndex), 0, 1);
			}
		}
	}

	[DomainMethod]
	public int GetExtraLegacyPointCharacterCountOnBlock(Location location, List<short> orgTemplateIds)
	{
		int count = 0;
		if (orgTemplateIds == null || orgTemplateIds.Count <= 0)
		{
			return count;
		}
		if (!location.IsValid())
		{
			return count;
		}
		MapBlockData blockData = DomainManager.Map.GetBlock(location);
		if (blockData.CharacterSet == null)
		{
			return count;
		}
		foreach (int charId in blockData.CharacterSet)
		{
			sbyte orgId = DomainManager.Character.GetAliveOrgDeadCharacterOrgInfo(charId).OrgTemplateId;
			if (orgTemplateIds.Contains(orgId) && IsCharacterEligibleForJieqingSeizeFortune(charId))
			{
				count++;
			}
		}
		return count;
	}

