	[DomainMethod]
	public bool AddReadingEventBookId(DataContext context, int id)
	{
		if (_readingEventBookIdList.Contains(id))
		{
			return false;
		}
		ReadingBookStrategies strategies = DomainManager.Taiwu.GetCurReadingStrategies();
		GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(id);
		byte pageCount = book.GetPageCount();
		if (IsAllEffectiveSlotsFull(context, strategies, book.GetItemKey(), pageCount))
		{
			return false;
		}
		_readingEventBookIdList.Add(id);
		SetReadingEventBookIdList(_readingEventBookIdList, context);
		DomainManager.Taiwu.GenerateAvailableReadingStrategies(context);
		DomainManager.Taiwu.CurrentReadingEventCostedIntelligence = 0;
		return true;
	}

	private bool IsAllEffectiveSlotsFull(DataContext context, ReadingBookStrategies strategies, ItemKey bookKey, byte pageCount)
	{
		int currentDate = DomainManager.World.GetCurrDate();
		IntList expireTimeList;
		bool hasExpireTimes = TryGetElement_BookStrategiesExpireTime(bookKey, out expireTimeList);
		for (byte page = 0; page < pageCount; page++)
		{
			for (int i = 0; i < 3; i++)
			{
				if (strategies.GetPageStrategy(page, i) == -1)
				{
					return false;
				}
				if (hasExpireTimes)
				{
					int index = page * 3 + i;
					if (index < expireTimeList.Items.Count && expireTimeList.Items[index] != -1 && currentDate >= expireTimeList.Items[index])
					{
						return false;
					}
				}
			}
		}
		return true;
	}

	[DomainMethod]
	public void RemoveReadingEventBookId(DataContext context, int id, short templateId)
	{
		if (_readingEventBookIdList.Remove(id))
		{
			SetReadingEventBookIdList(_readingEventBookIdList, context);
			RemoveElement_AvailableReadingStrategyMap(id, context);
			DomainManager.Taiwu.AddLegacyPoint(context, 47);
		}
		if (DomainManager.Taiwu.CurrentReadingEventCostedIntelligence > 0)
		{
			sbyte grade = Config.SkillBook.Instance[templateId].Grade;
			int addSeniority = ProfessionFormulaImpl.Calculate(36, DomainManager.Taiwu.CurrentReadingEventCostedIntelligence, grade);
			DomainManager.Extra.ChangeProfessionSeniority(context, 4, addSeniority);
		}
		DomainManager.Taiwu.CurrentReadingEventCostedIntelligence = 0;
	}

