	public void UpdateTaiwuSkillDataListener(DataContext context)
	{
		if (_listeningTaiwuCharId >= 0)
		{
			DataUid oldEquipSkillUid = new DataUid(4, 0, (ulong)_listeningTaiwuCharId, 60u);
			GameData.GameDataBridge.GameDataBridge.RemovePostDataModificationHandler(oldEquipSkillUid, GetType().Name);
		}
		_listeningTaiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		DataUid equipSkillUid = new DataUid(4, 0, (ulong)_listeningTaiwuCharId, 60u);
		GameData.GameDataBridge.GameDataBridge.AddPostDataModificationHandler(equipSkillUid, GetType().Name, UpdateTaiwuEquipSkillEffect);
		UpdateTaiwuEquipSkillEffect(context, equipSkillUid);
	}

