	public void CheckCombatSkillOrderPlan(DataContext context)
	{
		int planId = DomainManager.Taiwu.GetCurrCombatSkillPlanId();
		GameData.Utilities.ShortList orderPlan;
		GameData.Utilities.ShortList plan = (_combatSkillOrderPlans.TryGetValue(planId, out orderPlan) ? orderPlan : GameData.Utilities.ShortList.Create());
		List<short> notContainedSkills = ObjectPool<List<short>>.Instance.Get();
		notContainedSkills.Clear();
		CombatSkillEquipment combatSkillEquipment = DomainManager.Taiwu.GetTaiwu().GetCombatSkillEquipment();
		for (sbyte equipType = 1; equipType <= 3; equipType++)
		{
			ArraySegmentList<short>.Enumerator enumerator = combatSkillEquipment[equipType].GetEnumerator();
			while (enumerator.MoveNext())
			{
				short skillTemplateId = enumerator.Current;
				if (skillTemplateId >= 0 && !plan.Items.Contains(skillTemplateId))
				{
					notContainedSkills.Add(skillTemplateId);
				}
			}
		}
		for (int i = 0; i < 54; i++)
		{
			if (plan.Items.Count <= i)
			{
				plan.Items.Add(-1);
			}
			short skillId = plan.Items[i];
			if (skillId < 0 && notContainedSkills.Count > 0)
			{
				plan.Items[i] = notContainedSkills[0];
				notContainedSkills.RemoveAt(0);
			}
			else if (skillId >= 0 && !combatSkillEquipment.IsCombatSkillEquipped(skillId))
			{
				plan.Items[i] = -1;
			}
		}
		ObjectPool<List<short>>.Instance.Return(notContainedSkills);
		SetCombatSkillOrderPlan(context, plan);
	}

