	public void UpdateSkillActivationState(DataContext context, short skillId, GameData.Domains.Taiwu.SkillBreakPlate plate)
	{
		if (!plate.Success)
		{
			return;
		}
		int charId = DomainManager.Taiwu.GetTaiwuCharId();
		if (DomainManager.CombatSkill.TryGetElement_CombatSkills((charId: charId, skillId: skillId), out var skill))
		{
			if (skill.GetActivationState() != plate.SelectedPages)
			{
				AdaptableLog.Warning($"Unexpected activationState {skill.GetActivationState()} {plate.SelectedPages}");
			}
			skill.SetActivationState(skill.GetActivationState(), context);
			if (skill.Template.EquipType == 0)
			{
				GameData.Domains.Character.Character character = DomainManager.Taiwu.GetTaiwu();
				character.SetEquippedCombatSkills(character.GetEquippedCombatSkills(), context);
				character.UpdateAllocatedGenericGrids(context);
			}
		}
	}

