	public void SetReadingStrategiesExpireTime(DataContext context, ItemKey book, byte pageIndex, int strategyIndex, sbyte strategyId)
	{
		if (!_bookStrategiesExpireTime.ContainsKey(book))
		{
			IntList expireTimeList = IntList.Create();
			for (int i = 0; i < 18; i++)
			{
				expireTimeList.Items.Add(-1);
			}
			AddElement_BookStrategiesExpireTime(book, expireTimeList, context);
		}
		int index = pageIndex * 3 + strategyIndex;
		ReadingStrategyItem strategyCfg = ReadingStrategy.Instance[strategyId];
		_bookStrategiesExpireTime[book].Items[index] = DomainManager.World.GetCurrDate() + strategyCfg.Duration;
		SetElement_BookStrategiesExpireTime(book, _bookStrategiesExpireTime[book], context);
	}

	public void ClearReadingStrategiesExpireTimeForPage(DataContext context, ItemKey book, byte pageIndex)
	{
		if (TryGetElement_BookStrategiesExpireTime(book, out var expireTimeList))
		{
			int offset = pageIndex * 3;
			for (int i = 0; i < 3; i++)
			{
				int index = offset + i;
				expireTimeList.Items[index] = -1;
			}
			SetElement_BookStrategiesExpireTime(book, expireTimeList, context);
		}
	}

	public void DeleteExpiredReadingStrategiesOnMonthChange(DataContext context)
	{
		int currentDate = DomainManager.World.GetCurrDate();
		foreach (KeyValuePair<ItemKey, IntList> kv in _bookStrategiesExpireTime)
		{
			ItemKey book = kv.Key;
			IntList expireTimeList = kv.Value;
			for (int i = 0; i < expireTimeList.Items.Count; i++)
			{
				if (expireTimeList.Items[i] != -1 && currentDate >= expireTimeList.Items[i])
				{
					int pageIndex = i / 3;
					int strategyIndex = i % 3;
					expireTimeList.Items[i] = -1;
					DomainManager.Taiwu.ClearReadingStrategy(context, book, (byte)pageIndex, strategyIndex);
				}
			}
			SetElement_BookStrategiesExpireTime(book, expireTimeList, context);
		}
	}

