	public bool TryFixStrategiesExpireTime(DataContext context, ItemKey book, ReadingBookStrategies strategies)
	{
		if (!TryGetElement_BookStrategiesExpireTime(book, out var result))
		{
			result = IntList.Create();
			int currDate = DomainManager.World.GetCurrDate();
			for (int p = 0; p < 6; p++)
			{
				for (int i = 0; i < 3; i++)
				{
					sbyte strategy = strategies.GetPageStrategy((byte)p, i);
					if (strategy != -1)
					{
						ReadingStrategyItem strategyCfg = ReadingStrategy.Instance[strategy];
						result.Items.Add(currDate + strategyCfg.Duration);
					}
					else
					{
						result.Items.Add(-1);
					}
				}
			}
			AddElement_BookStrategiesExpireTime(book, result, context);
			return true;
		}
		return false;
	}

