	public void SetFriendOrFamilySendGiftResult(DataContext context, int charId, EventArgBox argBox)
	{
		if (DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			OrganizationInfo orgInfo = character.GetOrganizationInfo();
			sbyte cooldown;
			ItemKey itemKey = GetFriendOrFamilySendGift(context, character, out cooldown);
			if (!itemKey.HasTemplate)
			{
				int exp = GetFriendOrFamilySendExpAmount(orgInfo.InteractionGrade);
				argBox.Set("AddExp", arg: true);
				argBox.Set("AddExpCount", exp);
			}
			else if (ItemTemplateHelper.IsMiscResource(itemKey.ItemType, itemKey.TemplateId))
			{
				sbyte resourceType = ItemTemplateHelper.GetMiscResourceType(itemKey.ItemType, itemKey.TemplateId);
				int amount = GetFriendOrFamilySendResourceAmount(orgInfo.InteractionGrade, resourceType);
				int sendAmount = CorrectFriendOrFamilySendResourceAmount(context.Random, amount, character.GetResource(resourceType));
				argBox.Set("IsMiscResource", arg: true);
				argBox.Set("ResourceType", resourceType);
				argBox.Set("Count", sendAmount);
			}
			else
			{
				argBox.Set("ItemKey", itemKey);
			}
			argBox.Set("CoolDown", cooldown);
		}
	}

	public ItemKey GetFriendOrFamilySendGift(DataContext context, GameData.Domains.Character.Character character, out sbyte cooldown)
	{
		ItemKey resultItemKey = ItemKey.Invalid;
		OrganizationInfo orgInfo = character.GetOrganizationInfo();
		bool isSect = Config.Organization.Instance[orgInfo.OrgTemplateId].IsSect;
		bool isTaiwuVillage = orgInfo.OrgTemplateId == 16;
		cooldown = 0;
		sbyte interactionGrade = orgInfo.InteractionGrade;
		if (1 == 0)
		{
		}
		(sbyte, sbyte) tuple;
		switch (interactionGrade)
		{
		case 0:
		case 1:
		case 2:
			tuple = (0, 2);
			break;
		case 3:
		case 4:
		case 5:
			tuple = (0, 4);
			break;
		case 6:
		case 7:
		case 8:
			tuple = (0, 6);
			break;
		default:
			tuple = (0, 8);
			break;
		}
		if (1 == 0)
		{
		}
		(sbyte, sbyte) gradeRange = tuple;
		if (!isTaiwuVillage)
		{
			resultItemKey = (isSect ? GetFriendOrFamilySectCharGift(context, character, gradeRange) : GetFriendOrFamilyCityCharGift(context, character, gradeRange));
		}
		return resultItemKey;
	}

	private ItemKey GetFriendOrFamilySectCharGift(DataContext context, GameData.Domains.Character.Character character, (sbyte min, sbyte max) gradeRange)
	{
		OrganizationInfo orgInfo = character.GetOrganizationInfo();
		HashSet<sbyte> allowItemTypeSet = new HashSet<sbyte>();
		for (sbyte itemType = 0; itemType < 13; itemType++)
		{
			if (itemType != 3 && itemType != 4)
			{
				allowItemTypeSet.Add(itemType);
			}
		}
		HashSet<sbyte> allowResourceTypeSet = new HashSet<sbyte>();
		for (sbyte resourceType = 0; resourceType < 7; resourceType++)
		{
			allowResourceTypeSet.Add(resourceType);
		}
		sbyte interactionGrade = orgInfo.InteractionGrade;
		if (interactionGrade >= 0 && interactionGrade <= 2)
		{
			allowItemTypeSet.RemoveWhere((sbyte t) => t != 10);
			allowResourceTypeSet.RemoveWhere((sbyte t) => t >= 6);
		}
		List<ItemKey> itemList = new List<ItemKey>();
		List<ItemKey> resourceList = new List<ItemKey>();
		foreach (var (itemKey2, _) in character.GetInventory().Items)
		{
			if (!allowItemTypeSet.Contains(itemKey2.ItemType) || !ItemTemplateHelper.IsTransferable(itemKey2.ItemType, itemKey2.TemplateId))
			{
				continue;
			}
			bool hasPoison = DomainManager.Item.GetPoisonEffects(itemKey2).IsValid;
			if (!ItemType.IsEquipmentItemType(itemKey2.ItemType) && hasPoison)
			{
				continue;
			}
			sbyte grade = ItemTemplateHelper.GetGrade(itemKey2.ItemType, itemKey2.TemplateId);
			if (grade > gradeRange.max || grade < gradeRange.min)
			{
				continue;
			}
			OrganizationItem organizationItem = Config.Organization.Instance.GetItem(character.GetOrganizationInfo().OrgTemplateId);
			if (organizationItem != null)
			{
				short itemSubType = ItemTemplateHelper.GetItemSubType(itemKey2.ItemType, itemKey2.TemplateId);
				if ((organizationItem.NoMeatEating && itemSubType == 701) || (organizationItem.NoDrinking && itemSubType == 901))
				{
					continue;
				}
			}
			itemList.Add(itemKey2);
		}
		ResourceInts resources = character.GetResources();
		for (sbyte resType = 0; resType < 8; resType++)
		{
			if (allowResourceTypeSet.Contains(resType))
			{
				int targetAmount = GetFriendOrFamilySendResourceAmount(orgInfo.InteractionGrade, resType);
				if (resources.Get(resType) >= targetAmount)
				{
					int templateId = resType;
					resourceList.Add(new ItemKey(12, 0, (short)templateId, -1));
				}
			}
		}
		return SelectFriendOrFamilyGift(context, itemList, resourceList, -1);
	}

	private ItemKey GetFriendOrFamilyCityCharGift(DataContext context, GameData.Domains.Character.Character character, (sbyte min, sbyte max) gradeRange)
	{
		ItemKey resultItemKey = ItemKey.Invalid;
		OrganizationInfo orgInfo = character.GetOrganizationInfo();
		if (orgInfo.InteractionGrade == 0)
		{
			return resultItemKey;
		}
		List<ItemKey> itemList = new List<ItemKey>();
		List<ItemKey> resourceList = new List<ItemKey>();
		sbyte tempMerchantType;
		sbyte merchantType = (sbyte)(DomainManager.Extra.TryGetElement_MerchantCharToType(character.GetId(), out tempMerchantType) ? tempMerchantType : (-1));
		foreach (KeyValuePair<ItemKey, int> item in character.GetInventory().Items)
		{
			item.Deconstruct(out var key, out var _);
			ItemKey itemKey = key;
			bool needAdd = false;
			if (!ItemTemplateHelper.IsTransferable(itemKey.ItemType, itemKey.TemplateId))
			{
				continue;
			}
			sbyte grade = ItemTemplateHelper.GetGrade(itemKey.ItemType, itemKey.TemplateId);
			if (grade > gradeRange.max || grade < gradeRange.min)
			{
				continue;
			}
			bool hasPoison = DomainManager.Item.GetPoisonEffects(itemKey).IsValid;
			if (!ItemType.IsEquipmentItemType(itemKey.ItemType) && hasPoison)
			{
				continue;
			}
			switch (orgInfo.InteractionGrade)
			{
			case 1:
				if (itemKey.ItemType == 7)
				{
					needAdd = true;
				}
				if (itemKey.ItemType == 10 && Config.SkillBook.Instance[itemKey.TemplateId].LifeSkillType == 15)
				{
					needAdd = true;
				}
				break;
			case 2:
				if (itemKey.ItemType == 10)
				{
					sbyte lifeSkillType = Config.SkillBook.Instance[itemKey.TemplateId].LifeSkillType;
					if (((uint)(lifeSkillType - 6) <= 1u || (uint)(lifeSkillType - 10) <= 1u) ? true : false)
					{
						needAdd = true;
					}
				}
				else if (itemKey.ItemType == 6)
				{
					sbyte lifeSkillType2 = Config.CraftTool.Instance[itemKey.TemplateId].RequiredLifeSkillTypes.First();
					if (((uint)(lifeSkillType2 - 6) <= 1u || (uint)(lifeSkillType2 - 10) <= 1u) ? true : false)
					{
						needAdd = true;
					}
				}
				break;
			case 3:
				if (itemKey.ItemType == 10)
				{
					sbyte lifeSkillType3 = Config.SkillBook.Instance[itemKey.TemplateId].LifeSkillType;
					if ((uint)(lifeSkillType3 - 8) <= 1u)
					{
						needAdd = true;
					}
				}
				else if (itemKey.ItemType == 6)
				{
					sbyte lifeSkillType4 = Config.CraftTool.Instance[itemKey.TemplateId].RequiredLifeSkillTypes.First();
					if ((uint)(lifeSkillType4 - 8) <= 1u)
					{
						needAdd = true;
					}
				}
				break;
			case 4:
				switch (merchantType)
				{
				case 0:
				{
					sbyte itemType = itemKey.ItemType;
					if ((itemType == 4 || itemType == 7) ? true : false)
					{
						needAdd = true;
					}
					else if (itemKey.ItemType == 12 && itemKey.TemplateId == 18)
					{
						needAdd = true;
					}
					break;
				}
				case 1:
					if (itemKey.ItemType == 10)
					{
						needAdd = true;
					}
					break;
				case 2:
				{
					sbyte itemType = itemKey.ItemType;
					if ((itemType == 5 || itemType == 9 || itemType == 12) ? true : false)
					{
						needAdd = true;
					}
					break;
				}
				case 3:
				{
					sbyte itemType = itemKey.ItemType;
					if ((uint)itemType <= 2u)
					{
						needAdd = true;
					}
					break;
				}
				case 4:
					if (itemKey.ItemType == 8)
					{
						needAdd = true;
					}
					else if (itemKey.ItemType == 0 && Config.Weapon.Instance[itemKey.TemplateId].ItemSubType == 0)
					{
						needAdd = true;
					}
					break;
				case 5:
				{
					sbyte itemType = itemKey.ItemType;
					if ((itemType == 4 || itemType == 6) ? true : false)
					{
						needAdd = true;
					}
					break;
				}
				case 6:
				{
					sbyte itemType = itemKey.ItemType;
					if ((uint)itemType <= 2u)
					{
						needAdd = true;
					}
					break;
				}
				}
				break;
			case 5:
				if (itemKey.ItemType == 10)
				{
					sbyte lifeSkillType5 = Config.SkillBook.Instance[itemKey.TemplateId].LifeSkillType;
					if ((uint)lifeSkillType5 <= 3u)
					{
						needAdd = true;
					}
				}
				if (itemKey.ItemType == 9)
				{
					needAdd = true;
				}
				break;
			case 6:
			{
				sbyte itemType = itemKey.ItemType;
				if ((uint)(itemType - 9) <= 1u)
				{
					needAdd = true;
				}
				break;
			}
			case 7:
			{
				sbyte itemType = itemKey.ItemType;
				if ((itemType == 3 || itemType == 7 || (uint)(itemType - 9) <= 1u) ? true : false)
				{
					needAdd = true;
				}
				if (itemKey.ItemType == 5)
				{
					sbyte resourceType = Config.Material.Instance[itemKey.TemplateId].ResourceType;
					if ((uint)(resourceType - 3) <= 1u)
					{
						needAdd = true;
					}
				}
				break;
			}
			case 8:
				needAdd = true;
				break;
			}
			if (needAdd)
			{
				itemList.Add(itemKey);
			}
		}
		if (orgInfo.InteractionGrade >= 4)
		{
			ResourceInts resources = character.GetResources();
			for (sbyte resType = 0; resType <= 6; resType++)
			{
				switch (orgInfo.InteractionGrade)
				{
				case 4:
					if (resType != 6)
					{
						continue;
					}
					break;
				}
				int targetAmount = GetFriendOrFamilySendResourceAmount(orgInfo.InteractionGrade, resType);
				if (resources.Get(resType) >= targetAmount)
				{
					int templateId = resType;
					resourceList.Add(new ItemKey(12, 0, (short)templateId, -1));
				}
			}
		}
		return SelectFriendOrFamilyGift(context, itemList, resourceList, merchantType);
	}

	private ItemKey SelectFriendOrFamilyGift(DataContext context, List<ItemKey> itemList, List<ItemKey> resourceList, sbyte merchantType)
	{
		ItemKey resultItemKey = ItemKey.Invalid;
		int totalWeight = 0;
		int weightOfItem = 0;
		if (itemList.Count > 0)
		{
			totalWeight++;
			weightOfItem = totalWeight;
		}
		int weightOfResource = 0;
		if (resourceList.Count > 0)
		{
			totalWeight += 5;
			weightOfResource = totalWeight;
		}
		int weightOfExp = 0;
		totalWeight += 3;
		weightOfExp = totalWeight;
		if (totalWeight <= 0)
		{
			return resultItemKey;
		}
		int random = context.Random.Next(totalWeight);
		if (random < weightOfItem)
		{
			List<ItemKey> lowGradeItemList = itemList.Where((ItemKey key) => ItemTemplateHelper.GetGrade(key.ItemType, key.TemplateId) <= 2).ToList();
			List<ItemKey> middleGradeItemList = itemList.Where(delegate(ItemKey key)
			{
				sbyte grade = ItemTemplateHelper.GetGrade(key.ItemType, key.TemplateId);
				return grade > 2 && grade <= 4;
			}).ToList();
			List<ItemKey> highGradeItemList = itemList.Where(delegate(ItemKey key)
			{
				sbyte grade = ItemTemplateHelper.GetGrade(key.ItemType, key.TemplateId);
				return grade > 4 && grade <= 6;
			}).ToList();
			int totalItemWeight = 0;
			int weightOfLowItem = 0;
			if (lowGradeItemList.Count > 0)
			{
				totalItemWeight += 3;
				weightOfLowItem = totalItemWeight;
			}
			int weightOfMiddleItem = 0;
			if (middleGradeItemList.Count > 0)
			{
				totalItemWeight += 5;
				weightOfMiddleItem = totalItemWeight;
			}
			int weightOfHighItem = 0;
			if (highGradeItemList.Count > 0)
			{
				totalItemWeight++;
				weightOfHighItem = totalItemWeight;
			}
			List<ItemKey> targetList = null;
			if (totalItemWeight > 0)
			{
				int itemRandom = context.Random.Next(totalItemWeight);
				if (itemRandom < weightOfLowItem)
				{
					targetList = lowGradeItemList;
				}
				else if (itemRandom < weightOfMiddleItem)
				{
					targetList = middleGradeItemList;
				}
				else if (itemRandom < weightOfHighItem)
				{
					targetList = highGradeItemList;
				}
			}
			if (targetList != null)
			{
				resultItemKey = ((merchantType >= 0) ? GetCityMerchantCharGiftItem(context, merchantType, targetList) : targetList.GetRandom(context.Random));
			}
		}
		else if (random < weightOfResource)
		{
			resultItemKey = resourceList.GetRandom(context.Random);
		}
		return resultItemKey;
	}

	private ItemKey GetCityMerchantCharGiftItem(DataContext context, int merchantType, List<ItemKey> otherItemList)
	{
		List<(sbyte, short, sbyte)> weightList = new List<(sbyte, short, sbyte)>();
		switch (merchantType)
		{
		case 0:
			weightList.Add((4, -1, 4));
			weightList.Add((7, -1, 4));
			weightList.Add((12, -1, 2));
			break;
		case 1:
			return (otherItemList.Count > 0) ? otherItemList.First() : ItemKey.Invalid;
		case 2:
			weightList.Add((5, -1, 4));
			weightList.Add((9, -1, 4));
			weightList.Add((12, -1, 2));
			break;
		case 3:
			weightList.Add((0, -1, 4));
			weightList.Add((1, -1, 4));
			weightList.Add((2, -1, 2));
			break;
		case 4:
			weightList.Add((8, 800, 4));
			weightList.Add((8, 801, 4));
			weightList.Add((0, -1, 2));
			break;
		case 5:
			weightList.Add((6, -1, 2));
			weightList.Add((4, -1, 1));
			break;
		case 6:
			weightList.Add((2, -1, 4));
			weightList.Add((1, -1, 4));
			weightList.Add((0, -1, 2));
			break;
		}
		return GetCityMerchantCharGiftItem(context, otherItemList, weightList);
	}

	private ItemKey GetCityMerchantCharGiftItem(DataContext context, List<ItemKey> itemList, List<(sbyte itemType, short itemSubType, sbyte weight)> weightList)
	{
		List<ItemKey>[] listArray = new List<ItemKey>[weightList.Count];
		int[] weightArray = new int[weightList.Count];
		int[] curWeightArray = new int[weightList.Count];
		for (int index = 0; index < weightList.Count; index++)
		{
			(sbyte itemType, short itemSubType, sbyte weight) valueTuple = weightList[index];
			listArray[index] = itemList.Where(delegate(ItemKey k)
			{
				if (valueTuple.itemSubType < 0)
				{
					return k.ItemType == valueTuple.itemType;
				}
				short itemSubType = ItemTemplateHelper.GetItemSubType(k.ItemType, k.TemplateId);
				return k.ItemType == valueTuple.itemType && itemSubType == valueTuple.itemSubType;
			}).ToList();
			weightArray[index] = ((listArray[index].Count > 0) ? valueTuple.weight : 0);
		}
		int totalTypeWeight = 0;
		for (int index2 = 0; index2 < weightList.Count; index2++)
		{
			curWeightArray[index2] = totalTypeWeight + weightArray[index2];
			totalTypeWeight += weightArray[index2];
		}
		ItemKey itemKey = ItemKey.Invalid;
		if (totalTypeWeight > 0)
		{
			int random = context.Random.Next(totalTypeWeight);
			for (int index3 = 0; index3 < weightList.Count; index3++)
			{
				if (random < curWeightArray[index3] && listArray[index3].Count > 0)
				{
					itemKey = listArray[index3].GetRandom(context.Random);
					break;
				}
			}
		}
		return itemKey;
	}

	private int GetFriendOrFamilySendResourceAmount(sbyte charGrade, sbyte resourceType)
	{
		int value = 0;
		if (resourceType < 6)
		{
			value = 20;
		}
		else if (resourceType == 6)
		{
			value = 100;
		}
		return (int)Math.Pow(charGrade + 2, 2.0) * value;
	}

	private int CorrectFriendOrFamilySendResourceAmount(IRandomSource randomSource, int sendAmount, int curAmount)
	{
		int random = randomSource.Next(80, 121);
		sendAmount = sendAmount * random / 100;
		int limit = curAmount / 3;
		return Math.Min(sendAmount, limit);
	}

	private int GetFriendOrFamilySendExpAmount(sbyte charGrade)
	{
		return (int)Math.Pow(charGrade + 2, 2.0) * 50;
	}

