	[DomainMethod]
	public void UnlockLegendaryBookBonus(DataContext context, sbyte skillType, bool isYin)
	{
		SByteList bonusCount = (isYin ? _legendaryBookBonusCountYin : _legendaryBookBonusCountYang);
		bool limitionActive = DomainManager.World.IsChallengeModeEnabled(EChallengeModeImplement.LegendaryBookLimitation);
		if (bonusCount.Items == null)
		{
			bonusCount.Items = new List<sbyte>();
			for (sbyte i = 0; i < 14; i++)
			{
				bonusCount.Items.Add(0);
			}
			if (isYin)
			{
				SetLegendaryBookBonusCountYin(bonusCount, context);
			}
			else
			{
				SetLegendaryBookBonusCountYang(bonusCount, context);
			}
		}
		if (bonusCount.Items[skillType] < 12)
		{
			int unlockedCount = bonusCount.Items[skillType];
			SByteList anotherBonusCount = (isYin ? _legendaryBookBonusCountYang : _legendaryBookBonusCountYin);
			if (anotherBonusCount.Items != null)
			{
				unlockedCount += anotherBonusCount.Items[skillType];
			}
			int costExp = GlobalConfig.Instance.LegendaryBookUnlockExp[unlockedCount];
			if (limitionActive)
			{
				costExp *= 2;
			}
			GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
			if (costExp > taiwuChar.GetExp())
			{
				throw new Exception($"Exp not enough. need {costExp}, have {taiwuChar.GetExp()}");
			}
			taiwuChar.ChangeExp(context, -costExp);
			bonusCount.Items[skillType]++;
			if (isYin)
			{
				SetLegendaryBookBonusCountYin(bonusCount, context);
			}
			else
			{
				SetLegendaryBookBonusCountYang(bonusCount, context);
			}
		}
	}

	public void SetLegendaryBookBonusCount(bool isYin, SByteList bonusCount, DataContext context)
	{
		if (isYin)
		{
			SetLegendaryBookBonusCountYin(bonusCount, context);
		}
		else
		{
			SetLegendaryBookBonusCountYang(bonusCount, context);
		}
	}

