	private long AddLegendaryBookWeaponEffect(DataContext context, sbyte skillType, ItemKey weaponKey)
	{
		string className = LegendaryBookSlot.Instance[Config.CombatSkillType.Instance[skillType].LegendaryBookWeaponSlot].ClassName;
		if (string.IsNullOrEmpty(className))
		{
			return -1L;
		}
		string fullTypeName = "GameData.Domains.SpecialEffect." + className;
		Type specialEffectType = Type.GetType(fullTypeName);
		if (specialEffectType == null)
		{
			throw new Exception("Cannot find type '" + fullTypeName + "'.");
		}
		SpecialEffectBase effect = (SpecialEffectBase)Activator.CreateInstance(specialEffectType, DomainManager.Taiwu.GetTaiwuCharId(), weaponKey);
		DomainManager.SpecialEffect.Add(context, effect);
		return effect.Id;
	}

