		GameData.Domains.Character.Character enemyChar = DomainManager.Character.CreateTemporaryCopyOfCharacter(context, (prevOwnerId >= 0) ? DomainManager.Character.GetElement_Objects(prevOwnerId) : DomainManager.Taiwu.GetTaiwu());
		enemyChar.SetHealth(enemyChar.GetLeftMaxHealth(), context);
		_unlockCombatInfo = (skillType: skillType, isYin: isYin, enemyChar: enemyChar);
