	private void EnterUnlockBreakPlateCombatOnCombatEnd(DataContext context)
	{
		if (DomainManager.Combat.GetCombatStatus() == 3)
		{
			UnlockLegendaryBookBreakPlate(context, _unlockCombatInfo.skillType, _unlockCombatInfo.isYin);
		}
		DomainManager.Character.RemoveTemporaryIntelligentCharacter(context, _unlockCombatInfo.enemyChar);
		Events.UnRegisterHandler_CombatEnd(EnterUnlockBreakPlateCombatOnCombatEnd);
	}

	[DomainMethod]
	public void UnlockLegendaryBookBreakPlate(DataContext context, sbyte skillType, bool isYin)
	{
		sbyte oldStateSbyte;
		bool exist = _legendaryBookBreakPlateCounts.TryGetValue(skillType, out oldStateSbyte);
		ELegendaryBookSlotState oldState = (ELegendaryBookSlotState)(exist ? oldStateSbyte : (-1));
		ELegendaryBookSlotState eLegendaryBookSlotState = oldState;
		if (1 == 0)
		{
		}
		ELegendaryBookSlotState eLegendaryBookSlotState2;
		switch (eLegendaryBookSlotState)
		{
		case ELegendaryBookSlotState.Locked:
			eLegendaryBookSlotState2 = ((!isYin) ? ELegendaryBookSlotState.OnlyYang : ELegendaryBookSlotState.OnlyYin);
			break;
		case ELegendaryBookSlotState.OnlyYang:
			if (!isYin)
			{
				goto default;
			}
			eLegendaryBookSlotState2 = ELegendaryBookSlotState.BothUnlocked;
			break;
		case ELegendaryBookSlotState.OnlyYin:
			if (isYin)
			{
				goto default;
			}
			eLegendaryBookSlotState2 = ELegendaryBookSlotState.BothUnlocked;
			break;
		default:
			eLegendaryBookSlotState2 = oldState;
			break;
		}
		if (1 == 0)
		{
		}
		ELegendaryBookSlotState newState = eLegendaryBookSlotState2;
		if (newState != oldState)
		{
			if (exist)
			{
				SetElement_LegendaryBookBreakPlateCounts(skillType, (sbyte)newState, context);
			}
			else
			{
				AddElement_LegendaryBookBreakPlateCounts(skillType, (sbyte)newState, context);
			}
		}
	}

