	public bool IsBookOwnedByTaiwu(sbyte bookType)
	{
		if (DomainManager.LegendaryBook.GetElement_BookOwners(bookType) == DomainManager.Taiwu.GetTaiwuCharId())
		{
			return true;
		}
		foreach (SectStoryThreeCorpsesCharacter corpse in _sectRanshanThreeCorpses)
		{
			if (corpse.LegendaryBooks == null)
			{
				continue;
			}
			foreach (sbyte corpseBookType in corpse.LegendaryBooks)
			{
				if (bookType == corpseBookType)
				{
					return true;
				}
			}
		}
		return false;
	}

	private void RegisterLegendaryBookDataListener()
	{
		for (ulong type = 0uL; type < 14; type++)
		{
			DataUid legendaryBookUid = new DataUid(11, 0, type);
			GameData.GameDataBridge.GameDataBridge.AddPostDataModificationHandler(legendaryBookUid, GetType().Name, OnLegendaryBookChange);
			OnLegendaryBookChange(DataContextManager.GetCurrentThreadDataContext(), legendaryBookUid);
		}
	}

	private void OnLegendaryBookChange(DataContext context, DataUid dataUid = default(DataUid))
	{
		sbyte skillType = (sbyte)dataUid.SubId0;
		if (IsBookOwnedByTaiwu(skillType))
		{
			if (_legendaryBookWeaponSlot.ContainsKey(skillType) && _legendaryBookWeaponSlot[skillType].IsValid() && _legendaryBookWeaponEffectId[skillType] < 0)
			{
				long effectId = AddLegendaryBookWeaponEffect(context, skillType, _legendaryBookWeaponSlot[skillType]);
				SetElement_LegendaryBookWeaponEffectId(skillType, effectId, context);
			}
			if (!_legendaryBookSkillSlot.TryGetValue(skillType, out var value))
			{
				return;
			}
			List<short> skillIdList = value.Items;
			LongList effectIdList = _legendaryBookSkillEffectId[skillType];
			for (int i = 0; i < 9; i++)
			{
				if (skillIdList[i] >= 0 && effectIdList.Items[i] < 0)
				{
					long effectId2 = AddLegendaryBookSkillEffect(context, skillType, i, skillIdList[i]);
					effectIdList.Items[i] = effectId2;
				}
			}
			SetElement_LegendaryBookSkillEffectId(skillType, effectIdList, context);
			return;
		}
		if (_legendaryBookWeaponEffectId.ContainsKey(skillType) && _legendaryBookWeaponEffectId[skillType] >= 0)
		{
			DomainManager.SpecialEffect.Remove(context, _legendaryBookWeaponEffectId[skillType]);
			SetElement_LegendaryBookWeaponEffectId(skillType, -1L, context);
		}
		if (!_legendaryBookSkillSlot.ContainsKey(skillType))
		{
			return;
		}
		LongList effectIdList2 = _legendaryBookSkillEffectId[skillType];
		for (int j = 0; j < 9; j++)
		{
			if (effectIdList2.Items[j] >= 0)
			{
				DomainManager.SpecialEffect.Remove(context, effectIdList2.Items[j]);
				effectIdList2.Items[j] = -1L;
			}
		}
		SetElement_LegendaryBookSkillEffectId(skillType, effectIdList2, context);
	}

	public void UpdateTaiwuLegendaryBookEffects(DataContext context)
	{
		for (sbyte skillType = 0; skillType < 14; skillType++)
		{
			if (_legendaryBookWeaponEffectId.ContainsKey(skillType) && _legendaryBookWeaponEffectId[skillType] >= 0)
			{
				long effectId = AddLegendaryBookWeaponEffect(context, skillType, _legendaryBookWeaponSlot[skillType]);
				DomainManager.SpecialEffect.Remove(context, _legendaryBookWeaponEffectId[skillType]);
				SetElement_LegendaryBookWeaponEffectId(skillType, effectId, context);
			}
			if (_legendaryBookSkillSlot.TryGetValue(skillType, out var value))
			{
				List<short> skillIdList = value.Items;
				LongList effectIdList = _legendaryBookSkillEffectId[skillType];
				for (int i = 0; i < 9; i++)
				{
					if (effectIdList.Items[i] >= 0)
					{
						long effectId2 = AddLegendaryBookSkillEffect(context, skillType, i, skillIdList[i]);
						DomainManager.SpecialEffect.Remove(context, effectIdList.Items[i]);
						effectIdList.Items[i] = effectId2;
					}
				}
				SetElement_LegendaryBookSkillEffectId(skillType, effectIdList, context);
			}
		}
	}

