	}

	public CValueModifyDelta CalcLegendaryBookAddPropertyValue(ECharacterPropertyReferencedType propertyType)
	{
		int value = 0;
		for (sbyte skillType = 0; skillType < 14; skillType++)
		{
			if (IsBookOwnedByTaiwu(skillType))
			{
				CombatSkillTypeItem config = Config.CombatSkillType.Instance[skillType];
				sbyte yinCount = _legendaryBookBonusCountYin.Items?[skillType] ?? 0;
				for (int i = 0; i < yinCount; i++)
				{
					short type = config.LegendaryBookAddPropertyYin[i];
					PropertyAndValue[] propertyBonusList = LegendaryBookPropertyBonusType.Instance[type].PropertyBonusList;
					foreach (PropertyAndValue bonus in propertyBonusList)
					{
						value += propertyType.Sum(bonus);
					}
				}
				sbyte yangCount = _legendaryBookBonusCountYang.Items?[skillType] ?? 0;
				for (int k = 0; k < yangCount; k++)
				{
					short type2 = config.LegendaryBookAddPropertyYang[k];
					PropertyAndValue[] propertyBonusList2 = LegendaryBookPropertyBonusType.Instance[type2].PropertyBonusList;
					foreach (PropertyAndValue bonus2 in propertyBonusList2)
					{
						value += propertyType.Sum(bonus2);
					}
				}
			}
		}
		EDataModifyType modifyType = ((!CharacterPropertyReferenced.Instance[(int)propertyType].LegendaryBookIsAdd) ? EDataModifyType.AddPercent : EDataModifyType.Add);
		return new CValueModifyDelta(modifyType, value);
	}

	private int Comparision(short x, short y)
	{
		int brokenLevelX = DomainManager.Map.QueryAreaBrokenLevel(x);
		return DomainManager.Map.QueryAreaBrokenLevel(y).CompareTo(brokenLevelX);
	}

	public void InitializeTreasureMaterials(DataContext context, EMiscGenerateType type = EMiscGenerateType.Any)
	{
		for (int i = 0; i < 90; i++)
		{
			TreasureMaterialData[] brokenAreaMaterials = _brokenAreaMaterials;
			int num = i;
			if (brokenAreaMaterials[num] == null)
			{
				brokenAreaMaterials[num] = new TreasureMaterialData();
			}
		}
		List<short> brokenAreas = ObjectPool<List<short>>.Instance.Get();
		List<short> areaPicked = ObjectPool<List<short>>.Instance.Get();
		List<short> areaBlocks = ObjectPool<List<short>>.Instance.Get();
		MapDomain mapDomain = DomainManager.Map;
		TreasureMaterialHelper helper = new TreasureMaterialHelper(type);
		for (int j = 0; j < 90; j++)
		{
			if (_brokenAreaMaterials[j].BlockMaterialTemplateIds.Count == 0)
			{
				continue;
			}
			areaPicked.Clear();
			areaBlocks.Clear();
			Dictionary<short, List<short>> areaMaterials = _brokenAreaMaterials[j].BlockMaterialTemplateIds;
			short areaId = (short)(45 + j);
			sbyte stateId = DomainManager.Map.GetStateTemplateIdByAreaId(areaId);
			foreach (var (blockId, templateIds) in areaMaterials)
			{
				if (!DomainManager.Map.TryGetBlock(new Location(areaId, blockId), out var data) || !data.IsPassable())
				{
					areaPicked.AddRange(templateIds);
					areaBlocks.Add(blockId);
				}
			}
			helper.RegenerateInState(stateId, areaPicked);
			foreach (short blockId2 in areaBlocks)
			{
				areaMaterials.Remove(blockId2);
			}
		}
		for (sbyte stateId2 = 0; stateId2 < 15; stateId2++)
		{
			mapDomain.GetAllBrokenAreaInState(stateId2, brokenAreas);
			brokenAreas.Sort(Comparision);
			for (int areaIndex = 0; areaIndex < brokenAreas.Count; areaIndex++)
			{
				short areaId2 = brokenAreas[areaIndex];
				areaPicked.Clear();
				helper.PickAreaTemplates(context.Random, areaPicked, areaId2);
				areaBlocks.Clear();
				Span<MapBlockData> blocks = mapDomain.GetAreaBlocks(areaId2);
				Span<MapBlockData> span = blocks;
				for (int k = 0; k < span.Length; k++)
				{
					MapBlockData block = span[k];
					if (block.TemplateId != 38 && block.IsPassable())
					{
						areaBlocks.Add(block.BlockId);
					}
				}
				TreasureMaterialData areaMaterials2 = _brokenAreaMaterials[areaId2 - 45];
				foreach (short picked in areaPicked)
				{
					short blockId3 = areaBlocks.GetRandom(context.Random);
					List<short> blockTemplates = areaMaterials2.BlockMaterialTemplateIds.GetOrNew(blockId3);
					blockTemplates.Add(picked);
				}
			}
		}
		ObjectPool<List<short>>.Instance.Return(brokenAreas);
		ObjectPool<List<short>>.Instance.Return(areaPicked);
		ObjectPool<List<short>>.Instance.Return(areaBlocks);
		for (int l = 0; l < 90; l++)
		{
			SetElement_BrokenAreaMaterials(l, _brokenAreaMaterials[l], context);
		}
	}

	public void ComplementTreasureMaterials(DataContext context)
	{
		if (_brokenAreaMaterials[0] == null)
		{
			InitializeTreasureMaterials(context);
		}
		else if (DomainManager.World.IsCurrWorldBeforeVersion(0, 0, 78, 31))
		{
			InitializeTreasureMaterials(context, EMiscGenerateType.V78R31);
		}
		else if (DomainManager.World.IsCurrWorldBeforeVersion(0, 0, 78, 42))
		{
			InitializeTreasureMaterials(context, EMiscGenerateType.Invalid);
		}
	}

	[DomainMethod]
	public TreasureFindResult FindTreasure(DataContext context, int charId)
	{
		if (DomainManager.World.GetLeftDaysInCurrMonth() < 3)
		{
			return TreasureFindResult.Invalid;
		}
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			return TreasureFindResult.Invalid;
		}
		Location location = character.GetLocation();
		if (!location.IsValid())
		{
			return TreasureFindResult.Invalid;
		}
		DomainManager.World.AdvanceDaysInMonth(context, 3);
		TreasureFindResult treasureFindResult = new TreasureFindResult();
		treasureFindResult.Location = location;
		TreasureFindResult result = treasureFindResult;
		if (FindTreasureExtra(context, location, character, ref result))
		{
			FindTreasureStandard(context, location, character, ref result);
		}
		if (result.AnyMaterial)
		{
			int brokenLevel = DomainManager.Map.QueryAreaBrokenLevel(location.AreaId);
			DomainManager.TaiwuEvent.OnEvent_TaiwuFindMaterial(brokenLevel, result);
		}
		else
		{
			FindTreasureApplyResult(context, charId, result);
			FindTreasureGenerateLifeRecord(charId, result);
		}
		return result;
	}

	private unsafe int FindTreasureChance(MapBlockData block, GameData.Domains.Character.Character character)
	{
		Personalities personalities = character.GetPersonalities();
		sbyte luck = personalities.Items[5];
		return block.CalcFindTreasureChance(luck);
	}

	private unsafe int FindTreasureChance(MapBlockData block, GameData.Domains.Character.Character character, int itemsCount)
	{
		Personalities personalities = character.GetPersonalities();
		sbyte luck = personalities.Items[5];
		return block.CalcFindTreasureChanceByItemsCount(luck, itemsCount);
	}

	private void FindTreasureStandard(DataContext context, Location location, GameData.Domains.Character.Character character, ref TreasureFindResult result)
	{
		MapBlockData block = DomainManager.Map.GetBlock(location);
		int chance = FindTreasureChance(block, character);
		if (context.Random.CheckPercentProb(chance))
		{
			result.ItemKeyAndDate = RandomUtils.GetRandomResult(block.Items.Keys.Select((ItemKeyAndDate itemAndDate) => ((ItemKeyAndDate itemAndDate, short))(itemAndDate: itemAndDate, GlobalConfig.Instance.FindTreasureGradeRate[ItemTemplateHelper.GetGrade(itemAndDate.ItemKey.ItemType, itemAndDate.ItemKey.TemplateId)])), context.Random);
			result.ItemCount = (uint)block.Items[result.ItemKeyAndDate];
		}
		if (TryGetLocationMaterials(location, out var materials) && materials.Count > 0 && context.Random.CheckPercentProb(20 + _treasureMaterialFailedTimes * 10))
		{
			SetTreasureMaterialFailedTimes(0, context);
			result.MaterialTemplateId = materials[context.Random.Next(materials.Count)];
		}
		else if (materials != null && materials.Count > 0)
		{
			SetTreasureMaterialFailedTimes(_treasureMaterialFailedTimes + 1, context);
			result.ResourceType = 6;
			result.ResourceCount = context.Random.Next(100, 300);
		}
	}

	private bool FindTreasureExtra(DataContext context, Location location, GameData.Domains.Character.Character character, ref TreasureFindResult result)
	{
		MapBlockData block = DomainManager.Map.GetBlock(location);
		if (DomainManager.World.IsExtraTaskInProgress(141) && character.GetId() == DomainManager.Taiwu.GetTaiwuCharId() && block.GetConfig().SubType == EMapBlockSubType.ShaolinPai)
		{
			List<ItemKey> extraItems = new List<ItemKey>(3);
			DomainManager.Story.ShaolinGetSutraBooks(context, 0, 2, delegate(ItemKey item)
			{
				extraItems.Add(item);
			});
			result.ExtraItems = extraItems;
			result.SetExtraItemType(ETreasureExtraItemType.ShaolinSutra);
			return false;
		}
		if (block.Items != null && block.Items.Keys.Any((ItemKeyAndDate x) => EatingItems.IsWugKing(x.ItemKey)))
		{
			List<ItemKeyAndDate> pool = ObjectPool<List<ItemKeyAndDate>>.Instance.Get();
			foreach (ItemKeyAndDate itemAndDate in block.Items.Keys)
			{
				if (EatingItems.IsWugKing(itemAndDate.ItemKey))
				{
					pool.Add(itemAndDate);
				}
			}
			ItemKeyAndDate treasure = pool.GetRandom(context.Random);
			DomainManager.Map.RemoveBlockItem(context, block, treasure);
			result.ExtraItems = new List<ItemKey>();
			result.ExtraItems.Add(treasure.ItemKey);
			result.SetExtraItemType(ETreasureExtraItemType.WuxianWugKing);
			return false;
		}
		foreach (LoongInfo loongInfo in _fiveLoongDict.Values)
		{
			if (!loongInfo.MapBlockExtraItems.TryGetValue(location, out var inventory))
			{
				continue;
			}
			List<ItemKey> extraItems2 = new List<ItemKey>();
			foreach (KeyValuePair<ItemKey, int> itemKey in inventory.Items)
			{
				for (int c = 0; c < itemKey.Value; c++)
				{
					extraItems2.Add(itemKey.Key);
				}
			}
			if (extraItems2.Count <= 0 || !context.Random.CheckPercentProb(FindTreasureChance(block, character, extraItems2.Count)))
			{
				continue;
			}
			result.ExtraItems = extraItems2;
			result.SetExtraItemType(ETreasureExtraItemType.LoongInventory);
			return false;
		}
		return true;
	}

	[DomainMethod]
	public void InvokeFindExtraTreasureEvent(TreasureFindResult result)
	{
		DomainManager.TaiwuEvent.OnEvent_TaiwuFindExtraTreasure(result);
	}

	[DomainMethod]
	public TreasureExpectResult FindTreasureExpect(Location location)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(DomainManager.Taiwu.GetTaiwuCharId());
		MapBlockData block = DomainManager.Map.GetBlock(location);
		int chance = FindTreasureChance(block, character);
		bool anyNormalItem = chance > 0;
		sbyte maxGrade = 0;
		if (anyNormalItem)
		{
			for (int index = 0; index < block.Items.Keys.Count; index++)
			{
				ItemKey itemKey = block.Items.Keys[index].ItemKey;
				sbyte grade = ItemTemplateHelper.GetGrade(itemKey.ItemType, itemKey.TemplateId);
				maxGrade = Math.Max(maxGrade, grade);
			}
		}
		bool anyMaterial = IsLocationContainsAnyMaterial(location);
		FindTreasureExpectExtra(location, ref maxGrade, ref chance);
		return new TreasureExpectResult
		{
			MaxGrade = maxGrade,
			Chance = chance,
			Location = location,
			AnyMaterial = anyMaterial,
			AnyNormalItem = anyNormalItem
		};
	}

	private void FindTreasureExpectExtra(Location location, ref sbyte maxGrade, ref int chance)
	{
		foreach (LoongInfo loongInfo in _fiveLoongDict.Values)
		{
			if (!loongInfo.MapBlockExtraItems.TryGetValue(location, out var inventory))
			{
				continue;
			}
			foreach (KeyValuePair<ItemKey, int> itemKey in inventory.Items)
			{
				sbyte grade = ItemTemplateHelper.GetGrade(itemKey.Key.ItemType, itemKey.Key.TemplateId);
				if (grade > maxGrade)
				{
					maxGrade = grade;
				}
			}
			GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(DomainManager.Taiwu.GetTaiwuCharId());
			MapBlockData block = DomainManager.Map.GetBlock(location);
			chance = FindTreasureChance(block, character, inventory.Items.Count);
		}
	}

	public void FindTreasureApplyResult(DataContext context, int charId, TreasureFindResult result, List<ItemKey> addedItemKeys = null)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			return;
		}
		if (result.AnyResource)
		{
			character.ChangeResource(context, result.ResourceType, result.ResourceCount);
		}
		if (!result.Success)
		{
			return;
		}
		bool requireObjectPool = addedItemKeys == null;
		if (addedItemKeys == null)
		{
			addedItemKeys = ObjectPool<List<ItemKey>>.Instance.Get();
		}
		addedItemKeys.Clear();
		if (result.AnyItem)
		{
			ItemKeyAndDate itemAndDates = result.ItemKeyAndDate;
			MapBlockData block = DomainManager.Map.GetBlock(result.Location);
			int amount = block.Items[itemAndDates];
			DomainManager.Map.RemoveBlockItem(context, block, itemAndDates);
			Tester.Assert(amount > 0);
			character.AddInventoryItem(context, result.ItemKey, amount);
			for (int i = 0; i < amount; i++)
			{
				addedItemKeys.Add(result.ItemKey);
			}
		}
		if (result.AnyMaterial)
		{
			int brokenIndex = result.Location.AreaId - 45;
			List<short> materials = _brokenAreaMaterials[brokenIndex].BlockMaterialTemplateIds[result.Location.BlockId];
			materials.Remove(result.MaterialTemplateId);
			SetElement_BrokenAreaMaterials(brokenIndex, _brokenAreaMaterials[brokenIndex], context);
			ItemKey itemKey = DomainManager.Item.CreateMisc(context, result.MaterialTemplateId);
			character.AddInventoryItem(context, itemKey, 1);
			addedItemKeys.Add(itemKey);
		}
		if (result.AnyExtraItem)
		{
			List<ItemKey> loongItemKeys = new List<ItemKey>();
			short[] fiveLoongKeys = _fiveLoongDict.Keys.ToArray();
			for (int j = result.ExtraItems.Count - 1; j >= 0; j--)
			{
				ItemKey itemKey2 = result.ExtraItems[j];
				bool shouldRemove = false;
				short[] array = fiveLoongKeys;
				foreach (short loongKey in array)
				{
					LoongInfo loongInfo = _fiveLoongDict[loongKey];
					bool shouldUpdate = false;
					if (loongInfo.MapBlockExtraItems.TryGetValue(result.Location, out var blockInventory) && blockInventory.Items.ContainsKey(itemKey2))
					{
						ItemKey createdItemKey = ((itemKey2.TemplateId == 278) ? DropJiaoEgg(context, isIgnoreDropRate: true, loongInfo.CharacterTemplateId, -1) : DomainManager.Item.CreateItem(context, itemKey2.ItemType, itemKey2.TemplateId));
						if (createdItemKey.IsValid())
						{
							character.AddInventoryItem(context, createdItemKey, 1);
							shouldUpdate = true;
							loongItemKeys.Add(createdItemKey);
						}
						blockInventory.OfflineRemove(itemKey2, 1);
						shouldRemove = true;
					}
					if (shouldUpdate)
					{
						SetLoongInfo(context, loongKey, loongInfo);
					}
				}
				if (shouldRemove)
				{
					result.ExtraItems.RemoveAt(j);
				}
			}
			foreach (ItemKey itemKey3 in result.ExtraItems)
			{
				character.AddInventoryItem(context, itemKey3, 1);
			}
			result.ExtraItems.AddRange(loongItemKeys);
			addedItemKeys.AddRange(result.ExtraItems);
		}
		foreach (ItemKey itemKey4 in addedItemKeys)
		{
			ItemBase item = DomainManager.Item.GetBaseItem(itemKey4);
			ProfessionFormulaItem formula = ProfessionFormula.Instance[5];
			int addSeniority = formula.Calculate(item.GetValue());
			DomainManager.Extra.ChangeProfessionSeniority(context, 0, addSeniority);
		}
		if (requireObjectPool)
		{
			ObjectPool<List<ItemKey>>.Instance.Return(addedItemKeys);
		}
	}

	public void FindTreasureGenerateLifeRecord(int charId, TreasureFindResult result, bool battleFailed = false)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		Location location = character.GetLocation();
		LifeRecordCollection lifeRecord = DomainManager.LifeRecord.GetLifeRecordCollection();
		int currDate = DomainManager.World.GetCurrDate();
		if (!result.Success)
		{
			lifeRecord.AddFindLostItemFail(charId, currDate, location);
			return;
		}
		if (battleFailed)
		{
			lifeRecord.AddDiggingXiangshuMinionCombatLost(charId, currDate, location);
			return;
		}
		if (result.AnyItem)
		{
			ItemKey itemKey = result.ItemKey;
			lifeRecord.AddFindLostItemSucceed(charId, currDate, location, itemKey.ItemType, itemKey.TemplateId);
		}
		if (result.AnyExtraItem)
		{
			foreach (ItemKey itemKey2 in result.ExtraItems)
			{
				lifeRecord.AddFindLostItemSucceed(charId, currDate, location, itemKey2.ItemType, itemKey2.TemplateId);
			}
		}
		if (result.AnyMaterial)
		{
			lifeRecord.AddDiggingXiangshuMinionCombatWon(charId, currDate, location, 12, result.MaterialTemplateId);
		}
	}

	private bool IsLocationContainsAnyMaterial(Location location)
	{
		short areaId = location.AreaId;
		if ((areaId < 45 || areaId >= 135) ? true : false)
		{
			return false;
		}
		TreasureMaterialData treasureData = _brokenAreaMaterials[location.AreaId - 45];
		if (treasureData?.BlockMaterialTemplateIds == null)
		{
			return false;
		}
		if (!treasureData.BlockMaterialTemplateIds.TryGetValue(location.BlockId, out var materials))
		{
			return false;
		}
		return materials != null && materials.Count > 0;
	}

	private bool TryGetLocationMaterials(Location location, out List<short> materials)
	{
		materials = null;
		short areaId = location.AreaId;
		if ((areaId < 45 || areaId >= 135) ? true : false)
		{
			return false;
		}
		TreasureMaterialData treasureData = _brokenAreaMaterials[location.AreaId - 45];
		if (treasureData?.BlockMaterialTemplateIds == null)
		{
			return false;
		}
		return treasureData.BlockMaterialTemplateIds.TryGetValue(location.BlockId, out materials);
	}

	public void SetTreasuries(DataContext context, short id, SettlementLayeredTreasuries treasuries, bool needUpdateTotalValue)
	{
		if (needUpdateTotalValue)
		{
			treasuries.CurrentTotalValue = 0;
			SettlementTreasury[] settlementTreasuries = treasuries.SettlementTreasuries;
			foreach (SettlementTreasury treasury in settlementTreasuries)
			{
				for (sbyte resourceType = 0; resourceType < 7; resourceType++)
				{
					treasuries.CurrentTotalValue += ResourceTypeHelper.ResourceAmountToWorth(resourceType, treasury.Resources[resourceType]);
				}
				treasuries.CurrentTotalValue += treasury.Inventory.GetTotalValue();
			}
		}
		if (_settlementLayeredTreasuries.ContainsKey(id))
		{
			SetElement_SettlementLayeredTreasuries(id, treasuries, context);
		}
		else
		{
			AddElement_SettlementLayeredTreasuries(id, treasuries, context);
		}
	}

	public IEnumerable<short> GetAllAlteredSettlementIds()
	{
		foreach (var (settlementId, treasury) in _settlementLayeredTreasuries)
		{
			if (treasury.AlertTime > 0)
			{
				yield return settlementId;
			}
		}
	}

